#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_CHANNEL 0
#define GPIO_PIN 8
#define MAX_SAMPLES 1023

static int spi_fd;
static int gpio_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct timespec ts;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        close(spi_fd);
        gpiod_chip_close(chip);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "spi_cs", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        close(spi_fd);
        gpiod_line_release(line);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Set CS low
        gpiod_line_set_value(line, 0);

        // Send SPI command to read from channel 0
        uint8_t tx[3] = {0x01, 0x80, 0x00};
        uint8_t rx[3];
        if (write(spi_fd, tx, 3) != 3) {
            perror("Failed to write to SPI");
            gpiod_line_set_value(line, 1);
            continue;
        }

        // Read response
        if (read(spi_fd, rx, 3) != 3) {
            perror("Failed to read from SPI");
            gpiod_line_set_value(line, 1);
            continue;
        }

        // Calculate raw ADC value
        uint16_t adc_value = (rx[1] << 8) | rx[2];

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            gpiod_line_set_value(line, 1);
            continue;
        }

        // Log the result
        printf("%ld.%09ld: %d\n", ts.tv_sec, ts.tv_nsec, adc_value);

        // Set CS high
        gpiod_line_set_value(line, 1);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(spi_fd);
    gpiod_chip_close(chip);
    gpiod_line_release(line);

    return 0;
}

