#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <i2c-dev.h>
#include <gpiod.h>
#include <stdint.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define GPIO_SDA 2
#define GPIO_SCL 3
#define SAMPLE_RATE 128
#define GAIN 4096
#define ADC_RESOLUTION 16
#define ADC_MAX_VALUE (1 << ADC_RESOLUTION) - 1
#define CURRENT_LSB 0.00000125  // 125 nA per LSB
#define LOG_INTERVAL 500  // 500 ms

static int i2c_fd;
static int gpiod_chip;
static int gpiod_line_sda;
static int gpiod_line_scl;

static void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpiod_chip >= 0) {
        gpiod_chip_close(gpiod_chip);
    }
    if (gpiod_line_sda >= 0) {
        gpiod_line_close(gpiod_line_sda);
    }
    if (gpiod_line_scl >= 0) {
        gpiod_line_close(gpiod_line_scl);
    }
    exit(0);
}

static void configure_ads1115() {
    uint8_t config = 0x00;  // Default configuration

    // Set single-shot mode
    config |= 0x80;

    // Set single-ended input on AIN0
    config |= 0x00;

    // Set programmable gain of ±4.096 V
    config |= 0x00;

    // Set data rate to 128 SPS
    config |= 0x00;

    if (i2c_smbus_write_byte_data(i2c_fd, 0x01, config) < 0) {
        perror("Failed to write configuration to ADS1115");
        exit(EXIT_FAILURE);
    }
}

static void read_current() {
    uint16_t raw_value;
    int16_t signed_value;
    float current;

    if (i2c_smbus_read_word_data(i2c_fd, 0x00) < 0) {
        perror("Failed to read conversion result from ADS1115");
        return;
    }

    // Read the raw value from the ADS1115
    raw_value = i2c_smbus_read_word_data(i2c_fd, 0x00);

    // Convert the raw value to a signed 16-bit integer
    signed_value = (int16_t)raw_value;

    // Convert the signed 16-bit integer to a float
    current = (float)signed_value * CURRENT_LSB * GAIN / ADC_MAX_VALUE;

    // Log the current value
    printf("Current: %.6f A\n", current);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line_sda = gpiod_chip_get_line(gpiod_chip, GPIO_SDA);
    if (gpiod_line_sda < 0) {
        perror("Failed to get GPIO line for SDA");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_scl = gpiod_chip_get_line(gpiod_chip, GPIO_SCL);
    if (gpiod_line_scl < 0) {
        perror("Failed to get GPIO line for SCL");
        gpiod_line_close(gpiod_line_sda);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpiod_line_sda, "ADS1115_SDA", 0) < 0) {
        perror("Failed to request GPIO line for SDA");
        gpiod_line_close(gpiod_line_sda);
        gpiod_line_close(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpiod_line_scl, "ADS1115_SCL", 0) < 0) {
        perror("Failed to request GPIO line for SCL");
        gpiod_line_close(gpiod_line_sda);
        gpiod_line_close(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_close(gpiod_line_sda);
        gpiod_line_close(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_close(gpiod_line_sda);
        gpiod_line_close(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    configure_ads1115();

    while (1) {
        read_current();
        usleep(LOG_INTERVAL * 1000);
    }

    close(i2c_fd);
    gpiod_line_close(gpiod_line_sda);
    gpiod_line_close(gpiod_line_scl);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

