        fprintf(stderr, "Failed to get buzzer GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(buzz_chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(heat_line);
        gpiod_chip_close(flame_chip);
        gpiod_chip_close(heat_chip);
        exit(1);
    }

    ret = gpiod_line_request_output(buzz_line, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request buzzer GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(buzz_chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(heat_line);
        gpiod_chip_close(flame_chip);
        gpiod_chip_close(heat_chip);
        gpiod_line_release(buzz_line);
        exit(1);
    }
