static void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(1);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(1);
    }
}

static void setup_adc() {
    // Assuming the ADC is configured for 12-bit resolution and the reference voltage is 4.096V
    // The configuration register is 0x01 and the gain is set to 1x
    uint8_t config = 0x01;
    ret = i2c_smbus_write_byte_data(i2c_fd, 0x01, config);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure ADC: %s\n", strerror(errno));
        close(i2c_fd);
        exit(1);
    }
}

static void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }

    if (adc_fd >= 0) {
        close(adc_fd);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (buzz_line != NULL) {
        gpiod_line_release(buzz_line);
    }

    if (heat_line != NULL) {
        gpiod_line_release(heat_line);
    }

    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }

    if (flame_chip != NULL) {
        gpiod_chip_close(flame_chip);
    }

    if (heat_chip != NULL) {
        gpiod_chip_close(heat_chip);
    }

    if (buzz_chip != NULL) {
        gpiod_chip_close(buzz_chip);
    }
}

int main() {
    setup_gpio();
    setup_i2c();
    setup_adc();

    signal(SIGINT, handle_sigint);

    while (running) {
        int flame_state = gpiod_line_get_value(flame_line);
        int heat_state = gpiod_line_get_value(heat_line);

        if (flame_state == 0 && heat_state == 0) {
            usleep(DEBOUNCE_TIME * 1000);
            flame_state = gpiod_line_get_value(flame_line);
            heat_state = gpiod_line_get_value(heat_line);
        }

        if (flame_state == 0 && heat_state == 0) {
            log_flame_detected();
        } else if (flame_state == 0) {
            log_temperature(convert_adc_to_temperature(read_adc()));
        } else if (heat_state == 0) {
            log_temperature(convert_adc_to_temperature(read_adc()));
        } else {
            log_fire_event(convert_adc_to_temperature(read_adc()));
            buzz_line = gpiod_chip_get_line(buzz_chip, BUZZER_PIN);
            if (buzz_line != NULL) {
                gpiod_line_request_output(buzz_line, "buzzer", 1);
                usleep(2000000);
                gpiod_line_request_output(buzz_line, "buzzer", 0);
            }
        }

        usleep(100000);
    }

    cleanup();
    return 0;
}
