#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 5
#define GPIO_CHIP_NAME "gpiochip5"
#define GPIO_FAN_PIN 18
#define CURRENT_THRESHOLD 1000 // in milliamps

static int spi_fd = -1;
static int gpio_fd = -1;
static int fan_pin = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *fan_line = NULL;

static void handle_signal(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_fd != -1) {
        gpiod_chip_close(chip);
    }
    if (fan_line != NULL) {
        gpiod_line_release(fan_line);
    }
    exit(signum);
}

static void log_current_reading(uint16_t current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, %d\n", timestamp, current);
    fclose(log_file);
}

static int read_current() {
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start conversion, single-ended, channel 0
    uint8_t rx[3];
    int retries = SPI_MAX_RETRIES;

    while (retries--) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE, tx, sizeof(tx)) < 0) {
            perror("SPI ioctl failed");
            return -1;
        }

        if (read(spi_fd, rx, sizeof(rx)) != sizeof(rx)) {
            perror("SPI read failed");
            return -1;
        }

        if (rx[0] == 0xFF && rx[1] == 0xFF && rx[2] == 0xFF) {
            // All-zero or all-ones ADC value, treat as sensor-absent
            return -1;
        }

        uint16_t current = (rx[1] << 8) | rx[2];
        log_current_reading(current);
        return current;
    }

    perror("SPI read failed (retries exhausted)");
    return -1;
}

static void control_fan(int state) {
    if (fan_line == NULL) {
        fan_line = gpiod_line_request_output(chip, GPIO_FAN_PIN, state);
        if (fan_line == NULL) {
            perror("Failed to request fan GPIO line");
            return;
        }
    }

    gpiod_line_set_value(fan_line, state);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI parameters
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tr) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        chip = gpiod_chip_open(0);
        if (chip == NULL) {
            perror("Failed to open GPIO chip");
            close(spi_fd);
            return EXIT_FAILURE;
        }
    }

    // Request fan GPIO line
    fan_line = gpiod_line_request_output(chip, GPIO_FAN_PIN, 0);
    if (fan_line == NULL) {
        perror("Failed to request fan GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        int current = read_current();
        if (current < 0) {
            continue;
        }

        if (current > CURRENT_THRESHOLD) {
            control_fan(1);
        } else {
            control_fan(0);
        }

        sleep(1);
    }

    // Clean up
    gpiod_line_release(fan_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

