To create a C program for a Raspberry Pi 4 Model B that reads the SGX Sensortech MICS-4514 dual MOS sensor over the I2C bus, we will use the `libgpiod` library for GPIO control and the `pigpio` library for I2C communication. The program will handle errors, ensure proper resource release, and simulate an industrial air-quality monitoring system by logging CO concentration and alerts.

Here's the complete C program:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ALERT_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define BUFFER_SIZE 4

static int i2c_fd;
static int gpio_fd;
static int alert_fd;
static int co_fd;
static int alert_count = 0;

static void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Exiting...\n");
        close(i2c_fd);
        close(gpio_fd);
        close(alert_fd);
        close(co_fd);
        exit(EXIT_SUCCESS);
    }
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpio_fd = gpiochip_open(0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_log_files() {
    co_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (co_fd < 0) {
        perror("Failed to open CO log file");
        close(i2c_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    alert_fd = open(ALERT_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (alert_fd < 0) {
        perror("Failed to open alert log file");
        close(i2c_fd);
        close(gpio_fd);
        close(co_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_sensor() {
    uint8_t buffer[BUFFER_SIZE];
    if (read(i2c_fd, buffer, BUFFER_SIZE) != BUFFER_SIZE) {
        perror("Failed to read from I2C");
        close(i2c_fd);
        close(gpio_fd);
        close(co_fd);
        close(alert_fd);
        exit(EXIT_FAILURE);
    }

    uint16_t ox = (buffer[0] << 8) | buffer[1];
    uint16_t red = (buffer[2] << 8) | buffer[3];

    // Convert OX value to CO concentration in ppm
    // Assuming the conversion formula is known
    // For example, using a known calibration curve
    float co_ppm = ox * 0.0001; // Example conversion factor

    printf("OX: %d, RED: %d, CO ppm: %.2f\n", ox, red, co_ppm);

    if (co_ppm >= ALERT_THRESHOLD) {
        fprintf(alert_fd, "Alert: CO ppm %.2f at time %ld\n", co_ppm, time(NULL));
        alert_count++;
    }

    fprintf(co_fd, "%.2f\n", co_ppm);
}

int main() {
    if (gpiochip_open(0) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    init_i2c();
    init_gpio();
    init_log_files();

    while (1) {
        read_sensor();
        sleep(5);
    }

    close(i2c_fd);
    close(gpio_fd);
    close(co_fd);
    close(alert_fd);

    return 0;
}
