#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SAMPLES 100
#define SPI_SAMPLE_PERIOD 1000000 // 1 ms
#define LED_PIN 27
#define HIGH_THRESHOLD 0.5 // RMS threshold for LED activation

static int spi_fd;
static int led_fd;
static struct gpiod_chip *led_chip;
static struct gpiod_line *led_line;
static struct timespec start_time;
static FILE *log_file;

void sigint_handler(int signum) {
    if (led_fd >= 0) {
        gpiod_line_set_value(led_line, 0);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
    }
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize LED
    led_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!led_chip) {
        perror("Failed to open LED GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(led_chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(led_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "audio_event_led", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(led_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("audio_events.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(led_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Start time
    if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
        perror("Failed to get start time");
        fclose(log_file);
        gpiod_line_release(led_line);
        gpiod_chip_close(led_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        uint8_t tx[3] = {0x01, 0x00, 0x00}; // Start command, channel 0, dummy byte
        uint8_t rx[3] = {0, 0, 0};
        int ret;

        // Read from SPI
        ret = read(spi_fd, rx, 3);
        if (ret < 0) {
            perror("Failed to read from SPI");
            fclose(log_file);
            gpiod_line_release(led_line);
            gpiod_chip_close(led_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Read from SPI
        ret = read(spi_fd, rx + 1, 3);
        if (ret < 0) {
            perror("Failed to read from SPI");
            fclose(log_file);
            gpiod_line_release(led_line);
            gpiod_chip_close(led_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Calculate RMS
        double mic1_rms = sqrt((double)rx[0] * rx[0] + (double)rx[1] * rx[1] + (double)rx[2] * rx[2]) / 3.0;
        double mic2_rms = sqrt((double)rx[3] * rx[3] + (double)rx[4] * rx[4] + (double)rx[5] * rx[5]) / 3.0;

        // Log to file
        struct timespec current_time;
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) < 0) {
            perror("Failed to get current time");
            fclose(log_file);
            gpiod_line_release(led_line);
            gpiod_chip_close(led_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        fprintf(log_file, "%ld,%f,%f\n", current_time.tv_sec * 1000000 + current_time.tv_nsec / 1000, mic1_rms, mic2_rms);

        // Check for high threshold
        if (mic1_rms > HIGH_THRESHOLD || mic2_rms > HIGH_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
            usleep(500000); // 500 ms
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 1 ms
        usleep(SPI_SAMPLE_PERIOD);
    }

    // Close resources
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(led_chip);
    close(spi_fd);

    return 0;
}

