#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define CHANNEL_A0 0
#define BUFFER_SIZE 100
#define LED_PIN 17
#define CURRENT_THRESHOLD 50.0
#define SAMPLE_RATE 10

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_fd = -1;
static int buffer_index = 0;
static float buffer[BUFFER_SIZE];
static float current_sum = 0.0;
static float current_average = 0.0;
static int running = 1;

static void handle_sigint(int signum) {
    running = 0;
    gpio_set_value(gpiod_line, 0);
    close(i2c_fd);
    gpiod_line_close(gpiod_line);
    gpiod_chip_close(gpiod_chip);
    exit(0);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    gpiod_line = gpiod_chip_get_line(gpiod_chip, LED_PIN);
    if (gpiod_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(gpiod_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_adc() {
    uint8_t config_reg = 0x40 | (CHANNEL_A0 << 4) | (SAMPLE_RATE << 2) | 0x01;
    if (write(i2c_fd, &config_reg, 1) != 1) {
        perror("Failed to write to ADC config register");
        return;
    }
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from ADC data register");
        return;
    }
    uint16_t raw_value = (data[0] << 8) | data[1];
    float voltage = (raw_value * 4.096) / 32768.0;
    float current = voltage / 0.02; // Assuming 0.02 A per V
    buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    current_sum += current;
    current_average = current_sum / BUFFER_SIZE;
    if (current_average > CURRENT_THRESHOLD) {
        gpio_set_value(gpiod_line, 1);
    } else {
        gpio_set_value(gpiod_line, 0);
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    init_i2c();
    init_gpio();
    while (running) {
        read_adc();
        usleep(100000); // 100 Hz
    }
    close(i2c_fd);
    gpiod_line_close(gpiod_line);
    gpiod_chip_close(gpiod_chip);
    return 0;
}

