    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Read the sensor ID
    uint8_t id[2];
    ret = gpiod_line_request_edge_detection(irq_line, "color_sensor", GPIOD_EDGE_RISING);
