                retries++;
                continue;
            }

            ret = read(i2c_fd, &green, 2);
            if (ret != 2) {
                fprintf(stderr, "Failed to read green register\n");
                retries++;
                continue;
            }

            ret = read(i2c_fd, &blue, 2);
            if (ret != 2) {
                fprintf(stderr, "Failed to read blue register\n");
                retries++;
                continue;
            }

            retries = 0;
            break;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor values\n");
            cleanup();
            return EXIT_FAILURE;
        }

        // Format the output
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, clear, red, green, blue);

        // Wait for the next second
        nanosleep(&sleep_time, &remaining_time);
    }

    cleanup();
    return EXIT_SUCCESS;
}

