static struct gpiod_line *ce0_line;
static struct gpiod_line *miso_line;
static struct gpiod_line *mosi_line;
static struct gpiod_line *sclk_line;

static void sig_handler(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (ce0_line != NULL) {
        gpiod_line_release(ce0_line);
    }
    if (miso_line != NULL) {
        gpiod_line_release(miso_line);
    }
    if (mosi_line != NULL) {
        gpiod_line_release(mosi_line);
    }
    if (sclk_line != NULL) {
        gpiod_line_release(sclk_line);
    }
    exit(signum);
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .delay_usecs = SPI_DELAY_USECS,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .cs_change_delay_usecs = 0,
        .pad = 0
    };

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int spi_read(uint8_t channel, uint8_t *data) {
    uint8_t cmd = 0b11000000 | (channel << 4);
    uint8_t rx[3];

    if (spi_transfer(&cmd, rx, 3) < 0) {
        return -1;
    }

    *data = (rx[1] << 4) | (rx[2] >> 4);
    return 0;
}

static void log_moisture_reading(uint64_t timestamp, uint8_t moisture1, uint8_t moisture2) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%llu,%u,%u\n", timestamp, moisture1, moisture2);
    fclose(file);
}

static void read_moisture_sensors() {
    uint8_t moisture1, moisture2;
    uint64_t timestamp = time(NULL);

    if (spi_read(0, &moisture1) < 0) {
        fprintf(stderr, "Failed to read moisture sensor 1\n");
    }

    if (spi_read(1, &moisture2) < 0) {
        fprintf(stderr, "Failed to read moisture sensor 2\n");
    }

    log_moisture_reading(timestamp, moisture1, moisture2);
}

