#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define GPIO_SHUTDOWN 17
#define MAX_RETRIES 3
#define FILE_NAME "current_log.csv"
#define HEADER "Timestamp,Amps\n"

static int spi_fd;
static int gpio_shutdown_fd;
static FILE *log_file;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line_shutdown;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(signum);
}

void log_current(double current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, current);
}

void check_error(int result, const char *message) {
    if (result < 0) {
        perror(message);
        exit(EXIT_FAILURE);
    }
}

int spi_transfer(unsigned char *tx, unsigned char *rx, int len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = ioctl(spi_fd, SPI_IOC_MESSAGE, 1, (void *)&tx);
        if (result >= 0) {
            return result;
        }
        retries++;
        usleep(100000); // Wait for 100ms before retrying
    }
    perror("SPI transfer failed");
    exit(EXIT_FAILURE);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    check_error(spi_fd, "Failed to open SPI device");

    // Set SPI mode and speed
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .pad = 0
    };
    unsigned char tx_data[] = {0x01, 0x80, 0x00}; // Start conversion
    unsigned char rx_data[3];
    int result = spi_transfer(tx_data, rx_data, 3);
    check_error(result, "Failed to start conversion");

    // Open GPIO for shutdown control
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    check_error(gpio_chip, "Failed to open GPIO chip");
    gpio_line_shutdown = gpiod_chip_get_line(gpio_chip, GPIO_SHUTDOWN);
    check_error(gpio_line_shutdown, "Failed to get GPIO line");
    result = gpiod_line_request_output(gpio_line_shutdown, "current_sensor", 0);
    check_error(result, "Failed to request GPIO line");

    // Open log file
    log_file = fopen(FILE_NAME, "a");
    if (log_file == NULL) {
        log_file = fopen(FILE_NAME, "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, HEADER);
    }

    // Main loop
    while (1) {
        // Read ADC value
        transfer.tx_buf = (unsigned long)tx;
        transfer.rx_buf = (unsigned long)rx;
        transfer.len = 3;
        result = spi_transfer(tx_data, rx_data, 3);
        check_error(result, "Failed to read ADC value");

        // Convert ADC value to current
        double current = (rx_data[1] << 8) | rx_data[2];
        current = current * 0.00001; // Convert to amperes

        // Log current
        log_current(current);

        // Check for over-current
        if (current > 10.0) {
            // Drive GPIO17 low to disable motor
            result = gpiod_line_set_value(gpio_line_shutdown, 0);
            check_error(result, "Failed to drive GPIO17 low");

            // Log over-current event
            log_current(current);
            printf("Over-current detected: %.2f A\n", current);

            // Wait one second
            sleep(1);

            // Drive GPIO17 high to re-enable motor
            result = gpiod_line_set_value(gpio_line_shutdown, 1);
            check_error(result, "Failed to drive GPIO17 high");
        }

        // Wait one second
        sleep(1);
    }

    // Close file descriptors and release GPIO lines
    fclose(log_file);
    gpiod_line_release(gpio_line_shutdown);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return 0;
}

