#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90817_ADDR 0x5A
#define MLX90817_REG_TEMP 0x00
#define MLX90817_REG_PRESSURE 0x01
#define MLX90817_REG_STATUS 0x02
#define MLX90817_STATUS_SENSOR_ABSENT 0x01

#define LOG_FILE "pressure_log.csv"
#define BUFFER_SIZE 1024

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    exit(0);
}

static void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    char buffer[BUFFER_SIZE];
    snprintf(buffer, BUFFER_SIZE, "%s,%f\n", timestamp, pressure);
    if (fwrite(buffer, 1, strlen(buffer), log_file) != strlen(buffer)) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    fflush(log_file);
}

static int read_sensor() {
    uint8_t reg = MLX90817_REG_TEMP;
    uint8_t data[2];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, reg, 2, data);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    double temp = (data[0] << 8) | data[1];
    temp = temp * 0.01; // Convert to Celsius

    reg = MLX90817_REG_PRESSURE;
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, reg, 2, data);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    double pressure = (data[0] << 8) | data[1];
    pressure = pressure * 0.01; // Convert to kPa

    return 0;
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        return 1;
