#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define PRESSURE_CHANNEL 0
#define NTC_CHANNEL 1
#define MAX_RETRIES 3
#define WARNING_LED_PIN 17
#define MAX_PRESSURE 105.0

static int gpiod_chip_fd = -1;
static int i2c_fd = -1;
static int warning_led_fd = -1;
static struct gpiod_line *warning_led_line = NULL;

static void handle_sigint(int signum) {
    if (warning_led_fd >= 0) {
        gpiod_line_release(warning_led_line);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpiod_chip_fd >= 0) {
        gpiod_chip_close(gpiod_chip_fd);
    }
    exit(0);
}

static int read_i2c_register(int reg) {
    int retries = 0;
    int result;
    do {
        result = i2c_smbus_read_word_data(i2c_fd, reg);
        if (result < 0) {
            perror("i2c_smbus_read_word_data");
            retries++;
        } else {
            return result;
        }
    } while (retries < MAX_RETRIES);
    fprintf(stderr, "Failed to read register 0x%02X\n", reg);
    return -1;
}

static int write_i2c_register(int reg, int value) {
    int retries = 0;
    int result;
    do {
        result = i2c_smbus_write_word_data(i2c_fd, reg, value);
        if (result < 0) {
            perror("i2c_smbus_write_word_data");
            retries++;
        } else {
            return result;
        }
    } while (retries < MAX_RETRIES);
    fprintf(stderr, "Failed to write register 0x%02X with value 0x%04X\n", reg, value);
    return -1;
}

static int read_pressure() {
    int pressure_raw = read_i2c_register(0x00);
    if (pressure_raw < 0) {
        return -1;
    }
    return pressure_raw * 0.01; // Convert to kPa
}

static int read_ntc_temperature() {
    int ntc_raw = read_i2c_register(0x02);
    if (ntc_raw < 0) {
        return -1;
    }
    // Convert NTC raw value to temperature using a known NTC curve
    // This is a placeholder for actual NTC curve conversion
    // Replace with actual conversion formula
    return 25.0; // Placeholder temperature in °C
}

static void set_warning_led(int state) {
    if (state) {
        gpiod_line_set_value(warning_led_line, 1);
    } else {
        gpiod_line_set_value(warning_led_line, 0);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip_fd < 0) {
        perror("gpiod_chip_open");
        exit(1);
    }

    warning_led_line = gpiod_line_request_output(gpiod_chip_fd, WARNING_LED_PIN, 0);
    if (warning_led_line == NULL) {
        perror("gpiod_line_request_output");
        exit(1);
    }

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }

    while (1) {
        int pressure = read_pressure();
        if (pressure < 0) {
            fprintf(stderr, "Failed to read pressure\n");
            continue;
        }

        int temperature = read_ntc_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Failed to read NTC temperature\n");
            continue;
        }

        set_warning_led(pressure > MAX_PRESSURE);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
        sleep(1);
    }

    return 0;
}

