#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define GPIO_SHUTDOWN 27
#define ADC_CHANNEL 0
#define MAX_CURRENT 10.0
#define LOG_FILE "current_log.txt"

static int spi_fd;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void sig_handler(int sig) {
    should_exit = 1;
}

static void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpio_close(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpio_unexport(GPIO_SHUTDOWN);
}

static int init_spi() {
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_MODE) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

static int init_gpio() {
    gpio_fd = gpio_open(GPIO_SHUTDOWN, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        return -1;
    }

    if (gpio_set_value(gpio_fd, 0) < 0) {
        perror("Failed to set GPIO value");
        gpio_close(gpio_fd);
        return -1;
    }

    return 0;
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4) | 0x01, 0x00};
    uint8_t rx[3];

    if (write(spi_fd, tx, 3) != 3) {
        perror("Failed to write to SPI");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("Failed to read from SPI");
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

static void log_current(float current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fclose(log_file);
}

static void check_current(float current) {
    if (current > MAX_CURRENT) {
        log_current(current);
        log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "OVERCURRENT\n");
            fclose(log_file);
        }
        gpio_set_value(gpio_fd, 1);
        sleep(1);
        gpio_set_value(gpio_fd, 0);
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main() {
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        float current = (float)adc_value * 5.0 / 1023.0 * 3.3 / 0.025;
        check_current(current);
        log_current(current);
    }

    cleanup();
    return EXIT_SUCCESS;
}

