    return (rx[1] << 8) | rx[2];
}

static void log_current(float current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fclose(log_file);
}

static void check_current(float current) {
    if (current > MAX_CURRENT) {
        log_current(current);
        log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "OVERCURRENT\n");
            fclose(log_file);
        }
        gpio_set_value(gpio_fd, 1);
        sleep(1);
        gpio_set_value(gpio_fd, 0);
        cleanup();
        exit(EXIT_FAILURE);
    }
}

int main() {
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        float current = (float)adc_value * 5.0 / 1023.0 * 3.3 / 0.025;
        check_current(current);
        log_current(current);
    }

    cleanup();
    return EXIT_SUCCESS;
}
