#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 5
#define LOG_FILE "co_log.txt"
#define ALARM_PIN 4
#define VOLTAGE_THRESHOLD 2.5

static int spi_fd;
static int alarm_pin_fd;
static FILE *log_file;
static int retries = 0;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(spi_fd);
        fclose(log_file);
        gpio_close(alarm_pin_fd);
        exit(EXIT_SUCCESS);
    }
}

static void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

static void log_data(const char *timestamp, float voltage) {
    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
}

static void setup_gpio() {
    int ret;

    // Set up alarm pin
    ret = gpiochip_open(0);
    if (ret < 0) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    alarm_pin_fd = ret;

    ret = gpio_direction_output(alarm_pin_fd, 0);
    if (ret < 0) {
        log_error("Failed to set alarm pin direction");
        gpiochip_close(alarm_pin_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_spi() {
    struct spi_ioc_transfer transfer;
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        log_error("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        log_error("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        log_error("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set up SPI transfer
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned char *)"\x01\x80";
    transfer.rx_buf = (unsigned char *)"\x00\x00";
    transfer.len = 4;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.delay_usecs = 0;
    transfer.cs_change = 1;

    // Perform SPI transfer
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
    if (ret < 0) {
        log_error("Failed to perform SPI transfer");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_sensor() {
    struct spi_ioc_transfer transfer;
    unsigned char buffer[3];
    int ret;
    float voltage;

    // Set up SPI transfer
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned char *)"\x01\x80";
    transfer.rx_buf = buffer;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.delay_usecs = 0;
    transfer.cs_change = 1;

    // Perform SPI transfer
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
    if (ret < 0) {
        log_error("Failed to perform SPI transfer");
        retries++;
        if (retries >= SPI_MAX_RETRIES) {
            gpio_set_value(alarm_pin_fd, 1);
            close(spi_fd);
            fclose(log_file);
            gpiochip_close(alarm_pin_fd);
            exit(EXIT_FAILURE);
        }
        sleep(1);
        return;
    }

    // Calculate voltage
    voltage = (buffer[1] << 8) | buffer[2];
    voltage = (voltage >> 4) * 0.125;

    // Log data
    log_data(strftime(NULL, sizeof(NULL), "%Y-%m-%d %H:%M:%S", NULL), voltage);

    // Drive alarm pin
    if (voltage > VOLTAGE_THRESHOLD) {
        gpio_set_value(alarm_pin_fd, 1);
    } else {
        gpio_set_value(alarm_pin_fd, 0);
    }
}

int main() {
    int ret;

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Set up GPIO
    setup_gpio();

    // Set up SPI
    setup_spi();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        close(spi_fd);
        gpiochip_close(alarm_pin_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        read_sensor();
        sleep(1);
    }

    // Close log file
    fclose(log_file);

    // Close SPI handle
    close(spi_fd);

    // Close GPIO handle
    gpiochip_close(alarm_pin_fd);

    return EXIT_SUCCESS;
}

