#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADC_CHANNEL 0
#define MAX_READS 100
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_RATE 1000 // Hz

static int gpiod_fd;
static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
}

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_adc() {
    // No specific initialization needed for ADS1115
}

void read_pressure() {
    uint16_t raw_value;
    int ret;

    // Start conversion
    ret = write(i2c_fd, "\x01\x80\x00", 3);
    if (ret < 0) {
        perror("Failed to start conversion");
        return;
    }

    // Wait for conversion to complete
    usleep(1000000 / SAMPLE_RATE);

    // Read conversion result
    ret = read(i2c_fd, &raw_value, 2);
    if (ret < 0) {
        perror("Failed to read conversion result");
        return;
    }

    // Convert raw value to pressure
    double pressure = (raw_value * 100.0) / 32767.0;
    if (pressure < 0 || pressure > 100000.0) {
        fprintf(stderr, "Invalid pressure reading: %.2f kPa\n", pressure);
        return;
    }

    log_pressure(pressure);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    gpiod_fd = gpiochip_open(0);
    if (gpiod_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    init_i2c();
    init_adc();

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiochip_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        read_pressure();
        usleep(1000000 / SAMPLE_RATE);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiochip_close(gpiod_fd);

    return 0;
}

