            perror("Failed to open log file");
            return;
        }
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%d\n", timestamp, temperature_celsius);
    fflush(log_file);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (open_spi_device() < 0) {
        return EXIT_FAILURE;
    }

    if (configure_spi_device() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    if (open_gpio_device() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    if (configure_gpio_device() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        int temperature_celsius = read_temperature();
        if (temperature_celsius >= 0) {
            log_temperature(temperature_celsius);
        }
        usleep(1000000); // 1 Hz
    }

    close_resources();
    return EXIT_SUCCESS;
}

