#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_CHANNEL_1 1
#define ADC_CHANNEL_2 2
#define ADC_MAX_VALUE 1023
#define IMPACT_THRESHOLD 1000
#define LOG_FILE "impact_log.txt"

static int spi_fd;
static int gpio_fd;
static int impact_detected = 0;

static void sigint_handler(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpio_fd = gpiod_chip_close(gpio_fd);
    }
    if (impact_detected) {
        fclose(stdout);
    }
    exit(signum);
}

static void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_request_output(line, "SPI_CS", 0);
    if (gpio_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void init_spi() {
    struct spi_ioc_transfer tr;
    unsigned char tx[3] = {0x01, 0x80 | ADC_CHANNEL, 0x00};
    unsigned char rx[3];

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tr) < 0) {
        perror("Failed to send SPI message");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (rx[0] != 0x01 || rx[1] != 0x80 | ADC_CHANNEL || rx[2] != 0x00) {
        fprintf(stderr, "Invalid SPI response\n");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_adc() {
    struct spi_ioc_transfer tr;
    unsigned char tx[3] = {0x01, 0x80 | ADC_CHANNEL, 0x00};
    unsigned char rx[3];
    int value;

    gpio_set_value(gpio_fd, 0); // CS low

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tr) < 0) {
        perror("Failed to send SPI message");
        gpio_set_value(gpio_fd, 1); // CS high
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    gpio_set_value(gpio_fd, 1); // CS high

    value = (rx[1] << 8) | rx[2];
    if (value < 0 || value > ADC_MAX_VALUE) {
        fprintf(stderr, "Invalid ADC value: %d\n", value);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    fprintf(stdout, "%lu,%d,%d,%d\n", time(NULL), value, value, value);
}

static void log_impact() {
    impact_detected = 1;
    fprintf(stdout, "IMPACT DETECTED\n");
}

int main() {
    signal(SIGINT, sigint_handler);
    init_gpio();
    init_spi();

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        gpio_fd = gpiod_chip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_adc();
        if (impact_detected) {
            log_impact();
        }
        usleep(10000); // 100 Hz sampling
    }

    fclose(log_file);
    close(spi_fd);
    gpio_fd = gpiod_chip_close(gpio_fd);

    return 0;
}

