#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define MEASURE_CMD 0x01
#define CRC_LENGTH 2
#define MAX_RETRIES 3
#define LOG_FILE "environmental_data.csv"

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_reading(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    exit(0);
}

int main() {
    int retries = 0;
    double temperature, pressure;
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;
    uint8_t buffer[8];

    // Initialize GPIO for LED
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        log_error("Failed to open GPIO chip");
        return 1;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, 17);
    if (!gpio_line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    gpiod_line_request_output(gpio_line, "LED", 0);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Write measurement command
    msgs[0].addr = I2C_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &MEASURE_CMD;
    msgs[1].addr = I2C_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 8;
    msgs[1].buf = buffer;
    data.msgs = msgs;
    data.nmsgs = 2;

    // Main loop
    while (1) {
        if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
            log_error("I2C read/write error");
            retries++;
            if (retries >= MAX_RETRIES) {
                log_error("Too many retries, exiting");
                close(i2c_fd);
                fclose(log_file);
                gpiod_line_release(gpio_line);
                gpiod_chip_close(gpio_chip);
                return 1;
            }
            sleep(5);
            continue;
        }

        // Apply calibration formulas
        uint16_t pressure_raw = (buffer[0] << 8) | buffer[1];
        uint16_t temperature_raw = (buffer[2] << 8) | buffer[3];
        uint16_t crc = (buffer[6] << 8) | buffer[7];
        uint16_t crc_calculated = (buffer[0] ^ buffer[1] ^ buffer[2] ^ buffer[3] ^ buffer[4] ^ buffer[5] ^ buffer[6] ^ buffer[7]) & 0xFF;
        if (crc != crc_calculated) {
            log_error("CRC mismatch");
            retries++;
            if (retries >= MAX_RETRIES) {
                log_error("Too many retries, exiting");
                close(i2c_fd);
                fclose(log_file);
                gpiod_line_release(gpio_line);
                gpiod_chip_close(gpio_chip);
                return 1;
            }
            sleep(5);
            continue;
        }

        // Convert raw ADC values to pressure and temperature
        double pressure_kpa = (pressure_raw * 100.0) / 32767.0;
        double temperature_celsius = (temperature_raw * 100.0) / 32767.0 - 40.0;

        // Log and display reading
        log_reading(temperature_celsius, pressure_kpa);
        printf("Temperature: %.2f°C, Pressure: %.2f kPa\n", temperature_celsius, pressure_kpa);

        // Toggle LED
        gpiod_line_set_value(gpio_line, 1);
        sleep(1);
        gpiod_line_set_value(gpio_line, 0);
        sleep(1);

        // Wait for 5 seconds
        sleep(5);
    }

    // Handle graceful shutdown
    close(i2c_fd);
    fclose(log_file);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    return 0;
}

