static int spi_fd;
static int gpio_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct timespec last_log_time;

void log_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, "\n");
}

void log_info(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stdout, fmt, args);
    va_end(args);
    fprintf(stdout, "\n");
}

void log_moisture(int moisture_percent) {
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, %d\n", timestamp, moisture_percent);
    fflush(log_file);
}

void send_email(int moisture_percent) {
    char email_body[256];
    snprintf(email_body, sizeof(email_body), "Moisture level is %d%%, please check the plant.", moisture_percent);
    FILE *msmtp = popen("msmtp -t", "w");
    if (!msmtp) {
        log_error("Failed to open msmtp process");
        return;
    }
    fprintf(msmtp, "To: %s\n", EMAIL_ADDRESS);
    fprintf(msmtp, "Subject: Plant Moisture Alert\n");
    fprintf(msmtp, "Content-Type: text/plain; charset=UTF-8\n\n");
    fprintf(msmtp, "%s\n", email_body);
    int status = pclose(msmtp);
    if (status != 0) {
        log_error("Failed to send email (msmtp exited with status %d)", status);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_info("Received signal %d, cleaning up", signum);
        if (log_file) {
            fclose(log_file);
        }
        if (spi_fd >= 0) {
            close(spi_fd);
        }
        if (gpio_fd >= 0) {
            gpiod_line_release(line);
            gpiod_chip_close(chip);
        }
        exit(0);
    }
}

int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4) | 0x01, 0x00};
    uint8_t rx[3];
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        log_error("Failed to send SPI message: %s", strerror(errno));
        return -1;
    }
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &rx);
    if (ret < 0) {
        log_error("Failed to receive SPI message: %s", strerror(errno));
        return -1;
    }
    return (rx[1] << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    if (argc != 10) {
        log_error("Usage: %s <spi_channel> <adc_channel> <min_calibration> <max_calibration> <moisture_threshold> <logging_interval> <email_address> <msmtphost_config>", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_calibration = atoi(argv[3]);
    int max_calibration = atoi(argv[4]);
    int moisture_threshold = atoi(argv[5]);
    int logging_interval = atoi(argv[6]);
    const char *email_address = argv[7];
    const char *msmtphost_config = argv[8];

    if (spi_channel < 0 || spi_channel > 3 || adc_channel < 0 || adc_channel > 7 || min_calibration < 0 || max_calibration > 1023 || moisture_threshold < 0 || logging_interval < 0) {
        log_error("Invalid argument values");
        return 1;
    }

    if (strcmp(email_address, "") == 0 || strcmp(msmtphost_config, "") == 0) {
        log_error("Email address and msmtp configuration file must be specified");
        return 1;
    }

    if (access(msmtphost_config, F_OK) != 0) {
        log_error("msmtp configuration file not found: %s", msmtphost_config);
        return 1;
    }

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        log_error("Failed to set signal handler for SIGINT");
        return 1;
    }

    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        log_error("Failed to set signal handler for SIGTERM");
        return 1;
    }

    if ((gpio_fd = open("/dev/gpiomem", O_RDWR)) < 0) {
        log_error("Failed to open /dev/gpiomem: %s", strerror(errno));
        return 1;
    }

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        log_error("Failed to open gpiochip0: %s", strerror(errno));
        close(gpio_fd);
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, 17)) == NULL) {
        log_error("Failed to get line 17: %s", strerror(errno));
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    if (gpiod_line_request_output(line, "LED", 0) < 0) {
        log_error("Failed to request line 17 as output: %s", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        log_error("Failed to open /dev/spidev0.0: %s", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0x00) < 0) {
        log_error("Failed to set SPI mode: %s", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        log_error("Failed to set SPI bits per word: %s", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 500000) < 0) {
        log_error("Failed to set SPI max speed: %s", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    if ((log_file = fopen("plant_data.txt", "a")) == NULL) {
        log_error("Failed to open plant_data.txt: %s", strerror(errno));
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(gpio_fd);
        return 1;
    }

    time(&last_log_time);
    while (1) {
        int moisture_percent = read_adc();
        if (moisture_percent < 0) {
            log_error("Failed to read ADC");
            continue;
        }

        if (moisture_percent < min_calibration || moisture_percent > max_calibration) {
            log_error("ADC value out of calibration range: %d", moisture_percent);
            continue;
        }

        if (moisture_percent < moisture_threshold) {
            send_email(moisture_percent);
        }

        log_moisture(moisture_percent);

        time_t now;
        time(&now);
        if (difftime(now, last_log_time) >= logging_interval) {
            last_log_time = now;
        }

        sleep(logging_interval);
    }

    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(gpio_fd);

    return 0;
}

