#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define MAX_LOG_LINE_LENGTH 256

static int spi_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void signal_handler(int signum) {
    should_exit = 1;
}

static void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

static void log_warning(const char *message) {
    fprintf(stderr, "Warning: %s\n", message);
}

static void log_moisture_reading(int adc_value, float moisture_percentage) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    char log_line[MAX_LOG_LINE_LENGTH];
    snprintf(log_line, sizeof(log_line), "%s, %d, %.2f\n", timestamp, adc_value, moisture_percentage);
    if (fprintf(log_file, "%s", log_line) < 0) {
        log_error("Failed to write to log file");
    }
}

static float calculate_moisture_percentage(int adc_value) {
    // Assuming the sensor's output is linear with moisture percentage
    // and the range is 0-1023 for 0-100% moisture
    return (float)adc_value / 1023.0 * 100.0;
}

static void read_soil_moisture() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t rx[3];

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tx) < 0) {
        log_error("Failed to send SPI message");
        return;
    }

    if (read(spi_fd, rx, 3) != 3) {
        log_error("Failed to read SPI data");
        return;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    float moisture_percentage = calculate_moisture_percentage(adc_value);

    log_moisture_reading(adc_value, moisture_percentage);
}

static void open_spi_device() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tr) < 0) {
        log_error("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void close_spi_device() {
    if (close(spi_fd) < 0) {
        log_error("Failed to close SPI device");
    }
}

static void open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void close_log_file() {
    if (fclose(log_file) < 0) {
        log_error("Failed to close log file");
    }
}

static void cleanup() {
    close_spi_device();
    close_log_file();
}

int main(int argc, char *argv[]) {
    if (argc > 2) {
        log_error("Usage: %s [interval_in_seconds]", argv[0]);
        exit(EXIT_FAILURE);
    }

    int interval = 1; // Default interval is 1 second
    if (argc == 2) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            log_error("Interval must be a positive integer");
            exit(EXIT_FAILURE);
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        log_error("Failed to set signal handler for SIGINT");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        log_error("Failed to set signal handler for SIGTERM");
        exit(EXIT_FAILURE);
    }

    open_spi_device();
    open_log_file();

    while (!should_exit) {
        read_soil_moisture();
        sleep(interval);
    }

    cleanup();
    return 0;
}

