    }

    miso_line = gpiod_chip_get_line(chip, GPIO_MISO);
    if (!miso_line) {
        perror("Failed to get GPIO MISO line");
        exit(EXIT_FAILURE);
    }

    sclk_line = gpiod_chip_get_line(chip, GPIO_SCLK);
    if (!sclk_line) {
        perror("Failed to get GPIO SCLK line");
        exit(EXIT_FAILURE);
    }

