        free(transfer.tx_buf);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    transfer.tx_buf[0] = 0b11000000 | (ADC_CHANNEL << 4); // Start bit, single-ended conversion, channel 0
    transfer.tx_buf[1] = 0; // Dummy byte
    transfer.tx_buf[2] = 0; // Dummy byte

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("Failed to send SPI message");
        free(transfer.tx_buf);
        free(transfer.rx_buf);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    free(transfer.tx_buf);
    free(transfer.rx_buf);
}

