        perror("Failed to allocate memory for SPI transfer buffer");
        return;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("Failed to receive SPI message");
        free(transfer.rx_buf);
        return;
    }

    int raw_value = (transfer.rx_buf[0] << 8) | transfer.rx_buf[1];
    float moisture_percentage = (raw_value / (1 << ADC_BITS)) * MOISTURE_PERCENTAGE_SCALE;

    printf("Raw ADC value: %d\n", raw_value);
    printf("Moisture percentage: %.2f%%\n", moisture_percentage);

    free(transfer.rx_buf);
}

