#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define GPIO_CE0 8
#define GPIO_SCLK 11
#define GPIO_MOSI 10
#define GPIO_MISO 9
#define ADC_CHANNEL 0
#define MAX_READINGS 10
#define LOG_FILE "soil_moisture.log"

static int spi_fd;
static int gpio_ce0;
static int gpio_sclk;
static int gpio_mosi;
static int gpio_miso;
static FILE *log_file;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(spi_fd);
        gpio_fd_close(gpio_ce0);
        gpio_fd_close(gpio_sclk);
        gpio_fd_close(gpio_mosi);
        gpio_fd_close(gpio_miso);
        fclose(log_file);
        printf("Program terminated.\n");
        exit(EXIT_SUCCESS);
    }
}

static void log_reading(int reading) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s: %d\n", timestamp, reading);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t rx[3] = {0, 0, 0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tx) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("read");
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        printf("ADC value stuck at 0 or 1023, assuming sensor absent or wiring fault.\n");
        return -1;
    }

    return adc_value;
}

int main() {
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if ((gpio_ce0 = gpiochip_open(0)) < 0) {
        perror("gpiochip_open");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

