#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define MOISTURE_SENSOR_CHANNEL 0
#define MOISTURE_SENSOR_MAX_VALUE 1023
#define MOISTURE_SENSOR_MIN_VALUE 0
#define MOISTURE_SENSOR_MAX_PERCENTAGE 100
#define MOISTURE_SENSOR_MIN_PERCENTAGE 0
#define LOG_INTERVAL 5

static int spi_fd = -1;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    struct spi_ioc_transfer transfer;
    uint8_t command[3] = {0x01, (MOISTURE_SENSOR_CHANNEL << 4), 0x00};
    uint8_t buffer[3];
    int moisture_percentage;
    struct sigaction sa;

    // Register signal handlers
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI channel
    if (ioctl(spi_fd, SPI_IOC_WR_CHANNEL, &SPI_CHANNEL) < 0) {
        perror("Failed to set SPI channel");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Perform SPI transfer
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)command;
    transfer.rx_buf = (unsigned long)buffer;
    transfer.len = sizeof(command);
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.cs_change = 1;

    while (!should_exit) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
            perror("Failed to perform SPI transfer");
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Calculate moisture percentage
        moisture_percentage = (buffer[1] << 8) | buffer[2];
        moisture_percentage = (moisture_percentage * MOISTURE_SENSOR_MAX_PERCENTAGE) / MOISTURE_SENSOR_MAX_VALUE;
        moisture_percentage = (moisture_percentage * MOISTURE_SENSOR_MIN_PERCENTAGE) / MOISTURE_SENSOR_MIN_VALUE;

        // Clamp moisture percentage to 0-100%
        moisture_percentage = (moisture_percentage < MOISTURE_SENSOR_MIN_PERCENTAGE) ? MOISTURE_SENSOR_MIN_PERCENTAGE : moisture_percentage;
        moisture_percentage = (moisture_percentage > MOISTURE_SENSOR_MAX_PERCENTAGE) ? MOISTURE_SENSOR_MAX_PERCENTAGE : moisture_percentage;

        // Log moisture percentage
        printf("Moisture percentage: %d%%\n", moisture_percentage);

        // Sleep for LOG_INTERVAL seconds
        sleep(LOG_INTERVAL);
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

