code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libmax30102.h>

#define MAX30102_I2C_ADDR 0x57
#define LOG_FILE "health_log.txt"
#define MAX_SAMPLES 100
#define MAX_SPO2 95
#define MAX_HR 100

static int i2c_fd;
static FILE *log_file;
static struct max30102 *sensor;
static struct timespec last_sample_time;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    if (log_file) {
        fprintf(log_file, "Error: %s\n", msg);
    }
}

void handle_sigint(int sig) {
    if (sensor) {
        max30102_close(sensor);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(1);
}

int main() {
    int ret;
    struct max30102_config config;
    struct max30102_data data;
    char part_id[4];
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize MAX30102
    ret = max30102_open(i2c_fd, MAX30102_I2C_ADDR, &sensor);
    if (ret < 0) {
        log_error("Failed to open MAX30102");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Read Part ID register
    ret = max30102_read_reg(sensor, MAX30102_REG_PART_ID, part_id, 4);
    if (ret < 0) {
        log_error("Failed to read Part ID register");
        max30102_close(sensor);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Check Part ID
    if (strncmp(part_id, "MAX30102", 8) != 0) {
        log_error("Invalid Part ID");
        max30102_close(sensor);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Configure MAX30102
    config.mode = MAX30102_MODE_SPO2;
    config.spo2_rate = MAX30102_SPO2_RATE_50;
    config.hr_rate = MAX30102_HR_RATE_50;
    config.spo2_led_current = MAX30102_SPO2_LED_CURRENT_100;
    config.hr_led_current = MAX30102_HR_LED_CURRENT_100;
    ret = max30102_set_config(sensor, &config);
    if (ret < 0) {
        log_error("Failed to set MAX30102 configuration");
        max30102_close(sensor);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Start continuous sampling
    ret = max30102_start_continuous(sensor);
    if (ret < 0) {
        log_error("Failed to start continuous sampling");
        max30102_close(sensor);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data
        ret = max30102_read_data(sensor, &data);
        if (ret < 0) {
            log_error("Failed to read data");
            continue;
        }

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &last_sample_time);

        // Check SpO2 and HR
        if (data.spo2 < MAX_SPO2 || data.hr > MAX_HR) {
            // Format timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&last_sample_time.tv_sec));

            // Write to log file
            fprintf(log_file, "%s: SpO2 %d, HR %d\n", timestamp, data.spo2, data.hr);
            fflush(log_file);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close MAX30102
    max30102_close(sensor);

    // Close I2C bus
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    return 0;
}

