    config.hr_led_current = MAX30102_HR_LED_CURRENT_100;
    ret = max30102_set_config(sensor, &config);
    if (ret < 0) {
        log_error("Failed to set MAX30102 configuration");
        max30102_close(sensor);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Start continuous sampling
    ret = max30102_start_continuous(sensor);
    if (ret < 0) {
        log_error("Failed to start continuous sampling");
        max30102_close(sensor);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read data
        ret = max30102_read_data(sensor, &data);
        if (ret < 0) {
            log_error("Failed to read data");
            continue;
        }

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &last_sample_time);

        // Check SpO2 and HR
        if (data.spo2 < MAX_SPO2 || data.hr > MAX_HR) {
            // Format timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&last_sample_time.tv_sec));

            // Write to log file
            fprintf(log_file, "%s: SpO2 %d, HR %d\n", timestamp, data.spo2, data.hr);
            fflush(log_file);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close MAX30102
    max30102_close(sensor);

    // Close I2C bus
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    return 0;
}
```

This C program uses the `libmax30102` library to interact with the MAX30102 pulse oximeter on the Raspberry Pi Zero W. It continuously monitors the sensor, checks for valid Part ID, and logs any readings below 95% SpO2 or above 100 BPM. The program handles SIGINT and SIGTERM by releasing the I2C handle and any driver resources before exiting.

