static int read_spi_channel(int channel) {
    int ret;
    uint8_t tx[3] = {0x01, (channel << 4) | 0x01, 0x00};
    uint8_t rx[3];

    for (int i = 0; i < SPI_MAX_RETRIES; i++) {
        ret = spi_i2c_read(spi_fd, tx, 3, rx, 3);
        if (ret == 0) {
            return (rx[1] << 8) | rx[2];
        } else {
            log_error("SPI read failed");
        }
    }
