#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define ADC_CHANNEL 0
#define BUZZER_PIN 24
#define THRESHOLD 500

static int spi_fd;
static int gpio_fd;
static int buzzer_state = 0;

static void handle_sigint(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpio_fd = gpiochip_close(gpio_fd);
    }
    printf("Exiting...\n");
    exit(0);
}

static int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_MODE) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_MODE) < 0) {
        perror("Failed to read bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set max speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to read max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

static int init_gpio() {
    gpio_fd = gpiochip_open(0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    int ret = gpio_claim_line(gpio_fd, BUZZER_PIN);
    if (ret < 0) {
        perror("Failed to claim GPIO line");
        gpiochip_close(gpio_fd);
        return -1;
    }

    return 0;
}

static int read_adc() {
    unsigned char tx[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    if (write(spi_fd, tx, 3) != 3) {
        perror("Failed to write to SPI");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("Failed to read from SPI");
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

static void set_buzzer(int state) {
    if (state == 0) {
        if (gpio_set_value(gpio_fd, BUZZER_PIN, 0) < 0) {
            perror("Failed to set GPIO low");
        }
    } else {
        if (gpio_set_value(gpio_fd, BUZZER_PIN, 1) < 0) {
            perror("Failed to set GPIO high");
        }
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        return 1;
    }

    while (1) {
        int adc_reading = read_adc();
        printf("ADC Reading: %d\n", adc_reading);

        if (adc_reading >= THRESHOLD) {
