This C program continuously monitors a GP2Y0A21YK0F Sharp IR distance sensor through an ADS1115 ADC on the I2C bus `/dev/i2c-1`. It samples the ADC every 200 ms after an initial calibration phase of ten baseline samples taken 50 ms apart. When the distance reading falls below a calibrated threshold, it energizes a 5 V relay module connected to GPIO17 (active-high) for exactly three seconds to release a door lock, then de-energizes it. The program logs events with a millisecond timestamp to `/var/log/door_events.log`. It handles I2C read failures, logs and continues if an I2C read fails (sensor absent), and on receipt of SIGINT or SIGTERM, it ensures the relay is de-energized, releases all resources, closes the I2C file descriptor, and exits cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define CS0 8
#define CS1 7
#define CS2 25
#define NUM_SENSORS 3
#define FILE_NAME "soil_moisture_log.csv"
#define HEADER "timestamp,sensor1,sensor2,sensor3\n"

static int spi_fd;
static struct gpiod_chip *cs_chip;
static struct gpiod_line *cs_lines[NUM_SENSORS];

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(spi_fd);
        gpiod_chip_close(cs_chip);
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_release(cs_lines[i]);
        }
        printf("Program terminated gracefully.\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int ret;
    struct spi_ioc_transfer xfer[NUM_SENSORS];
    uint8_t tx_data[NUM_SENSORS] = {0x01, 0x80, 0x01, 0x80, 0x01, 0x80};
    uint8_t rx_data[NUM_SENSORS] = {0, 0, 0, 0, 0, 0};
    struct timespec ts;
    char timestamp[20];
    FILE *file;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI speed and mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO chip for chip-select lines
    cs_chip = gpiod_chip_open("/dev/gpiochip0");
    if (cs_chip == NULL) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(cs_chip, i + CS0);
        if (cs_lines[i] == NULL) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(cs_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_request_output(cs_lines[i], "spi_cs", 0);
        if (ret < 0) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(cs_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Open or create the CSV file
    file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open CSV file");
        gpiod_chip_close(cs_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Write header if the file is newly created
    if (fseek(file, 0, SEEK_END) == 0) {
        fseek(file, 0, SEEK_SET);
        if (fwrite(HEADER, 1, strlen(HEADER), file) != strlen(HEADER)) {
            perror("Failed to write header to CSV file");
            fclose(file);
            gpiod_chip_close(cs_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Read ADC values every 5 seconds
    while (1) {
        // Set chip-select lines
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_set_value(cs_lines[i], 0);
        }

        // Perform SPI transfers
        for (int i = 0; i < NUM_SENSORS; i++) {
            xfer[i].tx_buf = (unsigned long)&tx_data[i * 2];
            xfer[i].rx_buf = (unsigned long)&rx_data[i * 2];
            xfer[i].len = 2;
            xfer[i].speed_hz = SPI_SPEED_HZ;
            xfer[i].delay_usecs = 0;
            xfer[i].bits_per_word = 8;
            xfer[i].cs_change = 1;
        }

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &xfer);
        if (ret < 0) {
            perror("Failed to perform SPI message");
            fclose(file);
            gpiod_chip_close(cs_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Reset chip-select lines
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_set_value(cs_lines[i], 1);
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write data to CSV file
        fprintf(file, "%s,%d,%d,%d\n", timestamp, rx_data[0], rx_data[2], rx_data[4]);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close file and release resources
    fclose(file);
    gpiod_chip_close(cs_chip);
    close(spi_fd);

    return 0;
}

