#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 3
#define LOG_FILE "irrigation.log"
#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

static int spi_fd = -1;
static int relay_fd = -1;
static int threshold = DEFAULT_THRESHOLD;
static int pump_duration = DEFAULT_PUMP_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static int running = 1;

static void log_message(const char *message) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s - %s\n", buffer, message);
    fclose(file);
}

static void handle_signal(int signum) {
    running = 0;
    if (relay_fd != -1) {
        gpio_set_value(relay_fd, 0);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (relay_fd != -1) {
        gpio_close(relay_fd);
    }
    exit(EXIT_SUCCESS);
}

static void setup_gpio() {
    int ret;

    relay_fd = gpiochip_open("gpiochip0");
    if (relay_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpio_claim_line(relay_fd, 18);
    if (ret < 0) {
        perror("Failed to claim GPIO line 18");
        gpio_close(relay_fd);
        exit(EXIT_FAILURE);
    }

    gpio_set_value(relay_fd, 0);
}

static void setup_spi() {
    struct spi_ioc_transfer transfer;
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned char *)"\x01\x00"; // Start conversion
    transfer.rx_buf = (unsigned char *)"\x00\x00";
    transfer.len = 4;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
    if (ret < 0) {
        perror("Failed to send SPI message");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static int read_adc() {
    struct spi_ioc_transfer transfer;
    unsigned char buffer[4];
    int ret;
    int retries = 0;

    while (retries < SPI_MAX_RETRIES) {
        memset(&transfer, 0, sizeof(transfer));
        transfer.tx_buf = (unsigned char *)"\x01\x00"; // Start conversion
        transfer.rx_buf = buffer;
        transfer.len = 4;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
        if (ret < 0) {
            perror("Failed to send SPI message");
            retries++;
            continue;
        }

        // Convert ADC value to percentage
        int adc_value = (buffer[1] << 8) | buffer[0];
        int percentage = (adc_value * 100) / 1023;

        log_message(f"ADC reading: {percentage}%");

        if (percentage < threshold) {
            log_message("Moisture level below threshold, activating pump");
            gpio_set_value(relay_fd, 1);
            sleep(pump_duration);
            gpio_set_value(relay_fd, 0);
            log_message("Pump deactivated");
        }

        break;
    }

    if (retries == SPI_MAX_RETRIES) {
        log_message("Failed to read ADC after all retries, skipping irrigation cycle");
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_spi();

    while (running) {
        read_adc();
        sleep(sleep_interval);
    }

    close(spi_fd);
    gpio_close(relay_fd);

    return EXIT_SUCCESS;
}

