```

This C program sets up a Raspberry Pi 4 Model B to continuously monitor the moisture level of a soil sensor connected to an MCP3008 ADC on SPI0. It compares the sensor reading to a configurable threshold and activates a relay-driven water pump if the moisture level falls below the threshold. The program logs every moisture reading and each pump activation or deactivation with timestamps to a file named `irrigation.log`. It handles SPI communication errors by retrying up to three times per read and logs the error if all retries fail. The program also handles SIGINT and SIGTERM signals to ensure the pump is turned off, close the SPI interface, terminate any driver usage, and exit cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <syslog.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 10
#define ADC_CHANNEL 0
#define THRESHOLD 1000 // Adjust this threshold as needed
#define LOG_FILE "/var/log/sound_events.log"

static int spi_fd;
static int gpio_fd;
static int log_fd;
static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    running = 0;
    close(spi_fd);
    close(gpio_fd);
    close(log_fd);
    syslog(LOG_INFO, "Program terminated by signal %d", sig);
    closelog();
    exit(EXIT_SUCCESS);
}

static void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line 8");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_request_output(line, "sound_event_logger", 0);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line 8 as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

static void init_spi() {
    struct spi_ioc_transfer tr;
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device %s", SPI_DEVICE);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)0x00000000; // Start command
    tr.rx_buf = (unsigned long)0x00000000;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.delay_usecs = 0;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to send SPI message");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_log() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        exit(EXIT_FAILURE);
    }
}

static int read_adc() {
    struct spi_ioc_transfer tr;
    unsigned char tx[3] = {0x00, 0x00, 0x00};
    unsigned char rx[3];
    int ret;

    tx[0] = 0x01; // Start command
    tx[1] = (ADC_CHANNEL << 4) | 0x01; // Select channel 0 and start conversion

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.delay_usecs = 0;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to send SPI message");
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

static void log_peak(int value) {
    struct tm *tm;
    char timestamp[20];
    char log_entry[100];

    time_t now = time(NULL);
    tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    snprintf(log_entry, sizeof(log_entry), "%s %d\n", timestamp, value);
    write(log_fd, log_entry, strlen(log_entry));
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    init_gpio();
    init_spi();
    init_log();

    syslog(LOG_INFO, "Sound event logger started");

    while (running) {
        int value = read_adc();
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read ADC");
            continue;
        }

        if (value > THRESHOLD) {
            log_peak(value);
        }

        usleep(10000); // 10 ms interval
    }

    close(spi_fd);
    close(gpio_fd);
    close(log_fd);
    syslog(LOG_INFO, "Program terminated");
    closelog();

    return EXIT_SUCCESS;
}

