    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device %s", SPI_DEVICE);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)0x00000000; // Start command
    tr.rx_buf = (unsigned long)0x00000000;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.delay_usecs = 0;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to send SPI message");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_log() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file %s", LOG_FILE);
        exit(EXIT_FAILURE);
    }
}

static int read_adc() {
    struct spi_ioc_transfer tr;
    unsigned char tx[3] = {0x00, 0x00, 0x00};
    unsigned char rx[3];
    int ret;

    tx[0] = 0x01; // Start command
    tx[1] = (ADC_CHANNEL << 4) | 0x01; // Select channel 0 and start conversion

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.delay_usecs = 0;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to send SPI message");
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

static void log_peak(int value) {
    struct tm *tm;
    char timestamp[20];
    char log_entry[100];

    time_t now = time(NULL);
    tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    snprintf(log_entry, sizeof(log_entry), "%s %d\n", timestamp, value);
    write(log_fd, log_entry, strlen(log_entry));
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    init_gpio();
    init_spi();
    init_log();

    syslog(LOG_INFO, "Sound event logger started");

    while (running) {
        int value = read_adc();
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read ADC");
            continue;
        }

        if (value > THRESHOLD) {
            log_peak(value);
        }

        usleep(10000); // 10 ms interval
    }

    close(spi_fd);
    close(gpio_fd);
    close(log_fd);
    syslog(LOG_INFO, "Program terminated");
    closelog();

    return EXIT_SUCCESS;
}
