#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADC_CHANNEL 0
#define SAMPLE_RATE 1000
#define THRESHOLD_GAUS 500
#define GPIO_PIN 27
#define BUFFER_SIZE 10
#define LOG_FILE "/var/log/hall_sensor.log"

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_fd = -1;
static int buffer_index = 0;
static int buffer[BUFFER_SIZE];
static int running = 1;

static void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_INFO, format, args);
    va_end(args);
}

static void handle_signal(int signum) {
    running = 0;
    if (gpiod_line != -1) {
        gpiod_line_release(gpiod_chip, gpiod_line);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    closelog();
    exit(0);
}

static void init_gpio() {
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        log_message("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (gpiod_line == -1) {
        log_message("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    int flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_line_request_output(gpiod_line, "hall_sensor", flags);
    if (ret != 0) {
        log_message("Failed to request GPIO line");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        log_message("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    int ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret == -1) {
        log_message("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_adc() {
    // Set up the ADC configuration
    uint8_t config = 0x00; // Continuous conversion, single-ended, AIN0, 12-bit resolution
    config |= (1 << 7); // Start conversion
    config |= (1 << 5); // Single-ended mode
    config |= (0 << 4); // AIN0
    config |= (0 << 3); // 12-bit resolution
    config |= (0 << 2); // Continuous conversion
    config |= (0 << 1); // Disable comparator
    config |= (0 << 0); // Disable power-down

    if (write(i2c_fd, &config, 1) != 1) {
        log_message("Failed to write ADC configuration");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_adc() {
    uint8_t reg = 0x01; // ADC conversion register
    uint8_t data[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        log_message("Failed to write ADC register");
        return;
    }

    if (read(i2c_fd, data, 2) != 2) {
        log_message("Failed to read ADC data");
        return;
    }

    int adc_value = (data[0] << 8) | data[1];
    float voltage = adc_value * 3.3 / 4095.0;

    if (voltage < 0 || voltage > 3.3) {
        log_message("ADC voltage out of range");
        return;
    }

    // Convert voltage to magnetic field strength
    float gauss = voltage * 1000; // Assuming 1V = 1000 Gauss

    // Store in circular buffer
    buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Calculate rolling average
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    float average = sum / BUFFER_SIZE;

    // Check if threshold is exceeded
    if (average > THRESHOLD_GAUS) {
        log_message("Threshold exceeded: %.2f Gauss", average);
        gpiod_line_set_value(gpiod_chip, gpiod_line, 1);
    }
}

int main() {
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();
    init_adc();

    while (running) {
        read_adc();
        usleep(1000000 / SAMPLE_RATE); // 1 Hz sample rate
    }

    gpiod_line_set_value(gpiod_chip, gpiod_line, 0);
    close(i2c_fd);
    gpiod_line_release(gpiod_chip, gpiod_line);
    gpiod_chip_close(gpiod_chip);
    closelog();

    return 0;
}

