#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define THRESHOLD 300
#define LOG_FILE "watering_events.txt"
#define GPIO_PIN 18

static int spi_fd;
static int gpio_fd;
static int pump_active = 0;
static FILE *log_file;

void handle_signal(int sig) {
    if (pump_active) {
        gpio_set_value(gpio_fd, GPIO_PIN, 0);
        pump_active = 0;
    }
    fclose(log_file);
    close(spi_fd);
    close(gpio_fd);
    exit(0);
}

int main() {
