#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 3

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *ce0;

void handle_sigint(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    struct spi_ioc_transfer transfer;
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start conversion, single-ended, channel 0
    uint8_t rx[3];
    uint16_t adc_value;
    double intensity;
    struct timespec ts;

    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    // Initialize gpiod library
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request CE0 line
    ce0 = gpiod_chip_get_line(chip, 25); // GPIO25 is CE0 on Raspberry Pi 4
    if (!ce0) {
        perror("Failed to get CE0 line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request CE0 line as output
    ret = gpiod_line_request_output(ce0, "rain_sensor", 0);
    if (ret) {
        perror("Failed to request CE0 line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(ce0);
        exit(EXIT_FAILURE);
    }

    // Set CE0 line high
    ret = gpiod_line_set_value(ce0, 1);
    if (ret) {
        perror("Failed to set CE0 line high");
        gpiod_chip_close(chip);
        gpiod_line_release(ce0);
        exit(EXIT_FAILURE);
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        gpiod_line_release(ce0);
        exit(EXIT_FAILURE);
    }

    // Set SPI mode, speed, and bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(ce0);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(ce0);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(ce0);
        exit(EXIT_FAILURE);
    }

    // Perform SPI transfer
    while (1) {
        for (int i = 0; i < SPI_MAX_RETRIES; i++) {
            memset(&transfer, 0, sizeof(transfer));
            transfer.tx_buf = (unsigned long)tx;
            transfer.rx_buf = (unsigned long)rx;
            transfer.len = 3;

            ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
            if (ret < 0) {
                perror("SPI transfer failed");
                continue;
            }

            // Extract ADC value from received data
            adc_value = (rx[1] << 8) | rx[2];

            // Calculate rainfall intensity
            intensity = (adc_value / 1023.0) * 100.0; // Assuming 100% intensity at 1023

            // Get current time
            clock_gettime(CLOCK_REALTIME, &ts);

            // Log data to stdout
            printf("%ld.%09ld, %d, %.2f\n", ts.tv_sec, ts.tv_nsec, adc_value, intensity);

            // Sleep for 1 second
            sleep(1);

            break;
        }
    }

    // Close SPI device
    close(spi_fd);

    // Release CE0 line
    gpiod_line_release(ce0);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

