To accomplish the task of monitoring a Honeywell SS49E linear Hall-effect sensor using an ADS1115 ADC on a Raspberry Pi 4 Model B, we will use the `libgpiod` library for GPIO control and the `libi2c-dev` library for I2C communication. Below is a complete C program that fulfills the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADC_REG_CONFIG 0x01
#define ADC_REG_CONVERSION 0x00
#define ADC_GAIN_4_096 0x04
#define ADC_SINGLE_ENDED_AIN0 0x00
#define LED_PIN 17
#define DEFAULT_THRESHOLD 100.0

static int i2c_fd;
static int led_fd;
static int threshold = DEFAULT_THRESHOLD;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
    if (led_fd >= 0) {
        gpio_set_value(led_fd, 0);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_fd >= 0) {
        gpio_close(led_fd);
    }
    exit(EXIT_SUCCESS);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    const char *gpiochip = "gpiochip0";
    const char *gpio_name = "gpio17";
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(gpiochip);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, gpio_name);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led_fd = gpiod_line_request_output(line, "hall_sensor", 0);
    if (led_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void set_adc_config() {
    uint8_t config = ADC_GAIN_4_096 | ADC_SINGLE_ENDED_AIN0;
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write ADC configuration");
        exit(EXIT_FAILURE);
    }
}

void read_adc() {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read ADC data");
        exit(EXIT_FAILURE);
    }
    int16_t adc_value = (data[0] << 8) | data[1];
    float voltage = adc_value * 4.096 / 32768.0;
    float gauss = voltage * 100.0; // Assuming 100 Gauss per volt
    printf("Magnetic field strength: %.2f Gauss\n", gauss);
}

