#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <pigpio.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_CHANNEL 0
#define GPIO_PIN_MOISTURE 8
#define GPIO_PIN_RELAY 17
#define MQTT_TOPIC "soil_moisture"
#define MQTT_COMMAND_TOPIC "pump_control"
#define HYSTERESIS_LOW 30
#define HYSTERESIS_HIGH 35
#define LOG_LEVEL LOG_INFO

static int spi_fd;
static int gpio_moisture;
static int gpio_relay;
static int mqtt_client;
static int mqtt_subscribed;
static int pump_state = 0;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        syslog(LOG_LEVEL, "Received signal %d, cleaning up and exiting", signum);
        gpio_write(gpio_relay, 0); // Turn off the relay
        gpio_close(gpio_moisture);
        gpio_close(gpio_relay);
        close(spi_fd);
        if (mqtt_client != -1) {
            mqtt_unsubscribe(mqtt_client, MQTT_COMMAND_TOPIC);
            mqtt_disconnect(mqtt_client);
        }
        exit(EXIT_SUCCESS);
    }
}

static void log_event(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_LEVEL, format, args);
    va_end(args);
}

static int read_moisture() {
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start conversion, single-ended, channel 0
    uint8_t rx[3];
    int ret;

    ret = spi_xfer(spi_fd, tx, rx, 3);
    if (ret < 0) {
        log_event("SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    int moisture = (rx[1] << 8) | rx[2];
    moisture = (moisture >> 4) & 0x3FF; // Convert 10-bit ADC value to 0-100%
    return moisture;
}

static void publish_moisture(int moisture) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%d", moisture);
