#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_CS 8
#define SPI_CHANNEL 0
#define SPI_DELAY_USEC 0
#define SPI_MAX_RETRIES 10

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;

void handle_sigint(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    exit(signum);
}

int main() {
    int ret;
    struct spi_ioc_transfer transfer;
    uint8_t tx[2] = {0x01, 0x80}; // Start bit, channel 0, single-ended
    uint8_t rx[2];
    double voltage;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request CS line
    cs_line = gpiod_chip_get_line(chip, SPI_CS);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request output mode for CS line
    ret = gpiod_line_request_output(cs_line, "spi_cs", 0);
    if (ret < 0) {
        perror("Failed to request output mode for CS line");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set CS line high
    ret = gpiod_line_set_value(cs_line, 1);
    if (ret < 0) {
        perror("Failed to set CS line high");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Perform SPI transfer
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = 2;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.delay_usecs = SPI_DELAY_USEC;
    transfer.bits_per_word = SPI_BITS_PER_WORD;

    while (1) {
        // Set CS line low
        ret = gpiod_line_set_value(cs_line, 0);
        if (ret < 0) {
            perror("Failed to set CS line low");
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Perform SPI transfer
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            gpiod_line_set_value(cs_line, 1);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Set CS line high
        ret = gpiod_line_set_value(cs_line, 1);
        if (ret < 0) {
            perror("Failed to set CS line high");
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Calculate voltage
        voltage = (rx[0] << 8) | rx[1];
        voltage = voltage * 3.3 / 1023.0;

        // Print raw value and voltage
        printf("Raw value: %d, Voltage: %.3f V\n", voltage, voltage);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

