#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define ADC_CHANNEL 0
#define VIBRATION_PIN_1 17
#define VIBRATION_PIN_2 27
#define VIBRATION_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"
#define LOG_FORMAT "%s, %d\n"

static int spi_fd;
static int gpio_fd1, gpio_fd2;
static int vibration_state1 = 0;
static int vibration_state2 = 0;
static FILE *log_file;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Stop both motors
        gpio_set_value(gpio_fd1, 0);
        gpio_set_value(gpio_fd2, 0);
        // Close the SPI device
        close(spi_fd);
        // Close the GPIO files
        gpio_close(gpio_fd1);
        gpio_close(gpio_fd2);
        // Close the log file
        fclose(log_file);
        // Terminate the program
        exit(EXIT_SUCCESS);
    }
}

static void log_vibration_event(const char *timestamp) {
    if (log_file == NULL) {
        return;
    }
    fprintf(log_file, LOG_FORMAT, timestamp, vibration_state1 + vibration_state2);
    fflush(log_file);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t rx[3];
    int ret;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    ret = read(spi_fd, rx, 3);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

static void set_pwm(int gpio, int duty_cycle) {
    int ret;

    ret = gpio_set_value(gpio, 1);
    if (ret < 0) {
        perror("gpio_set_value");
        return;
    }

    ret = gpio_set_pwm_duty_cycle(gpio, duty_cycle);
    if (ret < 0) {
        perror("gpio_set_pwm_duty_cycle");
        gpio_set_value(gpio, 0);
        return;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    struct timespec ts;
    char timestamp[20];
    int adc_value;
    int duty_cycle = 500; // 50% duty cycle

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Set SPI speed and mode
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO files
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    line1 = gpiod_chip_get_line(chip, VIBRATION_PIN_1);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    line2 = gpiod_chip_get_line(chip, VIBRATION_PIN_2);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    gpio_fd1 = gpiod_line_request_output(line1, "vibration_motor1", 0);
    if (gpio_fd1 < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }
    gpio_fd2 = gpiod_line_request_output(line2, "vibration_motor2", 0);
    if (gpio_fd2 < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = read_adc();
        if (adc_value < 0) {
            // Skip this iteration if ADC read fails
            continue;
        }

        // Determine vibration state
        if (adc_value > VIBRATION_THRESHOLD) {
            vibration_state1 = 1;
            vibration_state2 = 1;
        } else {
            vibration_state1 = 0;
            vibration_state2 = 0;
        }

        // Set PWM duty cycle
        set_pwm(VIBRATION_PIN_1, duty_cycle);
        set_pwm(VIBRATION_PIN_2, duty_cycle);

        // Log vibration event
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        log_vibration_event(timestamp);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Close log file
    fclose(log_file);
    // Close GPIO files
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    // Close the SPI device
    close(spi_fd);
    // Close the GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

