#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 3
#define MOISTURE_THRESHOLD 30
#define RELAY_PIN 17

static int spi_fd;
static int relay_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        gpiochip_close(chip);
        close(spi_fd);
        close(relay_fd);
        exit(EXIT_SUCCESS);
    }
}

static void setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(relay_line, "water_pump", 0);
    if (ret) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(chip);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiod_chip_close(chip);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        close(relay_fd);
        exit(EXIT_FAILURE);
    }
}

static int read_moisture() {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int retries = SPI_MAX_RETRIES;

    while (retries--) {
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
        if (ret < 0) {
            perror("Failed to send SPI message");
            return -1;
        }

        if (rx[0] == 0x01 && rx[1] == 0x80 && rx[2] == 0x00) {
            return (rx[1] << 8) | rx[2];
        }
    }

    perror("Failed to read moisture sensor");
    return -1;
}

static void pump_water() {
    int ret = gpiod_line_set_value(relay_line, 1);
    if (ret) {
        perror("Failed to turn on water pump");
    }
}

static void stop_pump() {
    int ret = gpiod_line_set_value(relay_line, 0);
    if (ret) {
        perror("Failed to turn off water pump");
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    setup_gpio();
    setup_spi();

    while (1) {
        int moisture = read_moisture();
        if (moisture < 0) {
            perror("Failed to read moisture sensor");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        printf("%s: Moisture: %d%%\n", timestamp, moisture);

        if (moisture < MOISTURE_THRESHOLD) {
            pump_water();
        } else {
            stop_pump();
        }

        sleep(60);
    }

    stop_pump();
    gpiochip_close(chip);
    close(spi_fd);
    close(relay_fd);

    return 0;
}

