This C program continuously monitors an MQ-135 air quality sensor through an MCP3008 ADC connected on SPI0 CE0 using mode 0 at 1 MHz. It reads the sensor voltage on MCP3008 channel 0 every 5 seconds, converts the ADC value to an estimated CO₂ concentration, and activates a ventilation fan attached to GPIO18 (BCM numbering) whenever the estimated CO₂ exceeds 700 ppm. Each sample is logged to a file named `air_quality.log` in CSV format. The program handles SPI communication errors, logs them, and retries without crashing. It also handles SIGINT and SIGTERM by turning the fan off, closing the SPI interface, and releasing all driver resources before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define RELAY_PIN 17
#define DEBOUNCE_DELAY 1000000 // 1 second in microseconds
#define LOG_FILE "door_events.log"
#define MAX_LOG_SIZE 1024 * 1024 // 1 MB

static int spi_fd;
static int gpio_fd;
static int log_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct timespec start_time;

void log_event(const char *message) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_fd, "%s - %s\n", buffer, message);
    fflush(log_fd);
}

void handle_sigint(int signum) {
    close(spi_fd);
    close(gpio_fd);
    close(log_fd);
    gpiod_chip_close(chip);
    fclose(log_fd);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    int ret;
    uint8_t spi_buf[2];
    uint16_t adc_value;
    uint32_t distance;
    struct timespec current_time;
    struct timespec elapsed_time;
    uint32_t last_distance = 0;
    uint32_t debounce_timer = 0;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO line for relay
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request output mode for relay
    ret = gpiod_line_request_output(relay_line, "door_sensor", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line output");
        gpiod_chip_close(chip);
        close(spi_fd);
        gpiod_line_release(relay_line);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        close(spi_fd);
        gpiod_line_release(relay_line);
        exit(EXIT_FAILURE);
    }

    // Start logging
    log_event("Door sensor started");

    while (1) {
        // Read ADC value
        spi_buf[0] = 0x40 | (ADC_CHANNEL << 4);
        spi_buf[1] = 0x00;
        ret = write(spi_fd, spi_buf, 2);
        if (ret < 0) {
            perror("Failed to write to SPI device");
            break;
        }
        ret = read(spi_fd, spi_buf, 2);
        if (ret < 0) {
            perror("Failed to read from SPI device");
            break;
        }
        adc_value = (spi_buf[0] << 8) | spi_buf[1];

        // Convert ADC value to distance
        distance = (adc_value * 100) / 1024;

        // Check if distance is below 20 cm
        if (distance < 20 && distance != last_distance) {
            // Start debounce timer
            debounce_timer = 1;

            // Energize relay
            gpiod_line_set_value(relay_line, 1);

            // Log event
            log_event("Door opened");
        }

        // Check debounce timer
        if (debounce_timer > 0) {
            ret = clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (ret < 0) {
                perror("Failed to get current time");
                break;
            }
            elapsed_time = timespec_diff(&current_time, &start_time);
            if (elapsed_time.tv_nsec >= DEBOUNCE_DELAY) {
                debounce_timer = 0;
                gpiod_line_set_value(relay_line, 0);
            }
        }

        // Wait for 100 ms
        usleep(100000);

        // Update last distance
        last_distance = distance;
    }

    // Clean up
    close(spi_fd);
    close(gpio_fd);
    close(log_fd);
    gpiod_chip_close(chip);
    fclose(log_fd);
    printf("Door sensor stopped\n");

    return 0;
}

struct timespec timespec_diff(struct timespec *a, struct timespec *b) {
    struct timespec diff;
    diff.tv_sec = a->tv_sec - b->tv_sec;
    diff.tv_nsec = a->tv_nsec - b->tv_nsec;
    if (diff.tv_nsec < 0) {
        diff.tv_sec--;
        diff.tv_nsec += 1000000000;
    }
    return diff;
}

