        printf("Failed to open calibration file %s\n", CONFIG_FILE);
        return;
    }
    fprintf(file, "%d %d\n", calibration_distance, calibration_volume);
    fclose(file);
    printf("Saved calibration: distance = %d, volume = %d\n", calibration_distance, calibration_volume);
