#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOG_FILE "alcohol_log.txt"
#define MAX_BUFFER_SIZE 256

static int spi_fd;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void sig_handler(int signum) {
    should_exit = 1;
}

static void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

static void log_message(const char *msg) {
    fprintf(log_file, "%s\n", msg);
}

static void log_timestamped_message(const char *msg) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
    log_message(timestamp);
    log_message(msg);
}

static void log_sensor_absent() {
    log_message("Sensor absent.");
}

static void log_adc_error() {
    log_message("ADC read error.");
}

static void log_exit() {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpio_close(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t rx[3];
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = spi_read(spi_fd, tx, 3);
        if (ret < 0) {
            log_error("SPI read error");
            sleep(RETRY_DELAY_MS / 1000);
            retries++;
            continue;
        }
        if (tx[0] != 0x01 || tx[1] != (ADC_CHANNEL << 4) || tx[2] != 0x00) {
            log_error("Invalid SPI response");
            sleep(RETRY_DELAY_MS / 1000);
            retries++;
            continue;
        }
        return (rx[1] << 8) | rx[2];
    }
    log_adc_error();
    return -1;
}

static void check_sensor_absent(int adc_value) {
    if (adc_value == 0 || adc_value == 1023) {
        log_sensor_absent();
        log_exit();
    }
}

static void classify_reading(int adc_value) {
    if (adc_value > 50000) {
        log_timestamped_message("Alcohol detected! Limit exceeded.");
    } else if (adc_value < 20000) {
        log_timestamped_message("Sobriety confirmed.");
    } else {
        log_timestamped_message("Alcohol level within acceptable range.");
    }
}

int main() {
    struct spi_ioc_transfer tr;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        log_exit();
    }

    // Set SPI mode and speed
    tr.tx_buf = (unsigned long)&tx;
    tr.rx_buf = (unsigned long)&rx;
    tr.len = 3;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.cs_change = 1;
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        log_error("Failed to set SPI mode and speed");
        log_exit();
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        log_exit();
    }

    // Request line for SPI CE0
    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        log_exit();
    }

    // Request output mode for SPI CE0
    ret = gpiod_line_request_output(line, "spi_ce0", 0);
    if (ret < 0) {
        log_error("Failed to request GPIO line output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        log_exit();
    }

    // Set SPI CE0 high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        log_error("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        log_exit();
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        log_exit();
    }

    // Main loop
    while (!should_exit) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }
        check_sensor_absent(adc_value);
        classify_reading(adc_value);
        sleep(1);
    }

    // Graceful shutdown
    log_exit();
}

