#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define GPIO_RELAY 18

static int spi_fd;
static int gpio_fd;
static int log_fd;
static int pump_status = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        pump_status = 0;
        close(spi_fd);
        close(log_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for relay
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "irrigation", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read from MCP3008
        uint8_t tx[3] = {0x01, (MCP3008_CHANNEL << 4), 0x00};
        uint8_t rx[3] = {0, 0, 0};

        if (write(spi_fd, tx, 3) != 3) {
            perror("Failed to write to SPI");
            continue;
        }

        if (read(spi_fd, rx, 3) != 3) {
            perror("Failed to read from SPI");
            continue;
        }

        int moisture = (rx[1] << 8) | rx[2];
        printf("Moisture: %d\n", moisture);

        // Check if moisture is below threshold
        if (moisture < THRESHOLD) {
            pump_status = 1;
            gpiod_line_set_value(line, 1);
        } else {
            pump_status = 0;
            gpiod_line_set_value(line, 0);
        }

        // Log data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "%s, %d, %d\n", timestamp, moisture, pump_status);
        if (write(log_fd, log_entry, strlen(log_entry)) != strlen(log_entry)) {
            perror("Failed to write to log file");
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    close(spi_fd);
    close(log_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

