#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USECS 0
#define LED_PIN 17
#define CALIBRATION_TIME 5000000 // 5 seconds in microseconds
#define THRESHOLD 500 // Adjust this threshold as needed

static int spi_fd;
static int led_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct spi_ioc_transfer transfer;
static uint8_t spi_buf[3];
static uint16_t calibration_level = 0;
static uint32_t last_sample_time = 0;
static uint32_t debounce_timer = 0;

static void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
    gpiod_line_release(led_line);
    close(led_fd);
    close(spi_fd);
    gpiod_chip_close(chip);
    exit(0);
}

static void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void spi_close() {
    close(spi_fd);
}

static void gpio_init() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void gpio_close() {
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
}

static void spi_transfer() {
    spi_buf[0] = 0b11000000; // Start bit, MSB first
    spi_buf[1] = 0b00000000; // Channel 0
    spi_buf[2] = 0b00000000; // Dummy byte

    transfer.tx_buf = (unsigned long)spi_buf;
    transfer.rx_buf = (unsigned long)spi_buf;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.delay_usecs = SPI_DELAY_USECS;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("Failed to perform SPI transfer");
        spi_close();
        gpio_close();
        exit(EXIT_FAILURE);
    }

    uint16_t sample = (spi_buf[1] << 8) | spi_buf[2];
    printf("Sample: %d\n", sample);
}

static void calibrate() {
    printf("Calibrating ambient noise level...\n");
    for (int i = 0; i < 5000; i++) {
        spi_transfer();
        if (i % 100 == 0) {
            printf("Calibration progress: %d%%\n", i * 100 / 5000);
        }
    }
    calibration_level = sample;
    printf("Calibration complete. Baseline level: %d\n", calibration_level);
}

static void main() {
    signal(SIGINT, sigint_handler);

    spi_init();
    gpio_init();

    calibrate();

    while (1) {
        if (time(NULL) * 1000000 - last_sample_time >= 10000) {
            spi_transfer();
            last_sample_time = time(NULL) * 1000000;

            if (sample > calibration_level + THRESHOLD) {
                if (time(NULL) * 1000000 - debounce_timer >= 10000) {
                    gpiod_line_set_value(led_line, 1);
                    debounce_timer = time(NULL) * 1000000;
                }
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        }

        usleep(10000);
    }

    spi_close();
    gpio_close();
}

