#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_CHANNEL 0
#define SPI_MAX_RETRIES 5
#define SPI_RETRY_DELAY 100000 // 100 ms

#define LOG_FILE "gas_log.txt"
#define MAX_LOG_LINE_LENGTH 256

static int spi_fd = -1;
static int log_fd = -1;
static volatile sig_atomic_t should_exit = 0;

static void sigint_handler(int signum) {
    should_exit = 1;
}

static void spi_init() {
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .delay_usecs = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void spi_deinit() {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

static void log_data(double voltage, int ppm) {
    char log_line[MAX_LOG_LINE_LENGTH];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", tm);
    snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line), ", %.3f, %d\n", voltage, ppm);
    if (log_fd >= 0) {
        write(log_fd, log_line, strlen(log_line));
    }
}

static int spi_read() {
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .delay_usecs = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    int retries = SPI_MAX_RETRIES;
    while (retries > 0) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tr) < 0) {
            perror("Failed to perform SPI transfer");
            retries--;
            usleep(SPI_RETRY_DELAY);
            continue;
        }
        break;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read from SPI device after %d retries\n", SPI_MAX_RETRIES);
        return -1;
    }

    return tr.rx_buf[0] << 8 | tr.rx_buf[1];
}

static double read_voltage(int adc_value) {
    // Assuming the sensor outputs a 10-bit ADC value
    return (adc_value * 3.3) / 1023.0;
}

static int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    spi_init();
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        spi_deinit();
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        int adc_value = spi_read();
        if (adc_value < 0) {
            continue;
        }

        double voltage = read_voltage(adc_value);
        int ppm = 0; // Placeholder PPM value

        printf("Timestamp: %s, Voltage: %.3f V, PPM: %d\n", asctime(localtime(&time(NULL))), voltage, ppm);
        log_data(voltage, ppm);

        usleep(1000000); // 1 second delay
    }

    close(log_fd);
    spi_deinit();

    return 0;
}

