#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define MAX_MAGNETIC_FIELD 100.0
#define MIN_MAGNETIC_FIELD -100.0

static int gpiod_chip = -1;
static int gpio4_line = -1;
static int gpio17_line = -1;
static int gpio27_line = -1;

static void handle_sigint(int signum) {
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(EXIT_SUCCESS);
}

static void log_magnetic_field(double sensor1, double sensor2, double sensor3) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(file, "%.2f,%.2f,%.2f\n", sensor1, sensor2, sensor3);
    fclose(file);
}

static void check_magnetic_field(double magnetic_field) {
    if (magnetic_field < MIN_MAGNETIC_FIELD || magnetic_field > MAX_MAGNETIC_FIELD) {
        fprintf(stderr, "Warning: Magnetic field out of range: %.2f mT\n", magnetic_field);
    }
}

static void read_sensors() {
    int sensor1_state = gpiod_line_get_value(gpio4_line);
    int sensor2_state = gpiod_line_get_value(gpio17_line);
    int sensor3_state = gpiod_line_get_value(gpio27_line);

    double sensor1_magnetic_field = sensor1_state ? 3.3 : 0.0;
    double sensor2_magnetic_field = sensor2_state ? 3.3 : 0.0;
    double sensor3_magnetic_field = sensor3_state ? 3.3 : 0.0;

    check_magnetic_field(sensor1_magnetic_field);
    check_magnetic_field(sensor2_magnetic_field);
    check_magnetic_field(sensor3_magnetic_field);

    log_magnetic_field(sensor1_magnetic_field, sensor2_magnetic_field, sensor3_magnetic_field);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_sigint;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpio4_line = gpiod_chip_get_line(gpiod_chip, GPIO4);
    if (gpio4_line == -1) {
        fprintf(stderr, "Failed to get GPIO4 line\n");
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    gpio17_line = gpiod_chip_get_line(gpiod_chip, GPIO17);
    if (gpio17_line == -1) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        gpiod_chip_close(gpiod_chip);
        gpiod_line_release(gpio4_line);
        return EXIT_FAILURE;
    }

    gpio27_line = gpiod_chip_get_line(gpiod_chip, GPIO27);
    if (gpio27_line == -1) {
        fprintf(stderr, "Failed to get GPIO27 line\n");
        gpiod_chip_close(gpiod_chip);
        gpiod_line_release(gpio4_line);
        gpiod_line_release(gpio17_line);
        return EXIT_FAILURE;
    }

    gpiod_line_request_input(gpio4_line, "sensor1");
    gpiod_line_request_input(gpio17_line, "sensor2");
    gpiod_line_request_input(gpio27_line, "sensor3");

    while (1) {
        read_sensors();
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpiod_line_release(gpio4_line);
    gpiod_line_release(gpio17_line);
    gpiod_line_release(gpio27_line);
    gpiod_chip_close(gpiod_chip);

    return EXIT_SUCCESS;
}

