    if (gpiod_chip == -1) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpio4_line = gpiod_chip_get_line(gpiod_chip, GPIO4);
    if (gpio4_line == -1) {
        fprintf(stderr, "Failed to get GPIO4 line\n");
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    gpio17_line = gpiod_chip_get_line(gpiod_chip, GPIO17);
    if (gpio17_line == -1) {
        fprintf(stderr, "Failed to get GPIO17 line\n");
        gpiod_chip_close(gpiod_chip);
        gpiod_line_release(gpio4_line);
        return EXIT_FAILURE;
    }

    gpio27_line = gpiod_chip_get_line(gpiod_chip, GPIO27);
    if (gpio27_line == -1) {
        fprintf(stderr, "Failed to get GPIO27 line\n");
        gpiod_chip_close(gpiod_chip);
        gpiod_line_release(gpio4_line);
        gpiod_line_release(gpio17_line);
        return EXIT_FAILURE;
    }

    gpiod_line_request_input(gpio4_line, "sensor1");
    gpiod_line_request_input(gpio17_line, "sensor2");
    gpiod_line_request_input(gpio27_line, "sensor3");

    while (1) {
        read_sensors();
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpiod_line_release(gpio4_line);
    gpiod_line_release(gpio17_line);
    gpiod_line_release(gpio27_line);
    gpiod_chip_close(gpiod_chip);

    return EXIT_SUCCESS;
}
