#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 500000
#define SPI_MODE 0
#define MOISTURE_CHANNEL 0
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"
#define MAX_LOG_LINE_LENGTH 256

static int spi_fd;
static int pump_gpio;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void log_event(const char *format, ...) {
    time_t now;
    struct tm *tm_info;
    char log_line[MAX_LOG_LINE_LENGTH];

    time(&now);
    tm_info = localtime(&now);
    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S ", tm_info);

    va_list args;
    va_start(args, format);
    vsnprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line), format, args);
    va_end(args);

    fprintf(log_file, "%s\n", log_line);
}

static void handle_signal(int signum) {
    should_exit = 1;
    log_event("Received signal %d, turning off pump and exiting.", signum);
    gpio_set_value(pump_gpio, 0);
    fclose(log_file);
    close(spi_fd);
    exit(0);
}

static void setup_gpio() {
    int ret;

    ret = gpiochip_open(0);
    if (ret < 0) {
        log_event("Failed to open GPIO chip: %s", strerror(errno));
        exit(1);
    }

    pump_gpio = gpio_find_line("GPIO17");
    if (pump_gpio < 0) {
        log_event("Failed to find GPIO17: %s", strerror(errno));
        gpiochip_close(ret);
        exit(1);
    }

    ret = gpio_claim_line(pump_gpio);
    if (ret < 0) {
        log_event("Failed to claim GPIO17: %s", strerror(errno));
        gpiochip_close(ret);
        exit(1);
    }

    gpio_set_value(pump_gpio, 0);
}

static void setup_spi() {
    struct spi_ioc_transfer transfer;
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_event("Failed to open SPI device: %s", strerror(errno));
        exit(1);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        log_event("Failed to set SPI mode: %s", strerror(errno));
        close(spi_fd);
        exit(1);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        log_event("Failed to set SPI speed: %s", strerror(errno));
        close(spi_fd);
        exit(1);
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)0x00000000; // Command byte
    transfer.rx_buf = (unsigned long)0x00000000; // Data buffer
    transfer.len = 3; // Command byte + 2 data bytes
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = 8;
    transfer.cs_change = 1;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
    if (ret < 0) {
        log_event("Failed to send SPI command: %s", strerror(errno));
        close(spi_fd);
        exit(1);
    }
}

static void read_moisture() {
    struct spi_ioc_transfer transfer;
    unsigned char data[3];
    int ret;

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)0x00000000; // Command byte
    transfer.rx_buf = (unsigned long)data; // Data buffer
    transfer.len = 3; // Command byte + 2 data bytes
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = 8;
    transfer.cs_change = 1;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
    if (ret < 0) {
        log_event("Failed to read SPI data: %s", strerror(errno));
        return;
    }

    int moisture = (data[1] << 8) | data[2];
    log_event("Moisture reading: %d", moisture);

    if (moisture < MOISTURE_THRESHOLD) {
        gpio_set_value(pump_gpio, 1);
        log_event("Pump turned on.");
    } else {
        gpio_set_value(pump_gpio, 0);
        log_event("Pump turned off.");
    }
}

int main() {
    int ret;

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_event("Failed to open log file: %s", strerror(errno));
        exit(1);
    }

    setup_gpio();
    setup_spi();

    log_event("Program started.");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        read_moisture();
        sleep(60);
    }

    log_event("Program terminated.");

    fclose(log_file);
    close(spi_fd);
    gpiochip_close(0);

    return 0;
}

