This C program sets up a Raspberry Pi 4 Model B to read soil moisture from an MCP3008 ADC connected to the SPI bus, using channel 0 in single-ended mode. It continuously checks the moisture level every 60 seconds and turns on a pump relay connected to GPIO17 (BCM, active-high) when the moisture reading falls below 30%. The program logs all events, including program start, each pump on/off transition, any ADC read failures, and program termination with timestamps to a file named "watering.log". It handles errors by checking all driver and SPI calls and logging any ADC read failures but continuing operation. The program ensures a clean shutdown by installing signal handlers for SIGINT and SIGTERM that turn the pump off before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define NUM_CHANNELS 3
#define CSV_FILE "sensor_data.csv"

static int spi_fd;
static FILE *csv_file;
static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct spi_ioc_transfer transfers[NUM_CHANNELS];
    uint8_t tx_data[NUM_CHANNELS] = {0x01, 0x02, 0x03}; // Start bit, channel select, and dummy byte
    uint8_t rx_data[NUM_CHANNELS * 3]; // 3 bytes per channel
    int i, ret;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Prepare SPI transfers
    for (i = 0; i < NUM_CHANNELS; i++) {
        transfers[i].tx_buf = (unsigned long)&tx_data[i];
        transfers[i].rx_buf = (unsigned long)&rx_data[i * 3];
        transfers[i].len = 3;
        transfers[i].speed_hz = SPI_SPEED_HZ;
        transfers[i].bits_per_word = SPI_BITS_PER_WORD;
        transfers[i].delay_usecs = 0;
        transfers[i].cs_change = 0;
    }

    // Main loop
    while (!should_exit) {
        struct timespec sleep_time = {0, 100000000}; // 1 second
        nanosleep(&sleep_time, NULL);

        // Perform SPI transfers
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, transfers);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            continue;
        }

        // Log readings to CSV file
        for (i = 0; i < NUM_CHANNELS; i++) {
            fprintf(csv_file, "%d,", rx_data[i * 3] << 8 | rx_data[i * 3 + 1]);
        }
        fprintf(csv_file, "%d\n", rx_data[NUM_CHANNELS * 3] << 8 | rx_data[NUM_CHANNELS * 3 + 1]);
    }

    // Close CSV file
    fclose(csv_file);

    // Close SPI device
    close(spi_fd);

    return 0;
}

