#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <mosquitto.h>
#include <jansson.h>

#define LED_PIN 17
#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define MAX_RECONNECT_DELAY 60
#define JSON_KEY "led_state"

static struct mosquitto *mosq;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int reconnect_delay = 1;
static int led_state = 0;

static void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        fprintf(stderr, "Connected to MQTT broker\n");
    } else {
        fprintf(stderr, "Failed to connect to MQTT broker, retrying in %d seconds\n", reconnect_delay);
        reconnect_delay = reconnect_delay * 2;
        if (reconnect_delay > MAX_RECONNECT_DELAY) {
            reconnect_delay = MAX_RECONNECT_DELAY;
        }
        sleep(reconnect_delay);
        mosquitto_reconnect(mosq);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->topic != NULL && strcmp(msg->topic, MQTT_TOPIC) == 0) {
        json_error_t error;
        json_t *root = json_loads(msg->payload, 0, &error);
        if (root == NULL) {
            fprintf(stderr, "JSON parsing error: %s at line %d, column %d\n", error.text, error.line, error.column);
            return;
        }

        json_t *led_state_json = json_object_get(root, JSON_KEY);
        if (led_state_json != NULL && json_is_boolean(led_state_json)) {
            led_state = json_is_true(led_state_json);
            gpiod_line_set_value(line, led_state);
        } else {
            fprintf(stderr, "Invalid JSON payload, expected key '%s' with boolean value\n", JSON_KEY);
        }

        json_decref(root);
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    fprintf(stderr, "Disconnected from MQTT broker\n");
    reconnect_delay = 1;
}

static void on_subscribe(struct mosquitto *mosq, void *userdata, int mid, int qos_count, const int *granted_qos) {
    fprintf(stderr, "Subscribed to topic '%s'\n", MQTT_TOPIC);
}

static void on_unsubscribe(struct mosquitto *mosq, void *userdata, int mid) {
    fprintf(stderr, "Unsubscribed from topic '%s'\n", MQTT_TOPIC);
}

static void on_log(struct mosquitto *mosq, void *userdata, int level, const char *str) {
    fprintf(stderr, "MQTT log: %s\n", str);
}

static void signal_handler(int signum) {
    mosquitto_disconnect(mosq);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    mosquitto_destroy(mosq);
    exit(0);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler for SIGINT");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler for SIGTERM");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line = gpiod_chip_get_line(chip, LED_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, "LED", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        perror("Failed to create MQTT client");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
