#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define ALARM_PIN 18
#define DELAY_MS 100
#define MAX_TRIES 5

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line, *alarm_line;
    unsigned int value;
    int tries = 0;

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        perror("Failed to get alarm GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request lines
    ret = gpiod_line_request_input(line, "sound_sensor");
    if (ret) {
        perror("Failed to request input line");
        gpiod_line_release(line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(alarm_line, "alarm_led", 0);
    if (ret) {
        perror("Failed to request output line");
        gpiod_line_release(line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read sound sensor
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("Failed to read GPIO line");
            tries++;
            if (tries >= MAX_TRIES) {
                gpiod_line_release(line);
                gpiod_line_release(alarm_line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
            continue;
        }

        // Print sound level
        printf("Sound level: %d\n", ret);

        // Check for sound event
        if (ret == 0) {
            // Trigger alarm
            ret = gpiod_line_set_value(alarm_line, 1);
            if (ret < 0) {
                perror("Failed to set alarm line");
                gpiod_line_release(line);
                gpiod_line_release(alarm_line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }

            // Wait for 1 second
            usleep(1000000);

            // Turn off alarm
            ret = gpiod_line_set_value(alarm_line, 0);
            if (ret < 0) {
                perror("Failed to set alarm line");
                gpiod_line_release(line);
                gpiod_line_release(alarm_line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
        }

        // Delay
        usleep(DELAY_MS * 1000);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);

    return 0;
}

