#include <time.h>
#include <libgpiod.h>

#define VIBRATION_SENSOR_GPIO 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define MAX_LINE_LENGTH 256

static volatile sig_atomic_t exit_flag = 0;

static void sig_handler(int signum) {
    exit_flag = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    char timestamp[20];
    char line_buffer[MAX_LINE_LENGTH];

    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the line for GPIO17
    line = gpiod_chip_get_line(chip, VIBRATION_SENSOR_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request falling-edge detection
    ret = gpiod_line_request_edge_detection(line, "vibration-monitor", GPIOD_EDGE_FALLING);
    if (ret) {
        perror("Failed to request edge detection");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!exit_flag) {
        // Wait for an event
        ret = gpiod_line_event_wait(line, NULL);
        if (ret) {
            perror("Failed to wait for event");
            break;
        }

        // Read the event
        ret = gpiod_line_event_read(line, &event);
        if (ret) {
            perror("Failed to read event");
            break;
        }

        // Get the current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Append a timestamped message to the log file
        snprintf(line_buffer, MAX_LINE_LENGTH, "%s: Vibration detected\n", timestamp);
        if (fprintf(log_file, "%s", line_buffer) < 0) {
            perror("Failed to write to log file");
            break;
        }

        // Print the same message to stdout
        printf("%s", line_buffer);

        // Invoke system shutdown
        if (system("sudo shutdown -h now") != 0) {
            perror("Failed to invoke shutdown");
            break;
        }
    }

    // Clean up resources
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

