#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"
#define BUFFER_SIZE 256

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char buffer[BUFFER_SIZE];
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request input with pull-down resistor
    if (gpiod_line_request_input(line, "flame_sensor")) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Read the state of the line
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            perror("Failed to read GPIO line value");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Get current time
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            perror("Failed to get current time");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Format log entry
        snprintf(buffer, BUFFER_SIZE, "%ld,%d,%d\n", ts.tv_sec, FLAME_SENSOR_PIN, state);

        // Write log entry to file
        if (fwrite(buffer, 1, strlen(buffer), log_file) != strlen(buffer)) {
            perror("Failed to write to log file");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Print alarm message if sensor reports a HIGH
        if (state == 1) {
            fprintf(stderr, "ALARM: Flame detected!\n");
        }

        // Sleep for 1 second
        if (nanosleep(&ts, NULL) < 0) {
            perror("Failed to sleep");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

