#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP3008_CHANNEL 0
#define MCP4725_ADDRESS 0x60
#define DAC_RESOLUTION 4095
#define SAMPLE_INTERVAL 500000 // 0.5 seconds
#define MAX_RETRIES 3
#define LOG_FILE "temperature_log.txt"

static int spi_fd;
static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static FILE *log_file;

static void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .cs_change = 0,
    };
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int i2c_write(uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (value >> 8) & 0xFF, value & 0xFF};
    int ret = write(i2c_fd, buf, 3);
    if (ret < 0) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int read_temperature() {
    uint8_t tx[3] = {0x01, (MCP3008_CHANNEL << 4) | 0x01, 0x00};
    uint8_t rx[3];
    int retries = MAX_RETRIES;
    while (retries--) {
        if (spi_transfer(tx, rx, 3) == 0) {
            int raw_value = (rx[1] << 8) | rx[2];
            float voltage = raw_value * 3.3 / 1023.0;
            float temperature = (voltage - 0.5) * 100.0;
            return temperature;
        }
        usleep(100000); // Wait for 100ms before retrying
    }
    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1;
}

static int write_dac(float temperature) {
    float voltage = temperature / 100.0 * 3.3;
    uint16_t dac_value = (uint16_t)(voltage * DAC_RESOLUTION / 3.3);
    if (i2c_write(0x40, dac_value) == 0) {
        return 0;
    }
    fprintf(stderr, "Failed to write DAC voltage\n");
    return -1;
}

static void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, (int)temperature, temperature, voltage);
    fprintf(stdout, "%s, %d, %.2f, %.2f\n", timestamp, (int)temperature, temperature, voltage);
}

int main() {
    signal(SIGINT, sigint_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO for chip enable
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, 23); // Assuming CE0 is GPIO23
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(gpio_line, "spi_ce0", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Log header
    fprintf(log_file, "Timestamp, Raw ADC, Temperature (°C), DAC Voltage (V)\n");
    fprintf(stdout, "Timestamp, Raw ADC, Temperature (°C), DAC Voltage (V)\n");

    // Main loop
    while (1) {
        float temperature = read_temperature();
        if (temperature >= 0) {
            write_dac(temperature);
            log_temperature(temperature);
        }
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    close(spi_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

