#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNELS 8
#define SOIL_SENSORS 3
#define BUFFER_SIZE 1024
#define LOG_FILE "soil_data.txt"
#define MAX_READINGS 10000

static int spi_fd;
static int gpio_fd;
static int *gpio_pins;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

static void signal_handler(int signum) {
    exit_flag = 1;
}

static void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpio_close(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

static int read_soil_moisture(int channel) {
    uint8_t tx[3] = {0x01, (channel << 4) | 0x01, 0x00};
    uint8_t rx[BUFFER_SIZE];
    int ret;

    ret = spi_read(spi_fd, tx, sizeof(tx), rx, sizeof(rx));
    if (ret < 0) {
        perror("spi_read");
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

static void log_reading(const char *timestamp, int sensor, int value) {
    fprintf(log_file, "%s Sensor %d: %d\n", timestamp, sensor, value);
}

int main() {
    struct spi_ioc_transfer tr;
    struct timespec ts;
    char timestamp[BUFFER_SIZE];
    int readings[MAX_READINGS];
    int num_readings = 0;

    // Initialize GPIO
    gpio_fd = gpio_open("/dev/gpiochip0", 0);
    if (gpio_fd < 0) {
        perror("gpio_open");
        exit(1);
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Read soil moisture every 60 seconds
    while (!exit_flag) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        for (int i = 0; i < SOIL_SENSORS; i++) {
            int value = read_soil_moisture(i);
            if (value >= 0) {
                readings[num_readings++] = value;
                log_reading(timestamp, i, value);
            }
        }

        if (num_readings >= MAX_READINGS) {
            num_readings = 0;
        }

        ts.tv_sec = 60;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    close_resources();
    printf("Goodbye!\n");
    return 0;
}

