#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {17, 22, 23, 24}
#define DELAY_TIME 1000000 // 1 second in microseconds

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];

void signal_handler(int signum) {
    printf("Received signal %d, deactivating relays and releasing GPIO lines.\n", signum);
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], 0); // Deactivate relay
    }
    gpiod_chip_close(chip); // Release GPIO chip
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for each relay
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        // Set line direction to output
        if (gpiod_line_request_output(lines[i], "songle_relay", 0)) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set all relays to inactive (LOW)
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(lines[i], 0)) {
            perror("Failed to set GPIO line value to LOW");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

