#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define LED_PIN 16
#define THRESHOLD 500
#define DEBOUNCE_DELAY 100
#define LOG_FILE "sound_events.log"

static int spi_fd;
static int led_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct timespec start_time;
static struct timespec end_time;
static FILE *log_file;

static void sigint_handler(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (led_fd >= 0) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t rx[3];
    int ret;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

static void log_event(int value) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: ADC value %d exceeded threshold\n", timestamp, value);
    fclose(log_file);
}

static void debounce() {
    struct timespec current_time;

    clock_gettime(CLOCK_MONOTONIC, &current_time);
    if (current_time.tv_nsec - start_time.tv_nsec < DEBOUNCE_DELAY * 1000000) {
        return;
    }
    start_time = current_time;
}

int main() {
    int value;
    struct sigaction sa;

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "sound_sensor", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        value = read_adc();
        if (value > THRESHOLD) {
            debounce();
            log_event(value);
            gpiod_line_set_value(led_line, 1);
            usleep(500000);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(10000);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

