#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 10
#define LOG_FILE "rain_log.txt"
#define RAIN_THRESHOLD 5
#define MOTOR_PIN_FORWARD 17
#define MOTOR_PIN_REVERSE 18
#define MOTOR_PIN_ENABLE 27
#define MOTOR_PWM_DUTY 150
#define MOTOR_PWM_MAX 255

volatile sig_atomic_t stop_flag = 0;

static void sig_handler(int sig) {
    stop_flag = 1;
}

int main() {
    int spi_fd, gpio_fd;
    struct spi_ioc_transfer xfer;
    uint8_t spi_buf[3];
    uint8_t adc_buf[2];
    struct timespec ts;
    char log_buf[256];
    FILE *log_file;
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line_forward, *line_reverse, *line_enable;
    int pwm_fd;

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    line_forward = gpiod_chip_get_line(chip, MOTOR_PIN_FORWARD);
    if (!line_forward) {
        perror("Failed to get GPIO line for forward motor");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    line_reverse = gpiod_chip_get_line(chip, MOTOR_PIN_REVERSE);
    if (!line_reverse) {
        perror("Failed to get GPIO line for reverse motor");
        gpiod_line_release(line_forward);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    line_enable = gpiod_chip_get_line(chip, MOTOR_PIN_ENABLE);
    if (!line_enable) {
        perror("Failed to get GPIO line for motor enable");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_forward, "motor_forward", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for forward motor");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_reverse, "motor_reverse", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for reverse motor");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_enable, "motor_enable", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for motor enable");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    pwm_fd = gpio_export(MOTOR_PIN_ENABLE);
    if (pwm_fd < 0) {
        perror("Failed to export GPIO line for motor enable");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_direction(pwm_fd, GPIO_DIR_OUT);
    if (ret < 0) {
        perror("Failed to set GPIO direction for motor enable");
        gpio_unexport(pwm_fd);
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!stop_flag) {
        // Read ADC
        memset(spi_buf, 0, sizeof(spi_buf));
        spi_buf[0] = 0x40; // Start bit, single-ended conversion, channel 0
        spi_buf[1] = 0x00; // Dummy byte

        for (int i = 0; i < SPI_MAX_RETRIES; i++) {
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &xfer);
            if (ret < 0) {
                perror("Failed to send SPI message");
                break;
            }

            if (xfer.rx_buf) {
                memcpy(adc_buf, xfer.rx_buf, sizeof(adc_buf));
                break;
            }
        }

        if (ret < 0) {
            fprintf(log_file, "SPI transfer error\n");
            fflush(log_file);
            continue;
        }

        // Calculate rain level
        int rain_level = (adc_buf[0] << 8) | adc_buf[1];
        if (rain_level > RAIN_THRESHOLD) {
            // Open window
            gpiod_line_set_value(line_forward, 1);
            gpiod_line_set_value(line_reverse, 0);
            gpiod_line_set_value(line_enable, 1);
            pwm_set_duty_cycle(pwm_fd, MOTOR_PWM_DUTY);
            usleep(3000000);
            pwm_set_duty_cycle(pwm_fd, 0);
            gpiod_line_set_value(line_enable, 0);
            gpiod_line_set_value(line_forward, 0);
            gpiod_line_set_value(line_reverse, 1);
        } else {
            // Close window
            gpiod_line_set_value(line_forward, 0);
            gpiod_line_set_value(line_reverse, 1);
            gpiod_line_set_value(line_enable, 1);
            pwm_set_duty_cycle(pwm_fd, MOTOR_PWM_DUTY);
            usleep(3000000);
            pwm_set_duty_cycle(pwm_fd, 0);
            gpiod_line_set_value(line_enable, 0);
            gpiod_line_set_value(line_forward, 1);
            gpiod_line_set_value(line_reverse, 0);
        }

        // Log data
        time(&ts);
        strftime(log_buf, sizeof(log_buf), "%Y-%m-%d %H:%M:%S", localtime(&ts));
        fprintf(log_file, "%s, %d\n", log_buf, rain_level);
        fflush(log_file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    pwm_set_duty_cycle(pwm_fd, 0);
    gpiod_line_set_value(line_enable, 0);
    gpiod_line_release(line_forward);
    gpiod_line_release(line_reverse);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return 0;
}

