        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_reverse, "motor_reverse", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for reverse motor");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_enable, "motor_enable", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for motor enable");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    pwm_fd = gpio_export(MOTOR_PIN_ENABLE);
    if (pwm_fd < 0) {
        perror("Failed to export GPIO line for motor enable");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpio_set_direction(pwm_fd, GPIO_DIR_OUT);
    if (ret < 0) {
        perror("Failed to set GPIO direction for motor enable");
        gpio_unexport(pwm_fd);
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line_forward);
        gpiod_line_release(line_reverse);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!stop_flag) {
        // Read ADC
        memset(spi_buf, 0, sizeof(spi_buf));
        spi_buf[0] = 0x40; // Start bit, single-ended conversion, channel 0
        spi_buf[1] = 0x00; // Dummy byte

        for (int i = 0; i < SPI_MAX_RETRIES; i++) {
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &xfer);
            if (ret < 0) {
                perror("Failed to send SPI message");
                break;
            }

            if (xfer.rx_buf) {
                memcpy(adc_buf, xfer.rx_buf, sizeof(adc_buf));
                break;
            }
        }

        if (ret < 0) {
            fprintf(log_file, "SPI transfer error\n");
            fflush(log_file);
            continue;
        }

        // Calculate rain level
        int rain_level = (adc_buf[0] << 8) | adc_buf[1];
        if (rain_level > RAIN_THRESHOLD) {
            // Open window
            gpiod_line_set_value(line_forward, 1);
            gpiod_line_set_value(line_reverse, 0);
            gpiod_line_set_value(line_enable, 1);
            pwm_set_duty_cycle(pwm_fd, MOTOR_PWM_DUTY);
            usleep(3000000);
            pwm_set_duty_cycle(pwm_fd, 0);
            gpiod_line_set_value(line_enable, 0);
            gpiod_line_set_value(line_forward, 0);
            gpiod_line_set_value(line_reverse, 1);
        } else {
            // Close window
            gpiod_line_set_value(line_forward, 0);
            gpiod_line_set_value(line_reverse, 1);
            gpiod_line_set_value(line_enable, 1);
            pwm_set_duty_cycle(pwm_fd, MOTOR_PWM_DUTY);
            usleep(3000000);
            pwm_set_duty_cycle(pwm_fd, 0);
            gpiod_line_set_value(line_enable, 0);
            gpiod_line_set_value(line_forward, 1);
            gpiod_line_set_value(line_reverse, 0);
        }

        // Log data
        time(&ts);
        strftime(log_buf, sizeof(log_buf), "%Y-%m-%d %H:%M:%S", localtime(&ts));
        fprintf(log_file, "%s, %d\n", log_buf, rain_level);
        fflush(log_file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    pwm_set_duty_cycle(pwm_fd, 0);
    gpiod_line_set_value(line_enable, 0);
    gpiod_line_release(line_forward);
    gpiod_line_release(line_reverse);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(spi_fd);

    return 0;
}
```

This code initializes the SPI interface, GPIO lines, and PWM for the L298N motor driver. It reads the analog output of the Seeed Studio Grove Rain Sensor, calculates the rain level, and controls the motor based on the threshold. The program logs the data to a file and handles errors and signals appropriately.

