#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define MAX9814_ADC_PIN 26
#define LED_PIN 16
#define DEBOUNCE_INTERVAL 50  // in milliseconds
#define CLAP_THRESHOLD 1000  // in ADC units
#define CLAP_DURATION 500    // in milliseconds

static volatile sig_atomic_t should_exit = 0;
static struct gpiod_chip *chip;
static struct gpiod_line *adc_line;
static struct gpiod_line *led_line;

static void sigint_handler(int signum) {
    should_exit = 1;
    gpiod_line_release(led_line);
    gpiod_line_release(adc_line);
    gpiod_chip_close(chip);
    printf("LED turned off and resources released.\n");
    exit(0);
}

static void setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    adc_line = gpiod_chip_get_line(chip, MAX9814_ADC_PIN);
    if (!adc_line) {
        perror("Failed to get ADC line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(adc_line, "MAX9814 ADC")) {
        perror("Failed to request ADC line as input");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(adc_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "LED", 0)) {
        perror("Failed to request LED line as output");
        gpiod_line_release(adc_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void release_gpio() {
    gpiod_line_release(led_line);
    gpiod_line_release(adc_line);
    gpiod_chip_close(chip);
}

static void print_timestamped_message(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    printf("%ld.%09ld: %s\n", (long)ts.tv_sec, (long)ts.tv_nsec, message);
}

static void detect_clap() {
    int adc_value = 0;
    int last_state = 0;
    int debounce_count = 0;
    int clap_detected = 0;

    while (!should_exit) {
        int current_state = gpiod_line_get_value(adc_line);
        if (current_state != last_state) {
            debounce_count++;
            last_state = current_state;
        } else {
            debounce_count = 0;
        }

        if (debounce_count >= DEBOUNCE_INTERVAL) {
            adc_value = gpiod_line_get_value(adc_line);
            if (adc_value > CLAP_THRESHOLD) {
                if (!clap_detected) {
                    print_timestamped_message("Clap detected!");
                    clap_detected = 1;
                    gpiod_line_set_value(led_line, 1);
                    usleep(CLAP_DURATION * 1000);
                    gpiod_line_set_value(led_line, 0);
                }
            } else {
                clap_detected = 0;
            }
        }

        usleep(1000);
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    setup_gpio();

    printf("Monitoring MAX9814 electret microphone amplifier...\n");

    detect_clap();

    release_gpio();
    return 0;
}

