#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define MAX_RETRIES 5

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    struct timespec sleep_time = {1, 0}; // 1 second
    struct sigaction sa;
    FILE *log_file;
    int gpio_fd;
    int retries = 0;
    char timestamp[20];
    char gpio_path[20];
    char value[2];

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO file
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/value", GPIO_PIN);
    gpio_fd = open(gpio_path, O_RDONLY);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO file");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Export GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        perror("Failed to export GPIO");
        fclose(log_file);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Set GPIO direction to input
    if (gpio_direction_input(GPIO_PIN) < 0) {
        perror("Failed to set GPIO direction");
        gpio_unexport(GPIO_PIN);
        fclose(log_file);
        close(gpio_fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Read GPIO value
        if (read(gpio_fd, value, 1) != 1) {
            perror("Failed to read GPIO value");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Too many retries, exiting\n");
                gpio_unexport(GPIO_PIN);
                fclose(log_file);
                close(gpio_fd);
                return EXIT_FAILURE;
            }
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Get current time
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        // Log distance
        fprintf(log_file, "%s: %s\n", timestamp, value);

        // Check distance
        if (value[0] == '0') {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        // Wait for a second
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpio_unexport(GPIO_PIN);
    fclose(log_file);
    close(gpio_fd);

    return EXIT_SUCCESS;
}

