    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    return (rx[1] << 8) | rx[2];
}

static int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return -1;
    }
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .pad = 0
    };
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        close(spi_fd);
        return -1;
    }
    return 0;
}

static int init_gpio() {
    gpio_fd = gpio_open(BCM, 0);
    if (gpio_fd < 0) {
        perror("gpio_open");
        return -1;
    }
    ret = gpio_claim_line(gpio_fd, PUMP_PIN);
    if (ret < 0) {
        perror("gpio_claim_line");
        gpio_close(gpio_fd);
        return -1;
    }
    gpio_set_value(gpio_fd, PUMP_PIN, 0);
    return 0;
}

static int init_log() {
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("open");
        return -1;
    }
    fprintf(log_fd, "Timestamp, Moisture, Pump Status\n");
    return 0;
}

static void cleanup() {
    if (pump_status) {
        gpio_set_value(gpio_fd, PUMP_PIN, 0);
    }
    gpio_close(gpio_fd);
    close(log_fd);
    close(spi_fd);
}

int main() {
    signal(SIGINT, sigint_handler);
    if (init_spi() < 0) {
        cleanup();
        return 1;
    }
    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }
    if (init_log() < 0) {
        cleanup();
        return 1;
    }

    while (1) {
        int moisture = read_adc();
        if (moisture < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }
        log_sample(moisture, pump_status);
        if (moisture < PUMP_THRESHOLD && !pump_status) {
            gpio_set_value(gpio_fd, PUMP_PIN, 1);
            pump_status = 1;
        } else if (moisture >= PUMP_THRESHOLD && pump_status) {
            gpio_set_value(gpio_fd, PUMP_PIN, 0);
            pump_status = 0;
        }
        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}
