#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_RETRIES 10
#define LED_PIN 21
#define THRESHOLD 10.0

static int spi_fd;
static int led_fd;
static int log_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct timespec ts;
static double last_reading = 0.0;

static void sigint_handler(int signum) {
    close(spi_fd);
    close(led_fd);
    close(log_fd);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

static void init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_led() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "magnetic_field_sensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void init_log() {
    log_fd = open("magnetic_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void close_log() {
    close(log_fd);
}

static void close_led() {
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
}

static void close_spi() {
    close(spi_fd);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3] = {0, 0, 0};

    for (int i = 0; i < SPI_MAX_RETRIES; i++) {
        if (write(spi_fd, tx, 3) != 3) {
            perror("Failed to write to SPI");
            return -1;
        }

        if (read(spi_fd, rx, 3) != 3) {
            perror("Failed to read from SPI");
            return -1;
        }

        if ((rx[0] & 0x80) == 0) {
            return (rx[1] << 8) | rx[2];
        }
    }

    perror("Failed to read valid ADC data");
    return -1;
}

static double convert_adc_to_magnetic_field(int adc_value) {
    // Assuming the ADC value is linearly proportional to the magnetic field strength
    // and the conversion factor is 0.01 mT per ADC count
    return adc_value * 0.01;
}

static void log_reading(double reading) {
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_fd, "%ld.%09ld,%.2f\n", ts.tv_sec, ts.tv_nsec, reading);
    fflush(log_fd);
}

static void toggle_led(double reading) {
    if (reading > THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    init_spi();
    init_led();
    init_log();

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        double reading = convert_adc_to_magnetic_field(adc_value);
        log_reading(reading);
        toggle_led(reading);

        if (reading > last_reading) {
            last_reading = reading;
        }

        usleep(100000); // 100 ms
    }

    close_log();
    close_led();
    close_spi();

    return 0;
}

