#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_LINE 17
#define LOG_FILE "current_log.txt"
#define SAMPLE_RATE 1  // samples per second
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define VOLTAGE_PER_A 0.1  // 100 mV/A typical

static int spi_fd;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void sig_handler(int sig) {
    should_exit = 1;
}

static void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpiod_close(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    struct spi_ioc_transfer transfer;
    struct gpiochip_info chip_info;
    struct gpiochip_line_info line_info;
    struct gpiochip_line_request line_request;
    struct timespec ts;
    double current_A;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close_resources();
        return EXIT_FAILURE;
    }

    // Get SPI device information
    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &transfer.mode) < 0) {
        perror("Failed to get SPI mode");
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &transfer.bits_per_word) < 0) {
        perror("Failed to get SPI bits per word");
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &transfer.speed_hz) < 0) {
        perror("Failed to get SPI max speed");
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    // Open GPIO line
    gpio_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }
    if (ioctl(gpio_fd, GPIO_GET_CHIPINFO_IOCTL, &chip_info) < 0) {
        perror("Failed to get GPIO chip info");
        gpiod_chip_close(gpio_fd);
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }
    if (chip_info.lines < GPIO_LINE) {
        fprintf(stderr, "GPIO line %d does not exist\n", GPIO_LINE);
        gpiod_chip_close(gpio_fd);
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }
    line_info.offset = GPIO_LINE;
    line_info.consumer = "MLX91209";
    line_request.flags = GPIOHANDLE_REQUEST_OUTPUT;
    if (gpiod_line_request(gpio_fd, &line_request, &line_info) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_fd);
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }
    gpiod_line_set_value(gpio_fd, line_info.offset, 1);  // Enable sensor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_fd, line_info.offset);
        gpiod_chip_close(gpio_fd);
        close(spi_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Read ADC value
        memset(&transfer, 0, sizeof(transfer));
        transfer.tx_buf = (unsigned char *)"\x01\x80\x00";  // Start conversion
        transfer.rx_buf = (unsigned char *)"\x00\x00\x00";
        transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
            perror("Failed to read ADC value");
            gpiod_line_release(gpio_fd, line_info.offset);
            gpiod_chip_close(gpio_fd);
            fclose(log_file);
            close(spi_fd);
            close_resources();
            return EXIT_FAILURE;
        }
        unsigned int adc_value = (transfer.rx_buf[1] << 8) | transfer.rx_buf[2];
        if (adc_value == 0) {
            fprintf(stderr, "Sensor is absent or communication failed\n");
            gpiod_line_release(gpio_fd, line_info.offset);
            gpiod_chip_close(gpio_fd);
            fclose(log_file);
            close(spi_fd);
            close_resources();
            return EXIT_FAILURE;
        }

        // Convert ADC value to current
        current_A = adc_value * VOLTAGE_PER_A / ADC_MAX_VALUE;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Append data to log file
        fprintf(log_file, "%s,%f\n", timestamp, current_A);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close_resources();
    return EXIT_SUCCESS;
}

