#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "current_log.txt"
#define MAX_BUFFER_SIZE 256

volatile sig_atomic_t exit_flag = 0;

// Function to handle SIGINT
void sigint_handler(int signum) {
    exit_flag = 1;
}

// Function to convert ADC reading to current
float adc_to_current(int adc_reading) {
    // Assuming the sensor has a known voltage range and resolution
    // For MLX91211, the voltage range is 0-5V and the resolution is 12 bits
    // The current range is typically 0-10A, so we can use a simple linear conversion
    // This is a placeholder for actual conversion logic
    return (float)adc_reading * 10.0 / 4095.0;
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer transfer;
    uint8_t tx_buffer[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t rx_buffer[3];
    int adc_reading;
    float current;
    char log_line[MAX_BUFFER_SIZE];
    time_t now;
    struct tm *timeinfo;
    FILE *log_file;

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Perform SPI transfer
    transfer.tx_buf = (unsigned long)tx_buffer;
    transfer.rx_buf = (unsigned long)rx_buffer;
    transfer.len = 3;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("SPI transfer failed");
        fclose(log_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Read ADC reading
    adc_reading = (rx_buffer[1] << 8) | rx_buffer[2];

    // Convert ADC reading to current
    current = adc_to_current(adc_reading);

    // Check if measured voltage is within 0-5V
    if (current < 0.0 || current > 10.0) {
        fprintf(stderr, "Warning: Measured voltage is outside 0-5V range\n");
        fclose(log_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Get current time
    now = time(NULL);
    timeinfo = localtime(&now);

    // Format log line
    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S %.2f A", timeinfo, current);

    // Write log line to file
    if (fprintf(log_file, "%s\n", log_line) < 0) {
        perror("Failed to write to log file");
        fclose(log_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Flush log file
    if (fflush(log_file) != 0) {
        perror("Failed to flush log file");
        fclose(log_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Close log file
    fclose(log_file);

    // Close SPI device
    close(spi_fd);

    // Exit with success
    return EXIT_SUCCESS;
}
