        close(gpiod_ctx);
        close(gpio4_fd);
        close(gpio17_fd);
        exit(EXIT_FAILURE);
    }
    gpio17_fd = gpiod_line_request_input(line17, "sensor2");
    if (gpio17_fd < 0) {
        perror("Failed to request GPIO line 17 input");
        gpiod_chip_close(chip);
        close(gpiod_ctx);
        close(gpio4_fd);
        close(gpio17_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        check_sensors();
        usleep(LOG_INTERVAL);
    }

    // Cleanup
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_chip_close(chip);
    close(gpiod_ctx);
    close(gpio4_fd);
    close(gpio17_fd);

    return 0;
}

