#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

typedef struct {
    int channel;
    int baud;
} spi_config_t;

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signal) {
    exit_flag = 1;
    gpioTerminate();
    close_spi();
    exit(EXIT_FAILURE);
}

void close_spi() {
    if (spi_close(SPI_CHANNEL) != 0) {
        perror("Failed to close SPI");
    }
}

int read_mcp3008(int channel) {
    int fd = spi_open(SPI_CHANNEL, SPI_BAUD, 0);
    if (fd == -1) {
        perror("Failed to open SPI");
        return -1;
    }

    uint8_t cmd = (0b11000000 | (channel << 4));
    uint8_t data[3];
    data[0] = cmd;
    data[1] = 0;
    data[2] = 0;

    if (spi_xfer(fd, data, data, 3) != 3) {
        perror("Failed to transfer SPI");
        close_spi();
        return -1;
    }

    close_spi();
    return (data[1] << 8) | data[2];
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC || adc_value > MAX_ADC) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return (double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC) * 100;
}

void log_data(double moisture_level) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%f\n", timestamp, moisture_level);
    fclose(file);

    printf("%s,%f\n", timestamp, moisture_level);
}

void spi_setup(spi_config_t config) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (spiOpen(config.channel, config.baud, 0) < 0) {
        perror("Failed to open SPI");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

int main() {
    spi_config_t config = {SPI_CHANNEL, SPI_BAUD};
    spi_setup(config);

    signal(SIGINT, signal_handler);

    while (!exit_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        if (moisture_level == -1) {
            continue;
        }

        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    close_spi();
    gpioTerminate();
    return 0;
}

