#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <libcamera/still.h>
#include <libcamera/controls.h>

#define PIR_PIN 17
#define DEBOUNCE_DELAY 200
#define CAPTURE_DELAY 50
#define LOG_FILE "/var/log/security_cam.log"
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_FORMAT "motion_%Y%m%d_%H%M%S.jpg"

static int gpiod_fd = -1;
static libcamera::StillCaptureSession *session = nullptr;
static libcamera::ControlList controls;
static bool running = true;

static void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

static void handle_signal(int signum) {
    running = false;
    if (session) {
        session->stop();
        delete session;
        session = nullptr;
    }
    if (gpiod_fd != -1) {
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
    }
    closelog();
    exit(0);
}

static void setup_gpio() {
    gpiod_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_fd == -1) {
        log_event("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line_request req = {
        .line_offset = PIR_PIN,
        .direction = GPIOD_LINE_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN,
    };

    int err = gpiod_line_request(gpiod_fd, "security_cam", &req);
    if (err) {
        log_event("Failed to request GPIO line");
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
        exit(EXIT_FAILURE);
    }
}

static void setup_camera() {
    libcamera::CameraManager manager;
    libcamera::Camera *camera = manager.createCamera();
    if (!camera) {
        log_event("Failed to create camera");
        exit(EXIT_FAILURE);
    }

    camera->start();
    session = camera->createCaptureSession();
    if (!session) {
        log_event("Failed to create capture session");
        camera->stop();
        delete camera;
        camera = nullptr;
        exit(EXIT_FAILURE);
    }

    controls.set(libcamera::controls::ExposureTime, 1000000); // 1 second
    controls.set(libcamera::controls::Brightness, 50);
    controls.set(libcamera::controls::Contrast, 50);
    controls.set(libcamera::controls::Saturation, 50);
    controls.set(libcamera::controls::Sharpness, 50);
    controls.set(libcamera::controls::ISO, 800);
