#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <libgpiod.h>
#include <signal.h>
#include <sys/select.h>
#include <sys/mman.h>
#include <errno.h>

#define DEFAULT_VIDEO_DEVICE "/dev/video0"
#define MAX_FRAME_NUMBER 9999
#define MAX_FRAME_NAME_LENGTH 20

static int video_fd = -1;
static void *frame_buffer = NULL;
static size_t frame_size = 0;
static int frame_number = 0;
static int frame_count = 0;
static int buffer_count = 0;
static struct v4l2_buffer buffer;
static struct v4l2_requestbuffers req;
static struct v4l2_format fmt;
static struct v4l2_control ctrl;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static int gpio_fd = -1;
static int running = 1;

static void signal_handler(int signum) {
    running = 0;
    if (frame_buffer) {
        munmap(frame_buffer, frame_size);
    }
    if (video_fd != -1) {
        close(video_fd);
    }
    if (gpio_fd != -1) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

static void setup_camera() {
    video_fd = open(DEFAULT_VIDEO_DEVICE, O_RDWR);
    if (video_fd == -1) {
        perror("Failed to open video device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(video_fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query capabilities");
        close(video_fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(video_fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(video_fd);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(video_fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        close(video_fd);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        close(video_fd);
        exit(EXIT_FAILURE);
    }

    buffer_count = req.count;
    frame_size = fmt.fmt.pix.width * fmt.fmt.pix.height;

    for (int i = 0; i < buffer_count; i++) {
        memset(&buffer, 0, sizeof(buffer));
        buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffer.memory = V4L2_MEMORY_MMAP;
        buffer.index = i;

        if (ioctl(video_fd, VIDIOC_QUERYBUF, &buffer) == -1) {
            perror("Failed to query buffer");
            close(video_fd);
            exit(EXIT_FAILURE);
        }

        frame_buffer = mmap(NULL, buffer.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buffer.m.offset);
        if (frame_buffer == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(video_fd);
            exit(EXIT_FAILURE);
        }
    }

    if (ioctl(video_fd, VIDIOC_STREAMON, &fmt.type) == -1) {
        perror("Failed to start streaming");
        close(video_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_line_request_output(gpio_chip, "camera", 0);
    if (!gpio_line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_request_edge_event(gpio_line, "camera", GPIOD_EDGE_RISING);
    if (gpio_fd == -1) {
        perror("Failed to request GPIO edge event");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (frame_buffer) {
        munmap(frame_buffer, frame_size);
    }
    if (video_fd != -1) {
        close(video_fd);
    }
    if (gpio_fd != -1) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (argc > 1) {
        DEFAULT_VIDEO_DEVICE = argv[1];
    }

    setup_camera();
    setup_gpio();

    while (running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(video_fd, &readfds);
        FD_SET(gpio_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = 2;
        timeout.tv_usec = 0;

        int ret = select(video_fd + 1, &readfds, NULL, NULL, &timeout);
        if (ret == -1) {
            perror("Failed to select");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (FD_ISSET(video_fd, &readfds)) {
            if (ioctl(video_fd, VIDIOC_DQBUF, &buffer) == -1) {
                if (errno == EAGAIN) {
                    continue;
                }
                perror("Failed to dequeue buffer");
                cleanup();
                exit(EXIT_FAILURE);
            }

            char frame_name[MAX_FRAME_NAME_LENGTH];
            snprintf(frame_name, MAX_FRAME_NAME_LENGTH, "image_%04d.pgm", frame_number);

            FILE *file = fopen(frame_name, "wb");
            if (!file) {
                perror("Failed to open file");
                cleanup();
                exit(EXIT_FAILURE);
            }

            fwrite(frame_buffer, 1, frame_size, file);
            fclose(file);

            frame_number++;
            frame_count++;

            if (frame_count >= buffer_count) {
                frame_count = 0;
            }

            if (ioctl(video_fd, VIDIOC_QBUF, &buffer) == -1) {
                perror("Failed to queue buffer");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }

        if (FD_ISSET(gpio_fd, &readfds)) {
            if (gpiod_event_read(gpio_fd, NULL) == -1) {
                perror("Failed to read GPIO event");
                cleanup();
                exit(EXIT_FAILURE);
            }
            running = 0;
        }
    }

    cleanup();
    return 0;
}

