#define LOG_FILE "frame_log.txt"
#define MAX_FRAMES 1000
#define MAX_FRAME_SIZE 1024 * 1024

static int fd;
static int buffer_fd;
static void *buffer;
static struct v4l2_buffer buf;
static struct v4l2_requestbuffers req;
static struct v4l2_format fmt;
static struct v4l2_control ctrl;
static struct timespec ts;
static FILE *log_file;
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void init_video() {
    fd = open(DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open video device");
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set video format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        exit(EXIT_FAILURE);
    }

    buffer_fd = memfd_create("video_buffer", MFD_CLOEXEC);
    if (buffer_fd < 0) {
        perror("Failed to create memory-mapped file");
        close(fd);
        exit(EXIT_FAILURE);
    }

    buffer = mmap(NULL, req.count * BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, buffer_fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Failed to map memory");
        close(fd);
        close(buffer_fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Failed to query buffer");
            munmap(buffer, req.count * BUFFER_SIZE);
            close(buffer_fd);
            close(fd);
            exit(EXIT_FAILURE);
        }

        if (mmap(buffer + i * BUFFER_SIZE, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset) == MAP_FAILED) {
            perror("Failed to map buffer");
            munmap(buffer, req.count * BUFFER_SIZE);
            close(buffer_fd);
            close(fd);
            exit(EXIT_FAILURE);
        }
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        munmap(buffer, req.count * BUFFER_SIZE);
        close(buffer_fd);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Failed to start streaming");
        munmap(buffer, req.count * BUFFER_SIZE);
        close(buffer_fd);
        close(fd);
        exit(EXIT_FAILURE);
    }
}

static void capture_frame() {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        return;
    }

    if (buf.bytesused > MAX_FRAME_SIZE) {
        fprintf(stderr, "Frame size exceeds maximum allowed size\n");
        return;
    }

    time(&ts);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%s.%06lu", localtime(&ts));

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
    }
}

static void release_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (buffer) {
        munmap(buffer, req.count * BUFFER_SIZE);
    }
    if (buffer_fd) {
        close(buffer_fd);
    }
    if (fd) {
        close(fd);
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    init_video();

    while (running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        if (select(fd + 1, &readfds, NULL, NULL, NULL) < 0) {
            perror("Failed to select");
            break;
        }

        if (FD_ISSET(fd, &readfds)) {
            capture_frame();
        }
    }

    release_resources();
    return 0;
}

