#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <libgpiod.h>

#define BUFFER_COUNT 4
#define WIDTH 192
#define HEIGHT 1080
#define FILE_NAME "image.jpg"

static int fd;
static struct v4l2_capability cap;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers req;
static struct v4l2_buffer buf[BUFFER_COUNT];
static unsigned char *buffers[BUFFER_COUNT];
static int buffer_index = 0;
static int running = 1;

static void sig_handler(int signum) {
    running = 0;
}

int main() {
    int ret;
    struct sigaction sa;

    // Install signal handler
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    // Open the video device
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("open(/dev/video0)");
        return EXIT_FAILURE;
    }

    // Query device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set the pixel format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        buf[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf[i].memory = V4L2_MEMORY_MMAP;
        buf[i].index = i;
        ret = ioctl(fd, VIDIOC_QUERYBUF, &buf[i]);
        if (ret < 0) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            return EXIT_FAILURE;
        }
        buffers[i] = mmap(NULL, buf[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf[i].m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Queue buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        ret = ioctl(fd, VIDIOC_QBUF, &buf[i]);
        if (ret < 0) {
            perror("VIDIOC_QBUF");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMON, &type);
    if (ret < 0) {
        perror("VIDIOC_STREAMON");
        close(fd);
        return EXIT_FAILURE;
    }

    // Dequeue a single frame
    while (running) {
        ret = ioctl(fd, VIDIOC_DQBUF, &buf[buffer_index]);
        if (ret < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("VIDIOC_DQBUF");
            close(fd);
            return EXIT_FAILURE;
        }
        if (buf[buffer_index].bytesused > 0) {
            // Write the raw MJPEG bytes to a file
            FILE *file = fopen(FILE_NAME, "wb");
            if (file == NULL) {
                perror("fopen");
                close(fd);
                return EXIT_FAILURE;
            }
            fwrite(buffers[buffer_index], 1, buf[buffer_index].bytesused, file);
            fclose(file);
            printf("Frame written to %s\n", FILE_NAME);
        }
        buffer_index = (buffer_index + 1) % BUFFER_COUNT;
    }

    // Stop streaming
    ret = ioctl(fd, VIDIOC_STREAMOFF, &type);
    if (ret < 0) {
        perror("VIDIOC_STREAMOFF");
        close(fd);
        return EXIT_FAILURE;
    }

    // Unmap buffers
    for (int i = 0; i < BUFFER_COUNT; i++) {
        munmap(buffers[i], buf[i].length);
    }

    // Free the buffer array
    free(buffers);

    // Close the file
    fclose(file);

    // Close the device file descriptor
    close(fd);

    return EXIT_SUCCESS;
}

