        gpiod_line_release(left_line);
        gpiod_line_release(right_line);
        gpio_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize servos to mid-position
    gpio_set_pwm_duty_cycle(pan_fd, MID_POSITION);
    gpio_set_pwm_duty_cycle(tilt_fd, MID_POSITION);

    while (1) {
        // Poll button states
        up_pressed = gpiod_line_get_value(up_line);
        down_pressed = gpiod_line_get_value(down_line);
        left_pressed = gpiod_line_get_value(left_line);
        right_pressed = gpiod_line_get_value(right_line);

        // Adjust pan servo
        if (left_pressed) {
            pan_duty = MAX_POSITION;
        } else if (right_pressed) {
            pan_duty = MIN_POSITION;
        } else {
            pan_duty = MID_POSITION;
        }
        gpio_set_pwm_duty_cycle(pan_fd, pan_duty);

        // Adjust tilt servo
        if (up_pressed) {
            tilt_duty = MAX_POSITION;
        } else if (down_pressed) {
            tilt_duty = MIN_POSITION;
        } else {
            tilt_duty = MID_POSITION;
        }
        gpio_set_pwm_duty_cycle(tilt_fd, tilt_duty);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up resources
    gpio_unexport(4);
    gpio_unexport(5);
    gpio_unexport(up_line);
    gpio_unexport(down_line);
    gpio_unexport(left_line);
    gpio_unexport(right_line);
    gpio_chip_close(chip);

    return 0;
}
