int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_enum_framesizes fsize;
    struct v4l2_enum_frameinterval finterval;
    struct v4l2_queryctrl ctrl;
    int ret;

    // Open the CSI camera device node
    fd = open(CSI_CAMERA_NODE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open video device");
        return EXIT_FAILURE;
    }

    // Query the device capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if the device supports V4L2
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Enumerate all supported frame sizes
    fsize.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fsize.index = 0;
    while (1) {
        ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize);
        if (ret < 0) {
            perror("Failed to enumerate frame sizes");
            close(fd);
            return EXIT_FAILURE;
        }
        if (fsize.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            printf("Supported frame size: %ux%u\n", fsize.fmt.pix.width, fsize.fmt.pix.height);
        } else {
            break;
        }
        fsize.index++;
    }

    // Enumerate all available frame intervals for each frame size
    for (int i = 0; i < fsize.index; i++) {
        fsize.index = i;
        ret = ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fsize);
        if (ret < 0) {
            perror("Failed to enumerate frame sizes");
            close(fd);
            return EXIT_FAILURE;
        }
        printf("  Frame interval for %ux%u: %u/%u\n", fsize.fmt.pix.width, fsize.fmt.pix.height, fsize.fmt.pix.timeperframe.numerator, fsize.fmt.pix.timeperframe.denominator);
    }

    // Query the V4L2_CID_FOCUS_AUTO control
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    ret = ioctl(fd, VIDIOC_QUERYCTRL, &ctrl);
    if (ret < 0) {
        perror("Failed to query focus control");
        close(fd);
        return EXIT_FAILURE;
    }

    // Check if autofocus is supported
    if (ctrl.flags & V4L2_CTRL_FLAG_READ_ONLY) {
        printf("Autofocus is not supported\n");
    } else {
        printf("Autofocus is supported\n");
    }

    // Close the device
    close(fd);

    return EXIT_SUCCESS;
}

