#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9
#define PWM_FREQ 50
#define PWM_RANGE 1000
#define CENTER_POS 1500
#define MAX_POS 2000
#define MIN_POS 1000

static int pan_fd, tilt_fd;
static int pan_pos = CENTER_POS;
static int tilt_pos = CENTER_POS;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpio_set_line_value(pan_fd, GPIO_LINE_VALUE_LOW);
        gpio_set_line_value(tilt_fd, GPIO_LINE_VALUE_LOW);
        gpio_close(pan_fd);
        gpio_close(tilt_fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *pan_line, *tilt_line, *up_line, *down_line, *left_line, *right_line;

    // Initialize GPIO library
    chip = gpiochip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Open lines for servos and buttons
    pan_line = gpiochip_get_line(chip, PAN_PIN);
    tilt_line = gpiochip_get_line(chip, TILT_PIN);
    up_line = gpiochip_get_line(chip, UP_PIN);
    down_line = gpiochip_get_line(chip, DOWN_PIN);
    left_line = gpiochip_get_line(chip, LEFT_PIN);
    right_line = gpiochip_get_line(chip, RIGHT_PIN);

    if (!pan_line || !tilt_line || !up_line || !down_line || !left_line || !right_line) {
        perror("Failed to get GPIO lines");
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request lines for output
    ret = gpio_line_request_output(pan_line, "pan", 0);
    if (ret) {
        perror("Failed to request GPIO line for pan");
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpio_line_request_output(tilt_line, "tilt", 0);
    if (ret) {
        perror("Failed to request GPIO line for tilt");
        gpio_line_release(pan_line);
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request lines for input with pull-up
    ret = gpio_line_request_input(up_line, "up", GPIO_LINE_ACTIVE_LOW);
    if (ret) {
        perror("Failed to request GPIO line for up");
        gpio_line_release(pan_line);
        gpio_line_release(tilt_line);
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpio_line_request_input(down_line, "down", GPIO_LINE_ACTIVE_LOW);
    if (ret) {
        perror("Failed to request GPIO line for down");
        gpio_line_release(pan_line);
        gpio_line_release(tilt_line);
        gpio_line_release(up_line);
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpio_line_request_input(left_line, "left", GPIO_LINE_ACTIVE_LOW);
    if (ret) {
        perror("Failed to request GPIO line for left");
        gpio_line_release(pan_line);
        gpio_line_release(tilt_line);
        gpio_line_release(up_line);
        gpio_line_release(down_line);
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpio_line_request_input(right_line, "right", GPIO_LINE_ACTIVE_LOW);
    if (ret) {
        perror("Failed to request GPIO line for right");
        gpio_line_release(pan_line);
        gpio_line_release(tilt_line);
        gpio_line_release(up_line);
        gpio_line_release(down_line);
        gpio_line_release(left_line);
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up PWM for servos
    pan_fd = gpio_line_request_pwm(pan_line, "pan_pwm", PWM_FREQ, PWM_RANGE);
    if (pan_fd < 0) {
        perror("Failed to request PWM for pan");
        gpio_line_release(pan_line);
        gpio_line_release(tilt_line);
        gpio_line_release(up_line);
        gpio_line_release(down_line);
        gpio_line_release(left_line);
        gpio_line_release(right_line);
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    tilt_fd = gpio_line_request_pwm(tilt_line, "tilt_pwm", PWM_FREQ, PWM_RANGE);
    if (tilt_fd < 0) {
        perror("Failed to request PWM for tilt");
        gpio_line_release(pan_line);
        gpio_line_release(tilt_line);
        gpio_line_release(up_line);
        gpio_line_release(down_line);
        gpio_line_release(left_line);
        gpio_line_release(right_line);
        gpio_line_release(pan_fd);
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set initial positions
    gpio_line_set_value(pan_line, pan_pos);
    gpio_line_set_value(tilt_line, tilt_pos);

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        // Read button states
        int up = gpio_line_get_value(up_line);
        int down = gpio_line_get_value(down_line);
        int left = gpio_line_get_value(left_line);
        int right = gpio_line_get_value(right_line);

        // Adjust servo positions based on button presses
        if (up) {
            if (pan_pos < MAX_POS) {
                pan_pos += 10;
            }
        } else if (down) {
            if (pan_pos > MIN_POS) {
                pan_pos -= 10;
            }
        }

        if (left) {
            if (tilt_pos < MAX_POS) {
                tilt_pos += 10;
            }
        } else if (right) {
            if (tilt_pos > MIN_POS) {
                tilt_pos -= 10;
            }
        }

        // Set new positions
        gpio_line_set_value(pan_line, pan_pos);
        gpio_line_set_value(tilt_line, tilt_pos);

        // Delay
        usleep(50000);
    }

    // Clean up
    gpio_line_release(pan_line);
    gpio_line_release(tilt_line);
    gpio_line_release(up_line);
    gpio_line_release(down_line);
    gpio_line_release(left_line);
    gpio_line_release(right_line);
    gpio_line_release(pan_fd);
    gpio_line_release(tilt_fd);
    gpiochip_close(chip);

    return 0;
}

