#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIMEOUT 50
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"
#define IMAGE_FORMAT "%Y%m%d_%H%M%S_%3d.jpg"
#define CAPTURE_COMMAND "raspistill -o %s -w 640 -h 480 -q 85 -t 2000 -nopreview"

static int gpiod_chip = -1;
static int gpiod_line = -1;
static FILE *log_file = NULL;

static void log_message(const char *format, ...) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];
    va_list args;

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    va_start(args, format);
    fprintf(log_file, "%s: ", buffer);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    va_end(args);
}

static void handle_signal(int signum) {
    if (gpiod_chip != -1) {
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

static void capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), CAPTURE_COMMAND, filename);
    if (system(command) != 0) {
        log_message("Failed to capture image: %s", command);
    }
}

int main() {
    int ret;
    struct timespec ts;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        log_message("Failed to open GPIO chip: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request line
    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (gpiod_line < 0) {
        log_message("Failed to get GPIO line: %s", strerror(errno));
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    // Request input with edge-falling detection
    ret = gpiod_line_request_input(gpiod_line, "motion_sensor", GPIOD_EDGE_FALLING);
    if (ret < 0) {
        log_message("Failed to request GPIO line input: %s", strerror(errno));
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_message("Failed to open log file: %s", strerror(errno));
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Wait for edge-falling
        ret = gpiod_line_event_wait(gpiod_line, &ts);
        if (ret < 0) {
            log_message("Failed to wait for edge event: %s", strerror(errno));
            continue;
        }

        // Debounce
        struct timespec start = ts;
        struct timespec end;
        do {
            ret = gpiod_line_event_wait(gpiod_line, &end);
            if (ret < 0) {
                log_message("Failed to wait for edge event: %s", strerror(errno));
                break;
            }
        } while (difftime(end.tv_sec, start.tv_sec) < 0 || (difftime(end.tv_sec, start.tv_sec) == 0 && end.tv_nsec - start.tv_nsec < DEBOUNCE_TIMEOUT * 1000000));

        // Capture image
        char filename[128];
        time_t now;
        struct tm *tm_info;
        strftime(filename, sizeof(filename), IMAGE_FORMAT, &now);
        snprintf(filename, sizeof(filename), "%s/%s", IMAGE_DIR, filename);
        capture_image(filename);

        // Log success
        log_message("Captured image: %s", filename);
    }

    // Clean up
    gpiod_line_release(gpiod_chip, gpiod_line);
    gpiod_chip_close(gpiod_chip);
    fclose(log_file);

    return 0;
}

