#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <libgpiod.h>

#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define FIELD V4L2_FIELD_NONE
#define TIMEOUT 2000

static int fd;
static struct v4l2_capability cap;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers req;
static struct v4l2_buffer buf;
static struct v4l2_plane planes[1];
static char *buffer;
static int buffer_fd;
static int buffer_size;
static int buffer_index;
static int running = 1;

static void sig_handler(int signum) {
    running = 0;
    close(fd);
    munmap(buffer, buffer_size);
    fclose(buffer_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;
    struct sigaction sa;

    // Register signal handler
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open video device
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open video device");
        exit(EXIT_FAILURE);
    }

    // Query capabilities
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query capabilities");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Check if device supports UVC
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Set format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = FIELD;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to set format");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Request buffers
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("Failed to request buffers");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Map buffer
    planes[0].m.mem_offset = 0;
    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("Failed to query buffer");
        close(fd);
        exit(EXIT_FAILURE);
    }
    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("Failed to map buffer");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Queue buffer
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    ret = ioctl(fd, VIDIOC_QBUF, &buf);
    if (ret < 0) {
        perror("Failed to queue buffer");
        munmap(buffer, buffer_size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Start streaming
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMON, &buf.type);
    if (ret < 0) {
        perror("Failed to start streaming");
        munmap(buffer, buffer_size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Wait for frame
    while (running) {
        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = TIMEOUT / 1000;
        tv.tv_usec = (TIMEOUT % 1000) * 1000;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Failed to select");
            munmap(buffer, buffer_size);
            close(fd);
            exit(EXIT_FAILURE);
        }

        if (FD_ISSET(fd, &fds)) {
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            ret = ioctl(fd, VIDIOC_DQBUF, &buf);
            if (ret < 0) {
                perror("Failed to dequeue buffer");
                munmap(buffer, buffer_size);
                close(fd);
                exit(EXIT_FAILURE);
            }

            // Check format
            if (buf.fmt.pix.width != WIDTH || buf.fmt.pix.height != HEIGHT || buf.fmt.pix.pixelformat != PIXEL_FORMAT) {
                fprintf(stderr, "Buffer format mismatch\n");
                munmap(buffer, buffer_size);
                close(fd);
                exit(EXIT_FAILURE);
            }

            // Crop buffer
            buffer_fd = open("cropped.yuv", O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (buffer_fd < 0) {
                perror("Failed to open cropped.yuv");
                munmap(buffer, buffer_size);
                close(fd);
                exit(EXIT_FAILURE);
            }

            // Write cropped buffer
            ret = write(buffer_fd, buffer + buf.m.offset, WIDTH * HEIGHT * 2);
            if (ret < 0) {
                perror("Failed to write cropped.yuv");
                close(buffer_fd);
                munmap(buffer, buffer_size);
                close(fd);
                exit(EXIT_FAILURE);
            }

            close(buffer_fd);
        }
    }

    // Stop streaming
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ret = ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
    if (ret < 0) {
        perror("Failed to stop streaming");
        munmap(buffer, buffer_size);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Unmap buffer
    munmap(buffer, buffer_size);

    // Close file descriptor
    close(fd);

    return EXIT_SUCCESS;
}

