#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_RANGE 180
#define DELAY_MS 100

static int pan_servo_fd;
static int tilt_servo_fd;
static int pan_servo_value;
static int tilt_servo_value;

static void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
    }
    gpiochip_close(pan_servo_fd);
    gpiochip_close(tilt_servo_fd);
    exit(0);
}

static void set_servo_position(int fd, int pin, int value) {
    if (value < 0 || value > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid servo position %d\n", value);
        return;
    }
    int duty_cycle = (value * 1000) / PWM_RANGE;
    if (gpio_set_line_value(fd, pin, 1) < 0) {
        fprintf(stderr, "Error: Failed to set line value\n");
        return;
    }
    usleep(duty_cycle);
    gpio_set_line_value(fd, pin, 0);
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to set signal handler\n");
        return 1;
    }

    pan_servo_fd = gpiochip_open(0);
    if (pan_servo_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    tilt_servo_fd = gpiochip_open(0);
    if (tilt_servo_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        gpiochip_close(pan_servo_fd);
        return 1;
    }

    if (gpio_claim_line(pan_servo_fd, PAN_SERVO_PIN) < 0) {
        fprintf(stderr, "Error: Failed to claim line %d\n", PAN_SERVO_PIN);
        gpiochip_close(pan_servo_fd);
        gpiochip_close(tilt_servo_fd);
        return 1;
    }

    if (gpio_claim_line(tilt_servo_fd, TILT_SERVO_PIN) < 0) {
        fprintf(stderr, "Error: Failed to claim line %d\n", TILT_SERVO_PIN);
        gpiochip_close(pan_servo_fd);
        gpiochip_close(tilt_servo_fd);
        return 1;
    }

    if (gpio_set_line_config(pan_servo_fd, PAN_SERVO_PIN, GPIO_CONFIG_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set line configuration\n");
        gpiochip_close(pan_servo_fd);
        gpiochip_close(tilt_servo_fd);
        return 1;
    }

    if (gpio_set_line_config(tilt_servo_fd, TILT_SERVO_PIN, GPIO_CONFIG_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set line configuration\n");
        gpiochip_close(pan_servo_fd);
        gpiochip_close(tilt_servo_fd);
        return 1;
    }

    if (gpio_set_line_value(pan_servo_fd, PAN_SERVO_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set line value\n");
        gpiochip_close(pan_servo_fd);
        gpiochip_close(tilt_servo_fd);
        return 1;
    }

    if (gpio_set_line_value(tilt_servo_fd, TILT_SERVO_PIN, 1) < 0) {
        fprintf(stderr, "Error: Failed to set line value\n");
        gpiochip_close(pan_servo_fd);
        gpiochip_close(tilt_servo_fd);
        return 1;
    }

    usleep(1000000 / PWM_FREQUENCY);
    gpio_set_line_value(pan_servo_fd, PAN_SERVO_PIN, 0);
    gpio_set_line_value(tilt_servo_fd, TILT_SERVO_PIN, 0);

    pan_servo_value = 90;
    tilt_servo_value = 90;

    while (1) {
        char c = getchar();
        if (c == 'q') {
            break;
        } else if (c == 'w') {
            pan_servo_value = (pan_servo_value + 5) % (PWM_RANGE + 1);
        } else if (c == 's') {
            pan_servo_value = (pan_servo_value - 5 + (PWM_RANGE + 1)) % (PWM_RANGE + 1);
        } else if (c == 'a') {
            tilt_servo_value = (tilt_servo_value - 5 + (PWM_RANGE + 1)) % (PWM_RANGE + 1);
        } else if (c == 'd') {
            tilt_servo_value = (tilt_servo_value + 5) % (PWM_RANGE + 1);
        } else {
            fprintf(stderr, "Invalid key\n");
            continue;
        }

        set_servo_position(pan_servo_fd, PAN_SERVO_PIN, pan_servo_value);
        set_servo_position(tilt_servo_fd, TILT_SERVO_PIN, tilt_servo_value);

        usleep(DELAY_MS * 1000);
    }

    gpio_set_line_value(pan_servo_fd, PAN_SERVO_PIN, 0);
    gpio_set_line_value(tilt_servo_fd, TILT_SERVO_PIN, 0);

    gpiochip_close(pan_servo_fd);
    gpiochip_close(tilt_servo_fd);

    return 0;
}

