#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define LCD_ROWS 2
#define LCD_COLS 16

static volatile int running = 1;
static int gpio_fd;
static int i2c_fd;
static int lcd_fd;
static int flow_rate = 0;
static int total_volume = 0;
static int last_log_time = 0;
static int last_lcd_update_time = 0;

void handle_signal(int sig) {
    running = 0;
    gpio_close(gpio_fd);
    i2c_close(i2c_fd);
    lcd_close(lcd_fd);
    printf("Program terminated gracefully.\n");
    exit(0);
}

void init_gpio() {
    gpio_fd = gpio_open(0, 0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    i2c_fd = i2c_open(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C");
        gpio_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void init_lcd() {
    lcd_fd = lcd_open(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (lcd_fd < 0) {
        perror("Failed to open LCD");
        i2c_close(i2c_fd);
        gpio_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void log_data() {
    time_t now = time(NULL);
    if (now - last_log_time >= 1) {
        printf("Current Flow Rate: %d L/min\n", flow_rate);
        printf("Total Volume: %d L\n", total_volume);
        last_log_time = now;
    }
}

void update_lcd() {
    time_t now = time(NULL);
    if (now - last_lcd_update_time >= 10) {
        lcd_clear(lcd_fd);
        lcd_home(lcd_fd);
        lcd_string(lcd_fd, "Flow Rate: ");
        lcd_string(lcd_fd, itoa(flow_rate, NULL, 10));
        lcd_string(lcd_fd, " L/min");
        lcd_string(lcd_fd, "\n");
        lcd_string(lcd_fd, "Total Volume: ");
        lcd_string(lcd_fd, itoa(total_volume, NULL, 10));
        lcd_string(lcd_fd, " L");
        last_lcd_update_time = now;
    }
}

void read_flow_sensor() {
    int pulse_count = 0;
    struct timespec start, end;
    struct timespec diff;

    gpio_set_mode(gpio_fd, GPIO_PIN, GPIO_INPUT);
    gpio_set_edge(gpio_fd, GPIO_PIN, GPIO_RISING);

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (running) {
        gpio_wait_for_edge(gpio_fd, GPIO_PIN);
        clock_gettime(CLOCK_MONOTONIC, &end);
        diff.tv_sec = end.tv_sec - start.tv_sec;
        diff.tv_nsec = end.tv_nsec - start.tv_nsec;
        if (diff.tv_nsec < 0) {
            diff.tv_sec--;
            diff.tv_nsec += 1000000000;
        }
        pulse_count++;
        start = end;
    }

    gpio_set_mode(gpio_fd, GPIO_PIN, GPIO_OUTPUT);
    gpio_write(gpio_fd, GPIO_PIN, 1);

    flow_rate = pulse_count * 60 / 1000; // Assuming 1000 pulses per liter
    total_volume += flow_rate;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();
    init_lcd();

    while (running) {
        read_flow_sensor();
        log_data();
        update_lcd();
        usleep(1000000); // Sleep for 1 second
    }

    gpio_close(gpio_fd);
    i2c_close(i2c_fd);
    lcd_close(lcd_fd);

    return 0;
}

