To accomplish the task of reading a YF-S201 water flow sensor and displaying the flow rate and total volume on an HD44780 LCD, we will use the `libgpiod` library for GPIO operations and the `pigpio` library for I2C communication. Below is a complete C program that fulfills the specified requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define LCD_ROWS 2
#define LCD_COLS 16

static volatile int running = 1;
static int gpio_fd;
static int i2c_fd;
static int lcd_fd;
static int flow_rate = 0;
static int total_volume = 0;
static int last_log_time = 0;
static int last_lcd_update_time = 0;

void handle_signal(int sig) {
    running = 0;
    gpio_close(gpio_fd);
    i2c_close(i2c_fd);
    lcd_close(lcd_fd);
    printf("Program terminated gracefully.\n");
    exit(0);
}

void init_gpio() {
    gpio_fd = gpio_open(0, 0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
