        gpio_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

void log_data() {
    time_t now = time(NULL);
    if (now - last_log_time >= 1) {
        printf("Current Flow Rate: %d L/min\n", flow_rate);
        printf("Total Volume: %d L\n", total_volume);
        last_log_time = now;
    }
}

void update_lcd() {
    time_t now = time(NULL);
    if (now - last_lcd_update_time >= 10) {
