        lcd_string(lcd_fd, " L/min");
        lcd_string(lcd_fd, "\n");
        lcd_string(lcd_fd, "Total Volume: ");
        lcd_string(lcd_fd, itoa(total_volume, NULL, 10));
        lcd_string(lcd_fd, " L");
        last_lcd_update_time = now;
    }
}

void read_flow_sensor() {
    int pulse_count = 0;
    struct timespec start, end;
    struct timespec diff;

    gpio_set_mode(gpio_fd, GPIO_PIN, GPIO_INPUT);
    gpio_set_edge(gpio_fd, GPIO_PIN, GPIO_RISING);

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (running) {
        gpio_wait_for_edge(gpio_fd, GPIO_PIN);
        clock_gettime(CLOCK_MONOTONIC, &end);
        diff.tv_sec = end.tv_sec - start.tv_sec;
        diff.tv_nsec = end.tv_nsec - start.tv_nsec;
        if (diff.tv_nsec < 0) {
            diff.tv_sec--;
            diff.tv_nsec += 1000000000;
        }
        pulse_count++;
        start = end;
    }

    gpio_set_mode(gpio_fd, GPIO_PIN, GPIO_OUTPUT);
    gpio_write(gpio_fd, GPIO_PIN, 1);

    flow_rate = pulse_count * 60 / 1000; // Assuming 1000 pulses per liter
    total_volume += flow_rate;
