#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define LCD_LINE1 0x80
#define LCD_LINE2 0xC0
#define LCD_CLEAR 0x01
#define LCD_HOME 0x02
#define LCD_ENTRY_MODE 0x04
#define LCD_ENTRY_MODE_INCREMENT 0x02
#define LCD_DISPLAY_CONTROL 0x08
#define LCD_DISPLAY_CONTROL_DISPLAY_ON 0x04
#define LCD_DISPLAY_CONTROL_CURSOR_ON 0x02
#define LCD_DISPLAY_CONTROL_BLINK_ON 0x01
#define LCD_FUNCTION_SET 0x20
#define LCD_FUNCTION_SET_4BIT 0x04
#define LCD_FUNCTION_SET_2LINE 0x08
#define LCD_FUNCTION_SET_5x8DOTS 0x00
#define LCD_SET_CGRAM_ADDR 0x40
#define LCD_SET_DDRAM_ADDR 0x80

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_fd = -1;
static int lcd_initialized = 0;

void handle_signal(int sig) {
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    printf("Program terminated gracefully.\n");
    exit(0);
}

void init_gpiod() {
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (gpiod_line == -1) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_line_request_input(gpiod_line, "water_flow_sensor");
    if (ret != 0) {
        perror("Failed to request GPIO line");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_lcd() {
    if (lcd_initialized) {
        return;
    }

    // Send initialization commands to the LCD
    write_i2c(0x33); // Function set: 4-bit mode, 2 lines, 5x8 dots
    write_i2c(0x32); // Function set: 4-bit mode, 2 lines, 5x8 dots
    write_i2c(0x06); // Entry mode: increment, no shift
    write_i2c(0x0C); // Display control: display on, cursor off, blink off
    write_i2c(0x01); // Clear display

    lcd_initialized = 1;
}

void write_i2c(uint8_t data) {
    uint8_t buffer[2] = {0x80, data};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C");
        exit(EXIT_FAILURE);
    }
}

void display_message(const char *message) {
    init_lcd();
    write_i2c(LCD_LINE1);
    write_i2c(0x00); // Clear line
    write_i2c(message);
}

void display_flow_rate(float flow_rate) {
    char buffer[16];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    display_message(buffer);
}

void measure_flow_rate() {
    int pulse_count = 0;
    struct timespec start, end, diff;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (clock_gettime(CLOCK_MONOTONIC, &end) == 0) {
        if (gpiod_line_get_value(gpiod_line) == 1) {
            pulse_count++;
        }
        if (end.tv_sec - start.tv_sec >= 1) {
            break;
        }
    }

    float flow_rate = (pulse_count / 60.0) * 0.001; // Convert pulses to liters per minute
    display_flow_rate(flow_rate);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpiod();
    init_i2c();

    while (1) {
        measure_flow_rate();
        sleep(1); // Wait for 1 second
    }

    return 0;
}

