#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define ROW_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define COL_PINS {14, 15, 18, 23, 24, 25, 8, 7}
#define DELAY_MS 150

static gpiod_chip *chip;
static gpiod_line *row_lines[NUM_ROWS];
static gpiod_line *col_lines[NUM_COLS];

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
    printf("GPIO lines released.\n");
}

static void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW_PINS[i]);
        if (!row_lines[i]) {
            perror("Failed to get row line");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(row_lines[i], "row", 0)) {
            perror("Failed to request row line");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL_PINS[i]);
        if (!col_lines[i]) {
            perror("Failed to get column line");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(col_lines[i], "col", 1)) {
            perror("Failed to request column line");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    while (1) {
        for (int col = 0; col < NUM_COLS; col++) {
            // Clear the matrix by setting all column cathodes HIGH and all row anodes LOW
            for (int i = 0; i < NUM_ROWS; i++) {
                if (gpiod_line_set_value(row_lines[i], 0)) {
                    perror("Failed to set row line");
                    cleanup();
                    exit(EXIT_FAILURE);
                }
            }
            for (int i = 0; i < NUM_COLS; i++) {
                if (gpiod_line_set_value(col_lines[i], 1)) {
                    perror("Failed to set column line");
                    cleanup();
                    exit(EXIT_FAILURE);
                }
            }

            // Light the LEDs sequentially by setting the corresponding row anodes HIGH
            for (int i = 0; i < NUM_ROWS; i++) {
                if (gpiod_line_set_value(row_lines[i], 1)) {
                    perror("Failed to set row line");
                    cleanup();
                    exit(EXIT_FAILURE);
                }
                usleep(DELAY_MS * 1000);
            }

            // Set the current column cathode LOW
            if (gpiod_line_set_value(col_lines[col], 0)) {
                perror("Failed to set column line");
                cleanup();
                exit(EXIT_FAILURE);
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

