#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define LOG_FILE "biometric_log.txt"
#define MAX_READS 1000000
#define READ_INTERVAL_MS 500

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int sigint_received = 0;

static void sigint_handler(int signum) {
    sigint_received = 1;
}

static void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

static void log_read(const char *timestamp, int proximity, int ambient_light) {
    fprintf(log_file, "%s, %d, %d\n", timestamp, proximity, ambient_light);
}

static void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line) {
        gpiod_line_release(line);
    }
}

static int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

static int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        return -1;
    }
    line = gpiod_chip_get_line(chip, 17); // Assuming GPIO 17 is used for I2C SDA
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_input(line, "biometric_sensor") < 0) {
        log_error("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }
    return 0;
}

static int read_sensor() {
    uint8_t command = 0x01; // Start measurement
    if (write(i2c_fd, &command, 1) != 1) {
        log_error("Failed to write command to sensor");
        return -1;
    }
    usleep(100000); // Wait for measurement to complete

    uint8_t data[3];
    if (read(i2c_fd, data, 3) != 3) {
        log_error("Failed to read data from sensor");
        return -1;
    }

    int proximity = (data[0] << 8) | data[1];
    int ambient_light = (data[2] << 8) | data[3];

    return 0;
}

int main() {
    if (init_gpio() < 0) {
        return EXIT_FAILURE;
    }
    if (init_i2c() < 0) {
        close_resources();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        close_resources();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("Failed to set SIGINT handler");
        close_resources();
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    for (int i = 0; i < MAX_READS; i++) {
        if (sigint_received) {
            break;
        }
        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        if (read_sensor() < 0) {
            continue;
        }

        log_read(timestamp, proximity, ambient_light);

        usleep(READ_INTERVAL_MS * 1000);
    }

    close_resources();
    return EXIT_SUCCESS;
}

