#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 4
#define LED_LINE 17
#define POLL_INTERVAL 100000  // 100 ms in microseconds
#define LOG_FILE "proximity.log"

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, POLL_INTERVAL};
    struct timespec remaining_time;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *logfile;
    gpiod_chip *chip;
    gpiod_line *line;
    gpiod_line *led_line;

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        chip = gpiod_chip_open("the library's API call");
        if (!chip) {
            perror("Failed to open GPIO chip");
            exit(EXIT_FAILURE);
        }
    }

    // Request lines
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, LED_LINE);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request input and output modes
    ret = gpiod_line_request_input(line, "proximity_sensor");
    if (ret) {
        perror("Failed to request input mode for proximity sensor line");
        gpiod_line_release(line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led_line, "led");
    if (ret) {
        perror("Failed to request output mode for LED line");
        gpiod_line_release(line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    logfile = fopen(LOG_FILE, "a");
    if (!logfile) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read proximity sensor
        int value = gpiod_line_get_value(line);
        if (value == 0) {
            // Object detected
            time_t now = time(NULL);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            fprintf(logfile, "%s Object detected\n", timestamp);
            fflush(logfile);

            // Blink LED
            ret = gpiod_line_set_value(led_line, 1);
            if (ret) {
                perror("Failed to turn on LED");
            }
            usleep(100000);  // 100 ms
            ret = gpiod_line_set_value(led_line, 0);
            if (ret) {
                perror("Failed to turn off LED");
            }
        }

        // Sleep for 100 ms
        ret = nanosleep(&sleep_time, &remaining_time);
        if (ret) {
            perror("Failed to sleep");
        }
    }

    // Clean up
    fclose(logfile);
    gpiod_line_release(line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

