#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define PART_ID_REG 0x00
#define PROXIMITY_REG 0x01
#define AMBIENT_LIGHT_REG 0x02
#define RESET_REG 0x0F

#define LOG_FILE "biometric_data.log"
#define BUFFER_SIZE 1024

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *reset_line;
    int ret;

    // Initialize GPIO for reset
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    reset_line = gpiod_chip_get_line(chip, 17); // Assuming reset pin is GPIO 17
    if (!reset_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(reset_line, "Si1145 reset", 0);
    if (ret) {
        perror("Failed to request GPIO line");
        gpiod_line_release(reset_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Reset the sensor
    gpiod_line_set_value(reset_line, 1);
    usleep(100000); // Wait for reset to complete
    gpiod_line_set_value(reset_line, 0);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(reset_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Check PART_ID
    uint8_t part_id;
    ret = i2c_smbus_read_byte_data(i2c_fd, PART_ID_REG);
    if (ret < 0) {
        perror("Failed to read PART_ID");
        close(i2c_fd);
        gpiod_line_release(reset_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        close(i2c_fd);
        gpiod_line_release(reset_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(reset_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    while (!should_exit) {
        struct timespec sleep_time = {1, 0}; // 1 second
        nanosleep(&sleep_time, NULL);

        // Read proximity and ambient light
        uint8_t proximity_data[2];
        uint8_t ambient_light_data[2];
        ret = i2c_smbus_read_i2c_block_data(i2c_fd, PROXIMITY_REG, 2, proximity_data);
        if (ret < 0) {
            perror("Failed to read proximity data");
            continue;
        }

        ret = i2c_smbus_read_i2c_block_data(i2c_fd, AMBIENT_LIGHT_REG, 2, ambient_light_data);
        if (ret < 0) {
            perror("Failed to read ambient light data");
            continue;
        }

        // Format timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        // Write to log file
        fprintf(log_file, "%s, %d, %d\n", timestamp, proximity_data[0] << 8 | proximity_data[1], ambient_light_data[0] << 8 | ambient_light_data[1]);
        fflush(log_file);
    }

    // Cleanup
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(reset_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

