#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_MS 30000
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 15

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

static void log_distance(int distance) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    if (distance < 0) {
        fprintf(log_file, "%s,Error\n", timestamp);
    } else if (distance > MAX_DISTANCE_CM) {
        fprintf(log_file, "%s,Out of range\n", timestamp);
    } else if (distance < MIN_DISTANCE_CM) {
        fprintf(log_file, "%s,Time to water the plant!\n", timestamp);
    } else {
        fprintf(log_file, "%s,%d\n", timestamp, distance);
    }
}

static void handle_signal(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static int setup_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    struct gpiod_line *trigger_line = gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN);
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line");
        gpiod_chip_close(gpiod_ctx);
        return -1;
    }

    struct gpiod_line *echo_line = gpiod_chip_get_line(gpiod_ctx, ECHO_PIN);
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_ctx);
        return -1;
    }

    return 0;
}

static int measure_distance() {
    gpiod_line_set_value(gpiod_ctx, TRIGGER_PIN, 1);
    usleep(10000);
    gpiod_line_set_value(gpiod_ctx, TRIGGER_PIN, 0);

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (gpiod_line_get_value(gpiod_ctx, ECHO_PIN) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (difftime(end.tv_sec, start.tv_sec) * 1000000 + difftime(end.tv_nsec, start.tv_nsec) / 1000 > TIMEOUT_MS) {
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(gpiod_ctx, ECHO_PIN) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (difftime(end.tv_sec, start.tv_sec) * 1000000 + difftime(end.tv_nsec, start.tv_nsec) / 1000 > TIMEOUT_MS) {
            return -1;
        }
    }

    long duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    long distance_cm = duration / 58.2;

    return distance_cm;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (setup_gpio() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_chip_close(gpiod_ctx);
        return 1;
    }

    while (1) {
        int distance = measure_distance();
        log_distance(distance);

        sleep(60);
    }

    fclose(log_file);
    gpiod_chip_close(gpiod_ctx);

    return 0;
}

