    if (proximity > PROXIMITY_THRESHOLD) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        write_csv(timestamp, (int[]){red, green, blue}, proximity);
    }
}

