    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_gpio();
    init_csv();

    while (1) {
        read_apds9960();
        usleep(100000); // Sleep for 100 ms
    }

    fclose(csv_file);
    gpiod_chip_close(gpio_chip);
    gpiod_line_release(gpio_line);
    close(i2c_fd);

