#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_TRIGGER 17
#define TIMEOUT_MS 100
#define LOG_FILE "distance_log.txt"

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_trigger_line;

static void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

static void log_distance(unsigned long long timestamp, int distance_mm) {
    fprintf(log_file, "%llu,%d\n", timestamp, distance_mm);
    fflush(log_file);
}

static int read_distance() {
    unsigned char data[6];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x0F, 6, data);
    if (ret < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }

    unsigned long long timestamp = data[0] << 40 | data[1] << 32 | data[2] << 24 | data[3] << 16 | data[4] << 8 | data[5];
    int distance_mm = (data[0] << 8 | data[1]) & 0x3FFF;

    return distance_mm;
}

static int check_sensor_presence() {
    unsigned char data[2];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x01, 2, data);
    if (ret < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }

    return data[0] == 0x00 && data[1] == 0x00;
}

static void configure_trigger() {
    int ret;

    ret = gpiod_line_request_input(gpio_trigger_line, "trigger");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        exit(1);
    }

    ret = gpiod_line_set_value(gpio_trigger_line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        exit(1);
    }
}

static void wait_for_trigger() {
    int ret;

    ret = gpiod_line_event_wait(gpio_trigger_line, TIMEOUT_MS);
    if (ret < 0) {
        perror("gpiod_line_event_wait");
        exit(1);
    }
}

static void trigger_measurement() {
    int ret;

    ret = gpiod_line_set_value(gpio_trigger_line, 0);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        exit(1);
    }

    usleep(10000); // Wait for the sensor to process the measurement

    ret = gpiod_line_set_value(gpio_trigger_line, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        exit(1);
    }
}

int main() {
    int ret;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Request GPIO line
    gpio_trigger_line = gpiod_chip_get_line(gpio_chip, GPIO_TRIGGER);
    if (!gpio_trigger_line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    // Configure GPIO line
    configure_trigger();

    // Check sensor presence
    if (!check_sensor_presence()) {
        fprintf(stderr, "Sensor not found\n");
        exit(1);
    }

    // Main loop
    while (1) {
        // Wait for trigger
        wait_for_trigger();

        // Trigger measurement
        trigger_measurement();

        // Read distance
        int distance_mm = read_distance();
        if (distance_mm < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }

        // Log distance
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        log_distance(ts.tv_sec * 1000000 + ts.tv_nsec / 1000, distance_mm);
    }

    // Close I2C bus
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Release GPIO resources
    gpiod_line_release(gpio_trigger_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

