This C program uses the `libgpiod` library to handle GPIO operations and the `i2c-dev` library to communicate with the I2C bus. It checks the presence of the VL53L0X sensor, configures a falling-edge trigger on GPIO 17, waits for each trigger, triggers a single distance measurement, reads the distance, and logs it to a file in CSV format. The program handles errors and provides a graceful shutdown on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define LOG_FILE "distance_log.txt"
#define BUFFER_SIZE 20

static int gpiod_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        close(i2c_handle);
    }
    if (gpiod_handle != -1) {
        gpiod_chip_close(gpiod_handle);
    }
    exit(0);
}

static void init_gpiod() {
    gpiod_handle = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_handle == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
}

static void init_i2c() {
    i2c_handle = open("/dev/i2c-1", O_RDWR);
    if (i2c_handle == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_handle, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_handle);
        exit(EXIT_FAILURE);
    }
}

static void init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void close_logging() {
    if (log_file) {
        fclose(log_file);
    }
}

static void close_i2c() {
    if (i2c_handle != -1) {
        close(i2c_handle);
    }
}

static void close_gpiod() {
    if (gpiod_handle != -1) {
        gpiod_chip_close(gpiod_handle);
    }
}

static void write_trigger() {
    int ret = gpiod_line_set_value(gpiod_chip_get_line(gpiod_handle, TRIGGER_PIN), 1);
    if (ret == -1) {
        perror("Failed to set trigger pin high");
    }
    usleep(50000); // Wait for 50 ms
    ret = gpiod_line_set_value(gpiod_chip_get_line(gpiod_handle, TRIGGER_PIN), 0);
    if (ret == -1) {
        perror("Failed to set trigger pin low");
    }
}

static int read_distance() {
    uint8_t data[2];
    int ret = i2c_smbus_read_i2c_block_data(i2c_handle, 0x00, 2, data);
    if (ret == -1) {
        perror("Failed to read distance from I2C");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

static void log_distance(int distance) {
    char timestamp[BUFFER_SIZE];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(timestamp, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, %d\n", timestamp, distance);
    printf("%s, %d\n", timestamp, distance);
}

int main() {
    signal(SIGINT, handle_sigint);

    init_gpiod();
    init_i2c();
    init_logging();

    while (1) {
        write_trigger();
        int distance = read_distance();
        if (distance != -1) {
            log_distance(distance);
        }
        usleep(200000); // Wait for 200 ms
    }

    close_logging();
    close_i2c();
    close_gpiod();

    return 0;
}

