static void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_fd != -1) {
        close(led_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (led_line != NULL) {
