        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    int ret = gpiod_line_request_output(led_line, "distance_sensor", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set sample interval
    sample_interval.tv_sec = SAMPLE_INTERVAL_MS / 1000;
    sample_interval.tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000;

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

