            continue;
        }

        // Calculate distance in cm
        uint16_t distance = (data[0] << 8) | data[1];
        distance = distance * 0.034 / 2;

        // Log distance to file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
