        // Turn LED on if distance is below 20 cm
        if (distance < 20) {
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                perror("Failed to set LED on");
            }
        } else {
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                perror("Failed to set LED off");
            }
        }

        // Sleep for sample interval
        nanosleep(&sample_interval, NULL);
    }

    // Close log file
    fclose(log_file);

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

