#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define MAX_RETRIES 3
#define LOG_FILE "biometric_log.txt"

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Exiting...\n");
    exit(0);
}

static int read_i2c_register(int reg) {
    int retries = 0;
    uint8_t data[2];

    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_RDWR, &reg) < 0) {
            perror("ioctl(I2C_RDWR)");
            retries++;
            continue;
        }

        if (read(i2c_fd, data, 2) != 2) {
            perror("read");
            retries++;
            continue;
        }

        return data[0] << 8 | data[1];
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1;
}

static void write_i2c_register(int reg, int value) {
    int retries = 0;
    uint8_t data[3];

    data[0] = reg;
    data[1] = value >> 8;
    data[2] = value & 0xFF;

    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_RDWR, data) < 0) {
            perror("ioctl(I2C_RDWR)");
            retries++;
            continue;
        }

        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write register 0x%02X with value 0x%04X after %d retries\n", reg, value, MAX_RETRIES);
    }
