static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Exiting...\n");
    exit(0);
}

static int read_i2c_register(int reg) {
    int retries = 0;
    uint8_t data[2];

    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_RDWR, &reg) < 0) {
            perror("ioctl(I2C_RDWR)");
            retries++;
            continue;
        }

        if (read(i2c_fd, data, 2) != 2) {
            perror("read");
            retries++;
            continue;
        }

        return data[0] << 8 | data[1];
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1;
}

static void write_i2c_register(int reg, int value) {
    int retries = 0;
    uint8_t data[3];

    data[0] = reg;
    data[1] = value >> 8;
    data[2] = value & 0xFF;

    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_RDWR, data) < 0) {
            perror("ioctl(I2C_RDWR)");
            retries++;
            continue;
        }

