### Explanation:
- **I2C Initialization**: The program opens the I2C bus and sets the device address.
- **Configuration Registers**: The program writes configuration registers to enable proximity and ambient light interrupts and set the measurement range.
- **Reading Data**: The program reads the proximity and ambient light data from the sensor, handling retries if any read operation fails.
- **Logging**: Each reading is logged with a timestamp to the `biometric_log.txt` file.
- **SIGINT Handler**: The program installs a SIGINT handler to cleanly close the I2C bus and log file before exiting.
- **Main Loop**: The program continuously reads and logs data every 500 ms.

This code should be compiled and run on a Raspberry Pi Zero W with the `libgpiod` library installed. Make sure to install `libgpiod` using `sudo apt-get install libgpiod-dev` if it's not already installed.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LED_PIN 17
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"

static int gpiod_handle = -1;
static int i2c_fd = -1;
static int threshold = DEFAULT_THRESHOLD;
static FILE *log_file = NULL;

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_handle != -1) {
        gpiod_chip_close(gpiod_handle);
    }
    exit(0);
}

static void log_reading(unsigned int distance) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, %u\n", timestamp, distance);
}

static int read_distance() {
    unsigned char data[2];
    int ret;

    ret = i2c_smbus_read_word_data(i2c_fd, 0x00);
    if (ret < 0) {
        perror("i2c_smbus_read_word_data");
        return -1;
    }

    data[0] = ret >> 8;
    data[1] = ret & 0xFF;

    return (data[0] << 8) | data[1];
}

static int verify_who_am_i() {
    unsigned char data[2];
    int ret;

