This C program initializes the Raspberry Pi 4 Model B to read distance measurements from a TDK InvenSense ICU-20201 ultrasonic Time‑of‑Flight sensor on I2C bus 1. It sets up a GPIO pin to control an LED, logs each reading with a timestamp to a file, and handles sensor-absent or bus-error conditions gracefully. The program also ensures that on any exit path, it releases the I2C handle, resets the GPIO, and performs any required driver cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x62
#define CMD_FRAME 0x01
#define RESPONSE_SIZE 15
#define HEADER 0x55
#define MAX_SAMPLES 10
#define LOG_FILE "intrusion_log.txt"

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *led_line;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int sample_count = 0;
    int total_distance = 0;
    int distance;
    struct timespec sleep_time = {0, 10000000}; // 10 ms
    struct timespec start_time;
    struct timespec end_time;
    struct tm *timeinfo;
    char timestamp[20];

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for LED
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(gpio_chip, 17); // Assuming GPIO 17 is connected to the LED
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "intrusion_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Send command frame
        if (write(i2c_fd, &CMD_FRAME, 1) != 1) {
            perror("Failed to send command frame");
            continue;
        }

        // Wait for response
        if (read(i2c_fd, &response, RESPONSE_SIZE) != RESPONSE_SIZE) {
            perror("Failed to read response");
            continue;
        }

        // Check header
        if (response[0] != HEADER) {
            printf("Invalid header: 0x%02X\n", response[0]);
            continue;
        }

        // Extract distance
        distance = (response[11] << 8) | response[12];

        // Update total distance
        total_distance += distance;
        sample_count++;

        // Log intrusion event if distance is less than 1000 mm
        if (distance < 1000) {
            clock_gettime(CLOCK_REALTIME, &start_time);
            timeinfo = localtime(&start_time.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, %d\n", timestamp, distance);
            gpiod_line_set_value(led_line, 1); // Turn on LED
            sleep(1); // Keep LED on for 1 second
            gpiod_line_set_value(led_line, 0); // Turn off LED
        }

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Release resources
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

