This C program communicates with an Omron B5L‑LD50‑07050 3D TOF sensor over the I2C bus (/dev/i2c-1) to detect intrusion events within 1 meter and log the average distance. It sends a command frame to request a measurement, waits at least 10 ms before reading the response, verifies that byte 0 matches the documented header value, extracts the 16-bit big-endian distance from bytes 11 and 12, samples the sensor ten times per cycle with a 100 ms delay between cycles, computes the average distance, and when the average is less than 1000 mm writes a timestamp and the average distance to a file named intrusion_log.txt. The program handles sensor-absent (I2C NACK) and bus-error conditions, and installs a SIGINT handler so that pressing Ctrl-C closes the I2C file descriptor and any open log files and releases all resources on every exit path.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libi2c-dev/libi2c.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define VL53L0X_MODEL_ID_REGISTER 0x00
#define VL53L0X_MODEL_ID 0x1000

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *irq_line = NULL;

static void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (irq_line) {
        gpiod_line_release(irq_line);
    }
    exit(EXIT_FAILURE);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for interrupt
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    irq_line = gpiod_chip_get_line(chip, 17); // Assuming GPIO 17 is the interrupt line
    if (!irq_line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(irq_line, "VL53L0X")) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        gpiod_line_release(irq_line);
        exit(EXIT_FAILURE);
    }

    // Verify sensor presence
    uint16_t model_id;
    if (i2c_smbus_read_word_data(i2c_fd, VL53L0X_MODEL_ID_REGISTER) != VL53L0X_MODEL_ID) {
        fprintf(stderr, "Failed to read model ID from sensor\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(irq_line);
        exit(EXIT_FAILURE);
    }

    // Main loop
    struct timespec sleep_time = {0, 1000000}; // 100 ms
    struct timespec timeout = {0, 500000000}; // 500 ms
    struct tm now;
    time_t current_time;
    while (1) {
        if (gpiod_line_get_value(irq_line)) {
            // Interrupt received, read distance
            uint16_t distance;
            if (i2c_smbus_read_word_data(i2c_fd, 0x01)) {
                fprintf(stderr, "Failed to read distance from sensor: %s\n", strerror(errno));
                continue;
            }
            distance = i2c_smbus_read_word_data(i2c_fd, 0x01);
            current_time = time(NULL);
            localtime_r(&current_time, &now);
            printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
                   now.tm_year + 1900, now.tm_mon + 1, now.tm_mday,
                   now.tm_hour, now.tm_min, now.tm_sec, distance);
        }
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    close(i2c_fd);
    gpiod_chip_close(chip);
    gpiod_line_release(irq_line);

    return 0;
}

