#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define MLX75030_I2C_ADDR 0x50
#define MLX75030_REG_DISTANCE 0x00

static int i2c_fd = -1;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    // Open the I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open(/dev/i2c-1)");
        return EXIT_FAILURE;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_I2C_ADDR) == -1) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read the distance measurement
    uint16_t distance;
    if (read(i2c_fd, &distance, sizeof(distance)) != sizeof(distance)) {
        perror("read(distance)");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Print the distance measurement
    printf("Distance: %d mm\n", distance);

    // Enter a loop to read the distance every 500 ms
    struct timespec sleep_time = {0, 500000000};
    while (!should_exit) {
        if (read(i2c_fd, &distance, sizeof(distance)) != sizeof(distance)) {
            perror("read(distance)");
            continue;
        }
        printf("Distance: %d mm\n", distance);
        nanosleep(&sleep_time, NULL);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    return EXIT_SUCCESS;
}

