#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>

#define OPT3101_I2C_ADDR 0x44
#define OPT3101_I2C_BUS 1
#define OPT3101_I2C_CHANNEL 0
#define OPT3101_I2C_TIMEOUT 1000
#define LOG_INTERVAL_MS 500

static int gpiod_chip_fd = -1;
static int gpiod_line_fd = -1;
static int pigpio_handle = -1;
static int opt3101_i2c_handle = -1;

static void handle_sigint(int signum) {
    printf("Received SIGINT, shutting down...\n");
    cleanup();
    exit(0);
}

static void cleanup() {
    if (opt3101_i2c_handle != -1) {
        i2cClose(opt3101_i2c_handle);
    }
    if (pigpio_handle != -1) {
        gpioTerminate();
    }
    if (gpiod_line_fd != -1) {
        gpiod_line_close(gpiod_line_fd);
    }
    if (gpiod_chip_fd != -1) {
        gpiod_chip_close(gpiod_chip_fd);
    }
}

int main() {
    // Initialize GPIO
    if ((gpiod_chip_fd = gpiod_chip_open_by_name("gpiochip0")) < 0) {
        perror("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    if ((gpiod_line_fd = gpiod_line_request_by_offset(gpiod_chip_fd, 0, "opt3101_int")) < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if ((opt3101_i2c_handle = i2cOpen(OPT3101_I2C_BUS, OPT3101_I2C_ADDR, 0)) < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        cleanup();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Read distance measurement
        uint8_t data[3];
        if (i2cReadDevice(opt3101_i2c_handle, 0x00, data, 3) < 0) {
            perror("Failed to read from OPT3101");
            continue;
        }

        // Extract distance and ambient light values
        uint16_t distance = (data[0] << 8) | data[1];
        uint16_t ambient_light = (data[2] << 8) | data[3];

        // Check for error flags
        uint8_t error_flags = data[0] >> 6;
        if (error_flags & 0x01) {
            printf("Error: Distance measurement error\n");
        }
        if (error_flags & 0x02) {
            printf("Error: Ambient light measurement error\n");
        }

        // Log the data
        printf("Distance: %d mm, Ambient Light: %d lux\n", distance, ambient_light);

        // Sleep for the log interval
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Cleanup on exit
    cleanup();
    return 0;
}

