#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_TIMEOUT 200000  // 200 ms in microseconds
#define MAX_PULSE 38000    // 38 ms in microseconds
#define SAMPLE_RATE 1  // 1 read per second

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;

static void handle_signal(int signum) {
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request output mode for trigger line
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request input mode for echo line
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set echo line to 1kΩ resistor
    if (gpiod_line_set_value(echo_line, 1) < 0) {
        perror("Failed to set echo line to 1kΩ resistor");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    struct timespec start, end;
    struct timespec diff;
    long duration;

    while (1) {
        // Trigger the ultrasonic sensor
        gpiod_line_set_value(trigger_line, 1);
        usleep(10000);  // 10 µs trigger pulse
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo rising edge
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            diff.tv_sec = end.tv_sec - start.tv_sec;
            diff.tv_nsec = end.tv_nsec - start.tv_nsec;
            duration = diff.tv_sec * 1000000000 + diff.tv_nsec;
            if (duration > MAX_TIMEOUT) {
                fprintf(stderr, "Echo edge timeout\n");
                break;
            }
        }

        // Wait for echo falling edge
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            diff.tv_sec = end.tv_sec - start.tv_sec;
            diff.tv_nsec = end.tv_nsec - start.tv_nsec;
            duration = diff.tv_sec * 1000000000 + diff.tv_nsec;
            if (duration > MAX_TIMEOUT) {
                fprintf(stderr, "Echo edge timeout\n");
                break;
            }
        }

        // Calculate distance in centimeters
        if (duration > 0 && duration <= MAX_PULSE) {
            long distance = (duration / 2) * 0.0343;  // Speed of sound is 343 m/s
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            printf("%02d:%02d:%02d.%03ld %ld cm\n", tm->tm_hour, tm->tm_min, tm->tm_sec, diff.tv_nsec / 1000000, distance);
        } else {
            fprintf(stderr, "Invalid pulse duration\n");
        }

        // Sleep for 1 second
        sleep(SAMPLE_RATE);
    }

    // Release resources
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
