#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <errno.h>

#define UART_DEVICE "/dev/serial0"
#define MAGIC_WORD "IWR1443"
#define MAGIC_WORD_LENGTH 8
#define DATA_LENGTH 128
#define TARGET_DISTANCE_THRESHOLD 1.0
#define ALERT_GPIO 17
#define ALERT_DURATION 2
#define LOG_FILE "intrusion_log.csv"

static int uart_fd;
static int alert_gpio_fd;
static struct gpiod_chip *alert_gpio_chip;
static struct gpiod_line *alert_gpio_line;
static FILE *log_file;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(uart_fd);
        close(alert_gpio_fd);
        fclose(log_file);
        gpiod_chip_close(alert_gpio_chip);
        exit(EXIT_SUCCESS);
    }
}

static void init_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART device");
        exit(EXIT_FAILURE);
    }
    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &options);
}

static void init_alert_gpio() {
    alert_gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!alert_gpio_chip) {
        perror("Failed to open alert GPIO chip");
        exit(EXIT_FAILURE);
    }
    alert_gpio_line = gpiod_chip_get_line(alert_gpio_chip, ALERT_GPIO);
    if (!alert_gpio_line) {
        perror("Failed to get alert GPIO line");
        gpiod_chip_close(alert_gpio_chip);
        exit(EXIT_FAILURE);
    }
    int ret = gpiod_line_request_output(alert_gpio_line, "alert", 0);
    if (ret) {
        perror("Failed to request alert GPIO line");
        gpiod_chip_close(alert_gpio_chip);
        gpiod_line_release(alert_gpio_line);
        exit(EXIT_FAILURE);
    }
}

static void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void log_intrusion(const char *timestamp, float distance) {
    fprintf(log_file, "%s,%f\n", timestamp, distance);
    fflush(log_file);
}

static void activate_alert() {
    gpiod_line_set_value(alert_gpio_line, 1);
    usleep(ALERT_DURATION * 1000000);
    gpiod_line_set_value(alert_gpio_line, 0);
}

static void read_and_decode_data() {
    char buffer[DATA_LENGTH + MAGIC_WORD_LENGTH + 1];
    ssize_t bytes_read;
    while (1) {
        bytes_read = read(uart_fd, buffer, DATA_LENGTH + MAGIC_WORD_LENGTH + 1);
        if (bytes_read == -1) {
            perror("Failed to read from UART");
            break;
        }
        if (bytes_read < DATA_LENGTH + MAGIC_WORD_LENGTH) {
            continue;
        }
        if (strncmp(buffer, MAGIC_WORD, MAGIC_WORD_LENGTH) != 0) {
            continue;
        }
        for (int i = 0; i < DATA_LENGTH; i += 2) {
            uint16_t distance = (buffer[i + 1] << 8) | buffer[i];
            if (distance <= TARGET_DISTANCE_THRESHOLD * 1000) {
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", tm);
                log_intrusion(timestamp, distance / 1000.0);
                activate_alert();
                break;
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_uart();
    init_alert_gpio();
    init_log_file();

    read_and_decode_data();

    fclose(log_file);
    gpiod_chip_close(alert_gpio_chip);
    gpiod_line_release(alert_gpio_line);
    close(uart_fd);

    return EXIT_SUCCESS;
}

