#include <gpiod.h>

#define GPIO_SENSOR 17
#define GPIO_BUZZER 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL 100000  // 100 ms in microseconds

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
}

int main() {
    int chip_fd, line_sensor, line_buzzer;
    struct timespec sleep_time;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *log_file;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    line_sensor = gpiod_chip_get_line(chip_fd, GPIO_SENSOR);
    if (line_sensor < 0) {
        perror("Failed to request GPIO line for sensor");
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    line_buzzer = gpiod_chip_get_line(chip_fd, GPIO_BUZZER);
    if (line_buzzer < 0) {
        perror("Failed to request GPIO line for buzzer");
        gpiod_line_release(line_sensor);
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Set line direction
    if (gpiod_line_request_input(line_sensor, "obstacle_sensor") < 0) {
        perror("Failed to set GPIO line direction for sensor");
        gpiod_line_release(line_sensor);
        gpiod_line_release(line_buzzer);
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line_buzzer, "obstacle_buzzer", 0) < 0) {
        perror("Failed to set GPIO line direction for buzzer");
        gpiod_line_release(line_sensor);
        gpiod_line_release(line_buzzer);
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(line_sensor);
        gpiod_line_release(line_buzzer);
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read sensor state
        int sensor_state = gpiod_line_get_value(line_sensor);
        if (sensor_state < 0) {
            perror("Failed to read GPIO line value for sensor");
            gpiod_line_release(line_sensor);
            gpiod_line_release(line_buzzer);
            gpiod_chip_close(chip_fd);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Get current time
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Log state transition
        if (sensor_state == 0) {
            fprintf(log_file, "%s: Obstacle detected\n", timestamp);
            gpiod_line_set_value(line_buzzer, 1);
        } else {
            fprintf(log_file, "%s: Obstacle removed\n", timestamp);
            gpiod_line_set_value(line_buzzer, 0);
        }

        // Sleep for 100 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line_sensor);
    gpiod_line_release(line_buzzer);
    gpiod_chip_close(chip_fd);
    fclose(log_file);

    return 0;
}

