#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ALERT_PIN 17
#define LOG_FILE "distance_log.txt"
#define MAX_DISTANCE 200.0
#define MIN_DISTANCE 10.0
#define LOG_INTERVAL 100000  // 100 ms

static int i2c_fd;
static int alert_gpio;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void handle_signal(int sig) {
    should_exit = 1;
}

static void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file);
}

static void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_gpio() {
    alert_gpio = gpiochip_open("gpiochip0");
    if (alert_gpio < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpio_claim_line(alert_gpio, ALERT_PIN) < 0) {
        perror("Failed to claim GPIO line");
        gpiochip_close(alert_gpio);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    gpio_direction_output(alert_gpio, 0);
}

static void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (alert_gpio >= 0) {
        gpio_direction_output(alert_gpio, 0);
        gpio_unclaim_line(alert_gpio);
        gpiochip_close(alert_gpio);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void read_distance() {
    uint8_t command = 0x01;  // Start measurement
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write to I2C");
        return;
    }
    usleep(100000);  // Wait for measurement to complete

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C");
        return;
    }

    uint16_t distance = (data[0] << 8) | data[1];
    double distance_cm = distance * 0.034 / 2.0;

    if (distance_cm < MIN_DISTANCE) {
        gpio_set_value(alert_gpio, 1);
    } else {
        gpio_set_value(alert_gpio, 0);
    }

    log_distance(distance_cm);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_gpio();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close_resources();
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        read_distance();
        usleep(LOG_INTERVAL);
    }

    close_resources();
    return 0;
}

