#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_PIN 18
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_fd = -1;
static struct gpiod_chip *led_chip;
static struct gpiod_line *led_line;

static void sig_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
    }
    exit(signum);
}

static void setup_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_led() {
    led_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!led_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(led_chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "ultrasonic_sensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void write_i2c(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    int retries = MAX_RETRIES;
    while (retries--) {
        if (write(i2c_fd, buf, 2) == 2) {
            return;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    perror("Failed to write to I2C");
    close(i2c_fd);
    gpiod_chip_close(led_chip);
    exit(EXIT_FAILURE);
}

static uint8_t read_i2c(uint8_t reg) {
    uint8_t buf[1] = {reg};
    int retries = MAX_RETRIES;
    while (retries--) {
        if (write(i2c_fd, buf, 1) == 1) {
            if (read(i2c_fd, buf, 1) == 1) {
