    }
    perror("Failed to read from I2C");
    close(i2c_fd);
    gpiod_chip_close(led_chip);
    exit(EXIT_FAILURE);
}

static void measure_distance() {
    write_i2c(0x00, 0x01); // Start measurement
    usleep(10000); // Wait for measurement to complete
    uint8_t distance_high = read_i2c(0x01);
    uint8_t distance_low = read_i2c(0x02);
    uint16_t distance = (distance_high << 8) | distance_low;
    printf("%ld: %d mm\n", time(NULL), distance);
    if (distance < 1000) {
        int blink_frequency = 1000 / distance;
        for (int i = 0; i < blink_frequency / 2; i++) {
            gpiod_line_set_value(led_line, 1);
            usleep(500);
            gpiod_line_set_value(led_line, 0);
            usleep(500);
        }
    }
