#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN_1 17
#define GPIO_PIN_2 27
#define DEBOUNCE_DELAY 50
#define LOG_FILE "proximity_log.txt"
#define MAX_LOG_LINE_LENGTH 100

static int gpio_fd;
static FILE *log_file;
static int sensor1_state = 0;
static int sensor2_state = 0;

static void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    char log_line[MAX_LOG_LINE_LENGTH];
    snprintf(log_line, sizeof(log_line), "%s,%d,%s\n", timestamp, sensor_id, event_type);
    if (fprintf(log_file, "%s", log_line) < 0) {
        perror("Error writing to log file");
    }
}

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    exit(0);
}

static void setup_gpio() {
    const char *chip_name = "gpiochip0";
    gpio_fd = gpiod_chip_open(chip_name);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    struct gpiod_line *line1 = gpiod_chip_get_line(gpio_fd, GPIO_PIN_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(gpio_fd, GPIO_PIN_2);
    if (!line1 || !line2) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(gpio_fd);
        exit(1);
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    if (gpiod_line_request_input(line1, "sensor1", flags) < 0) {
        perror("Failed to request GPIO line 1");
        gpiod_line_release(line1);
        gpiod_chip_close(gpio_fd);
        exit(1);
    }
    if (gpiod_line_request_input(line2, "sensor2", flags) < 0) {
        perror("Failed to request GPIO line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(gpio_fd);
        exit(1);
    }
}

static void release_gpio() {
    gpiod_line_release(gpio_fd);
    gpiod_chip_close(gpio_fd);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        release_gpio();
        exit(1);
    }

    while (1) {
        usleep(10000); // Poll every 10 ms

        int line1_state = gpiod_line_get_value(gpio_fd, GPIO_PIN_1);
        int line2_state = gpiod_line_get_value(gpio_fd, GPIO_PIN_2);

        if (line1_state != sensor1_state) {
            sensor1_state = line1_state;
            if (sensor1_state) {
                log_event(1, "DETECTED");
            } else {
                log_event(1, "CLEARED");
            }
        }

        if (line2_state != sensor2_state) {
            sensor2_state = line2_state;
            if (sensor2_state) {
                log_event(2, "DETECTED");
            } else {
                log_event(2, "CLEARED");
            }
        }

        usleep(DEBOUNCE_DELAY * 1000); // Software debounce
    }

    release_gpio();
    fclose(log_file);
    return 0;
}

