#define RETRY_DELAY 10

// Function to read a byte from the I2C bus
int i2c_read_byte(int fd, uint8_t reg) {
    int retries = 0;
    int result;

    do {
        result = pigpio_i2c_read_byte(fd, reg);
        if (result >= 0) {
            return result;
        }
        usleep(RETRY_DELAY * 1000);
        retries++;
    } while (retries < MAX_RETRIES);

    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

// Function to write a byte to the I2C bus
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    do {
        result = pigpio_i2c_write_byte(fd, reg, value);
        if (result >= 0) {
            return result;
        }
        usleep(RETRY_DELAY * 1000);
        retries++;
    } while (retries < MAX_RETRIES);

    fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
    return -1;
}

// Function to read a 16-bit word from the I2C bus
int i2c_read_word(int fd, uint8_t reg) {
    int retries = 0;
    int result;
    uint8_t data[2];

    do {
        result = pigpio_i2c_read_word_data(fd, reg, data);
        if (result >= 0) {
            return (data[0] << 8) | data[1];
        }
        usleep(RETRY_DELAY * 1000);
        retries++;
    } while (retries < MAX_RETRIES);

    fprintf(stderr, "I2C read word failed after %d retries\n", MAX_RETRIES);
    return -1;
}

