    gpioTerminate();
    exit(0);
}

int main() {
    int fd;
    int retries = 0;
    int result;
    uint16_t distance;
    struct timespec ts;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize I2C
    fd = pigpio_i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
