        result = i2c_read_word(fd, 0x00); // Assuming the distance is stored in register 0x00
        if (result < 0) {
            fprintf(stderr, "Failed to read distance\n");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Too many retries, exiting\n");
                gpioTerminate();
                return 1;
            }
            continue;
        }

