### Explanation:

1. **GPIO Initialization**: The program initializes the GPIO library using `gpioInitialise()`. This is necessary for any GPIO-related operations.

2. **I2C Initialization**: The program opens the I2C bus using `pigpio_i2c_open()`. It specifies the I2C bus number and the sensor's I2C address.

3. **Signal Handling**: A signal handler is set up for `SIGINT` (Ctrl-C) to gracefully terminate the program when the user interrupts it.

4. **Main Loop**: The program enters a loop where it reads the distance measurement from the sensor. If the read operation fails, it retries up to three times with a 10 ms delay between attempts.

5. **Timestamping**: The current time is obtained using `clock_gettime()` and printed along with the distance measurement.

6. **Sleep**: The program sleeps for 100 ms between each measurement.

7. **Resource Cleanup**: On exit, the I2C handle is closed using `pigpio_i2c_close()`, and the GPIO library is terminated using `gpioTerminate()`.

This program ensures that the sensor is properly initialized, handles I2C errors, and provides a clean shutdown on `SIGINT`.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libvl53l4cx.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define INTERRUPT_PIN 23
#define POLL_INTERVAL_MS 500

static int i2c_fd;
static struct vl53l4cx_dev *dev;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

static void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (dev) {
        vl53l4cx_close(dev);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize VL53L4CX
    dev = vl53l4cx_open(i2c_fd, I2C_ADDRESS);
    if (!dev) {
        perror("Failed to open VL53L4CX device");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO for interrupt
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        vl53l4cx_close(dev);
        close(i2c_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip, INTERRUPT_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        vl53l4cx_close(dev);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_input(line, "VL53L4CX interrupt")) {
        perror("Failed to request GPIO line input");
        gpiod_chip_close(chip);
        vl53l4cx_close(dev);
        close(i2c_fd);
        return 1;
    }

    // Start continuous ranging
    if (vl53l4cx_start_ranging(dev)) {
        perror("Failed to start ranging");
        gpiod_line_release_input(line);
        gpiod_chip_close(chip);
        vl53l4cx_close(dev);
        close(i2c_fd);
        return 1;
    }

    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec start_time;
    struct tm tm;
    char timestamp[20];

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Poll interrupt status
        uint8_t interrupt_status;
        if (gpiod_line_get_value(line, &interrupt_status)) {
            perror("Failed to read interrupt status");
            continue;
        }

        // Check if interrupt is set
        if (interrupt_status & VL53L4CX_INTERRUPT_STATUS_VALID_RANGE) {
            // Read distance
            uint16_t distance_mm;
            if (vl53l4cx_get_distance(dev, &distance_mm)) {
                perror("Failed to read distance");
                continue;
            }

            // Get current time
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            localtime_r(&start_time.tv_sec, &tm);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06lu", &tm);
            start_time.tv_nsec /= 1000; // Convert to microseconds

            // Log distance
            printf("%s, Distance: %d mm\n", timestamp, distance_mm);
        }

        // Wait for next poll interval
        nanosleep(&poll_interval, NULL);
    }

    // Stop continuous ranging
    vl53l4cx_stop_ranging(dev);

    // Clean up
    gpiod_line_release_input(line);
    gpiod_chip_close(chip);
    vl53l4cx_close(dev);
    close(i2c_fd);

    return 0;
}

