#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define LOG_FILE "sensor_data.log"
#define TIMEOUT_MS 50
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90
#define SAMPLE_RATE_MS 200

static int gpiod_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t should_stop = 0;

static void sig_handler(int signum) {
    should_stop = 1;
}

static void log_distance(int distance) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file, "%ld.%09ld,%d\n", (long)ts.tv_sec, (long)ts.tv_nsec / 1000, distance);
}

static int read_distance() {
    int trigger_pulse = 10; // 10 microseconds
    int echo_duration = 0;
    int distance = -1;

    // Trigger pulse
