        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        printf("Buzzer turned off and resources released.\n");
        exit(0);
    }
}

static void setup_interrupts() {
    struct gpiod_line_request_config config = {
        .flags = GPIOD_LINE_REQUEST_FLAG_EDGE_RISING,
    };

    trigger_fd = gpiod_line_request_edge_event(trigger_line, "trigger", &config);
    if (trigger_fd < 0) {
        perror("Failed to request trigger line event");
        exit(EXIT_FAILURE);
    }

    echo_fd = gpiod_line_request_edge_event(echo_line, "echo", &config);
    if (echo_fd < 0) {
        perror("Failed to request echo line event");
        gpiod_line_release(trigger_line);
        exit(EXIT_FAILURE);
    }
}

static void measure_distance() {
    struct timespec start, end;
    long long duration_ns;

    // Send a 10 µs HIGH pulse on the trigger pin
    gpiod_line_set_value(trigger_line, 1);
    usleep(10);
    gpiod_line_set_value(trigger_line, 0);

    // Wait for the echo pin to go HIGH
    if (gpiod_line_event_wait(echo_line, &event, TIMEOUT) < 0) {
        printf("Timeout: No echo received.\n");
        return;
    }

    // Read the start time
    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("Failed to get start time");
        return;
    }

    // Wait for the echo pin to go LOW
    if (gpiod_line_event_wait(echo_line, &event, TIMEOUT) < 0) {
        printf("Timeout: No echo received.\n");
        return;
    }

    // Read the end time
    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        perror("Failed to get end time");
        return;
    }

    // Calculate the duration
    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);

    // Convert duration to distance in centimeters
    distance = (int)(duration_ns / 58.26);

    // Check for valid reading
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        printf("Invalid reading: %d cm\n", distance);
        return;
    }

    // Turn on buzzer if distance is less than 30 cm
    if (distance < 30) {
        if (buzzer_state == 0) {
            gpiod_line_set_value(buzzer_line, 1);
            buzzer_state = 1;
        }
    } else {
        if (buzzer_state == 1) {
            gpiod_line_set_value(buzzer_line, 0);
            buzzer_state = 0;
        }
    }

    printf("Distance: %d cm\n", distance);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, handle_interrupt);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the GPIO lines to output mode
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to set trigger line to output");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to set buzzer line to output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the GPIO lines to input mode
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Failed to set echo line to input");
        gpiod_line_release(buzzer_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Setup interrupts
    setup_interrupts();

    // Main loop
    while (1) {
        measure_distance();
        usleep(100000); // 100 ms delay
    }

    // Clean up
    gpiod_line_release(buzzer_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return 0;
}
