#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define SG90_PWM_FREQ 50
#define SG90_MIN_PULSE_WIDTH 1000
#define SG90_MAX_PULSE_WIDTH 2000
#define SG90_CENTER_PULSE_WIDTH 1500
#define MAX_RETRIES 5
#define LOG_FILE "gate_log.txt"

static int i2c_fd;
static int servo_fd;
static int gate_open = 0;
static int gate_closed = 1;
static int gate_status = gate_closed;
static int retries = 0;

static void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s - %s\n", buffer, event);
    fclose(log_file);
}

static void handle_signal(int signum) {
    log_event("Received signal, cleaning up and exiting");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (servo_fd >= 0) {
        gpioPWMWrite(servo_fd, 0);
        gpioClose(servo_fd);
    }
    exit(EXIT_SUCCESS);
}

static void i2c_init() {
    retries = 0;
    while (retries < MAX_RETRIES) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C device");
            retries++;
            sleep(1);
            continue;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            retries++;
            sleep(1);
            continue;
        }
        log_event("I2C initialized successfully");
        break;
    }
    if (retries == MAX_RETRIES) {
        log_event("Failed to initialize I2C after multiple attempts");
        exit(EXIT_FAILURE);
    }
}

static void i2c_reset() {
    uint8_t reset_cmd = 0x01;
    if (write(i2c_fd, &reset_cmd, 1) != 1) {
        perror("Failed to send reset command");
        exit(EXIT_FAILURE);
    }
    log_event("VL53L1X reset sent");
}

static void i2c_start_ranging() {
    uint8_t start_ranging_cmd = 0x01;
    if (write(i2c_fd, &start_ranging_cmd, 1) != 1) {
        perror("Failed to start ranging");
        exit(EXIT_FAILURE);
    }
    log_event("VL53L1X ranging started");
}

static void i2c_read_distance() {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read distance");
        exit(EXIT_FAILURE);
    }
    int distance = (data[0] << 8) | data[1];
    log_event("Distance read: %d cm", distance);
    return distance;
}

static void servo_init() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    servo_fd = gpioServo(18, SG90_CENTER_PULSE_WIDTH);
    if (servo_fd < 0) {
        perror("Failed to initialize servo");
        exit(EXIT_FAILURE);
    }
    log_event("Servo initialized successfully");
}

static void servo_open() {
    gpioPWMWrite(servo_fd, SG90_MAX_PULSE_WIDTH);
    log_event("Gate opened");
    gate_open = 1;
    gate_closed = 0;
    gate_status = gate_open;
}

static void servo_close() {
    gpioPWMWrite(servo_fd, SG90_MIN_PULSE_WIDTH);
    log_event("Gate closed");
    gate_open = 0;
    gate_closed = 1;
    gate_status = gate_closed;
}

static void servo_set_position(int position) {
    gpioPWMWrite(servo_fd, position);
    log_event("Servo set to position: %d", position);
}

static void handle_v2_callback(int cmd) {
    switch (cmd) {
        case 0x01:
            servo_open();
            break;
        case 0x02:
            servo_close();
            break;
        case 0x03:
            log_event("Status request received");
            break;
        default:
            log_event("Unknown command received");
            break;
    }
}

static void main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init();
    i2c_reset();
    i2c_start_ranging();
    servo_init();

    while (1) {
        int distance = i2c_read_distance();
        if (distance < 20) {
            if (gate_status != gate_open) {
                servo_open();
            }
        } else {
            if (gate_status != gate_closed) {
                servo_close();
            }
        }
        sleep(1);
    }

    log_event("Exiting program");
    close(i2c_fd);
    gpioPWMWrite(servo_fd, 0);
    gpioClose(servo_fd);
    exit(EXIT_SUCCESS);
}

