#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SAMPLE_RATE 5  // Hz
#define TIMEOUT 60000  // ms
#define MIN_PULSE_WIDTH 100  // µs
#define MAX_PULSE_WIDTH 30000  // µs

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

static void handle_interrupt(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static void log_distance(int pulse_width) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(log_file, "%s,%.3f\n", timestamp, (double)pulse_width / 1000.0);
    fflush(log_file);
}

static void alert_callback(const struct gpiod_line_event *event) {
    static uint32_t rising_tick = 0;
    static uint32_t falling_tick = 0;
    static int first_event = 1;

    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        rising_tick = event->timestamp;
        first_event = 1;
    } else if (event->type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        falling_tick = event->timestamp;
        if (first_event) {
            first_event = 0;
            return;
        }

        uint32_t pulse_width = falling_tick - rising_tick;
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Warning: Invalid pulse width: %u µs\n", pulse_width);
            return;
        }

        int distance = pulse_width / 58.2;  // Convert pulse width to distance in cm
        log_distance(pulse_width);

        if (falling_tick - rising_tick > TIMEOUT) {
            fprintf(stderr, "Warning: Timeout waiting for echo\n");
        }
    }
}

int main() {
    // Initialize GPIO library
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig_line = gpiod_chip_get_line(gpiod_ctx, TRIG_PIN);
    if (trig_line == NULL) {
        perror("Failed to get TRIG line");
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo_line = gpiod_chip_get_line(gpiod_ctx, ECHO_PIN);
    if (echo_line == NULL) {
        perror("Failed to get ECHO line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Request output mode for TRIG
    if (gpiod_line_request_output(trig_line, "TRIG", 0) != 0) {
        perror("Failed to request TRIG line as output");
        gpiod_line_release(trig_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Request input mode for ECHO with pull-down
    if (gpiod_line_request_input(echo_line, "ECHO", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        perror("Failed to request ECHO line as input with pull-down");
        gpiod_line_release(trig_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Set up interrupt on ECHO
    struct gpiod_line_event_config config = {
        .flags = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE,
        .event_handler = alert_callback,
    };
    if (gpiod_line_request_event(echo_line, &config) != 0) {
        perror("Failed to request ECHO line event");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    // Main loop
    while (1) {
        // Generate 10 µs trigger pulse every 200 ms
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);
        usleep(190);

        // Wait for 200 ms
        usleep(200000);
    }

    // Clean up
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return EXIT_SUCCESS;
}

