        perror("Failed to get TRIG line");
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo_line = gpiod_chip_get_line(gpiod_ctx, ECHO_PIN);
    if (echo_line == NULL) {
        perror("Failed to get ECHO line");
        gpiod_line_release(trig_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Request output mode for TRIG
    if (gpiod_line_request_output(trig_line, "TRIG", 0) != 0) {
        perror("Failed to request TRIG line as output");
        gpiod_line_release(trig_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Request input mode for ECHO with pull-down
    if (gpiod_line_request_input(echo_line, "ECHO", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) != 0) {
        perror("Failed to request ECHO line as input with pull-down");
        gpiod_line_release(trig_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Set up interrupt on ECHO
    struct gpiod_line_event_config config = {
        .flags = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE,
        .event_handler = alert_callback,
    };
    if (gpiod_line_request_event(echo_line, &config) != 0) {
        perror("Failed to request ECHO line event");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(trig_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    // Main loop
    while (1) {
        // Generate 10 µs trigger pulse every 200 ms
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);
        usleep(190);

        // Wait for 200 ms
        usleep(200000);
    }

    // Clean up
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return EXIT_SUCCESS;
}
