    if (log_file) {
        fclose(log_file);
    }
    if (pigpio_ctx != -1) {
        gpioTerminate();
    }
    if (gpiod_ctx != -1) {
        gpiod_close(gpiod_ctx);
    }
    exit(signum);
}

