static void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    vl53l1x_close(&sensor);
    exit(signum);
}

static void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s %s\n", timestamp, event);
    fflush(log_file);
}

static void open_gate() {
    gpiod_line_set_value(gpio_fd, GPIO_18, 1);
    gpiod_line_set_value(gpio_fd, GPIO_19, 0);
    log_event("Gate opened");
}

static void close_gate() {
    gpiod_line_set_value(gpio_fd, GPIO_18, 0);
    gpiod_line_set_value(gpio_fd, GPIO_19, 1);
    log_event("Gate closed");
}

static void init_sensor() {
    int ret;

    ret = vl53l1x_init(&sensor, I2C_BUS, I2C_ADDRESS);
    if (ret != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize sensor: %d\n", ret);
        exit(EXIT_FAILURE);
    }

    ret = vl53l1x_set_timing_budget(&sensor, 20000); // 20 ms
    if (ret != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to set timing budget: %d\n", ret);
        exit(EXIT_FAILURE);
    }

    ret = vl53l1x_start_ranging(&sensor);
    if (ret != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to start ranging: %d\n", ret);
        exit(EXIT_FAILURE);
    }
}

static void read_distance() {
    int ret;
    uint16_t distance;

    ret = vl53l1x_get_distance(&sensor, &distance);
    if (ret != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to read distance: %d\n", ret);
        return;
    }

    if (distance <= MAX_DISTANCE) {
        open_gate();
    } else {
        close_gate();
    }
}

