    if (ret < 0) {
        perror("Failed to request GPIO line 19");
        gpiod_line_release(line_18);
        gpiod_line_release(line_19);
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line_18);
        gpiod_line_release(line_19);
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
