#include <vl53l1x_api.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_FORWARD 17
#define GPIO_BACKWARD 18
#define GPIO_TRIGGER 24
#define MAX_RETRIES 10
#define BACKOFF_DELAY 1000000 // 1 ms

static int i2c_handle;
static int gpio_handle;
static int sensor_handle;
static int distance;
static int motor_state = 0; // 0: stopped, 1: forward, -1: backward

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpio_write(gpio_handle, GPIO_FORWARD, 0);
        gpio_write(gpio_handle, GPIO_BACKWARD, 0);
        vl53l1x_stop_ranging(sensor_handle);
        vl53l1x_close(sensor_handle);
        close(i2c_handle);
        gpio_close(gpio_handle);
        printf("Program terminated.\n");
        exit(EXIT_SUCCESS);
    }
}

static void i2c_retry(int retries) {
    int delay = BACKOFF_DELAY;
    while (retries > 0) {
        if (i2c_write_byte_data(i2c_handle, 0x00, 0x00) == 0) {
            break;
        }
        usleep(delay);
        delay *= 2;
        retries--;
    }
    if (retries == 0) {
        printf("I2C write failed after %d retries.\n", MAX_RETRIES);
        exit(EXIT_FAILURE);
    }
}

static void gpio_isr(int gpio, int level, uint32_t tick) {
    if (level == PI_RISING_EDGE) {
        vl53l1x_start_ranging(sensor_handle);
    }
}

