#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define ELE0 0
#define ELE1 1
#define ELE2 2
#define ELE3 3
#define ELE4 4
#define ELE5 5
#define ELE6 6
#define ELE7 7
#define ELE8 8
#define ELE9 9
#define ELE10 10
#define ELE11 11
#define LED_PIN_17 17
#define LED_PIN_18 18
#define LED_PIN_27 27
#define LED_PIN_22 22
#define LOG_FILE "proximity_events.log"

static int i2c_fd;
static int gpio_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *led_lines[4];
static struct sigaction sa;

static void log_event(int electrode, time_t timestamp) {
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
    fprintf(log_file, "%s: ELE%d\n", timestamp_str, electrode);
    fflush(log_file);
}

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(i2c_fd);
        fclose(log_file);
        gpiod_chip_close(chip);
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        exit(0);
    }
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    led_lines[0] = gpiod_chip_get_line(chip, LED_PIN_17);
    led_lines[1] = gpiod_chip_get_line(chip, LED_PIN_18);
    led_lines[2] = gpiod_chip_get_line(chip, LED_PIN_27);
    led_lines[3] = gpiod_chip_get_line(chip, LED_PIN_22);

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(led_lines[i], "proximity_led", 0)) {
            perror("Failed to request LED GPIO line");
            exit(1);
        }
    }
}

static void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }
}

static void init_log() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(1);
    }
}

static void reset_sensor() {
    uint8_t reset_cmd = 0x80;
    if (write(i2c_fd, &reset_cmd, 1) != 1) {
        perror("Failed to reset sensor");
        close(i2c_fd);
        fclose(log_file);
        gpiod_chip_close(chip);
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        exit(1);
    }
}

static void check_sensor() {
    uint8_t status_reg;
    if (read(i2c_fd, &status_reg, 1) != 1) {
        perror("Failed to read status register");
        close(i2c_fd);
        fclose(log_file);
        gpiod_chip_close(chip);
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        exit(1);
    }

    if (status_reg != 0x00) {
        fprintf(stderr, "Sensor is not present or bus error\n");
        close(i2c_fd);
        fclose(log_file);
        gpiod_chip_close(chip);
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        exit(1);
    }
}

static void set_led_pattern(int pattern) {
    uint8_t led_pattern = pattern;
    if (write(i2c_fd, &led_pattern, 1) != 1) {
        perror("Failed to set LED pattern");
        close(i2c_fd);
        fclose(log_file);
        gpiod_chip_close(chip);
        for (int i = 0; i < 4; i++) {
            gpiod_line_release(led_lines[i]);
        }
        exit(1);
    }
}

static void poll_sensor() {
    uint8_t status_reg;
    uint8_t proximity_status;
    time_t timestamp;

    while (1) {
        timestamp = time(NULL);

        if (read(i2c_fd, &status_reg, 1) != 1) {
            perror("Failed to read status register");
            close(i2c_fd);
            fclose(log_file);
            gpiod_chip_close(chip);
            for (int i = 0; i < 4; i++) {
                gpiod_line_release(led_lines[i]);
            }
            exit(1);
        }

        proximity_status = status_reg & 0x0F;

        for (int i = 0; i < 12; i++) {
            if (proximity_status & (1 << i)) {
                log_event(i, timestamp);
                set_led_pattern(i);
            }
        }

        usleep(50000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();
    init_log();
    reset_sensor();
    check_sensor();

    poll_sensor();

    close(i2c_fd);
    fclose(log_file);
    gpiod_chip_close(chip);
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(led_lines[i]);
    }

    return 0;
}

