    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    gpiod_chip = chip;

    line = gpiod_chip_get_line(chip, LED_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    gpiod_line = line;

    int res = gpiod_line_request_output(line, "proximity_detector", 0);
    if (res < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    int res = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (res < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void write_log(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fprintf(log_file, "\n");
    fflush(log_file);
}

static void read_device_id() {
    uint8_t device_id;
    int res = i2c_smbus_read_byte_data(i2c_fd, 0x00);
    if (res < 0) {
        perror("Failed to read device ID");
        exit(EXIT_FAILURE);
    }
    device_id = res;
    write_log("Device ID: 0x%02X", device_id);
}

static void configure_mpr121() {
    uint8_t config[12];
    config[0] = 0x00; // ESI
    config[1] = 0x00; // SFI
    config[2] = 0x00; // FFI
    config[3] = 0x00; // Debounce
    config[4] = 0x00; // AFE
    config[5] = 0x00; // Baseline Filtering
    config[6] = 0x00; // Baseline
    config[7] = 0x00; // Baseline
    config[8] = 0x00; // Baseline
    config[9] = 0x00; // Baseline
    config[10] = 0x00; // Baseline
    config[11] = 0x00; // Baseline

    int res = i2c_smbus_write_block_data(i2c_fd, 0x01, 12, config);
    if (res < 0) {
        perror("Failed to configure MPR121");
        exit(EXIT_FAILURE);
    }
}

static void monitor_proximity() {
    uint8_t status;
    int res = i2c_smbus_read_byte_data(i2c_fd, 0x02);
    if (res < 0) {
        perror("Failed to read status");
        exit(EXIT_FAILURE);
    }
    status = res;

    if (status & 0x01) {
        write_log("Proximity event detected");
        gpiod_line_set_value(gpiod_line, 1);
        sleep(1);
        gpiod_line_set_value(gpiod_line, 0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();
    setup_log_file();

    read_device_id();
    configure_mpr121();

    while (1) {
        monitor_proximity();
        sleep(1);
    }

    return 0;
}

