#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_MS 30000
#define MAX_DISTANCE_CM 400
#define MIN_DISTANCE_CM 2

volatile sig_atomic_t exit_flag = 0;

static void sigint_handler(int signum) {
    exit_flag = 1;
}

static void log_distance(const char *timestamp, int distance_cm) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s, %d\n", timestamp, distance_cm);
    fclose(log_file);
}

static void release_resources(gpiod_chip *chip) {
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
}

static int measure_distance(gpiod_chip *chip, gpiod_line *trigger, gpiod_line *echo) {
    int trigger_fd = gpiod_line_request_output(trigger, "trigger", 0);
    if (trigger_fd < 0) {
        perror("Failed to request trigger line");
        return -1;
    }

    int echo_fd = gpiod_line_request_input(echo, "echo");
    if (echo_fd < 0) {
        perror("Failed to request echo line");
        close(trigger_fd);
        return -1;
    }

    struct timespec trigger_start, trigger_end, echo_start, echo_end;
    clock_gettime(CLOCK_MONOTONIC, &trigger_start);

    // Hold trigger low for 5 µs
    if (write(trigger_fd, NULL, 0) < 0) {
        perror("Failed to write to trigger line");
        close(trigger_fd);
        close(echo_fd);
        return -1;
    }

    // Pulse trigger high for 10 µs
    if (write(trigger_fd, NULL, 0) < 0) {
        perror("Failed to write to trigger line");
        close(trigger_fd);
        close(echo_fd);
        return -1;
    }

    // Wait up to 30 ms for echo rising edge
    if (read(echo_fd, NULL, 0) < 0) {
        perror("Failed to read from echo line");
        close(trigger_fd);
        close(echo_fd);
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &echo_start);

    // Wait up to 30 ms for echo falling edge
    if (read(echo_fd, NULL, 0) < 0) {
        perror("Failed to read from echo line");
        close(trigger_fd);
        close(echo_fd);
        return -1;
    }

    clock_gettime(CLOCK_MONOTONIC, &echo_end);

    close(trigger_fd);
    close(echo_fd);

    long duration_ns = (echo_end.tv_sec - echo_start.tv_sec) * 1000000000 +
                       (echo_end.tv_nsec - echo_start.tv_nsec);
    if (duration_ns < 0) {
        duration_ns = 0;
    }

    int distance_cm = (int)(duration_ns / 58000000.0);
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %d cm\n", distance_cm);
        return -1;
    }

    return distance_cm;
}

int main() {
    gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line *trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (trigger == NULL) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (echo == NULL) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(trigger);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!exit_flag) {
        int distance_cm = measure_distance(chip, trigger, echo);
        if (distance_cm >= 0) {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now));
            log_distance(timestamp, distance_cm);
        }

        sleep(1);
    }

    fclose(log_file);
    release_resources(chip);

    return EXIT_SUCCESS;
}

