This C program uses the `libgpiod` library to interact with the GPIO pins on a Raspberry Pi Zero W. It measures distance using an HC-SR04 ultrasonic sensor and logs the results to a file. The program handles errors, timeouts, and sensor absence conditions, and it includes a SIGINT handler to cleanly exit and release resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define MAX_READINGS 100
#define MAX_DISTANCE 4000  // in cm

static int gpiod_ctx = -1;
static int echo_fd = -1;
static int trigger_fd = -1;
static struct gpiod_line *echo_line = NULL;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line_event echo_event;
static struct timespec start_time;
static struct timespec end_time;
static int readings_count = 0;
static double readings[MAX_READINGS];
static FILE *log_file = NULL;

static void sig_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_ctx = -1;
    }
    if (echo_fd != -1) {
        close(echo_fd);
        echo_fd = -1;
    }
    if (trigger_fd != -1) {
        close(trigger_fd);
        trigger_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    exit(0);
}

static void echo_isr(const struct gpiod_line_event *event) {
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);
    } else if (event->type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        long long duration_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec);
        if (duration_ns > 0) {
            readings[readings_count++] = duration_ns / 1000000.0;  // Convert to microseconds
            if (readings_count >= MAX_READINGS) {
                readings_count = 0;
            }
        }
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize libgpiod
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request lines
    trigger_line = gpiod_line_request_output(gpiod_ctx, "trigger", TRIG_PIN, 0);
    if (trigger_line == NULL) {
        perror("Failed to request trigger line");
        gpiod_chip_close(gpiod_ctx);
        return 1;
    }

    echo_line = gpiod_line_request_input(gpiod_ctx, "echo", ECHO_PIN, GPIOD_LINE_REQUEST_FLAG_EDGE_RISING | GPIOD_LINE_REQUEST_FLAG_EDGE_FALLING);
    if (echo_line == NULL) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_ctx);
        return 1;
    }

    // Set up interrupt
    if (gpiod_line_event_config(echo_line, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE, echo_isr) < 0) {
        perror("Failed to configure echo line event");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_ctx);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_ctx);
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(1000);  // 1000 microseconds
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo
        while (gpiod_line_event_read(echo_line, &echo_event) < 0) {
            if (echo_event.type == GPIOD_LINE_EVENT_RISING_EDGE) {
                clock_gettime(CLOCK_MONOTONIC, &start_time);
            } else if (echo_event.type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                long long duration_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000LL + (end_time.tv_nsec - start_time.tv_nsec);
                if (duration_ns > 0) {
                    readings[readings_count++] = duration_ns / 1000000.0;  // Convert to microseconds
                    if (readings_count >= MAX_READINGS) {
                        readings_count = 0;
                    }
                }
            }
        }

        // Calculate distance
        double distance = readings[readings_count - 1];
        if (distance > 0 && distance <= MAX_DISTANCE) {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_event_config(echo_line, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE | GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE, NULL);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return 0;
}

