This C program initializes the Raspberry Pi Zero W to measure distance using an HC-SR04 ultrasonic sensor. It uses the `libgpiod` library to handle GPIO operations and interrupts. The program triggers a 10 µs pulse on the TRIG pin, waits for the echo pulse, calculates the distance, and logs the reading along with a timestamp to a file named `distance_log.txt`. The program handles signal interruptions to cleanly shut down and release resources.

code:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libvl53l1.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_GATE 24
#define LOG_FILE "gate_log.txt"
#define MAX_LOG_SIZE 1024
#define POLL_INTERVAL 100000  // 100 ms

static int i2c_fd;
static int gpio_fd;
static FILE *log_file;
static vl53l1_error_t error;
static vl53l1_dev_t sensor;
static vl53l1_config_t config;
static vl53l1_system_control_t system_control;
static vl53l1_timing_config_t timing_config;
static vl53l1_range_config_t range_config;
static vl53l1_ranging_data_t ranging_data;
static vl53l1_status_t status;
static vl53l1_distance_t distance;
static vl53l1_bool_t gate_open;
static vl53l1_bool_t gate_state_changed;
static vl53l1_bool_t sensor_initialized;
static vl53l1_bool_t log_file_opened;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_fd, GPIO_GATE);
        gpiod_close(gpio_fd);
    }
    if (log_file_opened) {
        fclose(log_file);
    }
    vl53l1_close(&sensor);
    exit(0);
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

static void init_sensor() {
    error = vl53l1_init(&sensor);
    if (error != VL53L1_ERROR_NONE) {
        log_event("Failed to initialize sensor");
        exit(1);
    }
    sensor_initialized = true;
}

static void configure_sensor() {
    error = vl53l1_set_sensor_mode(&sensor, VL53L1_MODE_SINGLE_RANGING);
    if (error != VL53L1_ERROR_NONE) {
        log_event("Failed to set sensor mode");
        exit(1);
    }
    error = vl53l1_set_timing_budget_in_us(&sensor, 20000);  // 20 ms
    if (error != VL53L1_ERROR_NONE) {
        log_event("Failed to set timing budget");
        exit(1);
    }
    error = vl53l1_set_inter_measurement_period_in_ms(&sensor, 200);  // 200 ms
    if (error != VL53L1_ERROR_NONE) {
        log_event("Failed to set inter-measurement period");
