#include <gpiod.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SAMPLES 5
#define TIMEOUT 30000000 // 30 ms in microseconds
#define FILTER_WINDOW 5
#define CSV_FILE "distance_log.csv"
#define HEADER "timestamp, distance, angle\n"

volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void echo_callback(gpiod_chip *chip, unsigned int line, unsigned int event_type, void *data) {
    struct timespec start, end;
    long duration;
    int pulse_width = 0;
    int new_pulse = 0;

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (duration > TIMEOUT) {
            break;
        }
    }

    pulse_width = duration / 2; // Calculate pulse width in microseconds
    new_pulse = 1;
}

