static void sigint_handler(int signum) {
    running = 0;
    gpio_set_value(led_fd, LED_OFF);
    close(i2c_fd);
    close(led_fd);
    exit(EXIT_SUCCESS);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_led() {
    led_fd = gpiochip_open(0);
    if (led_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpio_direction_output(led_fd, LED_OFF) < 0) {
        perror("Failed to set GPIO direction");
        gpiochip_close(led_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

