        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret) {
        perror("Failed to request trigger line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(pwm_line, "pwm", 0);
    if (ret) {
        perror("Failed to request PWM line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    trigger_fd = gpiod_line_export(trigger_line);
    if (trigger_fd < 0) {
        perror("Failed to export trigger line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_fd = gpiod_line_export(echo_line);
    if (echo_fd < 0) {
        perror("Failed to export echo line");
        close(trigger_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pwm_fd = open("/dev/pwm/0", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
