        perror("Failed to set PWM period");
        close(trigger_fd);
        close(echo_fd);
        close(pwm_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, PWM_DUTY_CYCLE);
    if (ret) {
        perror("Failed to set PWM duty cycle");
        close(trigger_fd);
        close(echo_fd);
        close(pwm_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(pwm_fd, PWM_SET_ENABLE, 1);
