static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line, *pwm_line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    gpiod_ctx = gpiod_chip_fd(chip);

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret) {
        perror("Failed to request trigger line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("Failed to get PWM line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(pwm_line, "pwm", 0);
    if (ret) {
        perror("Failed to request PWM line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    trigger_fd = gpiod_line_export(trigger_line);
    if (trigger_fd < 0) {
        perror("Failed to export trigger line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    echo_fd = gpiod_line_export(echo_line);
    if (echo_fd < 0) {
        perror("Failed to export echo line");
        close(trigger_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pwm_fd = open("/dev/pwm/0", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        close(trigger_fd);
        close(echo_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(pwm_fd, PWM_SET_FREQ, PWM_FREQ);
    if (ret) {
        perror("Failed to set PWM frequency");
        close(trigger_fd);
        close(echo_fd);
        close(pwm_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(pwm_fd, PWM_SET_PERIOD, PWM_PERIOD);
    if (ret) {
        perror("Failed to set PWM period");
        close(trigger_fd);
        close(echo_fd);
        close(pwm_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, PWM_DUTY_CYCLE);
    if (ret) {
        perror("Failed to set PWM duty cycle");
        close(trigger_fd);
        close(echo_fd);
        close(pwm_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(pwm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(pwm_fd, PWM_SET_ENABLE, 1);
    if (ret) {
        perror("Failed to enable PWM");
        close(trigger_fd);
        close(echo_fd);
        close(pwm_fd);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
