#define MIN_DISTANCE 5
#define MAX_DISTANCE 50
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line, *echo_line, *buzzer_line;
static struct gpiod_line_request trigger_request, echo_request, buzzer_request;
static struct timespec start_time, end_time;
static int fd;

void sigint_handler(int signum) {
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    close(fd);
    exit(0);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);

    gpiod_line_request(&trigger_request, "trigger", trigger_line, GPIOD_LINE_REQUEST_FLAG_OUTPUT);
    gpiod_line_request(&echo_request, "echo", echo_line, GPIOD_LINE_REQUEST_FLAG_INPUT);
    gpiod_line_request(&buzzer_request, "buzzer", buzzer_line, GPIOD_LINE_REQUEST_FLAG_OUTPUT);

    // Set trigger line to low
    gpiod_line_set_value(trigger_line, 0);

    // Open the PWM device
    fd = open("/dev/pwm/0", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM device");
        exit(EXIT_FAILURE);
    }

    // Set PWM frequency to 1000 Hz
    if (ioctl(fd, PWM_SET_FREQ, 1000) < 0) {
        perror("Failed to set PWM frequency");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo
        while (gpiod_line_get_value(echo_line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
                perror("Failed to get start time");
                exit(EXIT_FAILURE);
            }
        }

        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) < 0) {
                perror("Failed to get end time");
                exit(EXIT_FAILURE);
            }
        }

        // Calculate distance
        long duration = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;
        if (duration > TIMEOUT_US) {
            printf("Echo timeout\n");
            continue;
        }

        float distance = duration / 58.2f;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Distance out of range\n");
            continue;
        }

        // Map distance to frequency
        float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

        // Set buzzer frequency
        if (ioctl(fd, PWM_SET_FREQ, frequency) < 0) {
            perror("Failed to set buzzer frequency");
            exit(EXIT_FAILURE);
        }

        // Print distance and frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Wait 10 ms
        usleep(10000);
    }

    // Clean up
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    close(fd);

    return 0;
}

