This C program initializes the GPIO and PWM libraries, sets up the trigger and echo lines, and continuously measures the distance using the HC-SR04 sensor. It maps the distance to a frequency and generates a continuous tone on the buzzer using the PWM API. The program handles sensor read failures and exits cleanly on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_MS 50
#define LOOP_INTERVAL_MS 500
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400

static volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct timespec timeout;
    long duration;
    double distance;
    int valid_distance;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the trigger and echo lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    // Request the trigger and echo lines for output and input, respectively
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret) {
        perror("Failed to request trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the trigger line to low initially
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret) {
        perror("Failed to set trigger line to low");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!exit_flag) {
        // Trigger the sensor
        ret = gpiod_line_set_value(trigger_line, 1);
        if (ret) {
            perror("Failed to set trigger line to high");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        usleep(10); // 10 µs pulse
        ret = gpiod_line_set_value(trigger_line, 0);
        if (ret) {
            perror("Failed to set trigger line to low");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Wait for the echo pulse
        timeout.tv_sec = 0;
        timeout.tv_nsec = TIMEOUT_MS * 1000000;
        ret = gpiod_line_event_wait(echo_line, &timeout);
        if (ret < 0) {
            perror("Failed to wait for echo line event");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Get the duration of the echo pulse
        ret = gpiod_line_event_get_duration(echo_line, &duration);
        if (ret < 0) {
            perror("Failed to get echo line duration");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Convert the duration to distance
        distance = duration * 0.034 / 2.0; // Speed of sound is 343 m/s

        // Check if the distance is valid
        valid_distance = (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM);
        if (!valid_distance) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < 10.0) {
                printf("Too close!\n");
            }
        }

        // Wait for the next loop iteration
        usleep(LOOP_INTERVAL_MS * 1000);
    }

    // Release the lines and close the chip
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

