This C program uses the `libgpiod` library to interact with the Raspberry Pi's GPIO pins. It initializes the GPIO chip, requests the trigger and echo lines, sets the trigger line to low initially, and enters a loop where it triggers the sensor, waits for the echo pulse, converts the duration to distance, checks if the distance is valid, and prints the result. The program also handles a timeout and a SIGINT signal to exit cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define SPI_CS_PIN 8
#define MAX_DISTANCE 5000
#define MIN_DISTANCE 200
#define LOG_FILE "distance_log.csv"
#define BUFFER_SIZE 1024

static int spi_fd;
static int gpio_fd;
static FILE *log_file;

static void sig_handler(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpio_fd = gpiod_chip_close(gpio_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

static void init_spi() {
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, SPI_CS_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "spi_cs", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_chip_fd(chip);
    if (gpio_fd < 0) {
        perror("Failed to get GPIO file descriptor");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void write_to_log(const char *timestamp, int distance) {
    if (log_file) {
        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fflush(log_file);
    }
}

static int read_distance() {
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 1,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tr) < 0) {
        perror("SPI read failed");
        return -1;
    }

    return tr.rx_buf[0];
}

int main() {
    struct sigaction sa;
    char timestamp[20];
    int distance;

    init_gpio();
    init_spi();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        distance = read_distance();
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %d\n", distance);
        } else {
            write_to_log(timestamp, distance);
        }

        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    return 0;
}

