#include <stdint.h>

#define SI1175_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define HEADER "timestamp,als_visible\n"

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write header to log file
    if (fwrite(HEADER, 1, strlen(HEADER), log_file) != strlen(HEADER)) {
        perror("Failed to write header to log file");
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read ambient light value every 5 seconds
    while (!should_exit) {
        uint16_t als_visible;
        uint8_t buffer[2];

        // Read ALS visible value
        buffer[0] = 0x01; // ALS visible register
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to I2C");
            continue;
        }

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C");
            continue;
        }

        als_visible = (buffer[0] << 8) | buffer[1];

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        // Write timestamp and ALS visible value to log file
        if (fprintf(log_file, "%s,%u\n", timestamp, als_visible) < 0) {
            perror("Failed to write to log file");
            continue;
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

