#define SI1120_LOG_FILE "si1120_log.txt"
#define SI1120_LOG_FORMAT "%Y-%m-%d %H:%M:%S"

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd;
    uint8_t part_id;
    uint8_t command;
    uint8_t als_data[2];
    uint8_t prox_data[2];
    uint16_t als_value;
    uint16_t prox_value;
    char timestamp[20];
    FILE *log_file;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" SI1120_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1120_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(SI1120_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Reset the sensor
    command = SI1120_CMD_RESET;
    if (write(i2c_fd, &command, 1) != 1) {
        fprintf(stderr, "Failed to reset sensor: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Start the sensor
    command = SI1120_CMD_START;
    if (write(i2c_fd, &command, 1) != 1) {
        fprintf(stderr, "Failed to start sensor: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read part ID to verify the sensor
    if (read(i2c_fd, &part_id, 1) != 1) {
        fprintf(stderr, "Failed to read part ID: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (part_id != SI1120_PART_ID_VALUE) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set ALS and proximity configurations
    uint8_t als_config = 0x01; // Example configuration
    uint8_t prox_config = 0x01; // Example configuration
    if (write(i2c_fd, &als_config, 1) != 1) {
        fprintf(stderr, "Failed to set ALS configuration: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (write(i2c_fd, &prox_config, 1) != 1) {
        fprintf(stderr, "Failed to set proximity configuration: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Read ALS and proximity data
        if (read(i2c_fd, als_data, 2) != 2) {
            fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
            continue;
        }
        if (read(i2c_fd, prox_data, 2) != 2) {
            fprintf(stderr, "Failed to read proximity data: %s\n", strerror(errno));
            continue;
        }

        // Combine ALS and proximity byte pairs into 16-bit little-endian values
        als_value = (als_data[0] << 8) | als_data[1];
        prox_value = (prox_data[0] << 8) | prox_data[1];

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), SI1120_LOG_FORMAT, localtime(&now));

        // Append reading to log file
        fprintf(log_file, "%s, ALS: %04X, Proximity: %04X\n", timestamp, als_value, prox_value);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Stop the sensor
    command = SI1120_CMD_STOP;
    if (write(i2c_fd, &command, 1) != 1) {
        fprintf(stderr, "Failed to stop sensor: %s\n", strerror(errno));
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SI1182_I2C_ADDR 0x60
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x01
#define SI1182_LUX_DATA_REG 0x02
#define SI1182_PROX_DATA_REG 0x03

#define LOG_FILE "biometric_log.txt"
#define BUFFER_SIZE 1024

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

static void sig_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    exit(signum);
}

int main() {
    int ret;
    struct timespec ts;
    char buffer[BUFFER_SIZE];
    char timestamp[20];
    uint8_t part_id;
    uint8_t meas_rate = 0x01; // 100 ms measurement rate

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read part ID register
    ret = read(i2c_fd, &part_id, 1);
    if (ret != 1) {
        perror("Failed to read part ID register");
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Verify part ID
    if (part_id != 0x82) {
        fprintf(stderr, "Invalid part ID: 0x%02X\n", part_id);
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Write measurement rate register
    ret = write(i2c_fd, &meas_rate, 1);
    if (ret != 1) {
        perror("Failed to write measurement rate register");
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for LED
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_chip == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 17); // Assuming GPIO 17 is connected to the LED
    if (gpio_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(gpio_line, "biometric_log", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read lux data
        ret = read(i2c_fd, buffer, 2);
        if (ret != 2) {
            perror("Failed to read lux data");
            close(i2c_fd);
            fclose(log_file);
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            exit(EXIT_FAILURE);
        }
        uint16_t lux = (buffer[0] << 8) | buffer[1];

        // Read proximity data
        ret = read(i2c_fd, buffer, 2);
        if (ret != 2) {
            perror("Failed to read proximity data");
            close(i2c_fd);
            fclose(log_file);
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            exit(EXIT_FAILURE);
        }
        uint16_t proximity = (buffer[0] << 8) | buffer[1];

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", &ts);

        // Log and print the reading
        fprintf(log_file, "%s,%u,%u\n", timestamp, lux, proximity);
        printf("%s,%u,%u\n", timestamp, lux, proximity);

        // Toggle LED
        ret = gpiod_line_set_value(gpio_line, 1);
        if (ret < 0) {
            perror("Failed to toggle LED");
            close(i2c_fd);
            fclose(log_file);
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            exit(EXIT_FAILURE);
        }
        usleep(100000); // 100 ms delay
        ret = gpiod_line_set_value(gpio_line, 0);
        if (ret < 0) {
            perror("Failed to toggle LED");
            close(i2c_fd);
            fclose(log_file);
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            exit(EXIT_FAILURE);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close resources
    close(i2c_fd);
    fclose(log_file);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
