#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define SI1145_ADDR 0x60
#define SI1145_PS1_DATA0 0x12
#define SI1145_PS1_DATA1 0x13
#define SI1145_PS1_CONFIG 0x0E
#define SI1145_PS1_CONFIG_DEFAULT 0x07
#define SI1145_PS1_CONFIG_PS1_EN 0x01
#define SI1145_PS1_CONFIG_PS1_EN_MASK 0x01
#define SI1145_PS1_CONFIG_PS1_EN_SHIFT 0
#define SI1145_PS1_CONFIG_PS1_EN_TIMEOUT 1000000
#define SI1145_PS1_CONFIG_PS1_EN_TIMEOUT_RETRIES 3
#define SI1145_PS1_CONFIG_PS1_EN_TIMEOUT_DELAY 100000

#define LOG_FILE "proximity_log.txt"

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void sig_handler(int sig) {
    should_exit = 1;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(stderr, "%s: %s\n", timestamp, msg);
}

static void log_proximity(unsigned short proximity) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s: %hu\n", timestamp, proximity);
}

static int i2c_write(uint8_t reg, uint8_t value) {
    int ret;
    uint8_t buf[2] = {reg, value};
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read(uint8_t reg, uint8_t *value) {
    int ret;
    uint8_t buf[1] = {reg};
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        log_error("I2C write failed");
        return -1;
    }
    ret = read(i2c_fd, value, 1);
    if (ret != 1) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int si1145_init() {
    int ret;
    ret = i2c_write(SI1145_PS1_CONFIG, SI1145_PS1_CONFIG_DEFAULT);
    if (ret != 0) {
        return -1;
    }
    return 0;
}

static int si1145_read_proximity() {
    int ret;
    uint8_t data[2];
    for (int i = 0; i < SI1145_PS1_CONFIG_PS1_EN_TIMEOUT_RETRIES; i++) {
        ret = i2c_write(SI1145_PS1_CONFIG, SI1145_PS1_CONFIG_DEFAULT | SI1145_PS1_CONFIG_PS1_EN);
        if (ret != 0) {
            log_error("I2C write failed");
            return -1;
        }
        usleep(SI1145_PS1_CONFIG_PS1_EN_TIMEOUT);
        ret = i2c_read(SI1145_PS1_DATA0, &data[0]);
        if (ret != 0) {
            log_error("I2C read failed");
            return -1;
        }
        ret = i2c_read(SI1145_PS1_DATA1, &data[1]);
        if (ret != 0) {
            log_error("I2C read failed");
            return -1;
        }
        if ((data[0] & SI1145_PS1_CONFIG_PS1_EN_MASK) == SI1145_PS1_CONFIG_PS1_EN) {
            break;
        }
    }
    if (i == SI1145_PS1_CONFIG_PS1_EN_TIMEOUT_RETRIES) {
        log_error("PS1_EN timeout");
        return -1;
    }
    unsigned short proximity = (data[0] << 8) | data[1];
    return proximity;
}

int main() {
    int ret;
    struct sigaction sa;

    // Set up signal handlers
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR);
    if (ret < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    ret = si1145_init();
    if (ret != 0) {
        log_error("Failed to initialize sensor");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!should_exit) {
        unsigned short proximity = si1145_read_proximity();
        if (proximity != 0) {
            log_proximity(proximity);
        }
        usleep(1000000); // Read every second
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

