static int i2c_write(uint8_t reg, uint8_t value) {
    int ret;
    uint8_t buf[2] = {reg, value};
    ret = write(i2c_fd, buf, 2);
    if (ret != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read(uint8_t reg, uint8_t *value) {
    int ret;
    uint8_t buf[1] = {reg};
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        log_error("I2C write failed");
        return -1;
    }
    ret = read(i2c_fd, value, 1);
    if (ret != 1) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

static int si1145_init() {
    int ret;
    ret = i2c_write(SI1145_PS1_CONFIG, SI1145_PS1_CONFIG_DEFAULT);
    if (ret != 0) {
        return -1;
    }
    return 0;
}

static int si1145_read_proximity() {
    int ret;
    uint8_t data[2];
    for (int i = 0; i < SI1145_PS1_CONFIG_PS1_EN_TIMEOUT_RETRIES; i++) {
        ret = i2c_write(SI1145_PS1_CONFIG, SI1145_PS1_CONFIG_DEFAULT | SI1145_PS1_CONFIG_PS1_EN);
        if (ret != 0) {
            log_error("I2C write failed");
            return -1;
        }
        usleep(SI1145_PS1_CONFIG_PS1_EN_TIMEOUT);
        ret = i2c_read(SI1145_PS1_DATA0, &data[0]);
        if (ret != 0) {
            log_error("I2C read failed");
            return -1;
        }
        ret = i2c_read(SI1145_PS1_DATA1, &data[1]);
        if (ret != 0) {
            log_error("I2C read failed");
            return -1;
        }
        if ((data[0] & SI1145_PS1_CONFIG_PS1_EN_MASK) == SI1145_PS1_CONFIG_PS1_EN) {
            break;
        }
    }
    if (i == SI1145_PS1_CONFIG_PS1_EN_TIMEOUT_RETRIES) {
        log_error("PS1_EN timeout");
        return -1;
    }
    unsigned short proximity = (data[0] << 8) | data[1];
    return proximity;
}

int main() {
    int ret;
    struct sigaction sa;

    // Set up signal handlers
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR);
    if (ret < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    ret = si1145_init();
    if (ret != 0) {
        log_error("Failed to initialize sensor");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!should_exit) {
        unsigned short proximity = si1145_read_proximity();
        if (proximity != 0) {
            log_proximity(proximity);
        }
        usleep(1000000); // Read every second
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);

    return 0;
}
