#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MAX_TIMEOUT 1000000000 // 1 second in nanoseconds

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static struct gpiod_line_event *event;
static struct timespec start_time;
static struct timespec end_time;
static int trigger_fd;
static int echo_fd;
static int buzzer_fd;
static int distance;
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
    gpiod_chip_close(chip);
    close(trigger_fd);
    close(echo_fd);
    close(buzzer_fd);
    exit(0);
}

static void echo_callback(const struct gpiod_line_event *event) {
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);
    } else if (event->type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        long duration_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec);
        distance = (duration_ns / 58.2) / 2; // Convert microseconds to centimeters
        printf("Distance: %d cm\n", distance);
        if (distance < 20) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }
    }
}

int main() {
    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines for output
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines for input with rising/falling edge alert
    if (gpiod_line_request_edge_detect(echo_line, "echo", GPIOD_EDGE_BOTH, 0) < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up interrupt handler
    event = gpiod_line_event_allocate();
    if (!event) {
        perror("Failed to allocate event");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Generate 10 µs trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo pulse
        echo_fd = gpiod_line_event_wait(echo_line, MAX_TIMEOUT);
        if (echo_fd < 0) {
            perror("Failed to wait for echo event");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_line_release(buzzer_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Read event
        if (gpiod_line_event_read(echo_fd, event) < 0) {
            perror("Failed to read echo event");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_line_release(buzzer_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Handle event
        echo_callback(event);

        // Release event
        gpiod_line_event_free(event);
    }

    // Clean up
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

