This C program initializes the GPIO pins for the HC-SR04 ultrasonic sensor and a buzzer, sets up an interrupt handler to measure the distance, and prints the distance every second. The program also handles the SIGINT signal to cleanly terminate the program and release resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MAX_DISTANCE 200
#define MIN_DISTANCE 20
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define UPDATE_INTERVAL 100000  // 100 ms

static int gpiod_handle = -1;
static int servo_handle = -1;
static int servo_angle = 90;
static int distance = -1;

static void sigint_handler(int signum) {
    if (gpiod_handle != -1) {
        gpiod_close(gpiod_handle);
    }
    if (servo_handle != -1) {
        gpio_handle_close(servo_handle);
    }
    exit(EXIT_SUCCESS);
}

static void setup_gpio() {
    gpiod_handle = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_handle == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    int trigger_line = gpiod_chip_get_line(gpiod_handle, TRIGGER_PIN);
    if (trigger_line == -1) {
        perror("Failed to get trigger line");
        gpiod_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    int echo_line = gpiod_chip_get_line(gpiod_handle, ECHO_PIN);
    if (echo_line == -1) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    int servo_line = gpiod_chip_get_line(gpiod_handle, SERVO_PIN);
    if (servo_line == -1) {
        perror("Failed to get servo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(trigger_line, "trigger", 0);
    gpiod_line_request_input(echo_line, "echo", 0);
    gpiod_line_request_output(servo_line, "servo", 0);
}

static void setup_servo() {
    servo_handle = gpio_handle_open_by_name("gpiochip0", SERVO_PIN);
    if (servo_handle == -1) {
        perror("Failed to open servo GPIO handle");
        gpiod_line_release_all(gpiod_handle);
        gpiod_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }
}

static void measure_distance() {
    struct timespec start, end;
    long duration_ns;
    int pulse_width_us;

    gpiod_line_set_value(gpiod_handle, TRIGGER_PIN, 1);
    nanosleep(&(struct timespec){0, 1000000}, NULL);
    gpiod_line_set_value(gpiod_handle, TRIGGER_PIN, 0);

    while (gpiod_line_get_value(gpiod_handle, ECHO_PIN) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
    }

    while (gpiod_line_get_value(gpiod_handle, ECHO_PIN) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
    }

    duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
    pulse_width_us = duration_ns / 1000;

    if (pulse_width_us < 20000) {
        distance = -1.0;
    } else {
        distance = (pulse_width_us - 500) * 0.0343 / 2;
    }
}

static void set_servo_angle() {
    int pulse_width_us = SERVO_MIN_PULSE + (distance - MIN_DISTANCE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / (MAX_DISTANCE - MIN_DISTANCE);
    gpio_handle_set_value(servo_handle, 0, pulse_width_us / 1000);
}

int main() {
    signal(SIGINT, sigint_handler);

    setup_gpio();
    setup_servo();

    while (1) {
        measure_distance();
        if (distance != -1.0) {
            set_servo_angle();
            printf("Distance: %.2f cm, Angle: %d°\n", distance, servo_angle);
        } else {
            printf("Distance: -1.0 cm\n");
        }
        usleep(UPDATE_INTERVAL);
    }

    gpiod_line_release_all(gpiod_handle);
    gpiod_close(gpiod_handle);
    gpio_handle_close(servo_handle);

    return 0;
}

