#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define TIMEOUT_MS 50
#define INTERVAL_MS 100

static int gpiod_ctx = -1;
static int servo_handle = -1;

static void sigint_handler(int signum) {
    if (servo_handle != -1) {
        gpio_set_pulse_wid(servo_handle, SERVO_MIN_PULSE_WIDTH);
    }
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    printf("Program terminated by user.\n");
    exit(EXIT_SUCCESS);
}

static void init_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    int trigger_line = gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN);
    if (trigger_line == -1) {
        perror("Failed to get trigger line");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int echo_line = gpiod_chip_get_line(gpiod_ctx, ECHO_PIN);
    if (echo_line == -1) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int servo_line = gpiod_chip_get_line(gpiod_ctx, SERVO_PIN);
    if (servo_line == -1) {
        perror("Failed to get servo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) == -1) {
        perror("Failed to request trigger line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(servo_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(echo_line, "echo") == -1) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(servo_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) == -1) {
        perror("Failed to request servo line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_line_release(servo_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

static void init_servo() {
    servo_handle = gpio_servo_init(gpiod_ctx, SERVO_PIN);
    if (servo_handle == -1) {
        perror("Failed to initialize servo");
        gpiod_line_release(gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN));
        gpiod_line_release(gpiod_chip_get_line(gpiod_ctx, ECHO_PIN));
        gpiod_line_release(gpiod_chip_get_line(gpiod_ctx, SERVO_PIN));
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

static void measure_distance() {
    struct timespec start, end;
    long duration_ns;
    int distance_cm;

    // Trigger the sensor
    gpio_set_value(gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN), 1);
    nanosleep(&(struct timespec){0, 1000000}, NULL);
    gpio_set_value(gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN), 0);

    // Wait for the echo
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpio_get_value(gpiod_chip_get_line(gpiod_ctx, ECHO_PIN)) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
            perror("Failed to get end time");
            return;
        }
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (duration_ns > TIMEOUT_MS * 1000000) {
            distance_cm = -1;
            break;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpio_get_value(gpiod_chip_get_line(gpiod_ctx, ECHO_PIN)) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
            perror("Failed to get end time");
            return;
        }
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (duration_ns > TIMEOUT_MS * 1000000) {
            distance_cm = -1;
            break;
        }
    }

    if (distance_cm == -1) {
        printf("Timeout occurred.\n");
        return;
    }

    // Calculate distance in cm
    distance_cm = duration_ns / 58.26;

    // Map distance to servo angle
    float angle = 0.0;
    if (distance_cm < 20) {
        angle = SERVO_MIN_ANGLE;
    } else if (distance_cm > 200) {
        angle = SERVO_MAX_ANGLE;
    } else {
        angle = (distance_cm - 20) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) / (200 - 20) + SERVO_MIN_ANGLE;
    }

    // Clamp angle to valid range
    if (angle < SERVO_MIN_ANGLE) {
        angle = SERVO_MIN_ANGLE;
    } else if (angle > SERVO_MAX_ANGLE) {
        angle = SERVO_MAX_ANGLE;
    }

    // Set servo angle
    if (gpio_servo(servo_handle, angle) == -1) {
        perror("Failed to set servo angle");
    }

    // Print distance and angle
    printf("Distance: %.2f cm, Angle: %.2f°\n", distance_cm, angle);
}

int main() {
    signal(SIGINT, sigint_handler);

    init_gpio();
    init_servo();

    while (1) {
        measure_distance();
        usleep(INTERVAL_MS * 1000);
    }

    return 0;
}

