#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define SI7005_I2C_ADDR 0x40
#define CONFIG_REG 0xF5
#define TEMP_REG 0xF3
#define HUMIDITY_REG 0xF7
#define I2C_BUS 1
#define I2C_TIMEOUT 1000

static int i2c_fd = -1;
static int gpiod_ctx = -1;

static void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_ctx != -1) {
        gpiod_ctx = gpiod_ctx;
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize libgpiod
    gpiod_ctx = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_ctx < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Set I2C bus speed
    if (ioctl(i2c_fd, I2C_SET_SPEED, 100000) < 0) {
        perror("Failed to set I2C speed");
        close(i2c_fd);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Write CONFIG register to enable humidity and temperature readings
    uint8_t config_data[2] = {CONFIG_REG, 0x33};
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Failed to write CONFIG register");
        close(i2c_fd);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Wait for conversion
    usleep(I2C_TIMEOUT);

    // Read temperature
    uint8_t temp_data[2];
    if (read(i2c_fd, temp_data, 2) != 2) {
        perror("Failed to read temperature");
        close(i2c_fd);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
    uint16_t temp_raw = (temp_data[0] << 8) | temp_data[1];
    float temp_celsius = -46.85 + (175.72 * temp_raw / 65536.0);

    // Read humidity
    uint8_t humidity_data[2];
    if (read(i2c_fd, humidity_data, 2) != 2) {
        perror("Failed to read humidity");
        close(i2c_fd);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
    uint16_t humidity_raw = (humidity_data[0] << 8) | humidity_data[1];
    float humidity_percent = -6.0 + (125.0 * humidity_raw / 65536.0);

    // Log readings
    printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp_celsius, humidity_percent);

    // Main loop to read every 2 seconds
    while (1) {
        usleep(I2C_TIMEOUT);
        if (write(i2c_fd, config_data, 2) != 2) {
            perror("Failed to write CONFIG register");
            close(i2c_fd);
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }

        usleep(I2C_TIMEOUT);

        if (read(i2c_fd, temp_data, 2) != 2) {
            perror("Failed to read temperature");
            close(i2c_fd);
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }
        temp_raw = (temp_data[0] << 8) | temp_data[1];
        temp_celsius = -46.85 + (175.72 * temp_raw / 65536.0);

        if (read(i2c_fd, humidity_data, 2) != 2) {
            perror("Failed to read humidity");
            close(i2c_fd);
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }
        humidity_raw = (humidity_data[0] << 8) | humidity_data[1];
        humidity_percent = -6.0 + (125.0 * humidity_raw / 65536.0);

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp_celsius, humidity_percent);
    }

    close(i2c_fd);
    gpiod_chip_close(gpiod_ctx);
    return 0;
