#define MPU6050_ADDRESS 0x68
#define WHO_AM_I_REG 0x75
#define ACCEL_XOUT_H_REG 0x3B
#define ACCEL_XOUT_L_REG 0x3C
#define ACCEL_YOUT_H_REG 0x3D
#define ACCEL_YOUT_L_REG 0x3E
#define ACCEL_ZOUT_H_REG 0x3F
#define ACCEL_ZOUT_L_REG 0x40
#define TEMP_OUT_H_REG 0x41
#define TEMP_OUT_L_REG 0x42
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x44
#define GYRO_YOUT_H_REG 0x45
#define GYRO_YOUT_L_REG 0x46
#define GYRO_ZOUT_H_REG 0x47
#define GYRO_ZOUT_L_REG 0x48

static int i2c_fd;
static int gpiod_chip;
static int gpiod_line_sda;
static int gpiod_line_scl;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpiod_chip >= 0) {
        gpiod_chip_close(gpiod_chip);
    }
    if (gpiod_line_sda >= 0) {
        gpiod_line_close(gpiod_line_sda);
    }
    if (gpiod_line_scl >= 0) {
        gpiod_line_close(gpiod_line_scl);
    }
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_sda, *line_scl;
    int ret;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line_sda = gpiod_chip_get_line(chip, 2);
    if (!line_sda) {
        perror("Failed to get GPIO line SDA");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line_scl = gpiod_chip_get_line(chip, 3);
    if (!line_scl) {
        perror("Failed to get GPIO line SCL");
        gpiod_line_close(line_sda);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line_sda, "MPU6050_SDA");
    if (ret) {
        perror("Failed to request GPIO line SDA");
        gpiod_line_close(line_sda);
        gpiod_line_close(line_scl);
        gpiod_chip_close(chip);
