#define SHT40_I2C_ADDR 0x44
#define SHT40_CMD_MEASURE_HIGH_REPEATABILITY 0x24
#define SHT40_CMD_READ_TEMP_HUM 0xFD
#define SHT40_CRC8_POLYNOMIAL 0x31
#define SHT40_CRC8_INIT 0xFF

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *gpio = NULL;

static void sig_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (gpio != NULL) {
        gpiod_line_release(gpio);
    }
    exit(signum);
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHT40_CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc & 0x80) ? (crc << 1) ^ SHT40_CRC8_POLYNOMIAL : (crc << 1);
        }
    }
    return crc;
}

static int read_i2c(uint8_t reg, uint8_t *buf, size_t len) {
    if (i2c_fd == -1) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
