            return -1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) == -1) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            i2c_fd = -1;
            return -1;
        }
    }
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read from I2C");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int write_i2c(uint8_t reg, const uint8_t *buf, size_t len) {
    if (i2c_fd == -1) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
