        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (write(i2c_fd, buf, len) != len) {
        perror("Failed to write to I2C");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

