    if (crc_temp != buf[2] || crc_hum != buf[5]) {
        fprintf(stderr, "CRC failure\n");
        gpiod_line_release(gpio);
        gpiod_chip_close(chip);
        return 1;
    }

    float temp = (buf[0] << 8) | buf[1];
    float hum = (buf[3] << 8) | buf[4];

    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp / 100.0, hum / 100.0);

    while (1) {
