This C program uses the `libgpiod` library to handle GPIO operations and the `pigpio` library to handle I2C operations. It reads temperature and humidity from an Adafruit SHT40 sensor on I2C bus 1, validates the CRC checksums, and logs the readings to the console every 5 seconds. It also handles SIGINT and SIGTERM signals to perform a graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <pigpio.h>

#define MLX90614_I2C_ADDR 0x5A
#define MLX90614_REG_TA 0x06
#define MLX90614_REG_TOBJ1 0x07
#define MLX90614_I2C_BUS 1
#define LOG_FILE "temperature_log.csv"
#define LOG_INTERVAL 5000000  // 5 seconds in microseconds

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec sleep_time;
    struct tm *timeinfo;
    char timestamp[20];
    float ambient_temp, object_temp;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, MLX90614_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    while (!should_exit) {
        // Read ambient temperature
