#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define SDP810_CMD_CONFIG 0x01
#define SDP810_CMD_MEASURE 0x02
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

#define FILE_NAME "pressure_log.csv"
#define HEADER_ROW "timestamp,pressure (Pa),temperature (°C)\n"

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_handle = -1;
static FILE *file = NULL;

static void signal_handler(int signum) {
    if (file) {
        fclose(file);
    }
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(signum);
}

static void init_gpio() {
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line = gpiod_line_request_output(gpiod_chip, "SDP810", 0);
    if (gpiod_line == -1) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }
}

static void init_i2c() {
    i2c_handle = i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle == -1) {
        perror("Failed to open I2C bus");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }
}

static void send_command(uint8_t command) {
    if (i2c_write_byte(i2c_handle, command) != 0) {
        perror("Failed to send command");
        exit(EXIT_FAILURE);
    }
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void read_data(uint8_t *data) {
    if (i2c_read(i2c_handle, data, 9) != 9) {
        perror("Failed to read data");
        exit(EXIT_FAILURE);
    }
}

static void write_data(const uint8_t *data, size_t length) {
    if (i2c_write(i2c_handle, data, length) != length) {
        perror("Failed to write data");
        exit(EXIT_FAILURE);
    }
}

static void process_data(const uint8_t *data) {
    uint8_t crc = calculate_crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC-8 mismatch for pressure\n");
        return;
    }

    crc = calculate_crc8(data + 3, 2);
    if (crc != data[5]) {
        fprintf(stderr, "CRC-8 mismatch for temperature\n");
        return;
    }

    crc = calculate_crc8(data + 6, 2);
    if (crc != data[8]) {
        fprintf(stderr, "CRC-8 mismatch for scale factors\n");
        return;
    }

    uint16_t pressure = (data[0] << 8) | data[1];
    float pressure_pa = pressure * 0.01; // Scale factor is 0.01 Pa per LSB

    uint16_t temperature = (data[3] << 8) | data[4];
    float temperature_c = temperature * 0.01; // Scale factor is 0.01 °C per LSB

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&now));

    fprintf(file, "%s,%f,%f\n", timestamp, pressure_pa, temperature_c);
}

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler for SIGINT");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to set signal handler for SIGTERM");
        exit(EXIT_FAILURE);
    }

    init_gpio();
    init_i2c();

    send_command(SDP810_CMD_CONFIG);
    usleep(100000); // Wait for configuration to take effect

    send_command(SDP810_CMD_MEASURE);
    usleep(100000); // Wait for measurement to start

    file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    if (file == NULL) {
        fprintf(file, HEADER_ROW);
    }

    while (1) {
        uint8_t data[9];
        read_data(data);
        process_data(data);
        usleep(1000000); // Wait for 1 second before next measurement
    }

    fclose(file);
    i2c_close(i2c_handle);
    gpiod_line_close(gpiod_line);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

