#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SHT40_I2C_ADDR 0x44
#define SHT40_CMD_HIGH_REPEATABILITY 0x24
#define SHT40_CRC8_POLYNOMIAL 0x31
#define SHT40_CRC8_INIT 0xFF
#define SHT40_LOG_FILE "sht40_log.txt"
#define SHT40_LOG_INTERVAL 5

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *sda_line = NULL;
static struct gpiod_line *scl_line = NULL;

static void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

static void log_timestamped_value(const char *value) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s: %s\n", timestamp, value);
}

static void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

static void handle_sigterm(int signum) {
    handle_sigint(signum);
}

static int sht40_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = SHT40_CRC8_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc & 0x80) ? (crc << 1) ^ SHT40_CRC8_POLYNOMIAL : (crc << 1);
        }
    }
    return crc;
}

static int sht40_read_temperature_and_humidity() {
    unsigned char cmd = SHT40_CMD_HIGH_REPEATABILITY;
    unsigned char buffer[6];
    int ret;

    // Send the command
    ret = write(i2c_fd, &cmd, 1);
    if (ret != 1) {
        log_error("Failed to write command to SHT40");
        return -1;
    }

    // Wait for the measurement to complete
    usleep(10000);

    // Read the result
    ret = read(i2c_fd, buffer, 6);
    if (ret != 6) {
        log_error("Failed to read result from SHT40");
        return -1;
    }

    // Validate the CRC
    unsigned char calculated_crc = sht40_crc8(buffer, 4);
    if (calculated_crc != buffer[4]) {
        log_error("CRC mismatch on temperature and humidity data");
        return -1;
    }

    // Extract the temperature and humidity
    int16_t temperature = (buffer[0] << 8) | buffer[1];
    int16_t humidity = (buffer[3] << 8) | buffer[4];

    // Convert to Celsius and humidity percentage
    float temperature_celsius = (temperature * 175.72 / 65536.0) - 46.85;
    float humidity_percentage = (humidity * 100.0 / 65536.0);

    // Log the values
    log_timestamped_value(fprintf(NULL, "%.2f°C, %.2f%%", temperature_celsius, humidity_percentage));

    return 0;
}

int main() {
    // Set up GPIO for I2C
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        log_error("Failed to open GPIO chip");
        return 1;
    }
    sda_line = gpiod_chip_get_line(gpio_chip, 2);
    scl_line = gpiod_chip_get_line(gpio_chip, 3);
    if (!sda_line || !scl_line) {
        log_error("Failed to get GPIO lines");
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    gpiod_line_request_output(sda_line, "sda", 0);
    gpiod_line_request_output(scl_line, "scl", 0);

    // Set up I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open log file
    log_file = fopen(SHT40_LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        if (sht40_read_temperature_and_humidity() < 0) {
            usleep(1000000); // Retry after 1 second
        } else {
            usleep(1000000 * SHT40_LOG_INTERVAL); // Wait for 5 seconds
        }
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

