static int i2c_write(gpiod_chip *chip, unsigned int line, uint8_t *data, size_t length) {
    int ret;
    for (size_t i = 0; i < length; i++) {
        ret = gpiod_line_set_value(chip, line, data[i]);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            return ret;
        }
        usleep(SDP31_I2C_TIMEOUT);
    }
    return 0;
}

static int i2c_read(gpiod_chip *chip, unsigned int line, uint8_t *data, size_t length) {
    int ret;
    for (size_t i = 0; i < length; i++) {
        ret = gpiod_line_get_value(chip, line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            return ret;
        }
        data[i] = ret;
        usleep(SDP31_I2C_TIMEOUT);
    }
    return 0;
}

