#include <gpiod.h>
#include <fcntl.h>
#include <errno.h>

#define STS30_I2C_ADDR 0x44
#define STS30_CMD_SINGLE_SHOT 0x03
#define STS30_CRC_POLYNOMIAL 0x31
#define STS30_CRC_INIT 0xFF
#define STS30_DATA_LEN 3
#define STS30_TEMP_OFFSET 0x00
#define STS30_TEMP_SCALE 0.01
#define STS30_TEMP_MIN -40.0
#define STS30_TEMP_MAX 125.0

static int i2c_fd = -1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    exit(0);
}

static int crc8(const unsigned char *data, size_t len) {
    int crc = STS30_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1) ? STS30_CRC_POLYNOMIAL : 0);
        }
    }
    return crc;
}

static int read_temperature() {
    unsigned char cmd = STS30_CMD_SINGLE_SHOT;
    unsigned char data[STS30_DATA_LEN];
    unsigned char crc;

    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(error_log_file, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }

    usleep(15000); // Wait for conversion

    if (read(i2c_fd, data, STS30_DATA_LEN) != STS30_DATA_LEN) {
        fprintf(error_log_file, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }

    crc = crc8(data, STS30_DATA_LEN - 1);
    if (crc != data[STS30_DATA_LEN - 1]) {
        fprintf(error_log_file, "CRC mismatch: expected 0x%02X, got 0x%02X\n", crc, data[STS30_DATA_LEN - 1]);
        return -1;
    }

    float temp = (data[STS30_TEMP_OFFSET] << 8) | data[STS30_TEMP_OFFSET + 1];
    temp *= STS30_TEMP_SCALE;
    temp += STS30_TEMP_OFFSET;

    if (temp < STS30_TEMP_MIN || temp > STS30_TEMP_MAX) {
        fprintf(error_log_file, "Temperature out of range: %f\n", temp);
        return -1;
    }

    return temp;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        fprintf(error_log_file, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STS30_I2C_ADDR) == -1) {
        fprintf(error_log_file, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("enclosure_temp_log.txt", "a");
    if (log_file == NULL) {
        fprintf(error_log_file, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    error_log_file = fopen("error_log.txt", "a");
    if (error_log_file == NULL) {
        fprintf(error_log_file, "Error opening error log file: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    while (1) {
        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        float temp = read_temperature();
        if (temp != -1) {
            fprintf(log_file, "%s,%.2f\n", timestamp, temp);
        }

        sleep(60); // Sample every minute
    }

    fclose(log_file);
    fclose(error_log_file);
    close(i2c_fd);

    return 0;
}

