#define SHT40_CMD_READ_STATUS 0xF3
#define SHT40_CMD_SOFT_RESET 0x30
#define SHT40_CRC8_POLYNOMIAL 0x31
#define SHT40_CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void log_reading(const char *timestamp, float temperature, float humidity) {
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

static int calculate_crc8(const unsigned char *data, size_t length) {
    int crc = SHT40_CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc >> 1) ^ ((crc & 1) ? SHT40_CRC8_POLYNOMIAL : 0);
        }
    }
    return crc;
}

static int read_sht40_data(unsigned char *data) {
    if (write(i2c_fd, &SHT40_CMD_MEASURE_HIGH_REP, 1) != 1) {
        perror("Failed to write measurement command");
        return -1;
    }
    usleep(8500); // Wait at least 8.5 ms

    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read data");
        return -1;
    }

    unsigned char crc = calculate_crc8(data, 5);
    if (crc != data[5]) {
        fprintf(stderr, "CRC failure: expected 0x%02x, got 0x%02x\n", crc, data[5]);
        return -1;
    }

    return 0;
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set signal handler");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

