#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define COMMAND_START_CONTINUOUS_MEASUREMENT 0x01
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(signum);
}

int calculate_crc8(const unsigned char *data, size_t length) {
    int crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc >> 1) ^ ((crc & 1) ? CRC8_POLYNOMIAL : 0);
        }
    }
    return crc;
}

void read_sensor_data() {
    unsigned char command[1] = {COMMAND_START_CONTINUOUS_MEASUREMENT};
    unsigned char response[6];
    unsigned char crc8_response[6];

    // Write the command to start continuous measurement
    if (i2c_write(i2c_handle, command, 1) != 1) {
        fprintf(stderr, "Error writing command to sensor\n");
        return;
    }

    // Wait at least 1 ms before reading
    usleep(1000);

    // Read the 6-byte response
    if (i2c_read(i2c_handle, response, 6) != 6) {
        fprintf(stderr, "Error reading response from sensor\n");
        return;
    }

    // Calculate CRC8 for the response
    crc8_response[0] = calculate_crc8(response, 2);
    crc8_response[1] = calculate_crc8(response + 2, 2);
    crc8_response[2] = calculate_crc8(response + 4, 2);

    // Validate CRC8
    if (crc8_response[0] != response[2] || crc8_response[1] != response[4] || crc8_response[2] != response[6]) {
        fprintf(stderr, "CRC8 check failed\n");
        return;
    }

    // Convert raw data to pressure and temperature
    int pressure_msb = response[0] << 8 | response[1];
    int pressure_lsb = response[2] << 8 | response[3];
    int temperature_msb = response[4] << 8 | response[5];
    int temperature_lsb = response[6] << 8 | response[7];

    float pressure = (pressure_msb << 16 | pressure_lsb) / 100.0f;
    float temperature = (temperature_msb << 16 | temperature_lsb) / 100.0f;

    // Get the current timestamp
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    time_t now = ts.tv_sec;
    long ns = ts.tv_nsec / 1000000;

    // Append the timestamp, pressure, and temperature to the log file
    fprintf(log_file, "%ld,%f,%f\n", now, pressure, temperature);
}

int main() {
    // Initialize GPIO and I2C
    if (gpiochip_open(0) < 0) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }
    gpiod_chip = gpiochip_open(0);
    if (gpiod_chip < 0) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }
    gpiod_line = gpiod_chip_get_line(gpiod_chip, 23); // Assuming SDA is connected to GPIO 23
    if (gpiod_line < 0) {
        fprintf(stderr, "Error getting GPIO line\n");
        return 1;
    }
    if (gpiod_line_request_input(gpiod_line, "SDA") < 0) {
        fprintf(stderr, "Error requesting GPIO line\n");
        return 1;
    }
    i2c_handle = i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("airflow_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);

    // Main loop to read sensor data
    while (1) {
        read_sensor_data();
        usleep(1000000); // Wait for 1 second before the next read
    }

    // Clean up resources
    fclose(log_file);
    i2c_close(i2c_handle);
    gpiod_line_close(gpiod_line);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

