#define SCD40_CRC8_INIT 0xFF

#define SCD40_LOG_FILE "air_quality.log"

static void sigint_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, stopping periodic measurement...\n");
        if (gpio_write(gpio_pin, 0) != 0) {
            fprintf(stderr, "Failed to write GPIO pin: %s\n", strerror(errno));
        }
        if (i2c_close(i2c_handle) != 0) {
            fprintf(stderr, "Failed to close I2C handle: %s\n", strerror(errno));
        }
        if (libgpiod_close(gpio_chip) != 0) {
            fprintf(stderr, "Failed to close GPIO chip: %s\n", strerror(errno));
        }
        fclose(log_file);
        exit(EXIT_SUCCESS);
    }
}

static int crc8(const unsigned char *data, size_t length) {
    int crc = SCD40_CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SCD40_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_scd40_data(unsigned char *data) {
    if (i2c_write(i2c_handle, &SCD40_CMD_READ_MEASUREMENT, 1) != 1) {
        fprintf(stderr, "Failed to send command to SCD40: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read(i2c_handle, data, 9) != 9) {
        fprintf(stderr, "Failed to read data from SCD40: %s\n", strerror(errno));
        return -1;
    }
    if (crc8(data, 8) != data[8]) {
        fprintf(stderr, "CRC check failed for SCD40 data\n");
        return -1;
    }
    return 0;
}

