#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds
#define TIMEOUT 500000         // 50 ms timeout in microseconds
#define MAX_FAILURES 3
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

static int gpiod_chip = -1;
static int gpiod_line = -1;
static FILE *log_file = NULL;
static int failures = 0;

static void sig_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpiod_line != -1) {
        gpiod_line_release(gpiod_chip, gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(signum);
}

static void log_temperature(double temp) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, temp);
}

static double read_temperature() {
    struct timespec start, end;
    uint64_t high_pulse_width = 0;
    uint64_t total_cycle_width = 0;
    int ret;

    // Wait for the high pulse
    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret != 0) {
        perror("clock_gettime");
        return NAN;
    }
    while (1) {
        ret = gpiod_line_event_wait(gpiod_line, TIMEOUT);
        if (ret == -1) {
            perror("gpiod_line_event_wait");
            return NAN;
        }
        if (ret == 0) {
            // Timeout occurred
            return NAN;
        }
        ret = gpiod_line_event_get(gpiod_line, &start, &end);
        if (ret != 0) {
            perror("gpiod_line_event_get");
            return NAN;
        }
        if (end.tv_sec == start.tv_sec) {
            high_pulse_width = (end.tv_nsec - start.tv_nsec) / 1000;
        } else {
            high_pulse_width = (1000000000 - start.tv_nsec) + end.tv_nsec;
        }
        if (high_pulse_width > 0) {
            break;
        }
    }

    // Wait for the low pulse
    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret != 0) {
        perror("clock_gettime");
        return NAN;
    }
    while (1) {
        ret = gpiod_line_event_wait(gpiod_line, TIMEOUT);
        if (ret == -1) {
            perror("gpiod_line_event_wait");
            return NAN;
        }
        if (ret == 0) {
            // Timeout occurred
            return NAN;
        }
        ret = gpiod_line_event_get(gpiod_line, &start, &end);
        if (ret != 0) {
            perror("gpiod_line_event_get");
            return NAN;
        }
        if (end.tv_sec == start.tv_sec) {
            total_cycle_width = (end.tv_nsec - start.tv_nsec) / 1000;
        } else {
            total_cycle_width = (1000000000 - start.tv_nsec) + end.tv_nsec;
        }
        if (total_cycle_width > 0) {
            break;
        }
    }

    // Calculate temperature
    double temp = (high_pulse_width / (double)total_cycle_width) * 100.0 - 40.0;
    return temp;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize gpiod
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (gpiod_line == -1) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(gpiod_line, "temperature_sensor");
    if (ret != 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    while (1) {
        double temp = read_temperature();
        if (!isnan(temp)) {
            if (temp >= MIN_TEMP && temp <= MAX_TEMP) {
                log_temperature(temp);
                failures = 0;
            } else {
                failures++;
                if (failures >= MAX_FAILURES) {
                    fprintf(log_file, "SENSOR MALFUNCTION\n");
                    failures = 0;
                }
            }
        }
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpiod_line_release(gpiod_chip, gpiod_line);
    gpiod_chip_close(gpiod_chip);

    return EXIT_SUCCESS;
}

