#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define CRC8_CHECKSUM_LENGTH 1
#define MEASUREMENT_COMMAND 0x03
#define MEASUREMENT_DELAY 45000 // 45 ms in microseconds
#define CSV_FILE "airflow.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(0);
}

static void calculate_crc8(const unsigned char *data, size_t length, unsigned char *crc) {
    *crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        *crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                *crc <<= 1;
            }
        }
    }
}

static int read_sensor_data(unsigned char *data) {
    if (write(i2c_fd, &MEASUREMENT_COMMAND, 1) != 1) {
        perror("Failed to send measurement command");
        return -1;
    }

    usleep(MEASUREMENT_DELAY);

    if (read(i2c_fd, data, 10) != 10) {
        perror("Failed to read sensor data");
        return -1;
    }

    unsigned char crc;
    calculate_crc8(data, 9, &crc);
    if (data[9] != crc) {
        fprintf(stderr, "CRC8 checksum mismatch\n");
        return -1;
    }

    return 0;
}

static void log_data(double pressure, double temperature) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");

    while (1) {
        unsigned char data[10];
        if (read_sensor_data(data) == 0) {
            double pressure = (data[0] << 16) | (data[1] << 8) | data[2];
            double temperature = (data[3] << 16) | (data[4] << 8) | data[5];
            pressure *= 0.01; // Convert to pascals
            temperature *= 0.01; // Convert to degrees Celsius

            log_data(pressure, temperature);
        }

        usleep(1000000); // Wait for 1 second
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

