    int ret;
    struct i2c_msg msgs[2];
    struct i2c_msg *msg = msgs;
    struct i2c_msg *msg_end = msgs + 2;

    msg->addr = I2C_ADDRESS;
    msg->flags = 0;
    msg->len = 1;
    msg->buf = &reg;

    msg++;
    msg->addr = I2C_ADDRESS;
    msg->flags = I2C_M_WR;
    msg->len = len;
    msg->buf = data;

    ret = i2c_transfer(i2c_chip, msgs, msg_end - msgs);
    if (ret < 0) {
        perror("i2c_transfer");
        exit(EXIT_FAILURE);
    }
}

static void read_i2c(uint8_t reg, uint8_t *data, size_t len) {
