    if (ret < 0) {
        perror("i2c_transfer");
        exit(EXIT_FAILURE);
    }
}

static uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc = CRC8_UPDATE(crc, data[i]);
    }
    return CRC8_FINAL(crc);
}

static int validate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = calculate_crc8(data, len - 1);
    return crc == data[len - 1];
}

