        exit(EXIT_FAILURE);
    }

    // Calculate pressure
    uint32_t raw_pressure = (response[0] << 16) | (response[1] << 8) | response[2];
    double pressure = (double)raw_pressure * 0.01; // Convert to Pa

    // Log pressure
