        pressure = (double)raw_pressure * 0.01; // Convert to Pa

        // Log pressure
        log_pressure(pressure);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);
    gpiod_chip_close(i2c_chip);

    return 0;
}

