}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_data(double timestamp, double pressure_pa) {
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%.6f,%f\n", timestamp, pressure_pa);
    if (fprintf(log_file, "%s", log_entry) < 0) {
        log_error("Failed to write to log file");
    }
}

void setup_i2c() {
    i2c_handle = i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    gpiod_handle = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_handle < 0) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    int fan_line = gpiod_chip_get_line(gpiod_handle, GPIO_FAN);
    if (fan_line < 0) {
        log_error("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    int flags = GPIO_LINE_FLAG_OUTPUT;
    if (gpiod_line_request_output(fan_line, "fan", flags) < 0) {
        log_error("Failed to request GPIO line as output");
        exit(EXIT_FAILURE);
    }
}

void setup_pwm() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_FAN, PWM_FREQUENCY) < 0) {
        log_error("Failed to set PWM frequency");
        exit(EXIT_FAILURE);
    }
}

void close_i2c() {
    if (i2c_close(i2c_handle) < 0) {
        log_error("Failed to close I2C device");
    }
}

void close_gpio() {
    if (gpiod_line_release(gpiod_handle, GPIO_FAN) < 0) {
        log_error("Failed to release GPIO line");
    }
    if (gpiod_chip_close(gpiod_handle) < 0) {
        log_error("Failed to close GPIO chip");
    }
}

void close_pwm() {
    gpioTerminate();
}

void read_pressure() {
    uint8_t command[2] = {0x01, 0x00};  // Read pressure register
    uint8_t data[3];

    if (i2c_smbus_write_block_data(i2c_handle, 0x00, 2, command) < 0) {
        log_error("Failed to write command to I2C device");
        return;
    }

    if (i2c_smbus_read_block_data(i2c_handle, 0x00, 3, data) < 0) {
        log_error("Failed to read data from I2C device");
        return;
    }

    int16_t pressure_raw = (data[0] << 8) | data[1];
    double pressure_pa = (double)pressure_raw * 0.01;  // Convert to Pa

    log_data(time(NULL), pressure_pa);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_gpio();
    setup_pwm();

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        close_i2c();
        close_gpio();
        close_pwm();
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        read_pressure();
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    close_i2c();
    close_gpio();
    close_pwm();

    return 0;
}
