        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Read status register
        msgs[0].addr = LPS33HW_I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = &status;
        msgs[1].addr = LPS33HW_I2C_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 2;
        msgs[1].buf = &pressure_msb;
        msgset.msgs = msgs;
        msgset.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
            perror("Failed to read status register");
            fprintf(log_file, "%s: Failed to read status register\n", asctime(&timeinfo));
            fflush(log_file);
            continue;
        }

        // Check if pressure and temperature data is available
        if ((status & 0x01) == 0) {
            fprintf(log_file, "%s: Pressure and temperature data not available\n", asctime(&timeinfo));
            fflush(log_file);
            continue;
