        // Read pressure data
        msgs[0].addr = LPS33HW_I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = &status;
        msgs[1].addr = LPS33HW_I2C_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 2;
        msgs[1].buf = &pressure_msb;
        msgset.msgs = msgs;
        msgset.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
            perror("Failed to read pressure data");
            fprintf(log_file, "%s: Failed to read pressure data\n", asctime(&timeinfo));
            fflush(log_file);
            continue;
        }

        // Read temperature data
        msgs[0].addr = LPS33HW_I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = &status;
        msgs[1].addr = LPS33HW_I2C_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 2;
        msgs[1].buf = &temp_msb;
        msgset.msgs = msgs;
        msgset.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &msgset) < 0) {
            perror("Failed to read temperature data");
            fprintf(log_file, "%s: Failed to read temperature data\n", asctime(&timeinfo));
            fflush(log_file);
            continue;
        }

        // Convert pressure and temperature data
        pressure = (pressure_msb << 8) | pressure_lsb;
        temperature = (temp_msb << 8) | temp_lsb;
        pressure /= 4096.0;
        temperature /= 100.0;

        // Get current time
        time(&timeinfo);
        strftime(buffer, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S, Pressure: %.2f hPa, Temperature: %.2f °C\n", &timeinfo, pressure, temperature);

        // Write to log file
        if (fprintf(log_file, buffer) < 0) {
            perror("Failed to write to log file");
            fprintf(log_file, "%s: Failed to write to log file\n", asctime(&timeinfo));
            fflush(log_file);
            continue;
        }

        // Flush log file
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Invoke library's cleanup call
    // (Assuming there is a cleanup function provided by the library)
    // library_cleanup();

    return EXIT_SUCCESS;
}

