#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <i2c-dev.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_PIN 17
#define BUFFER_SIZE 10
#define AVG_PERIOD 1.0
#define AVG_THRESHOLD 28.0

static int gpiod_handle = -1;
static int i2c_fd = -1;
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;
static float running_average = 0.0;
static int running_average_count = 0;

static void handle_signal(int signum) {
    if (gpiod_handle != -1) {
        gpiod_line_set_value(gpiod_handle, LED_PIN, 0);
        gpiod_close(gpiod_handle);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

static void init_gpiod() {
    gpiod_handle = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_handle == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    gpiod_line *led_line = gpiod_chip_get_line(gpiod_handle, LED_PIN);
    if (gpiod_line_request_output(led_line, "temperature_sensor", 0) != 0) {
        perror("Failed to request GPIO line");
        gpiod_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        gpiod_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }
}

static float read_temperature() {
    uint8_t command = 0x01; // Read temperature register
    uint8_t data[2];
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write to I2C");
        return NAN;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C");
        return NAN;
    }
    float temp = (data[0] << 8) | data[1];
    temp = temp / 128.0 - 40.0;
    return temp;
}

static void update_average(float temp) {
    buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    running_average = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        running_average += buffer[i];
    }
    running_average /= BUFFER_SIZE;
}

static void main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpiod();
    init_i2c();

    while (1) {
        float temp = read_temperature();
        if (!isnan(temp)) {
            update_average(temp);
            if (running_average > AVG_THRESHOLD) {
                gpiod_line_set_value(gpiod_handle, LED_PIN, 1);
            } else {
                gpiod_line_set_value(gpiod_handle, LED_PIN, 0);
            }
        }
        sleep(AVG_PERIOD);
    }

    close(i2c_fd);
    gpiod_close(gpiod_handle);
    exit(EXIT_SUCCESS);
}

