#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define SCD30_I2C_BUS 1
#define SCD30_I2C_TIMEOUT 1000
#define LOG_FILE "air_quality.log"
#define MAX_LOG_LINE_LENGTH 256
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, stopping...\n", signum);
        if (log_file) {
            fclose(log_file);
        }
        if (i2c_handle) {
            i2c_close(i2c_handle);
        }
        if (gpio_handle) {
            gpio_close(gpio_handle);
        }
        exit(0);
    }
}

// Function to log an error message
void log_error(const char *message) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(stderr, "%s: %s\n", buffer, message);
}

// Function to read data from the SCD30 sensor
int read_scd30_data(int i2c_handle, float *co2, float *temperature, float *humidity) {
    uint8_t command[2] = {0x03, 0x00};  // Start measurement command
    uint8_t data[6];
    int result;

