    result = i2c_read(i2c_handle, data, 6);
    if (result < 0) {
        log_error("Failed to read from SCD30");
        return -1;
    }

    if (data[0] != 0x00 || data[1] != 0x00) {
        log_error("CRC mismatch on SCD30 data");
        return -1;
    }

    *co2 = (data[2] << 16) | (data[3] << 8) | data[4];
    *temperature = (data[5] << 16) | (data[6] << 8) | data[7];
    *humidity = (data[8] << 16) | (data[9] << 8) | data[10];

    return 0;
}

// Function to control ventilation based on CO2 concentration
