    if (co2 < 800.0) {
        printf("CO2 level is below 800 ppm, ventilation is OFF.\n");
    } else if (co2 < 1200.0) {
        printf("CO2 level is between 800 and 1199 ppm, ventilation is LOW.\n");
    } else {
        printf("CO2 level is above 1200 ppm, ventilation is HIGH.\n");
    }
