static volatile sig_atomic_t should_exit = 0;

static void signal_handler(int signum) {
    should_exit = 1;
}

static void print_usage(const char *progname) {
    fprintf(stderr, "Usage: %s [-i <interval>]\n", progname);
    fprintf(stderr, "  -i <interval>: Sampling interval in milliseconds (default: %d)\n", SAMPLE_INTERVAL_DEFAULT);
    exit(EXIT_FAILURE);
}

static void calculate_crc8(const unsigned char *data, int length, unsigned char *crc) {
    *crc = CRC8_INIT;
    for (int i = 0; i < length; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                *crc <<= 1;
            }
        }
    }
}

static int read_sensor_data(unsigned char *data) {
    int ret;
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0, 9, data);
    if (ret != 9) {
        fprintf(stderr, "I2C read error: %d\n", ret);
        return -1;
    }
    return 0;
}

static int verify_crc8(const unsigned char *data, int length) {
    unsigned char crc;
    calculate_crc8(data, length, &crc);
    return crc == data[length];
}

static void print_sensor_reading(const unsigned char *data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    printf("%ld.%09ld ", (long)ts.tv_sec, ts.tv_nsec);
    printf("Pressure: %d.%02d Pa\n", (data[0] << 8) | data[1], (data[2] << 8) | data[3]);
    printf("Temperature: %d.%02d °C\n", (data[4] << 8) | data[5], (data[6] << 8) | data[7]);
    printf("Scale Factor: %d.%02d\n", (data[8] << 8) | data[9], (data[10] << 8) | data[11]);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "i:")) != -1) {
        switch (opt) {
            case 'i':
                sample_interval = atoi(optarg);
                if (sample_interval < 1 || sample_interval > SAMPLE_INTERVAL_MAX) {
                    fprintf(stderr, "Invalid sampling interval: %d\n", sample_interval);
                    print_usage(argv[0]);
                }
                break;
            default:
                print_usage(argv[0]);
        }
    }

    if (gpiod_chip < 0) {
        gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
        if (gpiod_chip < 0) {
            perror("Failed to open GPIO chip");
            exit(EXIT_FAILURE);
        }
    }

    if (gpiod_line < 0) {
        gpiod_line = gpiod_line_request_by_name(gpiod_chip, "gpio17", GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN);
        if (gpiod_line < 0) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(gpiod_chip);
            exit(EXIT_FAILURE);
        }
    }

    if (i2c_fd < 0) {
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            perror("Failed to open I2C device");
            gpiod_line_release(gpiod_line);
            gpiod_chip_close(gpiod_chip);
            exit(EXIT_FAILURE);
        }
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("Failed to set I2C slave address");
            close(i2c_fd);
            gpiod_line_release(gpiod_line);
            gpiod_chip_close(gpiod_chip);
            exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!should_exit) {
        unsigned char data[9];
        if (read_sensor_data(data) < 0) {
            continue;
        }
        if (!verify_crc8(data, 9)) {
            fprintf(stderr, "CRC8 verification failed\n");
            continue;
        }
        print_sensor_reading(data);
        usleep(sample_interval * 1000);
    }

    close(i2c_fd);
    gpiod_line_release(gpiod_line);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

