This C program reads the differential pressure from a Sensirion SDP32 sensor over the I2C bus using the `libgpiod` library for GPIO control and the `i2c-dev` library for I2C communication. The program supports a default sampling interval of 1000 milliseconds, which can be overridden with a command-line argument. It verifies the CRC-8 for each reading and handles I2C failures by detecting sensor-absent and bus-error conditions. The program emits a clear diagnostic message and exits if the sensor is not connected, and ensures that all resources are cleanly released on every exit path by installing appropriate signal handlers for SIGINT and SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define SDA_PIN 2
#define SCL_PIN 3
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sda_line = NULL;
static struct gpiod_line *scl_line = NULL;

static void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (sda_line) {
        gpiod_line_release(sda_line);
    }
    if (scl_line) {
        gpiod_line_release(scl_line);
    }
    exit(signum);
}

static int crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLYNOMIAL : (crc << 1);
        }
    }
    return crc;
}

static int read_sdp810() {
    unsigned char buffer[9];
    int ret;

    // Trigger conversion
    ret = i2c_smbus_write_byte(i2c_fd, 0x01);
    if (ret < 0) {
        perror("i2c_smbus_write_byte");
        return -1;
    }

    // Wait for conversion to complete
    usleep(45000);

    // Read 9 bytes
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 9, buffer);
    if (ret < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }

    // Validate CRC-8
    for (size_t i = 0; i < 3; ++i) {
        if (crc8(&buffer[i * 3], 3) != buffer[i * 3 + 3]) {
            fprintf(stderr, "CRC mismatch at byte %zu\n", i * 3);
            return -1;
        }
    }

    // Check for sensor absent or bus error
    if (buffer[0] == 0xFF || buffer[1] == 0xFF || buffer[2] == 0xFF) {
        fprintf(stderr, "Sensor absent or bus error\n");
        return -1;
    }

    // Print results
    printf("Pressure: %.2f Pa\n", buffer[0] << 16 | buffer[1] << 8 | buffer[2]);
    printf("Temperature: %.2f °C\n", buffer[3] << 16 | buffer[4] << 8 | buffer[5]);
    printf("Scale factor: %.2f\n", buffer[6] / 100.0f);

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    sda_line = gpiod_chip_get_line(chip, SDA_PIN);
    if (!sda_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    scl_line = gpiod_chip_get_line(chip, SCL_PIN);
    if (!scl_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(sda_line, "sda", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(scl_line, "scl", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set I2C speed
    ret = i2c_set_speed(i2c_fd, I2C_SPEED_STANDARD);
    if (ret < 0) {
        perror("i2c_set_speed");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Read and log data every second
