#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define SDA_PIN 2
#define SCL_PIN 3
#define LOG_INTERVAL 5000000  // 5 seconds in microseconds

static int gpiod_chip = -1;
static int i2c_fd = -1;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    printf("Resources released.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_line *sda_line = gpiod_chip_get_line(gpiod_chip, SDA_PIN);
    if (gpiod_line == NULL) {
        perror("Failed to get SDA line");
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_line *scl_line = gpiod_chip_get_line(gpiod_chip, SCL_PIN);
    if (scl_line == NULL) {
        perror("Failed to get SCL line");
        cleanup();
        return EXIT_FAILURE;
    }

    int sda_flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int scl_flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;

    if (gpiod_line_request_output(sda_line, "si7051_sda", sda_flags) < 0) {
        perror("Failed to request SDA line");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(scl_line, "si7051_scl", scl_flags) < 0) {
        perror("Failed to request SCL line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    // Function to read temperature from Si7051
    int read_temperature() {
        uint8_t command = 0xF3; // Read temperature command
        uint8_t data[2];

        if (write(i2c_fd, &command, 1) != 1) {
            perror("Failed to write command to Si7051");
            return -1;
        }

        usleep(10000); // Wait for conversion

        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read temperature data from Si7051");
            return -1;
        }

        // Calculate temperature from raw data
        uint16_t raw_temp = (data[0] << 8) | data[1];
        float temp_celsius = -46.85 + (175.72 * raw_temp / 65536.0);

        return temp_celsius;
    }

    while (!should_exit) {
        float temperature = read_temperature();
        if (temperature != -1) {
            printf("Temperature: %.2f°C\n", temperature);
        } else {
            printf("Failed to read temperature from Si7051\n");
        }

        usleep(LOG_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

