    buffer[0] = (result >> 8) & 0xFF;
    buffer[1] = result & 0xFF;

    // Convert the 16-bit temperature value to a float
    float temperature = (buffer[0] << 8) | buffer[1];
    temperature = temperature * 0.01; // Convert to Celsius

    return temperature;
}

