        perror("gpiod_line_request_output");
        gpiod_line_release(line_sda);
        gpiod_line_release(line_scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line_scl, "MLX90819_SCL", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line_sda);
        gpiod_line_release(line_scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

