        gpiod_line_release(line_sda);
        gpiod_line_release(line_scl);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        struct timespec start_time = {0, 0};
        struct timespec end_time = {0, 0};
        struct timespec elapsed_time = {0, 0};

        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Write to the sensor to start a measurement
        uint8_t command = 0x01; // Start measurement command
        if (write(i2c_fd, &command, 1) != 1) {
            perror("write");
            continue;
        }

        // Read the temperature data
        uint8_t data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("read");
            continue;
        }

