        elapsed_time = timespec_sub(end_time, start_time);
        if (elapsed_time.tv_sec < 1) {
            nanosleep(&sleep_time, &remaining_time);
        }
    }

    // Clean up
    close(i2c_fd);
    gpiod_line_release(line_sda);
    gpiod_line_release(line_scl);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

