#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <errno.h>
#include <stdint.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define SDA_PIN 2
#define SCL_PIN 3
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL_MS 45
#define LOG_FILE "pressure_log.txt"

static int gpiod_chip = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

static uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_pressure_temperature() {
    uint8_t buffer[9];
    uint8_t crc;
    int ret;

    ret = gpiod_chip_get_line(gpiod_chip, SDA_PIN);
    if (ret < 0) {
        perror("Failed to get SDA line");
        return -1;
    }
    ret = gpiod_chip_get_line(gpiod_chip, SCL_PIN);
    if (ret < 0) {
        perror("Failed to get SCL line");
        gpiod_line_release(gpiod_chip, SDA_PIN);
        return -1;
    }

    ret = gpiod_line_request_input(gpiod_chip, SDA_PIN, 0);
    if (ret < 0) {
        perror("Failed to request SDA line input");
        gpiod_line_release(gpiod_chip, SDA_PIN);
        gpiod_line_release(gpiod_chip, SCL_PIN);
        return -1;
    }
    ret = gpiod_line_request_output(gpiod_chip, SCL_PIN, 0);
    if (ret < 0) {
        perror("Failed to request SCL line output");
        gpiod_line_release(gpiod_chip, SDA_PIN);
        gpiod_line_release(gpiod_chip, SCL_PIN);
        return -1;
    }

    ret = i2c_smbus_write_byte(i2c_fd, 0x00); // Start measurement
    if (ret < 0) {
        perror("Failed to write to I2C");
        gpiod_line_release(gpiod_chip, SDA_PIN);
        gpiod_line_release(gpiod_chip, SCL_PIN);
        return -1;
    }

    usleep(SAMPLE_INTERVAL_MS * 1000);

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 9, buffer);
    if (ret < 0) {
        perror("Failed to read from I2C");
        gpiod_line_release(gpiod_chip, SDA_PIN);
        gpiod_line_release(gpiod_chip, SCL_PIN);
        return -1;
    }

    crc = crc8(buffer, 9);

    if (crc != buffer[8]) {
        fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", buffer[8], crc);
        gpiod_line_release(gpiod_chip, SDA_PIN);
        gpiod_line_release(gpiod_chip, SCL_PIN);
        return -1;
    }

    uint16_t pressure = (buffer[0] << 8) | buffer[1];
    uint16_t temperature = (buffer[2] << 8) | buffer[3];
    float pressure_pascals = pressure * 0.01;
    float temperature_celsius = (temperature - 4000) / 100.0;

    fprintf(log_file, "%ld,%f,%f\n", time(NULL), pressure_pascals, temperature_celsius);

    gpiod_line_release(gpiod_chip, SDA_PIN);
    gpiod_line_release(gpiod_chip, SCL_PIN);

    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    ret = i2c_smbus_write_byte(i2c_fd, 0x00); // Start measurement
    if (ret < 0) {
        perror("Failed to write to I2C");
        close(i2c_fd);
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    while (1) {
        if (read_pressure_temperature() < 0) {
            fprintf(stderr, "Failed to read pressure and temperature\n");
            break;
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

