#include <gpiod.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define MAX_LOG_SIZE 1024 * 1024
#define LOG_FILE "airflow_log.csv"

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_line != -1) {
        gpiod_line_release(gpiod_chip, gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(signum);
}

static void init_gpio() {
    const char *gpio_chip_name = "gpiochip0";
    const char *gpio_line_name = "21"; // Assuming the trigger pin is GPIO21

    gpiod_chip = gpiod_chip_open(gpio_chip_name);
    if (gpiod_chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, gpio_line_name);
    if (gpiod_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_line_request_input(gpiod_chip, gpiod_line, flags);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    int ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void write_log(const char *timestamp, int pressure) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
        fprintf(log_file, "Timestamp,Pressure\n");
    }

    fprintf(log_file, "%s,%d\n", timestamp, pressure);
    fflush(log_file);
}

static int read_pressure() {
    uint8_t command = 0x03; // Read pressure command
    uint8_t data[3];
    uint8_t crc = 0;

    int ret = write(i2c_fd, &command, 1);
    if (ret < 0) {
        perror("Failed to write command to I2C");
        return -1;
    }

    ret = read(i2c_fd, data, 3);
    if (ret < 0) {
        perror("Failed to read data from I2C");
        return -1;
    }

    // Calculate CRC-8
    for (int i = 0; i < 3; i++) {
        crc = crc8(crc, data[i]);
    }

    // Verify CRC-8
    if (crc != data[3]) {
        fprintf(stderr, "CRC-8 mismatch: expected %02X, got %02X\n", data[3], crc);
        return -1;
    }

    // Convert two bytes to 16-bit signed integer
    int pressure = (data[0] << 8) | data[1];
    return pressure;
}

static uint8_t crc8(uint8_t crc, uint8_t data) {
    for (int i = 0; i < 8; i++) {
        crc ^= data;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();

    struct timespec sleep_time = {0, 8000000}; // 8 ms

    while (1) {
        if (access(LOG_FILE, F_OK) == 0) {
            // File exists, append to it
        } else {
            // File does not exist, write header
            write_log("Timestamp,Pressure", 0);
        }

        if (gpiod_line_get_value(gpiod_line) == 0) {
            // Trigger the sensor
            usleep(100000); // Wait for the sensor to settle
            int pressure = read_pressure();
            if (pressure != -1) {
                char timestamp[20];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                write_log(timestamp, pressure);
            }
        }

        nanosleep(&sleep_time, NULL);
    }

    handle_signal(EXIT_SUCCESS);
    return 0;
}

