This C program initializes the GPIO and I2C interfaces, reads the differential pressure from a Sensirion SDP800-500Pa sensor, and logs the pressure values to a CSV file. It handles errors, detects sensor absence or bus errors, and ensures proper resource release on normal termination and signal receipt.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5F
#define MAX_RETRIES 3
#define SAFE_PRESSURE_MIN 200
#define SAFE_PRESSURE_MAX 250

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

static void handle_sigterm(int signum) {
    handle_sigint(signum);
}

int main() {
    // Install signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize gpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request a line for the interrupt
    line = gpiod_chip_get_line(chip, 17);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Write header row if file is newly created
    if (fseek(log_file, 0, SEEK_END) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    // Read pressure every second
    while (1) {
        uint16_t pressure;
        int retries = MAX_RETRIES;

        while (retries > 0) {
            if (read(i2c_fd, &pressure, 2) != 2) {
                perror("Failed to read from I2C");
                close(i2c_fd);
                gpiod_chip_close(chip);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            retries--;
        }

        // Convert pressure from raw to kPa
        pressure = (pressure >> 2) * 0.01;

        // Check if pressure is within safe range
        if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
            fprintf(stderr, "Warning: Pressure out of safe range: %.2f kPa\n", pressure);
        }

        // Write timestamp and pressure to log file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

