#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define TIMEOUT 1000000 // 1 second in microseconds
#define MAX_PULSE_WIDTH 271 // Maximum pulse width in ticks
#define MIN_PULSE_WIDTH 12 // Minimum pulse width in ticks
#define SYNC_PULSE_WIDTH 56 // Synchronization pulse width in ticks
#define STATUS_NIBBLE 0x0F // Status nibble mask
#define DATA_NIBBLES 0x0F // Data nibble mask
#define CHECKSUM_NIBBLE 0x0F // Checksum nibble mask

static int gpiod_chip = -1;
static int gpiod_line = -1;

void handle_signal(int signum) {
    if (gpiod_chip != -1) {
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
    }
    exit(signum);
}

int read_sent_pulse_width() {
    struct timespec start, end;
    long elapsed;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (gpiod_line_get_value(gpiod_line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            elapsed = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (elapsed > TIMEOUT) {
                fprintf(stderr, "Timeout waiting for pulse\n");
                return -1;
            }
            return elapsed;
        }
    }
}

int read_sent_data() {
    int data = 0;
    for (int i = 0; i < 4; i++) {
        int pulse_width = read_sent_pulse_width();
        if (pulse_width == -1) {
            return -1;
        }
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
            return -1;
        }
        data = (data << 4) | (pulse_width - MIN_PULSE_WIDTH) / 3;
    }
    return data;
}

int read_sent_checksum() {
    int checksum = 0;
    for (int i = 0; i < 4; i++) {
        int pulse_width = read_sent_pulse_width();
        if (pulse_width == -1) {
            return -1;
        }
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
            return -1;
        }
        checksum = (checksum << 4) | (pulse_width - MIN_PULSE_WIDTH) / 3;
    }
    return checksum;
}

int read_sent_status() {
    int status = 0;
    for (int i = 0; i < 4; i++) {
        int pulse_width = read_sent_pulse_width();
        if (pulse_width == -1) {
            return -1;
        }
        if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
            return -1;
        }
        status = (status << 4) | (pulse_width - MIN_PULSE_WIDTH) / 3;
    }
    return status;
}

int main() {
    struct timespec start, end;
    long elapsed;

    // Initialize GPIO
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (gpiod_line == -1) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpiod_line, "sent", 0) != 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Send synchronization pulse
        gpiod_line_set_value(gpiod_line, 1);
        usleep(SYNC_PULSE_WIDTH * 36);
        gpiod_line_set_value(gpiod_line, 0);

        // Read status, data, and checksum
        int status = read_sent_status();
        if (status == -1) {
            continue;
        }

        int data = read_sent_data();
        if (data == -1) {
            continue;
        }

        int checksum = read_sent_checksum();
        if (checksum == -1) {
            continue;
        }

        // Calculate pressure in Pa
        int pressure = (status & STATUS_NIBBLE) << 12 | (data & DATA_NIBBLES) << 8 | (checksum & CHECKSUM_NIBBLE);
        pressure = pressure * 100 / 1023; // Convert to Pa

        // Log the reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);

        // Wait for the next reading
        usleep(1000000); // 1 second
    }

    fclose(log_file);
    gpiod_line_release(gpiod_chip, gpiod_line);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

