#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

#define TMP117_I2C_ADDR 0x48
#define TMP117_DEVICE_ID 0x44
#define TMP117_TEMP_REG 0x00
#define TMP117_TEMP_RESOLUTION 0.0625
#define LOG_FILE "greenhouse_temps.dat"
#define LOG_INTERVAL 60

static int i2c_fd;
static int log_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

void sig_handler(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_fd >= 0) {
        fclose(log_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;
    uint8_t device_id;
    float temperature;
    struct timespec sleep_time;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, TMP117_I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read device ID
    ret = read(i2c_fd, &device_id, 1);
    if (ret != 1) {
        perror("Failed to read device ID");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify device ID
    if (device_id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch, expected 0x%02x, got 0x%02x\n", TMP117_DEVICE_ID, device_id);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_fd = fopen(LOG_FILE, "wb");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for LED
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_chip == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 17); // Assuming GPIO 17 is connected to the LED
    if (gpio_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(gpio_line, "greenhouse_led", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read temperature
        ret = read(i2c_fd, &temperature, 2);
        if (ret != 2) {
            perror("Failed to read temperature");
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            fclose(log_fd);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Convert to float
        temperature = (temperature >> 4) * TMP117_TEMP_RESOLUTION;

        // Write to log file
        ret = fwrite(&temperature, sizeof(float), 1, log_fd);
        if (ret != 1) {
            perror("Failed to write to log file");
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            fclose(log_fd);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Toggle LED
        ret = gpiod_line_set_value(gpio_line, 1);
        if (ret < 0) {
            perror("Failed to toggle LED");
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            fclose(log_fd);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Sleep for 60 seconds
        sleep_time.tv_sec = LOG_INTERVAL;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);

        // Toggle LED
        ret = gpiod_line_set_value(gpio_line, 0);
        if (ret < 0) {
            perror("Failed to toggle LED");
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            fclose(log_fd);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Close resources
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_fd);
    close(i2c_fd);

    return 0;
}

