#define SHT40_I2C_ADDR 0x44
#define SHT40_CMD_TEMP 0x21
#define SHT40_CMD_HUM 0x22
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void sigint_handler(int signum) {
    should_exit = 1;
}

static void calculate_crc8(const unsigned char *data, int length, unsigned char *crc) {
    *crc = SHT40_CRC_INIT;
    for (int i = 0; i < length; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ SHT40_CRC_POLY;
            } else {
                *crc <<= 1;
            }
        }
    }
}

static int validate_crc8(const unsigned char *data, int length) {
    unsigned char crc;
    calculate_crc8(data, length - 1, &crc);
    return crc == data[length - 1];
}

static int read_sht40(unsigned char *data, int length) {
    if (write(i2c_fd, data, length) != length) {
        perror("Failed to write to I2C");
        return -1;
    }
    usleep(8500); // Wait for conversion and sampling
    if (read(i2c_fd, data, length) != length) {
        perror("Failed to read from I2C");
        return -1;
    }
    return 0;
}

static void log_data(const char *timestamp, const unsigned char *data) {
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data[0] | (data[1] << 8), data[3] | (data[4] << 8));
    fflush(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("environmental_data.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        unsigned char data[6];
        if (read_sht40(data, 6) == -1) {
            continue;
        }

        if (!validate_crc8(data, 6)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        log_data(timestamp, data);
    }

    fclose(log_file);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

