#define SHTC3_CMD_WAKEUP_SLEEP_115292150460684697600 0xF1
#define SHTC3_CMD_WAKEUP_SLEEP_230584300921369395200 0xF2
#define SHTC3_CMD_WAKEUP_SLEEP_461168601842738790400 0xF3
#define SHTC3_CMD_WAKEUP_SLEEP_922337203685477580800 0xF4
#define SHTC3_CMD_WAKEUP_SLEEP_1844674407370955161600 0xF5
#define SHTC3_CMD_WAKEUP_SLEEP_3689348814741910323200 0xF6
#define SHTC3_CMD_WAKEUP_SLEEP_7378697629483820646400 0xF7
#define SHTC3_CMD_WAKEUP_SLEEP_14757395258967641289600 0xF8
#define SHTC3_CMD_WAKEUP_SLEEP_29514790517935282579200 0xF9
#define SHTC3_CMD_WAKEUP_SLEEP_59029581035870565158400 0xFA
#define SHTC3_CMD_WAKEUP_SLEEP_118059162071741130316800 0xFB
#define SHTC3_CMD_WAKEUP_SLEEP_236118324143482260633600 0xFC
#define SHTC3_CMD_WAKEUP_SLEEP_472236648286964521267200 0xFD
#define SHTC3_CMD_WAKEUP_SLEEP_944473296573929042534400 0xFE
#define SHTC3_CMD_WAKEUP_SLEEP_188894659314785804508800 0xFF

#define SHTC3_CRC8_POLYNOMIAL 0x31
#define SHTC3_CRC8_INITIAL_VALUE 0xFF

#define SHTC3_MAX_RETRIES 3

static int gpiod_chip = -1;
static int gpiod_line_sda = -1;
static int gpiod_line_scl = -1;
static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static int crc8(const unsigned char *data, size_t length) {
    int crc = SHTC3_CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHTC3_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_i2c(unsigned char cmd, unsigned char *data, size_t length) {
    int ret;
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data msgset;

    msgs[0].addr = SHTC3_I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &cmd;

    msgs[1].addr = SHTC3_I2C_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = length;
    msgs[1].buf = data;

    msgset.msgs = msgs;
    msgset.nmsgs = 2;

    ret = ioctl(gpiod_chip, I2C_RDWR, &msgset);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int write_i2c(unsigned char cmd) {
    int ret;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data msgset;

    msg.addr = SHTC3_I2C_ADDR;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = &cmd;

    msgset.msgs = &msg;
    msgset.nmsgs = 1;

    ret = ioctl(gpiod_chip, I2C_RDWR, &msgset);
    if (ret < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int read_temperature_humidity() {
    unsigned char cmd = SHTC3_CMD_MEASURE;
    unsigned char data[6];
    int ret;
    int retries = 0;

    while (retries < SHTC3_MAX_RETRIES) {
        ret = write_i2c(cmd);
        if (ret < 0) {
            retries++;
            continue;
        }

        usleep(12400); // Wait for conversion and sampling

        ret = read_i2c(SHTC3_CMD_READ_TEMP, data, 2);
        if (ret < 0) {
            retries++;
            continue;
        }

        ret = read_i2c(SHTC3_CMD_READ_HUM, data + 2, 2);
        if (ret < 0) {
            retries++;
            continue;
        }

        unsigned char crc = crc8(data, 4);
        if (crc != data[4]) {
            retries++;
            continue;
        }

        float temperature = (data[0] << 8) | data[1];
        float humidity = (data[2] << 8) | data[3];
        temperature = temperature / 100.0f;
        humidity = humidity / 100.0f;

        if (temperature < -40.0f || temperature > 125.0f || humidity < 0.0f || humidity > 100.0f) {
            retries++;
            continue;
        }

        fprintf(stdout, "%f,%f\n", temperature, humidity);
        fprintf(log_file, "%s,%f,%f\n", asctime(localtime(&time(NULL))), temperature, humidity);

        return 0;
    }

    fprintf(stderr, "Failed to read temperature and humidity after %d retries\n", SHTC3_MAX_RETRIES);
    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpiod_line_sda = gpiod_line_request_output(gpiod_chip, "sda", 0);
    if (gpiod_line_sda < 0) {
        fprintf(stderr, "Failed to request GPIO line SDA: %s\n", strerror(errno));
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    gpiod_line_scl = gpiod_line_request_output(gpiod_chip, "scl", 0);
    if (gpiod_line_scl < 0) {
        fprintf(stderr, "Failed to request GPIO line SCL: %s\n", strerror(errno));
        gpiod_line_release(gpiod_line_sda);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("shtc3_environment.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(gpiod_line_scl);
        gpiod_line_release(gpiod_line_sda);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_temperature_humidity() < 0) {
            break;
        }
        sleep(5);
    }

    fclose(log_file);
    gpiod_line_release(gpiod_line_scl);
    gpiod_line_release(gpiod_line_sda);
    gpiod_chip_close(gpiod_chip);

    return EXIT_SUCCESS;
}
