#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define I2C_READ_REG 0x00
#define I2C_WRITE_REG 0x01
#define I2C_TEMP_REG 0x02
#define I2C_SPEED_REG 0x03
#define I2C_STATUS_REG 0x04
#define I2C_CONFIG_REG 0x05
#define I2C_RESET_REG 0x06

#define LOG_FILE "mag_temp_log.csv"
#define HEADER_ROW "Time,Speed (RPM),Temperature (Celsius)\n"

#define MAX_LOG_SIZE 1024
#define LOG_INTERVAL 1

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {LOG_INTERVAL, 0};
    char log_buffer[MAX_LOG_SIZE];
    char time_str[20];
    double speed_rpm, temperature_celsius;

    // Initialize libgpiod
    ret = gpiod_chip_open_by_name("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    ret = gpioInitialise();
    if (ret < 0) {
        perror("Failed to initialize pigpio");
        gpiod_chip_close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        gpiod_chip_close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_fd);
        gpioTerminate();
        gpiod_chip_close(gpiochip_fd);
        exit(EXIT_FAILURE);
    }

    // Write header row if the file does not exist
    if (fseek(log_file, 0, SEEK_END) == 0) {
        if (ftell(log_file) == 0) {
            fprintf(log_file, HEADER_ROW);
        }
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!should_exit) {
        // Read temperature
        ret = i2cReadReg(i2c_fd, I2C_TEMP_REG);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            speed_rpm = NAN;
            temperature_celsius = NAN;
        } else {
            temperature_celsius = ret / 10.0;
        }

        // Read speed
        ret = i2cReadReg(i2c_fd, I2C_SPEED_REG);
        if (ret < 0) {
            fprintf(stderr, "Failed to read speed\n");
            speed_rpm = NAN;
        } else {
            speed_rpm = ret * 60.0 / 1000.0; // Convert to RPM
        }

        // Format time string
        time_t now = time(NULL);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write to log file
        snprintf(log_buffer, MAX_LOG_SIZE, "%s,%f,%f\n", time_str, speed_rpm, temperature_celsius);
        if (fputs(log_buffer, log_file) == EOF) {
            perror("Failed to write to log file");
        }

        // Sleep for the next interval
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();
    gpiod_chip_close(gpiochip_fd);

    return 0;
}

