#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TMP117_I2C_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_CONFIG 0x01
#define TMP117_CONFIG_OS_SINGLE 0x80
#define TMP117_CONFIG_OS_BUSY 0x80
#define TMP117_CONFIG_OS_DONE 0x00
#define TMP117_CONFIG_ALERT_EN 0x04
#define TMP117_CONFIG_ALERT_POL 0x02
#define TMP117_CONFIG_ALERT_MODE 0x01

static int i2c_fd = -1;
static int gpio_fd = -1;
static int retries = 0;

static void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_fd != -1) {
        gpio_fd = gpiod_chip_close(gpio_fd);
    }
    exit(EXIT_SUCCESS);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpio_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_fd == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
}

static void read_temperature() {
    uint8_t config = 0;
    uint8_t data[2];
    int ret;

    // Read the current configuration
    ret = i2c_smbus_read_byte_data(i2c_fd, TMP117_REG_CONFIG);
    if (ret == -1) {
        perror("Failed to read configuration");
        retries++;
        if (retries >= 3) {
            exit(EXIT_FAILURE);
        }
        return;
    }
    config = ret;

    // Set the OS bit to start a single conversion
    config |= TMP117_CONFIG_OS_SINGLE;
    ret = i2c_smbus_write_byte_data(i2c_fd, TMP117_REG_CONFIG, config);
    if (ret == -1) {
        perror("Failed to set configuration");
        retries++;
        if (retries >= 3) {
            exit(EXIT_FAILURE);
        }
        return;
    }

    // Wait for the conversion to complete
    while ((config & TMP117_CONFIG_OS_BUSY) == TMP117_CONFIG_OS_BUSY) {
        usleep(100000);
        ret = i2c_smbus_read_byte_data(i2c_fd, TMP117_REG_CONFIG);
        if (ret == -1) {
            perror("Failed to read configuration");
            retries++;
            if (retries >= 3) {
                exit(EXIT_FAILURE);
            }
            return;
        }
        config = ret;
    }

    // Read the temperature data
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, TMP117_REG_TEMP, 2, data);
    if (ret == -1) {
        perror("Failed to read temperature data");
        retries++;
        if (retries >= 3) {
            exit(EXIT_FAILURE);
        }
        return;
    }

    // Convert the temperature data to a signed 16-bit integer
    int16_t temp = (data[0] << 8) | data[1];
    if (temp & 0x8000) {
        temp = -((temp ^ 0xFFFF) + 1);
    }

    // Format the temperature reading
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char buffer[100];
    snprintf(buffer, sizeof(buffer), "%s, Temperature: %.2f C\n", timestamp, temp / 1000.0);

    // Write the temperature reading to the log file
    FILE *file = fopen("temperature_log.txt", "a");
    if (file == NULL) {
        perror("Failed to open temperature log file");
        exit(EXIT_FAILURE);
    }
    fprintf(file, "%s", buffer);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_sigint);

    init_i2c();
    init_gpio();

    while (1) {
        read_temperature();
        sleep(1);
    }

    close(i2c_fd);
    gpio_fd = gpiod_chip_close(gpio_fd);
    return EXIT_SUCCESS;
}

