#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static int gpiod_chip = -1;
static int gpiod_line_sda = -1;
static int gpiod_line_scl = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sigint_handler(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_line_sda != -1) {
        gpiod_line_release(gpiod_line_sda);
    }
    if (gpiod_line_scl != -1) {
        gpiod_line_release(gpiod_line_scl);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

static int crc8(const unsigned char *data, size_t length) {
    int crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int write_i2c(const unsigned char *data, size_t length) {
    int retries = 3;
    while (retries--) {
        if (write(i2c_fd, data, length) == length) {
            return 0;
        }
        usleep(100000); // 100 ms
    }
    return -1;
}

static int read_i2c(unsigned char *data, size_t length) {
    int retries = 3;
    while (retries--) {
        if (read(i2c_fd, data, length) == length) {
            return 0;
        }
        usleep(100000); // 100 ms
    }
    return -1;
}

static int sht31d_init() {
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpiod_line_sda = gpiod_line_request_by_offset(gpiod_chip, SDA_PIN, "sht31d_sda");
    if (gpiod_line_sda == -1) {
        perror("Failed to request GPIO line SDA");
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    gpiod_line_scl = gpiod_line_request_by_offset(gpiod_chip, SCL_PIN, "sht31d_scl");
    if (gpiod_line_scl == -1) {
        perror("Failed to request GPIO line SCL");
        gpiod_line_release(gpiod_line_sda);
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    if (gpiod_line_set_direction(gpiod_line_sda, GPIOD_LINE_DIRECTION_OUTPUT) != 0) {
        perror("Failed to set GPIO line SDA direction");
        gpiod_line_release(gpiod_line_sda);
        gpiod_line_release(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    if (gpiod_line_set_direction(gpiod_line_scl, GPIOD_LINE_DIRECTION_OUTPUT) != 0) {
        perror("Failed to set GPIO line SCL direction");
        gpiod_line_release(gpiod_line_sda);
        gpiod_line_release(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        gpiod_line_release(gpiod_line_sda);
        gpiod_line_release(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT31D_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(gpiod_line_sda);
        gpiod_line_release(gpiod_line_scl);
        gpiod_chip_close(gpiod_chip);
        return -1;
    }

    return 0;
}

static int sht31d_measure() {
    unsigned char cmd[2] = {SHT31D_CMD_MEASURE_TEMP_HUM, 0x00};
    if (write_i2c(cmd, sizeof(cmd)) != 0) {
        perror("Failed to write measurement command");
        return -1;
    }

    usleep(15000); // 15 ms

    unsigned char data[6];
    if (read_i2c(data, sizeof(data)) != 0) {
        perror("Failed to read measurement data");
        return -1;
    }

    unsigned char crc = crc8(data, 2);
    if (data[2] != crc) {
        fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", crc, data[2]);
        return -1;
    }

    crc = crc8(data + 3, 2);
    if (data[5] != crc) {
        fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", crc, data[5]);
        return -1;
    }

    float temperature = (data[0] << 8) | data[1];
    temperature = temperature / 100.0f;

    float humidity = (data[3] << 8) | data[4];
    humidity = humidity / 100.0f;

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (sht31d_init() != 0) {
        fprintf(stderr, "Failed to initialize SHT31-D sensor\n");
        return 1;
    }

    log_file = fopen("sht31d_data.log", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        sht31d_deinit();
        return 1;
    }

    while (1) {
        if (sht31d_measure() != 0) {
            fprintf(stderr, "Failed to measure temperature and humidity\n");
        }
        sleep(5);
    }

    fclose(log_file);
    sht31d_deinit();

    return 0;
}
