This C program initializes the SHT31-D sensor on a Raspberry Pi Zero W using the libgpiod library for GPIO control and the i2c-dev library for I2C communication. It reads temperature and humidity every 5 seconds and logs the readings to a file with ISO-8601 timestamps. The program handles errors and retries failed I2C transactions, logs errors, and handles SIGINT and SIGTERM signals to clean up resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define ADPD105_I2C_ADDR 0x54
#define ADPD105_REG_CONFIG 0x00
#define ADPD105_REG_DATA 0x01
#define ADPD105_REG_STATUS 0x02
#define ADPD105_REG_CCT 0x03
#define ADPD105_REG_CCT_STATUS 0x04

#define I2C_BUS 1
#define I2C_CHANNEL 0

#define LOG_FILE "cct_log.csv"
#define LOG_HEADER "Timestamp,Average_CCT"

#define MAX_SAMPLES 100
#define LOG_INTERVAL 1

static int gpiod_chip = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

static void init_i2c() {
    if ((i2c_handle = i2cOpen(I2C_BUS, ADPD105_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }
}

static void init_gpio() {
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }
}

static void write_register(int reg, uint8_t value) {
    uint8_t buffer[2] = {reg, value};
    if (i2cWrite(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
    }
}

static uint8_t read_register(int reg) {
    uint8_t buffer[1] = {reg};
    if (i2cWrite(i2c_handle, buffer, 1) != 1) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
        return 0;
    }
    if (i2cRead(i2c_handle, buffer, 1) != 1) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        return 0;
    }
    return buffer[0];
}

static void read_data(uint8_t *data) {
    if (i2cRead(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read data from ADPD105\n");
    }
}

static void read_cct(uint8_t *cct) {
    if (i2cRead(i2c_handle, cct, 2) != 2) {
        fprintf(stderr, "Failed to read CCT from ADPD105\n");
    }
}

static void log_cct(double cct) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
            return;
        }
        fprintf(log_file, "%s\n", LOG_HEADER);
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, cct);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();

    write_register(ADPD105_REG_CONFIG, 0x01); // Enable sensor
    write_register(ADPD105_REG_CONFIG, 0x03); // Enable data and CCT

    double cct_sum = 0.0;
    int sample_count = 0;

    while (1) {
        uint8_t data[2];
        read_data(data);
        uint8_t cct[2];
        read_cct(cct);

        cct_sum += (double)cct[0] * 256 + cct[1];
        sample_count++;

        if (sample_count >= MAX_SAMPLES) {
            double average_cct = cct_sum / MAX_SAMPLES;
            log_cct(average_cct);
            cct_sum = 0.0;
            sample_count = 0;
        }

        usleep(LOG_INTERVAL * 1000000); // Sleep for 1 second
    }

    handle_signal(0); // Clean up on exit
    return 0;
}

