    if (i2cRead(i2c_handle, buffer, 1) != 1) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        return 0;
    }
    return buffer[0];
}

static void read_data(uint8_t *data) {
    if (i2cRead(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read data from ADPD105\n");
    }
}

static void read_cct(uint8_t *cct) {
    if (i2cRead(i2c_handle, cct, 2) != 2) {
        fprintf(stderr, "Failed to read CCT from ADPD105\n");
    }
}

static void log_cct(double cct) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
            return;
        }
        fprintf(log_file, "%s\n", LOG_HEADER);
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, cct);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();

    write_register(ADPD105_REG_CONFIG, 0x01); // Enable sensor
    write_register(ADPD105_REG_CONFIG, 0x03); // Enable data and CCT

    double cct_sum = 0.0;
    int sample_count = 0;

    while (1) {
        uint8_t data[2];
        read_data(data);
        uint8_t cct[2];
        read_cct(cct);

        cct_sum += (double)cct[0] * 256 + cct[1];
        sample_count++;

        if (sample_count >= MAX_SAMPLES) {
            double average_cct = cct_sum / MAX_SAMPLES;
            log_cct(average_cct);
            cct_sum = 0.0;
            sample_count = 0;
        }

        usleep(LOG_INTERVAL * 1000000); // Sleep for 1 second
    }

    handle_signal(0); // Clean up on exit
    return 0;
}
