#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define GPIO_PIN 18
#define BUFFER_SIZE 60
#define AVG_PERIOD 1
#define HYST 2

static int gpiod_fd = -1;
static int i2c_fd = -1;
static int buffer_index = 0;
static float buffer[BUFFER_SIZE];
static float running_avg = 0.0;
static int fan_state = 0;

static void handle_signal(int sig) {
    if (gpiod_fd >= 0) {
        gpiod_line_set_value(gpiod_fd, GPIO_PIN, 0);
        gpiod_close(gpiod_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

static void init_gpiod() {
    gpiod_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    gpiod_line *line = gpiod_chip_get_line(gpiod_fd, GPIO_PIN);
    if (gpiod_line_request_output(line, "fan_control", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_temperature() {
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read temperature from LM75B: %s\n", strerror(errno));
        return;
    }
    float temp = (data[0] << 8) | data[1];
    temp = temp * 0.125 - 273.15;
    buffer[buffer_index++] = temp;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
    }
}

static void compute_running_avg() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    running_avg = sum / BUFFER_SIZE;
}

static void control_fan() {
    if (running_avg > 28.0 + HYST) {
        if (fan_state == 0) {
            gpiod_line_set_value(gpiod_fd, GPIO_PIN, 1);
            fan_state = 1;
        }
    } else if (running_avg < 26.0 - HYST) {
        if (fan_state == 1) {
            gpiod_line_set_value(gpiod_fd, GPIO_PIN, 0);
            fan_state = 0;
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpiod();
    init_i2c();

    while (1) {
        read_temperature();
        compute_running_avg();
        control_fan();
        sleep(AVG_PERIOD);
    }

    close(i2c_fd);
    gpiod_close(gpiod_fd);
    return 0;
}

