#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL 1000000  // 1 second in microseconds
#define LOG_FILE "airflow.log"
#define MAX_READINGS 9

// Function to calculate CRC-8
unsigned char calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read from I2C
int read_i2c(gpiod_chip *chip, unsigned int line, unsigned char *data, size_t length) {
    int fd = gpiod_chip_open_line(chip, line, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (fd < 0) {
        perror("Failed to open I2C line");
        return -1;
    }

    int ret = gpiod_line_request_input(fd, "airflow");
    if (ret < 0) {
        perror("Failed to request I2C line");
        close(fd);
        return -1;
    }

    for (size_t i = 0; i < length; ++i) {
        ret = gpiod_line_get_value(fd);
        if (ret < 0) {
            perror("Failed to read I2C line");
            gpiod_line_release(fd);
            close(fd);
            return -1;
        }
        data[i] = ret;
    }

    gpiod_line_release(fd);
    close(fd);
    return 0;
}

// Function to write to I2C
int write_i2c(gpiod_chip *chip, unsigned int line, const unsigned char *data, size_t length) {
    int fd = gpiod_chip_open_line(chip, line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (fd < 0) {
        perror("Failed to open I2C line");
        return -1;
    }

    int ret = gpiod_line_request_output(fd, "airflow", 0);
    if (ret < 0) {
        perror("Failed to request I2C line");
        close(fd);
        return -1;
    }

    for (size_t i = 0; i < length; ++i) {
        ret = gpiod_line_set_value(fd, data[i]);
        if (ret < 0) {
            perror("Failed to write I2C line");
            gpiod_line_release(fd);
            close(fd);
            return -1;
        }
    }

    gpiod_line_release(fd);
    close(fd);
    return 0;
}

// Signal handler
void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    fclose(log_file);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    gpiod_chip *chip;
    int ret;

    // Open I2C bus
    chip = gpiod_chip_open(I2C_BUS);
    if (!chip) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set up I2C lines
    unsigned int lines[2] = {17, 18};  // SDA and SCL
    for (unsigned int line : lines) {
        ret = gpiod_chip_add_line_request(chip, line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        if (ret < 0) {
            perror("Failed to add I2C line request");
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,differential_pressure,temperature\n");

    // Read initial data
    unsigned char data[9];
    ret = read_i2c(chip, lines[0], data, 9);
    if (ret < 0) {
        fprintf(stderr, "Failed to read initial data\n");
        fclose(log_file);
        gpiod_chip_close(chip);
        return 1;
    }

    // Calculate CRC
    unsigned char calculated_crc = calculate_crc8(data, 8);
    if (calculated_crc != data[8]) {
        fprintf(stderr, "CRC mismatch\n");
        fclose(log_file);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read differential pressure and temperature
    for (int i = 0; i < MAX_READINGS; ++i) {
        // Wait 45 ms
        usleep(45000);

        // Read data
        ret = read_i2c(chip, lines[0], data, 9);
        if (ret < 0) {
            fprintf(stderr, "Failed to read data\n");
            fclose(log_file);
            gpiod_chip_close(chip);
            return 1;
        }

        // Calculate CRC
        calculated_crc = calculate_crc8(data, 8);
        if (calculated_crc != data[8]) {
            fprintf(stderr, "CRC mismatch\n");
            fclose(log_file);
            gpiod_chip_close(chip);
            return 1;
        }

        // Extract differential pressure and temperature
        float differential_pressure = (data[0] << 8) | data[1];
        float temperature = (data[2] << 8) | data[3];

        // Log reading
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%ld,%f,%f\n", ts.tv_sec * 1000000 + ts.tv_nsec / 1000, differential_pressure, temperature);

        // Print warning if pressure exceeds 5.0 Pa
        if (differential_pressure > 5000) {
            fprintf(stderr, "Warning: Differential pressure exceeds 5.0 Pa\n");
        }

        // Wait for next sample
        usleep(SAMPLE_INTERVAL);
    }

    // Close log file
    fclose(log_file);

    // Clean up
    gpiod_chip_close(chip);

    return 0;
}

