    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request output mode for LED line
    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request output mode for LED line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read temperature from STTS2004 sensor
    while (1) {
        uint8_t data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read temperature from STTS2004 sensor");
            close(i2c_fd);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Convert temperature data to Celsius
        int16_t temp = (data[0] << 8) | data[1];
        float celsius = (temp * 0.0625) - 40.0;

        // Log temperature
        printf("Temperature: %.2f°C\n", celsius);

        // Set LED based on temperature
        if (celsius > TEMP_THRESHOLD + HISTERSIS) {
            gpiod_line_set_value(led_line, 1);
        } else if (celsius < TEMP_THRESHOLD - HISTERSIS) {
            gpiod_line_set_value(led_line, 0);
