#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Function to calculate CRC-8
unsigned char crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(int i2c_fd, unsigned char *data) {
    if (i2c_write_byte(i2c_fd, 0x01) < 0) {
        perror("Failed to initiate measurement");
        return -1;
    }
    usleep(45000); // Wait at least 45 ms

    if (i2c_read(i2c_fd, data, 9) < 0) {
        perror("Failed to read data");
        return -1;
    }

    // Validate CRC-8
    unsigned char calculated_crc = crc8(data, 8);
    if (calculated_crc != data[8]) {
        fprintf(stderr, "CRC-8 validation failed\n");
        return -1;
    }

    return 0;
}

// Signal handler to clean up resources
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        if (i2c_close(i2c_fd) < 0) {
            perror("Failed to close I2C device");
        }
        if (gpio_close(gpio_fd) < 0) {
            perror("Failed to close GPIO device");
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int i2c_fd, gpio_fd;
    unsigned char data[9];
    struct timespec ts;

    // Initialize GPIO
    gpio_fd = gpiochip_open(0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpio_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    FILE *log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2c_close(i2c_fd);
        gpio_close(gpio_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, data) < 0) {
            continue;
        }

        // Extract differential pressure and temperature
        unsigned short pressure = (data[0] << 8) | data[1];
        unsigned short temperature = (data[3] << 8) | data[4];

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log the data
        fprintf(log_file, "%ld.%09ld, %hu, %hu\n", ts.tv_sec, ts.tv_nsec, pressure, temperature);

        // Wait for a short period before the next measurement
        usleep(1000000); // 1 second
    }

    // Close log file
    fclose(log_file);

    // Clean up resources
    i2c_close(i2c_fd);
    gpio_close(gpio_fd);

    return EXIT_SUCCESS;
}

