    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            log_error("Failed to set I2C slave address");
            return -1;
        }
        if (write(i2c_fd, &command, 1) != 1) {
            log_error("Failed to write command to sensor");
            retries++;
            continue;
        }
        usleep(sleep_time.tv_nsec);
        if (read(i2c_fd, &command, 1) != 1) {
            log_error("Failed to read response from sensor");
            retries++;
            continue;
        }
        if (command == 0x00) {
            log_error("Sensor did not respond");
            retries++;
            continue;
        }
        return command;
    }
    log_error("Failed to read sensor after multiple retries");
    return -1;
}

static int read_temperature() {
    int command = read_sensor(MEASURE_TEMP_NO_HOLD);
    if (command < 0) {
        return command;
    }
    int raw_temp = (command << 8) | read_sensor(MEASURE_TEMP_NO_HOLD);
    return (raw_temp >> 4) * 0.0625;
}

static int read_humidity() {
    int command = read_sensor(MEASURE_RH_NO_HOLD);
    if (command < 0) {
        return command;
    }
    int raw_humidity = (command << 8) | read_sensor(MEASURE_RH_NO_HOLD);
    return (raw_humidity >> 2) * 0.001953125;
}

static int read_temperature_from_prev_rh() {
    int command = read_sensor(READ_TEMP_FROM_PREV_RH);
    if (command < 0) {
        return command;
    }
    int raw_temp = (command << 8) | read_sensor(MEASURE_TEMP_NO_HOLD);
    return (raw_temp >> 4) * 0.0625;
}

static int read_sensor_id() {
    int command = read_sensor(0xFA);
    if (command < 0) {
        return command;
    }
    int sensor_id = (command << 8) | read_sensor(0xFB);
    return sensor_id;
}

static int read_sensor_firmware_revision() {
    int command = read_sensor(0xFC);
    if (command < 0) {
        return command;
    }
    int firmware_revision = (command << 8) | read_sensor(0xFD);
    return firmware_revision;
}

static int check_sensor_presence() {
    int sensor_id = read_sensor_id();
    if (sensor_id < 0) {
        return -1;
    }
    int firmware_revision = read_sensor_firmware_revision();
    if (firmware_revision < 0) {
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        log_error("Failed to open GPIO chip");
        return 1;
    }

    if ((sda_line = gpiod_chip_get_line(chip, SDA_PIN)) == NULL) {
        log_error("Failed to get SDA line");
        gpiod_chip_close(chip);
        return 1;
    }

    if ((scl_line = gpiod_chip_get_line(chip, SCL_PIN)) == NULL) {
        log_error("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(sda_line, "SDA", 0) < 0) {
        log_error("Failed to request SDA line as output");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(scl_line, "SCL", 0) < 0) {
        log_error("Failed to request SCL line as output");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        log_error("Failed to open I2C device");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (check_sensor_presence() < 0) {
        log_error("Sensor is absent");
        log_error("Exiting...");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        log_error("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((error_log = fopen(ERROR_LOG, "w")) == NULL) {
        log_error("Failed to open error log file");
        fclose(log_file);
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }

    time_t last_reading_time = time(NULL);
    while (1) {
        if (time(NULL) - last_reading_time >= 60) {
            float temperature_c = read_temperature();
            float humidity_pct = read_humidity();
            if (temperature_c < 0 || humidity_pct < 0) {
                log_error("Failed to read temperature or humidity");
                continue;
            }
            char timestamp[20];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            log_reading(timestamp, temperature_c, humidity_pct);
            last_reading_time = now;
        }
        sleep(1);
    }

    fclose(log_file);
    fclose(error_log);
    close(i2c_fd);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(chip);

    return 0;
}
