#define HDC1080_HUMIDITY_REG 0x01
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_CONFIG_TEMP 0x0000
#define HDC1080_CONFIG_HUMIDITY 0x0000
#define HDC1080_CONFIG_MODE 0x0000
#define HDC1080_CONFIG_OS 0x0000
#define HDC1080_CONFIG_OS_SINGLE 0x0001
#define HDC1080_CONFIG_OS_CONTINUOUS 0x0002
#define HDC1080_CONFIG_OS_NOHEAT 0x0004
#define HDC1080_CONFIG_OS_HEAT 0x0008
#define HDC1080_CONFIG_OS_MASK 0x000F
#define HDC1080_CONFIG_OS_DELAY 1000000 // 1 second

static int i2c_fd;
