    if (gpiod_fd < 0) {
        perror("Failed to open gpiod chip");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    // Set up I2C configuration
    uint8_t config = HDC1080_CONFIG_TEMP | HDC1080_CONFIG_HUMIDITY | HDC1080_CONFIG_MODE_CONTINUOUS | HDC1080_CONFIG_OS_SINGLE;
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write to configuration register");
        close(i2c_fd);
        gpiod_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("enviro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read temperature
        uint16_t temp_raw;
        if (read(i2c_fd, &temp_raw, 2) != 2) {
            perror("Failed to read temperature");
            continue;
        }
        float temp_C = (temp_raw * 175.72 / 65536.0) - 46.85;

        // Read humidity
        uint16_t humidity_raw;
        if (read(i2c_fd, &humidity_raw, 2) != 2) {
            perror("Failed to read humidity");
            continue;
        }
        float humidity_percent = (humidity_raw * 100.0 / 65536.0);

        // Get current time
        clock_gettime(CLOCK_REALTIME, &current_time);

        // Format log entry
        snprintf(log_entry, sizeof(log_entry), "%ld,%f,%f\n", current_time.tv_sec, temp_C, humidity_percent);

        // Write log entry
        if (fputs(log_entry, log_file) == EOF) {
            perror("Failed to write to log file");
            continue;
        }

        // Sleep for 20 ms
        nanosleep(&sleep_time, NULL);

        // Sleep for 5 seconds
        nanosleep(&log_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C
    close(i2c_fd);

    // Close gpiod
    gpiod_close(gpiod_fd);

    return 0;
}

