#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define STS40_I2C_ADDR 0x44
#define STS40_CMD_TEMP 0x03
#define STS40_CRC8_POLYNOMIAL 0x31
#define STS40_CRC8_INIT 0xFF

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sig_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

static void calculate_crc8(const unsigned char *data, size_t length, unsigned char *crc) {
    *crc = STS40_CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        *crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ STS40_CRC8_POLYNOMIAL;
            } else {
                *crc <<= 1;
            }
        }
    }
}

static int read_temperature() {
    unsigned char cmd[1] = {STS40_CMD_TEMP};
    unsigned char data[3];
    unsigned char crc;

    if (write(i2c_fd, cmd, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    usleep(10000); // Wait for conversion to complete

    if (read(i2c_fd, data, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    calculate_crc8(data, 2, &crc);

    if (data[2] != crc) {
        fprintf(stderr, "CRC8 mismatch\n");
        return -1;
    }

    float temperature = (data[0] << 8) | data[1];
    temperature *= 0.01; // Convert to Celsius

    return temperature;
}

int main() {
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        return 1;
    }
    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting SIGTERM handler\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error opening I2C device\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, STS40_I2C_ADDR) == -1) {
        fprintf(stderr, "Error setting I2C slave address\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        close(i2c_fd);
        return 1;
    }

    struct timespec sleep_time = {0, 500000000}; // 5 seconds

    while (1) {
        float temperature = read_temperature();
        if (temperature != -1) {
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
            fflush(log_file);
        }
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

