This C program reads the temperature from a Sensirion STS40 I2C temperature sensor on the Raspberry Pi Zero W. It continuously samples the temperature every 5 seconds, logs each reading with an ISO-8601 timestamp to a file named `temperature_log.txt`, and handles errors such as I2C communication failures and CRC mismatches. The program also installs signal handlers for `SIGINT` and `SIGTERM` to ensure proper cleanup and exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *irq_line;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

static void calculate_crc8(const unsigned char *data, size_t length, unsigned char *crc) {
    *crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        *crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                *crc <<= 1;
            }
        }
    }
}

static int read_i2c_register(unsigned char reg, unsigned char *data, size_t length) {
    unsigned char cmd[2] = {reg, 0};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("write");
        return -1;
    }
    if (read(i2c_fd, data, length) != length) {
        perror("read");
        return -1;
    }
    return 0;
}

static int write_i2c_register(unsigned char reg, const unsigned char *data, size_t length) {
    unsigned char cmd[length + 1] = {reg};
    memcpy(cmd + 1, data, length);
    if (write(i2c_fd, cmd, length + 1) != length + 1) {
        perror("write");
        return -1;
    }
    return 0;
}

static int validate_crc8(const unsigned char *data, size_t length, unsigned char crc) {
    unsigned char calculated_crc;
    calculate_crc8(data, length, &calculated_crc);
    return calculated_crc == crc;
}

static int read_pressure_temperature() {
    unsigned char data[9];
    if (read_i2c_register(0x00, data, 9) != 0) {
        return -1;
    }
    if (!validate_crc8(data, 2, data[2])) {
        fprintf(stderr, "CRC8 error for pressure\n");
        return -1;
    }
