#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libscd4x.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x62
#define BUFFER_SIZE 100
#define CSV_DIR "/var/log/scd40_data/"
#define CSV_FILE "scd40_data.csv"
#define ERROR_LOG "scd40_error.log"
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t buffer_cond = PTHREAD_COND_INITIALIZER;
static scd4x_t sensor;
static scd4x_data_t data;
static char buffer[BUFFER_SIZE][SCD4X_DATA_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *log_file = fopen(ERROR_LOG, "a");
    if (log_file) {
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fclose(log_file);
    }
}

static void *read_sensor(void *arg) {
    while (running) {
        if (scd4x_read(&sensor, &data) != SCD4X_SUCCESS) {
            log_error("Failed to read sensor data");
            continue;
        }

        if (scd4x_validate_crc8(&data) != SCD4X_SUCCESS) {
            log_error("CRC8 validation failed");
            continue;
        }

        pthread_mutex_lock(&buffer_mutex);
        if ((buffer_head + 1) % BUFFER_SIZE == buffer_tail) {
            pthread_cond_wait(&buffer_cond, &buffer_mutex);
        }
        memcpy(buffer[buffer_head], &data, SCD4X_DATA_SIZE);
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        pthread_cond_signal(&buffer_cond);
        pthread_mutex_unlock(&buffer_mutex);

        sleep(5);
    }
    return NULL;
}

static void *log_data(void *arg) {
    while (running) {
        sleep(60);
        pthread_mutex_lock(&buffer_mutex);
        while (buffer_head != buffer_tail) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            FILE *log_file = fopen(CSV_FILE, "a");
            if (log_file) {
                fprintf(log_file, "%s,%f,%f,%f\n", timestamp, data.co2, data.temperature, data.humidity);
                fclose(log_file);
            }
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&buffer_mutex);
    }
    return NULL;
}

static void handle_sigint(int signum) {
    running = 0;
    scd4x_stop_periodic_measurement(&sensor);
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&buffer_mutex);
    pthread_cond_destroy(&buffer_cond);
    scd4x_close(&sensor);
    exit(0);
}

int main() {
    if (scd4x_open(&sensor, I2C_BUS, I2C_ADDRESS) != SCD4X_SUCCESS) {
        log_error("Failed to open I2C device");
        return 1;
    }

    if (scd4x_start_periodic_measurement(&sensor) != SCD4X_SUCCESS) {
        log_error("Failed to start periodic measurement");
        scd4x_close(&sensor);
        return 1;
    }

    if (scd4x_read(&sensor, &data) != SCD4X_SUCCESS) {
        log_error("Failed to read initial sensor data");
        scd4x_stop_periodic_measurement(&sensor);
        scd4x_close(&sensor);
        return 1;
    }

    if (scd4x_validate_crc8(&data) != SCD4X_SUCCESS) {
        log_error("CRC8 validation failed for initial data");
        scd4x_stop_periodic_measurement(&sensor);
        scd4x_close(&sensor);
        return 1;
    }

    if (mkdir(CSV_DIR, 0755) == -1 && errno != EEXIST) {
        log_error("Failed to create CSV directory");
        scd4x_stop_periodic_measurement(&sensor);
        scd4x_close(&sensor);
        return 1;
    }

    if (pthread_create(&logging_thread, NULL, log_data, NULL) != 0) {
        log_error("Failed to create logging thread");
        scd4x_stop_periodic_measurement(&sensor);
        scd4x_close(&sensor);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    pthread_t read_thread;
    if (pthread_create(&read_thread, NULL, read_sensor, NULL) != 0) {
        log_error("Failed to create read thread");
        scd4x_stop_periodic_measurement(&sensor);
        scd4x_close(&sensor);
        return 1;
    }

    pthread_join(read_thread, NULL);
    pthread_join(logging_thread, NULL);

    pthread_mutex_destroy(&buffer_mutex);
    pthread_cond_destroy(&buffer_cond);
    scd4x_close(&sensor);

    return 0;
}

