#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static void calculate_crc8(const unsigned char *data, size_t length, unsigned char *crc) {
    *crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; ++i) {
        *crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (*crc & 0x80) {
                *crc = (*crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                *crc <<= 1;
            }
        }
    }
}

static int validate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc;
    calculate_crc8(data, length - 1, &crc);
    return crc == data[length - 1];
}

static void log_sample(const struct timespec *timestamp, int16_t pressure, int16_t temperature) {
    fprintf(log_file, "%ld,%d,%d\n", timestamp->tv_sec * 1000000000 + timestamp->tv_nsec, pressure, temperature);
}

static int read_sdp810() {
    unsigned char buffer[9];
    struct timespec timestamp;
    clock_gettime(CLOCK_MONOTONIC, &timestamp);

    if (write(i2c_fd, "\x01", 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }

    usleep(45000);

    if (read(i2c_fd, buffer, 9) != 9) {
        perror("Failed to read from I2C");
        return -1;
    }

    if (!validate_crc8(buffer, 9)) {
        fprintf(stderr, "CRC8 validation failed\n");
        return -1;
    }

    int16_t pressure = (buffer[0] << 8) | buffer[1];
    int16_t temperature = (buffer[2] << 8) | buffer[3];
    int16_t scale_factor = (buffer[4] << 8) | buffer[5];

    log_sample(&timestamp, pressure, temperature);

    return 0;
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((gpio_chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((gpio_line = gpiod_chip_get_line(gpio_chip, 17)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "SDP810", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("sdp810_log.txt", "w")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,pressure_Pa,temperature_C\n");

    while (1) {
        if (read_sdp810() < 0) {
            break;
        }
        usleep(1000000);
    }

    fclose(log_file);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

