        fflush(file);

        // Print to stdout
        printf("%s,Pressure: %d, Temperature: %d\n", timestamp, pressure, temperature);
    }

    // Close the file
    fclose(file);

    // Close the I2C handle
    close(i2c_fd);

    // Close the GPIO chip
    gpiod_chip_close(gpiod_chip_open_by_name("gpiochip0"));

