#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x76
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_fd;
static int gpio_fd;
static int led_pin;

void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_fd, led_pin);
        gpiod_close(gpio_fd);
    }
    exit(0);
}

uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    led_pin = gpiod_line_request_output(gpio_fd, "led", 0);
    if (led_pin < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t buffer[6];
    uint8_t crc;
    uint16_t pressure;
    uint16_t temperature;
    int count = 0;

    while (1) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("Failed to set I2C slave address");
            break;
        }

        if (write(i2c_fd, "\x00", 1) != 1) {
            perror("Failed to write to I2C device");
            break;
        }

        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read from I2C device");
            break;
        }

        crc = crc8(buffer, 5);
        if (buffer[5] != crc) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        pressure = (buffer[0] << 8) | buffer[1];
        temperature = (buffer[2] << 8) | buffer[3];

        printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);

        if (pressure < 95000) {
            gpiod_line_set_value(led_pin, 1);
        } else {
            gpiod_line_set_value(led_pin, 0);
        }

        usleep(20000); // 20 ms delay

        count++;
        if (count % 10 == 0) {
            printf("Reads: %d\n", count);
        }
    }

    close(i2c_fd);
    gpiod_line_release(gpio_fd, led_pin);
    gpiod_close(gpio_fd);

    return 0;
}

