code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define FAN_PIN 18
#define MAX_RETRIES 3
#define RETRY_DELAY 10
#define LOG_FILE "temperature_log.txt"
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0

static int i2c_fd = -1;
static int fan_gpio = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t should_exit = 0;

static void handle_sigint(int signum) {
    should_exit = 1;
}

static void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (fan_gpio != -1) {
        gpiod_line_release(fan_gpio);
    }
    gpiod_chip_close(fan_gpio);
}

static int read_temperature() {
    uint16_t raw_temp;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_smbus_read_word_data(i2c_fd, 0x07) == -1) {
            retries++;
            usleep(RETRY_DELAY * 1000);
            continue;
        }
        raw_temp = i2c_smbus_read_word_data(i2c_fd, 0x07);
        return (raw_temp - 0x3F80) * 0.02;
    }
    return -1;
}

static void control_fan(float temp) {
    if (temp > TEMP_THRESHOLD_HIGH) {
        gpiod_line_set_value(fan_gpio, 1);
    } else if (temp < TEMP_THRESHOLD_LOW) {
        gpiod_line_set_value(fan_gpio, 0);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) == -1) {
        perror("Failed to open I2C bus");
        close_resources();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    if ((fan_gpio = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    if ((fan_gpio = gpiod_line_request_output(fan_gpio, FAN_PIN, 0)) == NULL) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(fan_gpio);
        close(i2c_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(fan_gpio);
        gpiod_chip_close(fan_gpio);
        close(i2c_fd);
        close_resources();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        float temp = read_temperature();
        if (temp != -1) {
            struct tm *timeinfo;
            time_t now = time(NULL);
            timeinfo = localtime(&now);
            fprintf(log_file, "%02d:%02d:%02d %.2f\n", timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, temp);
            control_fan(temp);
        }
        sleep(2);
    }

    close_resources();
    return EXIT_SUCCESS;
}

