}

static void read_sht40() {
    uint8_t cmd = SHT40_MEASURE_CMD;
    uint8_t buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(sht40_i2c_fd, &cmd, 1) != 1) {
            perror("Failed to write measurement command");
            retries++;
            continue;
        }

        usleep(10000); // Wait at least 10 ms

        if (read(sht40_i2c_fd, buffer, 6) != 6) {
            perror("Failed to read data from SHT40");
            retries++;
            continue;
        }

        // Check CRC
        uint8_t crc = buffer[0] ^ buffer[1] ^ buffer[2] ^ buffer[3];
        if (crc != buffer[4]) {
            fprintf(stderr, "CRC mismatch\n");
            retries++;
            continue;
        }

        // Extract temperature and humidity
        float temperature = (buffer[0] << 8 | buffer[1]) * 0.01 - SHT40_TEMP_OFFSET;
        float humidity = (buffer[2] << 8 | buffer[3]) * 0.01 - SHT40_HUMIDITY_OFFSET;

