        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpiod_line = gpio_claim_line(gpiod_chip, 17); // Assuming SDA is connected to GPIO 17
    if (gpiod_line < 0) {
        perror("Failed to claim GPIO line");
        gpiochip_close(gpiod_chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sht40_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (sht40_i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpio_free_line(gpiod_line);
        gpiochip_close(gpiod_chip);
        gpioTerminate();
        return EXIT_FAILURE;
