        close(http_socket);
        close(sht40_i2c_fd);
        gpio_free_line(gpiod_line);
        gpiochip_close(gpiod_chip);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_sht40();
        sleep(1); // Update every second
    }

