#include <signal.h>
#include <gpiod.h>

#define TMP102_ADDR 0x48
#define I2C_BUS 1
#define CSV_FILE "temperature_log.csv"
#define MEASUREMENT_INTERVAL 5

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *gpio;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (gpio) {
        gpiod_line_release(gpio);
    }
    exit(EXIT_SUCCESS);
}

static void write_to_csv(const char *timestamp, float temperature) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        return;
    }
    fprintf(file, "%s,%.2f\n", timestamp, temperature);
    fclose(file);
}

static float read_temperature() {
    uint8_t data[2];
    int ret;

    ret = gpiod_line_request_value(gpio, "read", 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        return NAN;
    }

    ret = gpiod_line_set_value(gpio, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line low: %s\n", strerror(errno));
        gpiod_line_release(gpio);
        return NAN;
    }

    usleep(100000); // Wait for the sensor to take a measurement

    ret = gpiod_line_set_value(gpio, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line high: %s\n", strerror(errno));
        gpiod_line_release(gpio);
        return NAN;
    }

    usleep(100000); // Wait for the sensor to complete the measurement

    ret = gpiod_line_request_value(gpio, "read", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to release GPIO line: %s\n", strerror(errno));
        return NAN;
    }

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 2, data);
    if (ret < 0) {
        fprintf(stderr, "Failed to read from I2C: %s\n", strerror(errno));
        return NAN;
    }

    float raw_temp = (data[0] << 8) | data[1];
    float temperature = (raw_temp * 0.0625) - 40.0;

    return temperature;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    gpio = gpiod_chip_get_line(chip, 17); // Assuming GPIO 17 is connected to the TMP102's SDA pin
    if (!gpio) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = i2c_open(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_line_release(gpio);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        float temperature = read_temperature();
        if (!isnan(temperature)) {
            write_to_csv(timestamp, temperature);
        }

        sleep(MEASUREMENT_INTERVAL);
    }

    close(i2c_fd);
    gpiod_line_release(gpio);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

