#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define POLYNOMIAL 0x31
#define INITIAL_VALUE 0xFF

static int i2c_fd;
static int gpio_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *irq_line;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(irq_line);
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    uint8_t buffer[6];
    uint8_t crc8(uint8_t *data, size_t length) {
        uint8_t crc = INITIAL_VALUE;
        for (size_t i = 0; i < length; i++) {
            crc ^= data[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }
        return crc;
    }

    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request IRQ line
    irq_line = gpiod_chip_get_line(chip, 17); // Assuming IRQ line is GPIO 17
    if (!irq_line) {
        perror("Failed to get IRQ line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request IRQ line events
    ret = gpiod_line_request_edge_event(irq_line, GPIOD_EDGE_RISING, 0);
    if (ret < 0) {
        perror("Failed to request IRQ line events");
        gpiod_line_release(irq_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        gpiod_line_release(irq_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read pressure and temperature
    while (1) {
        // Send command to start measurement
        uint8_t command = 0x03; // SDP800-500Pa command
        ret = write(i2c_fd, &command, 1);
        if (ret < 0) {
            perror("Failed to write command");
            continue;
        }

        // Wait for measurement to complete
        usleep(45000);

        // Read six bytes (pressure, CRC, temperature, CRC)
        ret = read(i2c_fd, buffer, 6);
        if (ret < 0) {
            perror("Failed to read data");
            continue;
        }

        // Validate CRC-8 checksum
        uint8_t calculated_crc = crc8(buffer, 4);
        if (calculated_crc != buffer[4]) {
            printf("CRC mismatch: expected 0x%02X, got 0x%02X\n", buffer[4], calculated_crc);
            continue;
        }

        // Extract pressure and temperature
        uint16_t pressure = (buffer[0] << 8) | buffer[1];
        uint16_t temperature = (buffer[2] << 8) | buffer[3];

        // Log raw values
        printf("Pressure: %d Pa, Temperature: %d °C\n", pressure, temperature);

        // Wait 500 ms
        usleep(500000);
    }

    // Clean up
    gpiod_line_release(irq_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

