To implement a PID-controlled reflow oven using a Raspberry Pi 3 Model B+, we need to handle SPI communication with the MAX6675 thermocouple amplifier and GPIO control for the solid-state relay. We will also log temperature readings to a file and apply robust error handling. Below is a complete C program that accomplishes this:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <spi.h>

#define MAX6675_CS_PIN 24
#define MAX6675_CLK_PIN 23
#define MAX6675_DATA_PIN 22
#define SSR_PIN 17
#define SPI_BUS 0
#define SPI_SPEED_HZ 1000000
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_LINES 100
#define MAX_LINE_LENGTH 100

// PID constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// PID variables
double error = 0.0;
double integral = 0.0;
double derivative = 0.0;
double last_error = 0.0;
double setpoint = 0.0;
double output = 0.0;

// SPI context
struct spi_ioc_transfer transfer;
spi_ioc_transfer *spi_transfers;
int spi_fd;

// GPIO context
struct gpiod_chip *chip;
struct gpiod_line *ssr_line;

// Profile variables
double profile[MAX_PROFILE_LINES][2];
int profile_lines = 0;

// Log file
FILE *log_file;

// Signal handler
void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (ssr_line) {
        gpiod_line_release(ssr_line);
    }
    exit(signum);
}

// Read temperature from MAX6675
double read_temperature() {
    uint8_t data[3];
    int ret;

    // Send start bit
    data[0] = 0x00;
    ret = spi_ioc_transfer(spi_fd, &transfer);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1.0;
    }

    // Read data
    data[1] = 0x00;
    data[2] = 0x00;
    ret = spi_ioc_transfer(spi_fd, &transfer);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1.0;
    }

    // Calculate temperature
    int raw_temp = (data[1] << 8) | data[2];
    if (raw_temp & 0x8000) {
        raw_temp = ~raw_temp + 1;
    }
    double temp_celsius = (raw_temp * 0.25) - 273.15;

    return temp_celsius;
}

// Update SSR duty cycle based on PID output
void update_ssr(double duty_cycle) {
    if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else if (duty_cycle > 1.0) {
        duty_cycle = 1.0;
    }

    // Convert duty cycle to GPIO level
    int level = (int)(duty_cycle * 100);
    gpiod_line_set_value(ssr_line, level);
}

// Load profile from file
int load_profile() {
    FILE *file = fopen(PROFILE_FILE, "r");
    if (!file) {
        perror("Failed to open profile file");
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        char *token;
        token = strtok(line, ",");
        if (token == NULL) {
            continue;
        }
        profile[profile_lines][0] = atof(token);

        token = strtok(NULL, ",");
        if (token == NULL) {
            fclose(file);
            return -1;
        }
        profile[profile_lines][1] = atof(token);

        profile_lines++;
        if (profile_lines >= MAX_PROFILE_LINES) {
            break;
        }
    }

    fclose(file);
    return 0;
}

// Log temperature reading
void log_temperature(double temp_celsius) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%f\n", timestamp, temp_celsius);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_transfers = malloc(sizeof(transfer) * 2);
    memset(spi_transfers, 0, sizeof(transfer) * 2);

    transfer.tx_buf = (unsigned long)spi_transfers;
    transfer.rx_buf = (unsigned long)spi_transfers;
    transfer.len = 3;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.delay_usecs = 0;
    transfer.bits_per_word = 8;
    transfer.cs_change = 1;

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    ssr_line = gpiod_chip_get_line(chip, SSR_PIN);
    if (!ssr_line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(ssr_line, "SSR", 0);

    // Load profile
    if (load_profile() < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Main loop
    struct timespec sleep_time = {0, 100000000}; // 100 Hz
    while (1) {
        double temp_celsius = read_temperature();
        if (temp_celsius < 0.0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        // PID control
        error = setpoint - temp_celsius;
        integral += error;
        derivative = error - last_error;
        last_error = error;

        output = Kp * error + Ki * integral + Kd * derivative;

        update_ssr(output);

        // Log temperature
        log_temperature(temp_celsius);

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(ssr_line);
    gpiod_chip_close(chip);
    free(spi_transfers);

    return EXIT_SUCCESS;
}
