#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 100
#define LOG_INTERVAL 5

static int gpio_fd;
static int pwm_fd;
static int log_fd;
static int ds18b20_fd;
static int running = 1;

static void sig_handler(int sig) {
    running = 0;
    close(log_fd);
    close(pwm_fd);
    close(gpio_fd);
    close(ds18b20_fd);
    printf("Program terminated by signal %d\n", sig);
    exit(EXIT_SUCCESS);
}

static void log_data(double avg_temp, double setpoint, double pid_output, int pwm_duty) {
    struct tm *timeinfo;
    char timestamp[20];
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_fd, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, avg_temp, setpoint, pid_output, pwm_duty);
}

static double read_temperature() {
    char path[100];
    char line[100];
    double temp = -1.0;

    snprintf(path, sizeof(path), "%s%s/w1_slave", DS18B20_BUS, DS18B20_ID);
    if (access(path, F_OK) == -1) {
        fprintf(stderr, "DS18B20 sensor not found\n");
        return temp;
    }

    if (read_file(path, line, sizeof(line)) == -1) {
        fprintf(stderr, "Failed to read DS18B20 data\n");
        return temp;
    }

    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "CRC error in DS18B20 data\n");
        return temp;
    }

    char *temp_str = strstr(line, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Failed to parse DS18B20 temperature\n");
        return temp;
    }

    temp_str += 2;
    temp = atof(temp_str) / 1000.0;

    return temp;
}

static int read_file(const char *path, char *buf, size_t size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return -1;
    }

    ssize_t bytes_read = read(fd, buf, size - 1);
    if (bytes_read == -1) {
        perror("Failed to read file");
        close(fd);
        return -1;
    }

    buf[bytes_read] = '\0';
    close(fd);
    return 0;
}

static void set_pwm_duty(int duty) {
    struct pwm_control pwm;
    pwm.duty_cycle = duty;
    if (ioctl(pwm_fd, PWM_IOCTL_SET_DUTY, &pwm) == -1) {
        perror("Failed to set PWM duty cycle");
    }
}

static void set_relay_state(int state) {
    if (state) {
        if (ioctl(gpio_fd, GPIO_SET_OUTPUT, RELAY_PIN) == -1) {
            perror("Failed to set relay pin as output");
        }
        if (ioctl(gpio_fd, GPIO_SET_HIGH, RELAY_PIN) == -1) {
            perror("Failed to turn on relay");
        }
    } else {
        if (ioctl(gpio_fd, GPIO_SET_OUTPUT, RELAY_PIN) == -1) {
            perror("Failed to set relay pin as output");
        }
        if (ioctl(gpio_fd, GPIO_SET_LOW, RELAY_PIN) == -1) {
            perror("Failed to turn off relay");
        }
    }
}

static double compute_pid(double setpoint, double current_temp, double prev_error, double Kp, double Ki, double Kd) {
    double error = setpoint - current_temp;
    double integral = prev_error + error;
    double derivative = error - prev_error;
    double pid_output = Kp * error + Ki * integral + Kd * derivative;
    return pid_output;
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return EXIT_FAILURE;
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    if (Kp <= 0 || Ki <= 0 || Kd <= 0) {
        fprintf(stderr, "Kp, Ki, and Kd must be positive\n");
        return EXIT_FAILURE;
    }

    if (access(DS18B20_BUS, F_OK) == -1) {
        fprintf(stderr, "1-Wire bus not found\n");
        return EXIT_FAILURE;
    }

    if (access(DS18B20_ID, F_OK) == -1) {
        fprintf(stderr, "DS18B20 sensor not found\n");
        return EXIT_FAILURE;
    }

    if (access(LOG_FILE, F_OK) == -1) {
        if (open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644) == -1) {
            perror("Failed to create log file");
            return EXIT_FAILURE;
        }
    }

    log_fd = open(LOG_FILE, O_WRONLY);
    if (log_fd == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_MODE, RELAY_PIN) == -1) {
        perror("Failed to get relay pin mode");
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_SET_OUTPUT, RELAY_PIN) == -1) {
        perror("Failed to set relay pin as output");
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_SET_LOW, RELAY_PIN) == -1) {
        perror("Failed to turn off relay");
        return EXIT_FAILURE;
    }

    pwm_fd = open("/dev/pwmchip0", O_RDWR);
    if (pwm_fd == -1) {
        perror("Failed to open PWM chip");
        return EXIT_FAILURE;
    }

    if (ioctl(pwm_fd, PWM_GET_FREQ, &PWM_FREQ) == -1) {
        perror("Failed to get PWM frequency");
        return EXIT_FAILURE;
    }

    if (ioctl(pwm_fd, PWM_SET_FREQ, &PWM_FREQ) == -1) {
        perror("Failed to set PWM frequency");
        return EXIT_FAILURE;
    }

    if (ioctl(pwm_fd, PWM_GET_DUTY, &pwm.duty_cycle) == -1) {
        perror("Failed to get PWM duty cycle");
        return EXIT_FAILURE;
    }

    if (ioctl(pwm_fd, PWM_SET_DUTY, &pwm.duty_cycle) == -1) {
        perror("Failed to set PWM duty cycle");
        return EXIT_FAILURE;
    }

    double prev_error = 0.0;
    double current_temp = 0.0;
    double pid_output = 0.0;
    int pwm_duty = 0;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        current_temp = read_temperature();
        if (current_temp == -1.0) {
            continue;
        }

        pid_output = compute_pid(setpoint, current_temp, prev_error, Kp, Ki, Kd);
        pwm_duty = (int)(pid_output * PWM_DUTY_MAX);
        pwm_duty = (pwm_duty < 0) ? 0 : (pwm_duty > PWM_DUTY_MAX) ? PWM_DUTY_MAX : pwm_duty;
        set_pwm_duty(pwm_duty);
        set_relay_state(pwm_duty > 0);

        log_data(current_temp, setpoint, pid_output, pwm_duty);

        sleep(LOG_INTERVAL);
    }

    close(log_fd);
    close(pwm_fd);
    close(gpio_fd);
    close(ds18b20_fd);
    printf("Program terminated\n");
    return EXIT_SUCCESS;
