    openlog("htu21d_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request access to the HTU21D sensor
    status = ioctl(i2c_fd, I2C_SLAVE, HTU21D_I2C_ADDR);
    if (status < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "Failed to initialize libcurl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up the HTTP POST request
    curl_easy_setopt(curl, CURLOPT_URL, HTTP_API_URL);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, HTTP_TIMEOUT);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

    while (1) {
        // Read temperature
        buffer[0] = HTU21D_READ_TEMP;
        status = write(i2c_fd, buffer, 1);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to write to I2C bus: %s", strerror(errno));
            break;
        }
        usleep(50000); // Wait for the sensor to complete the measurement

        buffer[0] = 0;
        status = read(i2c_fd, buffer, 3);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to read from I2C bus: %s", strerror(errno));
            break;
        }
        if (buffer[0] != 0x00 || buffer[1] != 0x00) {
            syslog(LOG_ERR, "CRC mismatch or sensor error");
            break;
        }
        float temp = (buffer[2] << 8) | buffer[1];
        temp = -46.85 + (175.72 * temp / 65536.0);

        // Read humidity
        buffer[0] = HTU21D_READ_HUM;
        status = write(i2c_fd, buffer, 1);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to write to I2C bus: %s", strerror(errno));
            break;
        }
        usleep(50000); // Wait for the sensor to complete the measurement

        buffer[0] = 0;
        status = read(i2c_fd, buffer, 3);
        if (status < 0) {
            syslog(LOG_ERR, "Failed to read from I2C bus: %s", strerror(errno));
            break;
        }
        if (buffer[0] != 0x00 || buffer[1] != 0x00) {
            syslog(LOG_ERR, "CRC mismatch or sensor error");
            break;
        }
        float hum = (buffer[2] << 8) | buffer[1];
        hum = -6.0 + (125.0 * hum / 65536.0);

        // Convert to JSON
        snprintf(json, sizeof(json), "{\"temperature\": %.2f, \"humidity\": %.2f}", temp + HTU21D_TEMP_OFFSET, hum + HTU21D_HUM_OFFSET);

        // Perform HTTP POST
        res = curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "Failed to set POST fields: %s", curl_easy_strerror(res));
            break;
        }

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "Failed to perform HTTP POST: %s", curl_easy_strerror(res));
            break;
        }

        // Log the reading
        syslog(LOG_INFO, "Temperature: %.2f°C, Humidity: %.2f%%", temp + HTU21D_TEMP_OFFSET, hum + HTU21D_HUM_OFFSET);

        // Wait for 60 seconds
        sleep(60);
    }

    // Clean up
    curl_easy_cleanup(curl);
    curl_global_cleanup();
    close(i2c_fd);
    closelog();

    return EXIT_SUCCESS;
}
