#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_PIN 17
#define LOG_FILE "/home/pi/logger_%Y-%m-%d.csv"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

static int gpiod_chip = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

static void log_data(double temp, double humidity, int motion) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
        fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    fprintf(log_file, "%s,%f,%f,%d\n", timestamp, temp, humidity, motion);
    fclose(log_file);
}

static int read_i2c(int addr, uint8_t reg, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
            perror("Failed to set I2C slave address");
            return -1;
        }
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            return -1;
        }
        if (read(i2c_fd, data, len) != len) {
            perror("Failed to read data");
            return -1;
        }
        return 0;
    }
    return -1;
}

static int read_tmp117() {
    uint8_t data[2];
    if (read_i2c(TMP117_ADDR, 0x00, data, 2) < 0) {
        return -1;
    }
    int temp_raw = (data[0] << 8) | data[1];
    double temp = (temp_raw * 0.0625) - 40.0;
    return temp;
}

static int read_aht20() {
    uint8_t data[6];
    if (read_i2c(AHT20_ADDR, 0xAC, data, 6) < 0) {
        return -1;
    }
    uint32_t humidity_raw = (data[0] << 16) | (data[1] << 8) | data[2];
    uint32_t temp_raw = (data[3] << 16) | (data[4] << 8) | data[5];
    double humidity = (humidity_raw * 100.0) / 0x380000;
    double temp = (temp_raw * 200.0) / 0x380000 - 50.0;
    return temp;
}

static int read_pir() {
    int value = gpiod_line_get_value(gpiod_chip, PIR_PIN);
    return value;
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return 1;
    }

    gpiod_chip = gpiod_chip_open("/dev/gpiochip4");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpiod_line *pir_line = gpiod_chip_get_line(gpiod_chip, PIR_PIN);
    if (gpiod_line_request_input(pir_line, "PIR") < 0) {
        perror("Failed to request PIR line");
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(pir_line);
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    while (1) {
        double temp = read_tmp117();
        if (temp == -1) {
            fprintf(stderr, "Failed to read TMP117\n");
        }

        double humidity = read_aht20();
        if (humidity == -1) {
            fprintf(stderr, "Failed to read AHT20\n");
        }

        int motion = read_pir();
        if (motion == -1) {
            fprintf(stderr, "Failed to read PIR\n");
        }

        log_data(temp, humidity, motion);

        sleep(1);
    }

    gpiod_line_release(pir_line);
    gpiod_chip_close(gpiod_chip);
    close(i2c_fd);

    return 0;
}

