#define MOTOR_ENA 22
#define MOTOR_IN1 23
#define MOTOR_IN2 24
#define POLL_INTERVAL 2000000 // 2 seconds in microseconds

static volatile sig_atomic_t run = 1;

void sig_handler(int sig) {
    run = 0;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, POLL_INTERVAL};
    struct timespec remaining_time;
    struct timespec start_time;
    struct timespec end_time;
    struct tm *timeinfo;
    char buffer[80];
    char motor_status[80];
    gpiod_chip *chip;
    gpiod_line *line;
    gpiod_line *motor_ena_line;
    gpiod_line *motor_in1_line;
    gpiod_line *motor_in2_line;
    gpiod_line_request *request;

    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    motor_ena_line = gpiod_chip_get_line(chip, MOTOR_ENA);
    motor_in1_line = gpiod_chip_get_line(chip, MOTOR_IN1);
    motor_in2_line = gpiod_chip_get_line(chip, MOTOR_IN2);

    request = gpiod_line_request_input(line, "rain_sensor");
    if (request == NULL) {
        perror("Failed to request input line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    request = gpiod_line_request_output(motor_ena_line, "motor_ena");
    if (request == NULL) {
        perror("Failed to request output line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    request = gpiod_line_request_output(motor_in1_line, "motor_in1");
    if (request == NULL) {
        perror("Failed to request output line");
        gpiod_line_release(line);
        gpiod_line_release(motor_ena_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    request = gpiod_line_request_output(motor_in2_line, "motor_in2");
    if (request == NULL) {
        perror("Failed to request output line");
        gpiod_line_release(line);
        gpiod_line_release(motor_ena_line);
        gpiod_line_release(motor_in1_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (run) {
        ret = gpiod_line_get_value(line);
        if (ret == 0) {
            // Rain detected
            time(&start_time);
            timeinfo = localtime(&start_time);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s: Rain detected\n", buffer);

            // Start motor
            gpiod_line_set_value(motor_ena_line, 1);
            gpiod_line_set_value(motor_in1_line, 1);
            gpiod_line_set_value(motor_in2_line, 0);

            time(&end_time);
            timeinfo = localtime(&end_time);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s: Motor started\n", buffer);

            // Wait for 5 seconds
            nanosleep(&sleep_time, &remaining_time);

            // Stop motor
            gpiod_line_set_value(motor_ena_line, 0);
            gpiod_line_set_value(motor_in1_line, 0);
            gpiod_line_set_value(motor_in2_line, 0);

            time(&end_time);
            timeinfo = localtime(&end_time);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s: Motor stopped\n", buffer);
        }

        // Sleep for 2 seconds
        nanosleep(&sleep_time, &remaining_time);
    }

    // Release resources
    gpiod_line_release(motor_in2_line);
    gpiod_line_release(motor_in1_line);
    gpiod_line_release(motor_ena_line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

