#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>
#include <time.h>

#define GPIO_RED 17
#define GPIO_GREEN 22
#define GPIO_BLUE 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL 500000 // 500 ms in microseconds

static int gpiod_ctx = -1;
static int pwm_red = -1;
static int pwm_green = -1;
static int pwm_blue = -1;

static void sig_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (pwm_red != -1) {
        gpiochip_disable(pwm_red);
    }
    if (pwm_green != -1) {
        gpiochip_disable(pwm_green);
    }
    if (pwm_blue != -1) {
        gpiochip_disable(pwm_blue);
    }
    exit(signum);
}

static void init_pwm(int gpio, int range) {
    int ret;
    struct gpiochip_info info;
    struct gpiochip_config config;

    ret = gpiochip_open(gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(1);
    }
    gpiod_ctx = ret;

    ret = gpiochip_get_info(gpiod_ctx, &info);
    if (ret < 0) {
        fprintf(stderr, "Failed to get GPIO chip info: %s\n", strerror(errno));
        exit(1);
    }

    if (info.type != GPIOCHIP_PWM) {
        fprintf(stderr, "GPIO chip is not a PWM chip\n");
        exit(1);
    }

    config.lines = 1;
    config.line_config[0].offset = 0;
    config.line_config[0].flags = GPIO_LINE_FLAG_OUTPUT;
    config.line_config[0].consumer_label = "PWM";

    ret = gpiochip_config(gpiod_ctx, &config);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure GPIO chip: %s\n", strerror(errno));
        exit(1);
    }

    pwm_red = gpiochip_add_pwmchip(gpiod_ctx, range);
    if (pwm_red < 0) {
        fprintf(stderr, "Failed to add PWM chip: %s\n", strerror(errno));
        exit(1);
    }
}

static void set_pwm(int pwm, int duty_cycle) {
    int ret;
    struct pwm_state state;

    state.duty_cycle = duty_cycle;
    state.period = PWM_FREQUENCY * 1000000 / PWM_RANGE;

    ret = pwm_config(pwm, &state);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure PWM: %s\n", strerror(errno));
        exit(1);
    }
}

static void turn_off_led() {
    set_pwm(pwm_red, 0);
    set_pwm(pwm_green, 0);
    set_pwm(pwm_blue, 0);
}

int main() {
    int ret;
    int cpu_load;
    int prev_cpu_load = -1;
    struct timespec ts;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    init_pwm(GPIO_RED, PWM_RANGE);
    init_pwm(GPIO_GREEN, PWM_RANGE);
    init_pwm(GPIO_BLUE, PWM_RANGE);

    while (1) {
        ret = access("/proc/stat", F_OK);
        if (ret < 0) {
            fprintf(stderr, "Failed to access /proc/stat: %s\n", strerror(errno));
            exit(1);
        }

        FILE *stat_file = fopen("/proc/stat", "r");
        if (stat_file == NULL) {
            fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
            exit(1);
        }

        fscanf(stat_file, "cpu %d %d %d %d %d %d %d %d %d %d %d %d", &cpu_load, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
        fclose(stat_file);

        if (cpu_load != prev_cpu_load) {
            prev_cpu_load = cpu_load;
            int duty_cycle = (cpu_load * PWM_RANGE) / 100;
            set_pwm(pwm_red, duty_cycle);
            set_pwm(pwm_green, duty_cycle);
            set_pwm(pwm_blue, duty_cycle);
        }

        nanosleep(&ts, NULL);
    }

    turn_off_led();
    return 0;
}

