#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <max31855.h>

#define MAX_BUFFER_SIZE 20
#define FAN_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define TEMP_THRESHOLD_1 25.0
#define TEMP_THRESHOLD_2 40.0
#define TEMP_THRESHOLD_3 60.0

struct {
    time_t timestamp;
    float temperature;
    uint8_t duty_cycle;
} buffer[MAX_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_sigint(int signum) {
    // Stop PWM
    gpioPWM(FAN_PIN, 0);
    // Close SPI
    max31855_close();
    // Print buffer contents
    for (int i = 0; i < MAX_BUFFER_SIZE; i++) {
        printf("Timestamp: %ld, Temperature: %.2f°C, Duty Cycle: %d\n",
               buffer[(buffer_tail + i) % MAX_BUFFER_SIZE].timestamp,
               buffer[(buffer_tail + i) % MAX_BUFFER_SIZE].temperature,
               buffer[(buffer_tail + i) % MAX_BUFFER_SIZE].duty_cycle);
    }
