    if (gpio_timer_set(timer_fd, sample_interval_ms)) {
        perror("Failed to set timer");
        close(i2c_fd);
        gpio_timer_delete(timer_fd);
        gpio_exit();
        return 1;
    }

    if (gpio_timer_start(timer_fd)) {
        perror("Failed to start timer");
        close(i2c_fd);
        gpio_timer_delete(timer_fd);
        gpio_exit();
        return 1;
    }

    signal(SIGINT, handle_signal);
