        perror("Failed to start timer");
        close(i2c_fd);
        gpio_timer_delete(timer_fd);
        gpio_exit();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        usleep(100000);
    }

    gpio_timer_delete(timer_fd);
    close(i2c_fd);
    gpio_exit();

    return 0;
}
