#define MIN_DUTY 0
#define PWM_FREQ 25000
#define LOG_INTERVAL 5

static int gpiod_ctx = -1;
static int pwm_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t should_exit = 0;

static void handle_signal(int sig) {
    should_exit = 1;
}

static void log_data(time_t timestamp, int temp, int duty) {
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%ld,%d,%d\n", timestamp, temp, duty);
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }
    if (fprintf(log_file, log_entry) < 0) {
        perror("Failed to write to log file");
    }
    fclose(log_file);
    log_file = NULL;
}

static int read_temperature() {
    char temp_str[10];
    int temp;
    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (temp_file == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }
    if (fgets(temp_str, sizeof(temp_str), temp_file) == NULL) {
        perror("Failed to read temperature file");
        fclose(temp_file);
        return -1;
    }
    fclose(temp_file);
    temp = atoi(temp_str);
    return temp;
}

static int setup_pwm() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, PWM_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "fan_pwm", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    pwm_fd = pwm_set_frequency(line, PWM_FREQ);
    if (pwm_fd < 0) {
        perror("Failed to set PWM frequency");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

static int set_pwm_duty(int duty) {
    if (duty < MIN_DUTY || duty > MAX_DUTY) {
        duty = clamp(duty, MIN_DUTY, MAX_DUTY);
    }
    return pwm_set_duty_cycle(pwm_fd, duty);
}

static int clamp(int value, int min, int max) {
    return value < min ? min : (value > max ? max : value);
}

int main() {
    struct sigaction sa;
    time_t last_log_time = time(NULL);
    int temp, duty;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_pwm() < 0) {
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        temp = read_temperature();
        if (temp < 0) {
            continue;
        }

        duty = clamp((temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP), MIN_DUTY, MAX_DUTY);
        if (set_pwm_duty(duty) < 0) {
            continue;
        }

        if (time(NULL) - last_log_time >= LOG_INTERVAL) {
            log_data(time(NULL), temp, duty);
            last_log_time = time(NULL);
        }

        usleep(1000000); // Sleep for 1 second
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (pwm_fd >= 0) {
        pwm_close(pwm_fd);
    }
    if (gpiod_ctx >= 0) {
        gpiod_chip_close(gpiod_ctx);
    }

    return EXIT_SUCCESS;
}

