#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define LM75_ADDRESS 0x48
#define BUFFER_SIZE 60
#define ALERT_PIN 18
#define TEMPERATURE_THRESHOLD 28.0

static int i2c_fd;
static pthread_t alert_thread;
static pthread_mutex_t buffer_mutex;
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;
static float running_average = 0.0;

static void *alert_thread_func(void *arg) {
    while (1) {
        pthread_mutex_lock(&buffer_mutex);
        float max_temp = buffer[0];
        for (int i = 1; i < BUFFER_SIZE; i++) {
            if (buffer[i] > max_temp) {
                max_temp = buffer[i];
            }
        }
        pthread_mutex_unlock(&buffer_mutex);

        if (max_temp > TEMPERATURE_THRESHOLD) {
            gpio_set_value(ALERT_PIN, 1);
        } else {
            gpio_set_value(ALERT_PIN, 0);
        }

        sleep(1);
    }
    return NULL;
}

static void handle_signal(int sig) {
    pthread_cancel(alert_thread);
    pthread_join(alert_thread, NULL);
    gpio_close(ALERT_PIN);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer_mutex);
    exit(0);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }
}

static void init_gpio() {
    int line_desc = gpiochip_open(0);
    if (line_desc < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(1);
    }
    struct gpiochip_info info;
    if (ioctl(line_desc, GPIO_GET_CHIPINFO_IOCTL, &info) < 0) {
        perror("Failed to get GPIO chip info");
        gpiochip_close(line_desc);
        close(i2c_fd);
        exit(1);
    }
    if (info.lines < ALERT_PIN) {
        fprintf(stderr, "Alert pin %d is out of range\n", ALERT_PIN);
        gpiochip_close(line_desc);
        close(i2c_fd);
        exit(1);
    }
    struct gpiod_line_request req = {
        .line_offset = ALERT_PIN,
        .consumer = "lm75_temperature_alert",
        .request_type = GPIO_LINE_REQUEST_OUTPUT,
        .flags = GPIO_LINE_REQUEST_FLAG_OPEN_DRAIN,
    };
    if (gpiochip_line_request(line_desc, &req) < 0) {
        perror("Failed to request GPIO line");
        gpiochip_close(line_desc);
        close(i2c_fd);
        exit(1);
    }
    gpiochip_close(line_desc);
}

static void read_temperature() {
    uint8_t cmd[2] = {0x00, 0x00};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to write to I2C");
        return;
    }
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C");
        return;
    }
    float temp = (data[0] << 8) | data[1];
    temp = temp * 0.125 - 273.15;
    pthread_mutex_lock(&buffer_mutex);
    buffer[buffer_index] = temp;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    running_average = (running_average * (BUFFER_SIZE - 1) + temp) / BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

static void init_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i] = 0.0;
    }
}

int main() {
    signal(SIGINT, handle_signal);

    init_i2c();
    init_gpio();
    init_buffer();

    pthread_mutex_init(&buffer_mutex, NULL);
    pthread_create(&alert_thread, NULL, alert_thread_func, NULL);

    while (1) {
        read_temperature();
        sleep(1);
    }

    pthread_cancel(alert_thread);
    pthread_join(alert_thread, NULL);
    gpio_close(ALERT_PIN);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer_mutex);

    return 0;
}

