#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <json-c/json.h>
#include <gpiod.h>
#include <max31865.h>
#include <wiringPi.h>

#define MAX31865_CS_PIN 24
#define MAX31865_CLK_PIN 23
#define MAX31865_DIN_PIN 22
#define MAX31865_DOUT_PIN 21
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define REF_RESISTOR 430
#define PT100_NOMINAL_RESISTANCE 100
#define TARGET_TEMP 25
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define MAX_TEMP 80

static int spi_fd;
static int pwm_fd;
static int gpio_fd;
static struct max31865 *max31865;
static struct json_object *config;
static int running = 1;

static void sig_handler(int sig) {
    running = 0;
    gpio_write(gpio_fd, PWM_PIN, 0);
    gpio_close(gpio_fd);
    max31865_close(max31865);
    close(spi_fd);
    exit(EXIT_FAILURE);
}

static void load_config() {
    config = json_object_from_file("config.json");
    if (!config) {
        fprintf(stderr, "Failed to load config file\n");
        exit(EXIT_FAILURE);
    }
    TARGET_TEMP = json_object_get_int(json_object_object_get(config, "target_temp"));
    Kp = json_object_get_double(json_object_object_get(config, "Kp"));
    Ki = json_object_get_double(json_object_object_get(config, "Ki"));
    Kd = json_object_get_double(json_object_object_get(config, "Kd"));
}

static void init_gpio() {
    gpio_fd = gpio_open(0, 0);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpio_export(PWM_PIN, GPIO_OUTPUT);
    gpio_write(gpio_fd, PWM_PIN, 0);
}

static void init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        exit(EXIT_FAILURE);
    }
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 4,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .cs_change = 1,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &xfer) < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        exit(EXIT_FAILURE);
    }
}

static void init_max31865() {
    max31865 = max31865_open(spi_fd, MAX31865_CS_PIN, MAX31865_CLK_PIN, MAX31865_DIN_PIN, MAX31865_DOUT_PIN);
    if (!max31865) {
        fprintf(stderr, "Failed to open MAX31865\n");
        exit(EXIT_FAILURE);
    }
}

static void init_pwm() {
    pwm_fd = wiringPiSetupGpio();
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to initialize wiringPi\n");
        exit(EXIT_FAILURE);
    }
    pwmSetMode(pwm_fd, PWM_MODE_MS);
    pwmSetRange(pwm_fd, PWM_RANGE);
    pwmSetClock(pwm_fd, 19200000 / PWM_FREQ);
}

static void pid_loop() {
    static double last_error = 0;
    static double integral = 0;
    static double derivative = 0;
    static double last_time = 0;
    double current_temp;
    double error;
    double output;

    current_temp = max31865_read_temperature(max31865);
    if (current_temp < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        exit(EXIT_FAILURE);
    }

    error = TARGET_TEMP - current_temp;
    integral += error;
    derivative = error - last_error;
    last_error = error;
    last_time = time(NULL);

    output = Kp * error + Ki * integral + Kd * derivative;

    if (output < 0) {
