        exit(EXIT_FAILURE);
    }
    TARGET_TEMP = json_object_get_int(json_object_object_get(config, "target_temp"));
    Kp = json_object_get_double(json_object_object_get(config, "Kp"));
    Ki = json_object_get_double(json_object_object_get(config, "Ki"));
    Kd = json_object_get_double(json_object_object_get(config, "Kd"));
}

