    gpio_fd = gpio_open(0, 0);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpio_export(PWM_PIN, GPIO_OUTPUT);
    gpio_write(gpio_fd, PWM_PIN, 0);
}

static void init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        exit(EXIT_FAILURE);
    }
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 4,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .cs_change = 1,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &xfer) < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        exit(EXIT_FAILURE);
    }
}

static void init_max31865() {
    max31865 = max31865_open(spi_fd, MAX31865_CS_PIN, MAX31865_CLK_PIN, MAX31865_DIN_PIN, MAX31865_DOUT_PIN);
    if (!max31865) {
        fprintf(stderr, "Failed to open MAX31865\n");
        exit(EXIT_FAILURE);
