        exit(EXIT_FAILURE);
    }
    pwmSetMode(pwm_fd, PWM_MODE_MS);
    pwmSetRange(pwm_fd, PWM_RANGE);
    pwmSetClock(pwm_fd, 19200000 / PWM_FREQ);
