    uint8_t command[2] = {BMP180_REG_PRESS, 0};
    if (i2c_smbus_write_i2c_block_data(i2c_fd, BMP180_REG_PRESS, 2, command) != 2) {
        perror("Failed to write pressure command");
        return;
    }
    usleep(5000); // Wait for the sensor to complete the measurement
