static void timer_callback(void *arg) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (now.tv_sec - last_print_time.tv_sec >= 1) {
        last_print_time = now;
        printf("Temperature: %.2f°C, Pressure: %.2f hPa\n", buffer[buffer_index], buffer[buffer_index + 1]);
