        perror("Failed to get GPIO line");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(fan_gpio, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_state = 0;
