    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct itimerspec timer_spec;
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 500000000; // 500 ms
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 500000000; // 500 ms
    if (timerfd_create(CLOCK_MONOTONIC, 0, &timer_fd) < 0) {
        perror("Failed to create timer");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (timerfd_settime(timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("Failed to set timer");
        close(timer_fd);
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct epoll_event ev;
    ev.events = EPOLLIN;
    ev.data.fd = timer_fd;
    if (epoll_ctl(epoll_fd, EPOLL_CTL_ADD, timer_fd, &ev) < 0) {
        perror("Failed to add timer to epoll");
        close(timer_fd);
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        int events = epoll_wait(epoll_fd, &ev, 1, -1);
        if (events < 0) {
            perror("Failed to wait on epoll");
            close(timer_fd);
            close(i2c_fd);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (ev.data.fd == timer_fd) {
            timer_callback(NULL);
        }
    }

    close(timer_fd);
    close(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
