#define PWM_FREQUENCY 1000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define MAX_TEMP 60000000
#define MIN_TEMP 40000000

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int sig) {
    exit_flag = 1;
}

