#define BMP180_REG_CALIB_36 0xF2
#define BMP180_REG_CALIB_37 0xF4
#define BMP180_REG_CALIB_38 0xF6
#define BMP180_REG_CALIB_39 0xF8
#define BMP180_REG_CALIB_40 0xFA
#define BMP180_REG_CALIB_41 0xFC
#define BMP180_REG_CALIB_42 0xFE

#define OSS_3 3
#define CONVERSION_DELAY 26

#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 2

static int gpiod_chip;
static int gpiod_line;
static int i2c_fd;
static int logging_enabled = 0;
static struct timespec last_log_time;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpiod_line >= 0) {
        gpiod_line_close(gpiod_line);
    }
    if (gpiod_chip >= 0) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(EXIT_SUCCESS);
}

static int read_i2c_register(int reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(i2c_fd, buffer, 1) != 1) {
        perror("read");
        return -1;
    }
    return buffer[0];
}

static int write_i2c_register(int reg, int value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("write");
        return -1;
    }
    return 0;
}

static int read_i2c_block(int reg, uint8_t *buffer, int length) {
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(i2c_fd, buffer, length) != length) {
        perror("read");
        return -1;
    }
    return 0;
}

static int read_bmp180_calibration_data() {
    uint8_t buffer[64];
    if (read_i2c_block(BMP180_REG_CALIB_00, buffer, 64) != 64) {
        return -1;
    }
    return 0;
}

static int read_bmp180_pressure(int oss) {
    uint8_t buffer[3];
    buffer[0] = 0x2E + (oss << 6);
    if (write_i2c_register(BMP180_REG_CONTROL, buffer[0]) != 0) {
        return -1;
    }
    usleep(CONVERSION_DELAY * 1000);
    buffer[0] = read_i2c_register(BMP180_REG_RESULT);
    buffer[1] = read_i2c_register(BMP180_REG_RESULT + 1);
    buffer[2] = read_i2c_register(BMP180_REG_RESULT + 2);
    return (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
}

static int read_bmp180_temperature() {
    uint8_t buffer[3];
    buffer[0] = 0x2E;
    if (write_i2c_register(BMP180_REG_CONTROL, buffer[0]) != 0) {
        return -1;
    }
    usleep(CONVERSION_DELAY * 1000);
    buffer[0] = read_i2c_register(BMP180_REG_RESULT);
    buffer[1] = read_i2c_register(BMP180_REG_RESULT + 1);
    buffer[2] = read_i2c_register(BMP180_REG_RESULT + 2);
    return (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
}

static int calculate_bmp180_pressure(int oss, int temperature) {
    int ac1 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_00) << 8) | read_i2c_register(BMP180_REG_CALIB_01);
    int ac2 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_02) << 8) | read_i2c_register(BMP180_REG_CALIB_03);
    int ac3 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_04) << 8) | read_i2c_register(BMP180_REG_CALIB_05);
    int ac4 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_06) << 8) | read_i2c_register(BMP180_REG_CALIB_07);
    int ac5 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_08) << 8) | read_i2c_register(BMP180_REG_CALIB_09);
    int ac6 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_10) << 8) | read_i2c_register(BMP180_REG_CALIB_11);
    int b1 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_12) << 8) | read_i2c_register(BMP180_REG_CALIB_13);
    int b2 = (int16_t) (read_i2c_register(BMP180_REG_CALIB_14) << 8) | read_i2c_register(BMP180_REG_CALIB_15);
    int mb = (int16_t) (read_i2c_register(BMP180_REG_CALIB_16) << 8) | read_i2c_register(BMP180_REG_CALIB_17);
    int mc = (int16_t) (read_i2c_register(BMP180_REG_CALIB_18) << 8) | read_i2c_register(BMP180_REG_CALIB_19);
    int md = (int16_t) (read_i2c_register(BMP180_REG_CALIB_20) << 8) | read_i2c_register(BMP180_REG_CALIB_21);

    int x1 = (temperature - ac6) * ac5 / 2048;
    int x2 = (x1 * x1) / 4096;
    int x3 = (x2 * ac4) / 16384;
    int b3 = (ac3 * 2048 + x3 + mc) / 16384;
    int b4 = ac2 * 16384 + x1 * x2;
    int b5 = (b3 * 2 + b4) / 32768;
    int b6 = b5 - 4096;
    int x4 = (b6 * b6) / 65536;
    int x5 = (x4 * ac1) / 32768;
    int x6 = (x5 + b1) / 2;
    int p = (x6 * 256 + b2) / 16;
    return p;
}

static int read_bmp180_temperature_and_pressure(int oss) {
    int temperature = read_bmp180_temperature();
    if (temperature < 0) {
        return temperature;
    }
    int pressure = read_bmp180_pressure(oss);
    if (pressure < 0) {
        return pressure;
    }
    return calculate_bmp180_pressure(oss, temperature);
}

static void log_pressure(int pressure) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    fprintf(file, "%ld.%09ld %d\n", now.tv_sec, now.tv_nsec / 1000, pressure);
    fclose(file);
}

static void gpio_callback(int line, int event, void *data) {
    if (event == GPIO_EVENT_RISING_EDGE) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - last_log_time.tv_sec >= LOG_INTERVAL) {
            last_log_time = now;
            if (logging_enabled) {
                int pressure = read_bmp180_temperature_and_pressure(OSS_3);
                if (pressure < 0) {
                    fprintf(stderr, "Error reading pressure: %d\n", pressure);
                } else {
                    log_pressure(pressure);
                }
            } else {
                printf("Logging disabled\n");
            }
        }
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    gpiod_line = gpiod_line_request_input(gpiod_chip, 4, 0);
    if (gpiod_line < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_config(gpiod_line, GPIO_CONFIG_EDGE_RISING, 200000) < 0) {
        perror("gpiod_line_set_config");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_consumer(gpiod_line, "bmp180_logger") < 0) {
        perror("gpiod_line_set_consumer");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_event_handler(gpiod_line, gpio_callback, NULL) < 0) {
        perror("gpiod_line_set_event_handler");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (read_bmp180_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(i2c_fd);
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    printf("BMP180 sensor initialized\n");

    while (1) {
        sleep(1);
    }

    close(i2c_fd);
    gpiod_line_close(gpiod_line);
    gpiod_chip_close(gpiod_chip);

    return EXIT_SUCCESS;
}
