This C program initializes the BMP180 sensor on I2C bus 1, configures it for oversampling setting OSS=3, and sets up a GPIO interrupt on pin 4 to toggle data logging. The interrupt handler debounces using a 200,000 µs delay and logs pressure every 2 seconds when logging is enabled. The program checks every I2C read/write return value and handles errors, and it releases all resources on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <gpiod.h>

#define DHT_PIN 4
#define DHT_BUS 1
#define DHT_RETRY_COUNT 3
#define DHT_BACKOFF_TIME 2000000  // 2 seconds in microseconds
#define DHT_TIMEOUT 40000  // 40 microseconds
#define DHT_START_LOW_TIME 1000000  // 1 millisecond in microseconds
#define DHT_START_HIGH_TIME 20000  // 20 microseconds
#define DHT_DATA_BITS 40
#define DHT_CHECKSUM_BIT 8
#define DHT_CHECKSUM_MASK 0xFF

static const char *url = "http://your-the-library's-API-call.com/api/humidity";

static void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

static void handle_signal(int signum) {
    log_event("Received signal %d, performing graceful shutdown", signum);
    exit(EXIT_SUCCESS);
}

static void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip1");
    if (!chip) {
        log_event("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, DHT_PIN);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "dht22", 0);
    if (ret) {
        log_event("Failed to request GPIO line output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

static void deinit_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip1");
    if (!chip) {
        log_event("Failed to open GPIO chip");
        return;
    }

    line = gpiod_chip_get_line(chip, DHT_PIN);
    if (!line) {
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return;
    }

    ret = gpiod_line_release(line);
    if (ret) {
        log_event("Failed to release GPIO line");
    }

    gpiod_chip_close(chip);
}

static int read_dht22() {
    struct timespec start, end;
    int bit, data[5] = {0};
    int i, j, k;
    int ret;

    // Start signal
    clock_gettime(CLOCK_MONOTONIC, &start);
    gpiod_line_set_value(DHT_PIN, 0);
    usleep(DHT_START_LOW_TIME);
    gpiod_line_set_value(DHT_PIN, 1);
    usleep(DHT_START_HIGH_TIME);
    gpiod_line_set_value(DHT_PIN, 0);

    // Read data
    for (i = 0; i < DHT_DATA_BITS; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(DHT_PIN) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > DHT_TIMEOUT) {
                log_event("Timeout reading DHT22 data bit");
                return -1;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(DHT_PIN) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > DHT_TIMEOUT) {
                log_event("Timeout reading DHT22 data bit");
                return -1;
            }
        }
        if (gpiod_line_get_value(DHT_PIN) == 1) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Checksum
    int checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        log_event("Checksum failed");
        return -1;
    }

    // Calculate humidity and temperature
    int humidity = (data[0] << 8) + data[1];
    int temperature = ((data[2] & 0x7F) << 8) + data[3];
    if (data[2] & 0x80) {
        temperature = -temperature;
    }

    log_event("Humidity: %d%%, Temperature: %.1f°C", humidity, temperature / 10.0);

    return 0;
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char *)userp)[0] = 0;
    return size * nmemb;
}

static int post_data(const char *data) {
    CURL *curl;
    CURLcode res;
    char response[1024] = {0};

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        log_event("Failed to initialize curl");
        curl_global_cleanup();
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(data));
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        log_event("Failed to perform HTTP POST: %s", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return -1;
    }

    log_event("HTTP POST response: %s", response);

    curl_easy_cleanup(curl);
    curl_global_cleanup();

    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    int retry_count = DHT_RETRY_COUNT;
    int backoff_time = DHT_BACKOFF_TIME;
    int success = 0;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();

    while (1) {
        for (int i = 0; i < retry_count; i++) {
            if (read_dht22() == 0) {
                success = 1;
                break;
            }
            log_event("Failed to read DHT22, retrying in %d ms", backoff_time / 1000);
            usleep(backoff_time);
            backoff_time *= 2;
        }

        if (success) {
            char json[256];
            snprintf(json, sizeof(json), "{\"humidity\": %d, \"temperature\": %.1f}", humidity, temperature / 10.0);
            for (int i = 0; i < retry_count; i++) {
                if (post_data(json) == 0) {
                    break;
                }
                log_event("Failed to post data, retrying in %d ms", backoff_time / 1000);
                usleep(backoff_time);
                backoff_time *= 2;
            }
        }

        success = 0;
        backoff_time = DHT_BACKOFF_TIME;
        sleep(10);
    }

    deinit_gpio();
    return 0;
}

