#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define FAN_CONTROL_LOG "/var/log/fan_control.log"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_FAN_SPEED 3
#define MAX_TEMP 65000 // 65°C in millidegrees Celsius

static int fan_fd;
static int temp_fd;
static int gpio_fd;
static int fan_state;
static int max_fan_speed;
static struct timespec last_log_time;

void log_event(const char *message) {
    time_t now;
    struct tm *tm_info;
    char log_message[256];

    time(&now);
    tm_info = localtime(&now);
    strftime(log_message, sizeof(log_message), "%Y-%m-%d %H:%M:%S", tm_info);
    syslog(LOG_INFO, "%s: %s", log_message, message);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_event("Shutting down fan control");
        fan_state = 0;
        if (write(fan_fd, &fan_state, sizeof(fan_state)) != sizeof(fan_state)) {
            syslog(LOG_ERR, "Failed to write fan state: %m");
        }
        close(fan_fd);
        close(temp_fd);
        close(gpio_fd);
        exit(EXIT_SUCCESS);
    }
}

void read_temp() {
    char temp_str[10];
    ssize_t bytes_read;

    bytes_read = read(temp_fd, temp_str, sizeof(temp_str) - 1);
    if (bytes_read <= 0) {
        syslog(LOG_ERR, "Failed to read temperature: %m");
        return;
    }
    temp_str[bytes_read] = '\0';
    int temp = atoi(temp_str);
    if (temp < 0) {
        syslog(LOG_ERR, "Invalid temperature: %s", temp_str);
        return;
    }

    if (temp > MAX_TEMP) {
        syslog(LOG_ERR, "Temperature exceeds maximum: %d°C", temp);
        return;
    }

    int fan_speed = 0;
    if (temp < 45000) {
        fan_speed = 0;
    } else if (temp < 55000) {
        fan_speed = 1;
    } else if (temp < 65000) {
        fan_speed = 2;
    } else {
        fan_speed = 3;
    }

    if (fan_speed != fan_state) {
        fan_state = fan_speed;
        if (write(fan_fd, &fan_state, sizeof(fan_state)) != sizeof(fan_state)) {
            syslog(LOG_ERR, "Failed to write fan state: %m");
        }
        log_event("Fan speed set to %d", fan_state);
    }
}

int main() {
    int ret;
    struct sigaction sa;

    // Initialize logging
    openlog("fan_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    gpio_fd = gpiochip_open(0);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO: %m");
        exit(EXIT_FAILURE);
    }

    // Initialize temperature file
    temp_fd = open(TEMP_FILE, O_RDONLY);
    if (temp_fd < 0) {
        syslog(LOG_ERR, "Failed to open temperature file: %m");
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize fan state file
    fan_fd = open(FAN_STATE_FILE, O_RDWR);
    if (fan_fd < 0) {
        syslog(LOG_ERR, "Failed to open fan state file: %m");
        close(temp_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Read max fan speed
    char max_speed_str[10];
    ssize_t bytes_read = read(fan_fd, max_speed_str, sizeof(max_speed_str) - 1);
    if (bytes_read <= 0) {
        syslog(LOG_ERR, "Failed to read max fan speed: %m");
        close(fan_fd);
        close(temp_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
    max_speed_str[bytes_read] = '\0';
    max_fan_speed = atoi(max_speed_str);
    if (max_fan_speed < 0 || max_fan_speed > MAX_FAN_SPEED) {
        syslog(LOG_ERR, "Invalid max fan speed: %s", max_speed_str);
        close(fan_fd);
        close(temp_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler: %m");
        close(fan_fd);
        close(temp_fd);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize last log time
    clock_gettime(CLOCK_REALTIME, &last_log_time);

    // Main loop
    while (1) {
        read_temp();
        sleep(5);

        // Log event every 60 seconds
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        if (now.tv_sec - last_log_time.tv_sec >= 60) {
            log_event("Fan control loop running");
            last_log_time = now;
        }
    }

    // Close resources
    close(fan_fd);
    close(temp_fd);
    close(gpio_fd);
    closelog();

    return EXIT_SUCCESS;
}

