#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <math.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 500000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USECS 0
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0

static int spi_fd;
static int pwm_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *pwm_line;
static FILE *log_file;
static double last_error = 0.0;
static double integral = 0.0;
static double derivative = 0.0;
static double setpoint = 50.0;
static double current_temp = 0.0;
static double pid_output = 0.0;
static double last_time = 0.0;
static double dt = 0.001; // 1 ms

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(spi_fd);
        close(pwm_fd);
        gpiod_chip_close(chip);
        fclose(log_file);
        printf("Heater stopped and resources released.\n");
        exit(0);
    }
}

static void log_data(double temp, double duty, double pid) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", buffer, temp, duty, pid);
    fflush(log_file);
}

static void read_temperature() {
    uint8_t tx[4] = {0x01, 0x00, 0x00, 0x00};
    uint8_t rx[4];
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        perror("SPI read failed");
        exit(1);
    }
    current_temp = (rx[0] << 16) | (rx[1] << 8) | rx[2];
    current_temp = (current_temp >> 4) * 0.25;
    if (rx[3] & 0x01) {
        printf("Open-circuit fault detected.\n");
        pid_output = 0.0;
        integral = 0.0;
        derivative = 0.0;
        current_temp = 0.0;
    } else if (rx[3] & 0x02) {
        printf("Short-to-GND fault detected.\n");
        pid_output = 0.0;
        integral = 0.0;
        derivative = 0.0;
        current_temp = 0.0;
    } else if (rx[3] & 0x04) {
        printf("Short-to-VCC fault detected.\n");
        pid_output = 0.0;
        integral = 0.0;
        derivative = 0.0;
        current_temp = 0.0;
    }
    if (current_temp > MAX_TEMP) {
        printf("Temperature exceeded max limit.\n");
        pid_output = 0.0;
        integral = 0.0;
        derivative = 0.0;
        current_temp = 0.0;
    } else if (current_temp < MIN_TEMP) {
        printf("Temperature below min limit.\n");
        pid_output = 0.0;
        integral = 0.0;
        derivative = 0.0;
        current_temp = 0.0;
    }
}

static void pid_controller() {
    double error = setpoint - current_temp;
    integral += error * dt;
    derivative = (error - last_error) / dt;
    pid_output = Kp * error + Ki * integral + Kd * derivative;
    if (pid_output > PWM_RANGE) {
        pid_output = PWM_RANGE;
    } else if (pid_output < 0) {
        pid_output = 0;
    }
    last_error = error;
}

static void set_pwm_duty(double duty) {
    int ret = ioctl(pwm_fd, PWM_SETDUTYCYCLE, duty);
    if (ret < 0) {
        perror("PWM set duty cycle failed");
        exit(1);
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("SPI open failed");
        exit(1);
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .delay_usecs = SPI_DELAY_USECS,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &tr) < 0) {
        perror("SPI ioctl failed");
        close(spi_fd);
        exit(1);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("GPIO chip open failed");
        close(spi_fd);
        exit(1);
    }

    pwm_line = gpiod_chip_get_line(chip, PWM_PIN);
    if (!pwm_line) {
        perror("GPIO line open failed");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    int ret = gpiod_line_request_output(pwm_line, "heater_pwm", 0);
    if (ret < 0) {
        perror("GPIO line request failed");
        gpiod_line_close(pwm_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    pwm_fd = open("/dev/pwm/0", O_RDWR);
    if (pwm_fd < 0) {
        perror("PWM open failed");
        gpiod_line_close(pwm_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    ret = ioctl(pwm_fd, PWM_GET_FREQ, &PWM_FREQ);
    if (ret < 0) {
        perror("PWM get frequency failed");
        close(pwm_fd);
        gpiod_line_close(pwm_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    ret = ioctl(pwm_fd, PWM_GET_RANGE, &PWM_RANGE);
    if (ret < 0) {
        perror("PWM get range failed");
        close(pwm_fd);
        gpiod_line_close(pwm_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Log file open failed");
        close(pwm_fd);
        gpiod_line_close(pwm_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    while (1) {
        read_temperature();
        pid_controller();
        set_pwm_duty(pid_output);
        log_data(current_temp, pid_output, pid_output);
        last_time = time(NULL);
        sleep(1);
    }

    close(spi_fd);
    close(pwm_fd);
    gpiod_line_close(pwm_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

