#define TEMP_THRESHOLD_LOW 40
#define TEMP_THRESHOLD_HIGH 70
#define LOG_FILE "cooling_log.csv"
#define LOG_HEADER "Timestamp, Temperature (°C), PWM Duty Cycle (%)"

static int gpiod_chip = -1;
static int pwm_line = -1;
static FILE *log_file = NULL;

static void handle_signal(int signum) {
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    if (pwm_line != -1) {
        gpiod_line_release(pwm_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static void log_reading(const char *timestamp, float temperature, float duty_cycle) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "%s\n", LOG_HEADER);
    }
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fclose(log_file);
}

static float map_temperature_to_duty_cycle(float temperature) {
    if (temperature <= TEMP_THRESHOLD_LOW) {
        return 0.0;
    } else if (temperature >= TEMP_THRESHOLD_HIGH) {
        return 100.0;
    } else {
        return (temperature - TEMP_THRESHOLD_LOW) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW) * 100.0;
    }
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 5 seconds
    struct timespec start_time;
    struct timespec current_time;
    float temperature;
    float duty_cycle;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    pwm_line = gpiod_chip_get_line(gpiod_chip, PWM_PIN);
    if (pwm_line == -1) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(pwm_line, "cooling", 0);
    if (ret != 0) {
        perror("Failed to request GPIO line as output");
        exit(EXIT_FAILURE);
    }

    // Initialize PWM
    ret = gpiod_line_set_value(pwm_line, 0); // Turn off fan initially
    if (ret != 0) {
        perror("Failed to set PWM line value to 0");
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Log header
    fprintf(log_file, "%s\n", LOG_HEADER);
    fclose(log_file);

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Calculate elapsed time since last reading
        if (start_time.tv_sec == 0 && start_time.tv_nsec == 0) {
            start_time = current_time;
        } else {
            long elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000 + (current_time.tv_nsec - start_time.tv_nsec);
            if (elapsed_ns < sleep_time.tv_nsec) {
                nanosleep(&sleep_time, NULL);
            }
        }

        // Read CPU temperature
        FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (temp_file == NULL) {
            perror("Failed to open temperature file");
            exit(EXIT_FAILURE);
        }
        fscanf(temp_file, "%u", &temperature);
        fclose(temp_file);

        // Map temperature to duty cycle
        duty_cycle = map_temperature_to_duty_cycle(temperature / 1000.0);

        // Log reading
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));
        log_reading(timestamp, temperature / 1000.0, duty_cycle);

        // Set PWM duty cycle
        ret = gpiod_line_set_value(pwm_line, duty_cycle);
        if (ret != 0) {
            perror("Failed to set PWM line value");
            exit(EXIT_FAILURE);
        }

        // Update start time
        start_time = current_time;
    }

    // Clean up
    gpiod_chip_close(gpiod_chip);
    gpiod_line_release(pwm_line);
    fclose(log_file);

    return 0;
}

