#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48  // Address of the Sensirion SF06 multiplexer
#define SLF3S_1300F_ADDRESS 0x08  // Address of the SLF3S-1300F sensor
#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0xFF
#define MAX_RETRIES 3

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_handle = -1;
static FILE *flow_log = NULL;

static void handle_signal(int sig) {
    if (flow_log) {
        fclose(flow_log);
    }
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

static void init_i2c() {
    if (i2c_handle == -1) {
        i2c_handle = i2c_open(I2C_BUS, SLF3S_1300F_ADDRESS, 0);
        if (i2c_handle == -1) {
            perror("Failed to open I2C device");
            exit(EXIT_FAILURE);
        }
    }
}

static void init_gpio() {
    if (gpiod_chip == -1) {
        gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
        if (gpiod_chip == -1) {
            perror("Failed to open GPIO chip");
            exit(EXIT_FAILURE);
        }
    }
    if (gpiod_line == -1) {
        gpiod_line = gpiod_line_request_input(gpiod_chip, 17, GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN);
        if (gpiod_line == -1) {
            perror("Failed to request GPIO line");
            exit(EXIT_FAILURE);
        }
    }
}

static void write_mux(uint8_t channel) {
    uint8_t data = (channel << 1) | 0x01;  // Set channel and enable
    if (i2c_write_byte(i2c_handle, data) == -1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor(uint8_t *data) {
    for (int retry = 0; retry < MAX_RETRIES; ++retry) {
        if (i2c_read(i2c_handle, data, 3) == 3) {
            uint8_t crc = calculate_crc8(data, 2);
            if (crc == data[2]) {
                return 0;
            }
        }
        usleep(100000);  // Wait for 100ms before retrying
    }
    return -1;
}

static void log_flow(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s,%.2f,%.2f\n", timestamp, flow1, flow2);

    if (flow_log == NULL) {
        flow_log = fopen("flow_log.txt", "a");
        if (flow_log == NULL) {
            perror("Failed to open flow_log.txt");
            return;
        }
    }

    if (fprintf(flow_log, "%s", log_entry) < 0) {
        perror("Failed to write to flow_log.txt");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();

    while (1) {
        write_mux(0);  // Select sensor 1
        uint8_t data1[3];
        if (read_sensor(data1) == 0) {
            float flow1 = (data1[0] << 8) | data1[1];
            log_flow(flow1, 0.0);
        }

        write_mux(1);  // Select sensor 2
        uint8_t data2[3];
        if (read_sensor(data2) == 0) {
            float flow2 = (data2[0] << 8) | data2[1];
            log_flow(0.0, flow2);
        }

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

