static int event_count = 0;
static int current_position = 0;
static int last_position = 0;
static int last_time = 0;
static int running = 1;

static void signal_handler(int signum) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
