        close(gpiod_line_a_fd);
    }
    if (gpiod_line_b_fd != -1) {
        close(gpiod_line_b_fd);
    }
    exit(0);
}

static void log_position(int position, int time) {
    char line[MAX_LINE_LENGTH];
    struct tm *tm;
