    int i;
    for (i = 0; i < event_count; i++) {
        struct gpiod_line_event event = events[i];
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (line_a == gpiod_line_get_by_offset(chip, GPIO_A)) {
                current_position += 1;
            } else if (line_b == gpiod_line_get_by_offset(chip, GPIO_B)) {
                current_position -= 1;
            }
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (line_a == gpiod_line_get_by_offset(chip, GPIO_A)) {
                current_position -= 1;
            } else if (line_b == gpiod_line_get_by_offset(chip, GPIO_B)) {
                current_position += 1;
            }
        }
        if (current_position != last_position) {
            log_position(current_position, event.timestamp);
            last_position = current_position;
        }
    }
    event_count = 0;
}

