    if (!line_b) {
        perror("Failed to get GPIO line B");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line_a, "encoder_a") < 0) {
        perror("Failed to request GPIO line A");
        exit(EXIT_FAILURE);
