        perror("Failed to request GPIO line B");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (running) {
        int ret = gpiod_line_event_read_multiple(line_a, line_b, events, MAX_EVENTS, 1000);
        if (ret < 0) {
            perror("Failed to read GPIO events");
            exit(EXIT_FAILURE);
        }
        event_count = ret;
        process_events();
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    close(gpiod_chip_fd);

