#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x54
#define RED_CHANNEL 0
#define IR_CHANNEL 1
#define LED_PIN 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define BUFFER_SIZE 256

static int i2c_fd = -1;
static int led_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (led_fd != -1) {
        close(led_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    exit(signum);
}

static void log_measurement(time_t timestamp, int red, int ir) {
    char buffer[BUFFER_SIZE];
    snprintf(buffer, BUFFER_SIZE, "%ld,%d,%d\n", timestamp, red, ir);
    if (fputs(buffer, log_file) == EOF) {
        perror("Error writing to log file");
    }
}

static void read_sensor() {
    uint8_t command = 0x00; // Start conversion
    uint8_t data[2];
    int ret;

    ret = write(i2c_fd, &command, 1);
    if (ret < 0) {
        perror("Error writing to I2C");
        return;
    }

    ret = read(i2c_fd, data, 2);
    if (ret < 0) {
        perror("Error reading from I2C");
        return;
    }

    int red = (data[0] << 8) | data[1];
    int ir = (data[2] << 8) | data[3];

    log_measurement(time(NULL), red, ir);

    if (ir > THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(led_line, "ADPD144RI LED", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        fclose(log_file);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        fclose(log_file);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return EXIT_FAILURE;
    }

    while (1) {
        read_sensor();
        sleep(100);
    }

    close(i2c_fd);
    fclose(log_file);
    gpiod_chip_close(chip);
    gpiod_line_release(led_line);

    return EXIT_SUCCESS;
}

