        if (poll(&pollfd, 1, 0) > 0) {
            if (gpiod_event_read(fd, NULL) == 0) {
                pthread_mutex_lock(&rpm_mutex);
                pulse_count++;
                pthread_mutex_unlock(&rpm_mutex);
            }
        }
        usleep(100000); // 100 Hz
    }
    return NULL;
}

void calculate_rpm() {
    double rpm = (pulse_count / RPM_INTERVAL) * 60.0;
    if (rpm > MAX_RPM) {
        rpm = MAX_RPM;
    }
    pulse_count = 0;
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(rpm_log, "%s,%.2f\n", timestamp, rpm);
    fflush(rpm_log);
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize mutex
    if (pthread_mutex_init(&rpm_mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }

    // Open log file
    rpm_log = fopen(RPM_LOG_FILE, "a");
    if (!rpm_log) {
        perror("Failed to open log file");
        pthread_mutex_destroy(&rpm_mutex);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(rpm_log);
        pthread_mutex_destroy(&rpm_mutex);
        exit(EXIT_FAILURE);
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(rpm_log);
        pthread_mutex_destroy(&rpm_mutex);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(line, "rpm_sensor") != 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(rpm_log);
        pthread_mutex_destroy(&rpm_mutex);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_config(line, GPIO_LINE_CONFIG_INPUT_PULL_DOWN, 0) != 0) {
        perror("Failed to set GPIO line pull-down resistor");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(rpm_log);
        pthread_mutex_destroy(&rpm_mutex);
        exit(EXIT_FAILURE);
    }
    fd = gpiod_line_event_get_fd(line);
    if (fd < 0) {
        perror("Failed to get GPIO line event file descriptor");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(rpm_log);
        pthread_mutex_destroy(&rpm_mutex);
        exit(EXIT_FAILURE);
    }

    // Create and start interrupt service routine thread
    pthread_t isr_thread;
    if (pthread_create(&isr_thread, NULL, interrupt_service_routine, (void *)fd) != 0) {
        perror("Failed to create interrupt service routine thread");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(rpm_log);
        pthread_mutex_destroy(&rpm_mutex);
        exit(EXIT_FAILURE);
    }

    // Calculate and log RPM
    while (1) {
        calculate_rpm();
        sleep(1);
    }

    // Clean up
    pthread_join(isr_thread, NULL);
    close(fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(rpm_log);
    pthread_mutex_destroy(&rpm_mutex);

    return 0;
}
