#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x54
#define LED_PIN 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define BUFFER_SIZE 1024

static int i2c_fd;
static int led_fd;
static FILE *log_file;
static struct gpiod_chip *led_chip;
static struct gpiod_line *led_line;
static struct timespec sleep_time = {0, 100000000}; // 100 ms

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (led_fd >= 0) {
        gpio_close(led_fd);
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

static void log_reading(struct timespec *timestamp, int red, int ir) {
    char buffer[BUFFER_SIZE];
    snprintf(buffer, BUFFER_SIZE, "%ld,%d,%d\n", timestamp->tv_sec, red, ir);
    if (fputs(buffer, log_file) == EOF) {
        perror("Error writing to log file");
        exit(EXIT_FAILURE);
    }
}

static int read_sensor(int *red, int *ir) {
    uint8_t buffer[4];
    if (write(i2c_fd, &buffer[0], 1) != 1) {
        perror("Error writing to I2C");
        return -1;
    }
    if (read(i2c_fd, buffer, 4) != 4) {
        perror("Error reading from I2C");
        return -1;
    }
    *red = (buffer[0] << 8) | buffer[1];
    *ir = (buffer[2] << 8) | buffer[3];
    return 0;
}

int main() {
    struct timespec timestamp;
    int red, ir;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open LED GPIO
    led_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!led_chip) {
        perror("Error opening LED GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(led_chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED GPIO line");
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(led_line, "ADPD144RI LED", 0);
    if (ret < 0) {
        perror("Error requesting LED GPIO output");
        gpiod_line_release(led_line);
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(led_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Log header
    log_reading(&timestamp, 0, 0);
    fprintf(log_file, "Timestamp,Red,IR\n");

    // Main loop
    while (1) {
        if (read_sensor(&red, &ir) < 0) {
            continue;
        }
        log_reading(&timestamp, red, ir);
        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(led_line);
    gpiod_chip_close(led_chip);
    close(i2c_fd);

    return 0;
}

