#define MAX9814_OUT_PIN 17
#define MAX9814_GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define SAMPLE_RATE 10000 // 10 Hz
#define MAX_EVENTS 10000

static int gpiod_ctx = -1;
static int gain_pin = -1;
static int out_pin = -1;
static FILE *log_file = NULL;

static void handle_signal(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (gain_pin != -1) {
        gpio_unexport(gain_pin);
    }
    if (out_pin != -1) {
        gpio_unexport(out_pin);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 10000000}; // 10 ms
    struct sigaction sa;
    int events[MAX_EVENTS];
    int event_count = 0;
    time_t now;
    struct tm *tm_info;
    char log_entry[100];

    // Set up signal handler
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gain_pin = gpio_export(MAX9814_GAIN_PIN, GPIOF_OUT_INIT_LOW);
    if (gain_pin == -1) {
        perror("Failed to export GPIO18");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    out_pin = gpio_export(MAX9814_OUT_PIN, GPIOF_IN);
    if (out_pin == -1) {
        perror("Failed to export GPIO17");
        gpio_unexport(gain_pin);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpio_unexport(gain_pin);
        gpio_unexport(out_pin);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Print startup message
    printf("Audio sampling started. Press Ctrl+C to stop.\n");

    // Main loop
    while (1) {
        int value = gpio_get_value(out_pin);
        if (value == 1) {
            if (event_count < MAX_EVENTS) {
                events[event_count++] = time(NULL);
            } else {
                // Drop oldest event if buffer is full
                events[0] = events[1];
                for (int i = 1; i < MAX_EVENTS - 1; i++) {
                    events[i] = events[i + 1];
                }
                events[MAX_EVENTS - 1] = time(NULL);
            }
        }
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Clean up GPIO
    gpio_unexport(gain_pin);
    gpio_unexport(out_pin);
    gpiod_chip_close(gpiod_ctx);

    return 0;
}

