#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define CRC8_POLYNOMIAL 0x07
#define CRC8_INITIAL_VALUE 0xFF

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

static void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

static void log_measurement(const char *timestamp, float flow_rate) {
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
}

static int calculate_crc8(const unsigned char *data, size_t length) {
    int crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor() {
    unsigned char buffer[3];
    int bytes_read = read(i2c_fd, buffer, 3);
    if (bytes_read != 3) {
        log_error("Failed to read from sensor");
        return -1;
    }
    unsigned char msb = buffer[0];
    unsigned char lsb = buffer[1];
    unsigned char crc = buffer[2];
    unsigned int raw_value = (msb << 8) | lsb;
    unsigned char calculated_crc = calculate_crc8(buffer, 2);
    if (calculated_crc != crc) {
        log_error("CRC failure");
        return -1;
    }
    float flow_rate = (float)raw_value / 1000.0;
    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip, 17); // Example GPIO line
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(line, "flow_sensor", 0) < 0) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Log header
    fprintf(log_file, "YYYY-MM-DD HH:MM:SS,flow_rate_uL_min\n");
    fflush(log_file);

    // Main loop
    while (1) {
        struct tm *timeinfo;
        char timestamp[20];
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (read_sensor() == 0) {
            log_measurement(timestamp, flow_rate);
        }

        usleep(1000000); // 1000 ms
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}
