#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x58
#define TVOC_REG 0x00
#define ECO2_REG 0x02
#define IAQ_REG 0x04
#define IAQ_INDEX_REG 0x06
#define IAQ_INDEX_OFFSET 0x00
#define IAQ_INDEX_SCALE 0x01

#define LOG_FILE "air_quality_log.csv"
#define LOG_INTERVAL 5

static int gpiod_chip;
static int gpiod_line;
static int i2c_handle;
static FILE *log_file;

static void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    printf("Program terminated by user.\n");
    exit(0);
}

static int read_i2c_register(int reg) {
    uint8_t buffer[2];
    int result = i2c_read_word_data(i2c_handle, reg);
    if (result < 0) {
        perror("i2c_read_word_data");
        return -1;
    }
    buffer[0] = result >> 8;
    buffer[1] = result & 0xFF;
    return buffer[0] << 8 | buffer[1];
}

static int write_i2c_register(int reg, int value) {
    uint8_t buffer[2];
    buffer[0] = (value >> 8) & 0xFF;
    buffer[1] = value & 0xFF;
    int result = i2c_write_word_data(i2c_handle, reg, buffer[0] << 8 | buffer[1]);
    if (result < 0) {
        perror("i2c_write_word_data");
        return -1;
    }
    return 0;
}

static int check_sensor_presence() {
    int result = i2c_read_byte_data(i2c_handle, 0x00);
    if (result < 0) {
        perror("i2c_read_byte_data");
        return -1;
    }
    return result == 0x58;
}

static void log_data(int tvoc, int eco2, int iaq_index) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, tvoc, eco2, iaq_index);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }
    if (gpiod_chip_open_by_name("gpiochip0", &gpiod_chip) < 0) {
        perror("gpiod_chip_open_by_name");
        gpioTerminate();
        return 1;
    }
    if (gpiod_line_open_by_name(gpiod_chip, "gpio17", &gpiod_line) < 0) {
        perror("gpiod_line_open_by_name");
        gpiod_chip_close(gpiod_chip);
        gpioTerminate();
        return 1;
    }
    if (i2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        perror("i2cOpen");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        gpioTerminate();
        return 1;
    }

    if (!check_sensor_presence()) {
        fprintf(stderr, "Sensor not detected.\n");
        i2c_close(i2c_handle);
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        i2c_close(i2c_handle);
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int tvoc = read_i2c_register(TVOC_REG);
        int eco2 = read_i2c_register(ECO2_REG);
        int iaq_index = read_i2c_register(IAQ_INDEX_REG) + IAQ_INDEX_OFFSET;

        if (tvoc < 0 || eco2 < 0 || iaq_index < 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            break;
        }

        log_data(tvoc, eco2, iaq_index);

        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    gpiod_line_close(gpiod_line);
    gpiod_chip_close(gpiod_chip);
    gpioTerminate();

    return 0;
}

