#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define ALERT_THRESHOLD 5000000000 // 5 seconds in nanoseconds
#define POLL_INTERVAL 100000 // 100 ms in nanoseconds

static volatile sig_atomic_t should_exit = 0;

static void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    struct timespec last_touch_time = {0, 0};
    struct timespec current_time = {0, 0};
    struct timespec poll_interval = {0, POLL_INTERVAL};
    struct timespec alert_threshold = {0, ALERT_THRESHOLD};
    int chip_fd = -1;
    int line_fd = -1;
    int result;

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    chip_fd = gpiod_chip_open_by_name("gpiochip0");
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    line_fd = gpiod_chip_get_line(chip_fd, GPIO_PIN);
    if (line_fd < 0) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Request the line for input
    result = gpiod_line_request_input(line_fd, "ttp223_tamper");
    if (result < 0) {
        fprintf(stderr, "Failed to request GPIO line input: %s\n", strerror(errno));
        gpiod_line_release(line_fd);
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read the current state of the line
        result = gpiod_line_get_value(line_fd);
        if (result < 0) {
            fprintf(stderr, "Failed to read GPIO line value: %s\n", strerror(errno));
            gpiod_line_release(line_fd);
            gpiod_chip_close(chip_fd);
            exit(EXIT_FAILURE);
        }

        // Check if the line is HIGH
        if (result == 1) {
            // Check if the line has been HIGH for more than 5 seconds
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) < 0) {
                fprintf(stderr, "Failed to get current time: %s\n", strerror(errno));
                gpiod_line_release(line_fd);
                gpiod_chip_close(chip_fd);
                exit(EXIT_FAILURE);
            }

            if (current_time.tv_sec - last_touch_time.tv_sec > 5) {
                // Print an intrusion alert
                printf("Intrusion alert!\n");
                // Reset the last touch time
                last_touch_time = current_time;
            }
        } else {
            // Reset the last touch time if the line is LOW
            last_touch_time.tv_sec = 0;
            last_touch_time.tv_nsec = 0;
        }

        // Sleep for the poll interval
        result = nanosleep(&poll_interval, NULL);
        if (result < 0) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            gpiod_line_release(line_fd);
            gpiod_chip_close(chip_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Clean up resources
    gpiod_line_release(line_fd);
    gpiod_chip_close(chip_fd);

    return EXIT_SUCCESS;
}

