This C program continuously monitors a SainSmart TTP223B capacitive touch sensor connected to GPIO pin 17 on a Raspberry Pi 5. It uses the `libgpiod` library to handle GPIO operations. The program checks the state of the line every 100 ms and prints an intrusion alert if the line remains HIGH for more than 5 seconds. It also handles signals to gracefully exit and clean up resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define BUFFER_SIZE 4096
#define FILE_NAME "audio_capture.pcm"

static int gpiod_fd;
static int pcm_fd;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
    close(pcm_fd);
    close(gpiod_fd);
    unlink(FILE_NAME);
    printf("Signal received, exiting gracefully.\n");
    exit(0);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Initialize GPIO
    gpiod_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpiod_fd, GPIO_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(line, "audio_capture", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    // Open PCM device
    pcm_fd = open(PCM_DEVICE, O_RDWR);
    if (pcm_fd < 0) {
        perror("Failed to open PCM device");
        gpiod_line_release(line);
        close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    // Set PCM parameters
    struct audio_format format = {
        .format = AFMT_S16_LE,
        .channels = 2,
        .rate = SAMPLE_RATE,
        .period_size = BUFFER_SIZE,
        .period_count = 2,
    };

    ret = ioctl(pcm_fd, SNDCTL_DSP_SETFMT, &format.format);
    if (ret < 0) {
