    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_line_request_input(line, "flame_sensor", flags);
    if (ret != 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    log_event("GPIO initialized");
}

static void setup_pwm() {
    pwm_fd = pwm_create(PWM_PIN, PWM_FREQUENCY);
    if (pwm_fd == -1) {
        perror("Failed to create PWM");
        exit(EXIT_FAILURE);
    }

    log_event("PWM initialized");
}

static void start_pwm() {
    pwm_set_duty_cycle(pwm_fd, 50);
    pwm_enable(pwm_fd);
    log_event("PWM started");
}

static void stop_pwm() {
    pwm_disable(pwm_fd);
    log_event("PWM stopped");
}

static void reset_gpio() {
    gpiod_line_release(gpiod_ctx);
    gpiod_chip_close(gpiod_ctx);
    log_event("GPIO reset");
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_pwm();

    log_event("System start");

    while (1) {
        struct timespec sleep_time = {0, 50000000}; // 50 ms
        nanosleep(&sleep_time, NULL);

        int gpio_value = gpiod_line_get_value(gpiod_ctx, GPIO_PIN);
        if (gpio_value == -1) {
            perror("Failed to read GPIO value");
            stop_pwm();
            reset_gpio();
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        if (gpio_value == 0) {
            log_event("Flame detected");
            start_pwm();
        } else {
            log_event("Flame ended");
            stop_pwm();
        }
    }

    stop_pwm();
    reset_gpio();
    fclose(log_file);
    return 0;
}

