#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>
#include <spi.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_FRAME_SIZE 32768
#define MAGIC_NUMBER 0x4144
#define LOG_FILE "mmwave_data.bin"
#define FRAME_TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define FRAME_PERIOD_MS 100

static int spi_fd;
static int gpio_trigger_fd;
static int gpio_ready_fd;
static FILE *log_file;

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_trigger_fd >= 0) {
        gpio_close(gpio_trigger_fd);
    }
    if (gpio_ready_fd >= 0) {
        gpio_close(gpio_ready_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *ready_line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    trigger_line = gpiod_chip_get_line(chip, FRAME_TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get GPIO trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ready_line = gpiod_chip_get_line(chip, DATA_READY_PIN);
    if (!ready_line) {
        perror("Failed to get GPIO ready line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(trigger_line, "frame_trigger", 0) < 0) {
        perror("Failed to request GPIO trigger line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(ready_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(ready_line, "data_ready") < 0) {
        perror("Failed to request GPIO ready line");
        gpiod_line_release(trigger_line);
        gpiod_line_release(ready_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_trigger_fd = gpiod_line_get_fd(trigger_line);
    gpio_ready_fd = gpiod_line_get_fd(ready_line);

    gpiod_chip_close(chip);
}

static void setup_spi() {
    struct spi_ioc_transfer transfer;
    unsigned char header[16];
    struct mmwave_config config = {
        .start_frequency = 77000000000,
        .end_frequency = 79000000000,
        .num_chirps = 64,
        .num_samples = 256,
        .frame_size = SPI_MAX_FRAME_SIZE
    };

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Write header to log file
    header[0] = MAGIC_NUMBER >> 8;
    header[1] = MAGIC_NUMBER & 0xFF;
    header[2] = (uint8_t)(config.start_frequency >> 56);
    header[3] = (uint8_t)(config.start_frequency >> 48);
    header[4] = (uint8_t)(config.start_frequency >> 40);
    header[5] = (uint8_t)(config.start_frequency >> 32);
    header[6] = (uint8_t)(config.start_frequency >> 24);
    header[7] = (uint8_t)(config.start_frequency >> 16);
    header[8] = (uint8_t)(config.start_frequency >> 8);
    header[9] = (uint8_t)(config.start_frequency);
    header[10] = (uint8_t)(config.end_frequency >> 56);
    header[11] = (uint8_t)(config.end_frequency >> 48);
    header[12] = (uint8_t)(config.end_frequency >> 40);
    header[13] = (uint8_t)(config.end_frequency >> 32);
    header[14] = (uint8_t)(config.end_frequency >> 24);
    header[15] = (uint8_t)(config.end_frequency >> 16);
    header[16] = (uint8_t)(config.end_frequency >> 8);
    header[17] = (uint8_t)(config.end_frequency);

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (fwrite(header, sizeof(header), 1, log_file) != 1) {
        perror("Failed to write header to log file");
        fclose(log_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned char *)malloc(config.frame_size);
    if (!transfer.tx_buf) {
        perror("Failed to allocate memory for SPI transfer");
        fclose(log_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    transfer.rx_buf = (unsigned char *)malloc(config.frame_size);
    if (!transfer.rx_buf) {
        perror("Failed to allocate memory for SPI transfer");
        free(transfer.tx_buf);
        fclose(log_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    transfer.len = config.frame_size;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.cs_change = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        struct timespec sleep_time = {0, FRAME_PERIOD_MS * 1000000};
        nanosleep(&sleep_time, NULL);

        if (gpiod_line_get_value(gpio_ready_line) == 1) {
            gpiod_line_set_value(gpio_trigger_line, 1);
            usleep(1000); // Wait for trigger to settle
            gpiod_line_set_value(gpio_trigger_line, 0);

            if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
                perror("Failed to perform SPI transfer");
                free(transfer.tx_buf);
                free(transfer.rx_buf);
                fclose(log_file);
                close(spi_fd);
                exit(EXIT_FAILURE);
            }

            // Write frame data to log file
            if (fwrite(transfer.rx_buf, sizeof(transfer.rx_buf), 1, log_file) != 1) {
                perror("Failed to write frame data to log file");
                free(transfer.tx_buf);
                free(transfer.rx_buf);
                fclose(log_file);
                close(spi_fd);
                exit(EXIT_FAILURE);
            }

            // Write frame timestamp and number to log file
