#define I2C_BUS 1
#define I2C_ADDR 0x44
#define FILE_NAME "light_data.txt"
#define MAX_RETRIES 5
#define RETRY_DELAY 1000000  // 1 second in microseconds

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Exiting...\n");
    exit(0);
}

// Function to read lux value from OPT3001
int read_lux() {
    uint8_t data[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpiod_chip_open_by_name("gpiochip0") < 0) {
            perror("Failed to open GPIO chip");
            return -1;
        }

        if (gpiod_chip_get_line(i2c_fd, 0) < 0) {
            perror("Failed to get I2C line");
            gpiod_chip_close(i2c_fd);
            return -1;
        }

        if (gpiod_line_request_output(i2c_fd, 0, 0) < 0) {
            perror("Failed to request I2C line as output");
            gpiod_line_release(i2c_fd);
            gpiod_chip_close(i2c_fd);
            return -1;
        }

        if (gpiod_line_set_value(i2c_fd, 0, 1) < 0) {
            perror("Failed to set I2C line high");
            gpiod_line_release(i2c_fd);
            gpiod_chip_close(i2c_fd);
            return -1;
        }

        usleep(10000);  // Wait for the sensor to wake up

        if (gpiod_line_set_value(i2c_fd, 0, 0) < 0) {
            perror("Failed to set I2C line low");
            gpiod_line_release(i2c_fd);
            gpiod_chip_close(i2c_fd);
            return -1;
        }

        usleep(10000);  // Wait for the sensor to take a reading

        if (gpiod_line_set_value(i2c_fd, 0, 1) < 0) {
            perror("Failed to set I2C line high");
            gpiod_line_release(i2c_fd);
            gpiod_chip_close(i2c_fd);
            return -1;
        }

        usleep(10000);  // Wait for the sensor to complete the conversion

        if (gpiod_line_set_value(i2c_fd, 0, 0) < 0) {
            perror("Failed to set I2C line low");
            gpiod_line_release(i2c_fd);
            gpiod_chip_close(i2c_fd);
            return -1;
        }

        if (gpiod_line_release(i2c_fd) < 0) {
            perror("Failed to release I2C line");
            gpiod_chip_close(i2c_fd);
            return -1;
        }

        if (gpiod_chip_close(i2c_fd) < 0) {
            perror("Failed to close GPIO chip");
            return -1;
        }

        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x04, 3, data) < 0) {
            perror("Failed to read I2C block data");
            retries++;
            usleep(RETRY_DELAY);
            continue;
        }

        // Convert the data to lux
        uint16_t lux = (data[0] << 8) | data[1];
        return lux;
    }

    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if ((log_file = fopen(FILE_NAME, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value\n");
            continue;
        }

        fprintf(log_file, "%s, %d lux\n", timestamp, lux);
        fflush(log_file);

        usleep(100000);  // Wait for 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

