        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x04, 3, data) < 0) {
            perror("Failed to read I2C block data");
            retries++;
            usleep(RETRY_DELAY);
            continue;
        }

        // Convert the data to lux
        uint16_t lux = (data[0] << 8) | data[1];
        return lux;
    }

    return -1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if ((log_file = fopen(FILE_NAME, "a")) == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        int lux = read_lux();
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value\n");
            continue;
        }

        fprintf(log_file, "%s, %d lux\n", timestamp, lux);
        fflush(log_file);

        usleep(100000);  // Wait for 100 ms
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}
```

### Explanation:

1. **Signal Handling**: The program sets up signal handlers for `SIGINT` and `SIGTERM` to ensure a clean shutdown on exit.

2. **I2C Initialization**: The program opens the I2C bus and sets the slave address for the OPT3001 sensor.

3. **File Handling**: It opens a file named `light_data.txt` in append mode to store the lux readings.

4. **Reading Lux Values**: The `read_lux` function performs the necessary I2C transactions to read the lux value from the sensor. It retries up to 5 times if an I2C transaction fails.

5. **Logging**: Each lux reading is logged with an ISO-8601 timestamp to the file.

6. **Main Loop**: The program enters a loop where it reads the lux value, logs it, and waits for 100 ms before repeating.

7. **Resource Cleanup**: On exit, the program closes the I2C file descriptor and the log file, ensuring all resources are released.

This program is designed to be robust and handle errors gracefully, ensuring that the sensor and system remain stable even in the face of failures.

