        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line
    if (gpiod_line_request(&request, fd) < 0) {
        perror("Failed to request line");
        gpiod_line_release(fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
