        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!should_exit) {
        // Read the line value
        int value;
        if (gpiod_line_get_value(fd, &value) < 0) {
            perror("Failed to read line value");
            continue;
        }

        // Get the current time
        now = time(NULL);
        tm_info = localtime(&now);

        // Format the log entry
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm_info);
        if (value == 0) {
            fprintf(log_file, "%s Flame Detected: YES\n", log_entry);
        } else {
            fprintf(log_file, "%s Flame Detected: NO\n", log_entry);
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) < 0) {
            perror("Failed to sleep");
        }
    }

    // Cleanup
    fclose(log_file);
    gpiod_line_release(fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

