        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(gpiod_last_error()));
        return EXIT_FAILURE;
    }

    // Request lines
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", LEFT_PIN, gpiod_strerror(gpiod_last_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    center_line = gpiod_chip_get_line(chip, CENTER_PIN);
    if (!center_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", CENTER_PIN, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", RIGHT_PIN, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request input mode
    ret = gpiod_line_request_input(left_line, "left_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request input mode for line %d: %s\n", LEFT_PIN, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(center_line, "center_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request input mode for line %d: %s\n", CENTER_PIN, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(right_line, "right_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request input mode for line %d: %s\n", RIGHT_PIN, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        int left_state = gpiod_line_get_value(left_line);
        int center_state = gpiod_line_get_value(center_line);
        int right_state = gpiod_line_get_value(right_line);

        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        usleep(POLL_INTERVAL);
    }

    // Release resources
    gpiod_line_release(left_line);
    gpiod_line_release(center_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

