#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_LINES 8
#define LINE_OFFSET 2
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    int chip_fd, line_fd[NUM_LINES];
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_LINES];
    struct timespec sleep_time;
    char line_name[10];
    char state_str[10];
    int i, ret;

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip_fd = gpiod_chip_open(CHIP_NAME);
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(chip_fd));
        return EXIT_FAILURE;
    }

    // Get the chip object
    chip = gpiod_chip_get_from_fd(chip_fd);
    if (!chip) {
        fprintf(stderr, "Failed to get chip object\n");
        gpiod_chip_close(chip_fd);
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < NUM_LINES; i++) {
        snprintf(line_name, sizeof(line_name), "gpio%d", LINE_OFFSET + i);
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %s: %s\n", line_name, gpiod_strerror(gpiod_line_get_errno(lines[i])));
            gpiod_chip_close(chip_fd);
            return EXIT_FAILURE;
        }
        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %s as input: %s\n", line_name, gpiod_strerror(ret));
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip_fd);
            return EXIT_FAILURE;
        }
    }

    // Set up sleep time
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000;

    // Main loop
    while (!should_exit) {
        for (i = 0; i < NUM_LINES; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line %s: %s\n", line_name, gpiod_strerror(ret));
                continue;
            }
            snprintf(state_str, sizeof(state_str), "%d", ret);
            printf("%ld: %s\n", time(NULL), state_str);
        }
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    for (i = 0; i < NUM_LINES; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip_fd);

    return EXIT_SUCCESS;
}

