#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_BASE 2
#define GPIO_COUNT 8
#define SAMPLE_INTERVAL_USEC 100000

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[GPIO_COUNT];
    struct gpiod_line_bulk *bulk;
    unsigned int values[GPIO_COUNT];
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_USEC * 1000};

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < GPIO_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_BASE + i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Configure lines as inputs with pull-down resistors
    for (int i = 0; i < GPIO_COUNT; i++) {
        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret) {
            perror("Failed to request GPIO line as input");
            gpiod_line_release_bulk(lines, GPIO_COUNT);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Create a bulk line object
    bulk = gpiod_line_bulk_open(lines, GPIO_COUNT);
    if (!bulk) {
        perror("Failed to create line bulk object");
        gpiod_line_release_bulk(lines, GPIO_COUNT);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Read samples
    while (!should_exit) {
        ret = gpiod_line_bulk_get_values(bulk, values);
        if (ret) {
            perror("Failed to read GPIO line values");
