#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define POLL_INTERVAL_MS 50

static gpiod_chip *chip;
static gpiod_line *lines[NUM_CHANNELS];
static struct timespec poll_interval;

static void sigint_handler(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    exit(0);
}

int main() {
    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize poll interval
    poll_interval.tv_sec = 0;
    poll_interval.tv_nsec = POLL_INTERVAL_MS * 1000000;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_BASE + i);
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Configure lines as inputs with bias disabled
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(lines[i], "touch_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE)) {
            perror("Failed to request line as input");
            gpiod_chip_close(chip);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (1) {
        // Get current time
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        // Read channel states
        int states[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++) {
            states[i] = gpiod_line_get_value(lines[i]);
        }

        // Print CSV line
        printf("%s,", timestamp);
        for (int i = 0; i < NUM_CHANNELS; i++) {
            printf("%d", states[i]);
            if (i < NUM_CHANNELS - 1) {
                printf(",");
            }
        }
        printf("\n");

        // Sleep for poll interval
        nanosleep(&poll_interval, NULL);
    }

    // Release resources
    gpiod_chip_close(chip);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }

    return EXIT_SUCCESS;
}

