#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TILT_PIN 7
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request line
    line = gpiod_chip_get_line(chip, TILT_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure line as input with pull-up resistor
    ret = gpiod_line_request_input(line, "tilt_sensor");
    if (ret) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Print startup banner
    printf("Tilt sensor polling started...\n");

    // Main loop
    while (!should_exit) {
        int value;
        ret = gpiod_line_get_value(line, &value);
        if (ret) {
            perror("Failed to read GPIO line value");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Flush stdout and log tilt state
        fflush(stdout);
        if (value == 0) {
            printf("Tilted\n");
        } else {
            printf("Not Tilted\n");
        }

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Tilt sensor polling stopped.\n");

    return 0;
}

