#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define BUFFER_SIZE 100
#define GPIO_PIN 7
#define SAMPLE_INTERVAL_MS 50

static gpiod_chip *chip;
static gpiod_line *line;
static gpiod_line_request *request;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_full = 0;
static int running = 1;

static void handle_sigint(int signum) {
    running = 0;
    gpiod_line_release(request->line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

static void dump_buffer() {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);

    for (int i = 0; i < BUFFER_SIZE; i++) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("%s: %s\n", buffer, buffer[i] ? "Obstacle detected" : "No obstacle detected");
    }
}

int main() {
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    request = gpiod_line_request(line, "obstacle_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT | GPIOD_LINE_REQUEST_BIAS_PULL_UP);
    if (!request) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        int value = gpiod_line_get_value(request->line);
        if (value == 0) {
            buffer[buffer_index] = 1;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_full) {
                buffer_full = 0;
            }
        } else {
            buffer[buffer_index] = 0;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            buffer_full = 1;
        }

        if (buffer_full) {
            printf("Obstacle detected\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    dump_buffer();

    gpiod_line_release(request->line);
    gpiod_chip_close(chip);

    return 0;
}

