static void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    sda_line = gpiod_chip_get_line(chip, SDA_PIN);
    if (sda_line == NULL) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    scl_line = gpiod_chip_get_line(chip, SCL_PIN);
    if (scl_line == NULL) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(sda_line, "vibration_sensor", 0) == -1) {
        perror("Failed to request SDA line as output");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(scl_line, "vibration_sensor", 0) == -1) {
        perror("Failed to request SCL line as output");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

