    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (clock_gettime(CLOCK_MONOTONIC, &end) == 0 && (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec) < MAX_WAIT_TIME) {
        if (read(i2c_fd, &active, 1) != 1) {
            perror("Failed to read from sensor");
            exit(EXIT_FAILURE);
        }
        if (active) {
            break;
        }
        usleep(10000); // 10 ms
    }
    if (!active) {
        fprintf(stderr, "Sensor did not become active within the one-second window\n");
        exit(EXIT_FAILURE);
    }
}

static void read_sensor() {
    uint8_t buffer[6];
    for (int i = 0; i < MAX_SAMPLES; i++) {
