            perror("Failed to read from sensor");
            exit(EXIT_FAILURE);
        }
        // Parse X, Y, Z values from buffer
        // Append to CSV file with ISO-8601 timestamp
        // Example: fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
        usleep(SAMPLE_INTERVAL); // 500 ms
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();
    init_sensor();

    csv_file = fopen("fan_health.csv", "a");
