        perror("Failed to get line 1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_input(line1, &config);
    if (ret) {
        perror("Failed to request line 1");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("Failed to get line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_input(line2, &config);
    if (ret) {
        perror("Failed to request line 2");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line_led = gpiod_chip_get_line(chip, GPIO_PIN_LED);
    if (!line_led) {
        perror("Failed to get line LED");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
