#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define STALL_LOG_FILE "stall_log.txt"
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_THRESHOLD 2 // seconds
#define MAX_STALLS 100

static int gpiod_ctx = -1;
static int sensor1_fd = -1;
static int sensor2_fd = -1;
static int stall_count = 0;
static struct timespec last_stall_time;
static struct timespec current_time;
static int stalls[MAX_STALLS];
static int stall_index = 0;

static void handle_signal(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_close(gpiod_ctx);
    }
    if (sensor1_fd != -1) {
        close(sensor1_fd);
    }
    if (sensor2_fd != -1) {
        close(sensor2_fd);
    }
    exit(0);
}

static void log_stall() {
    FILE *file = fopen(STALL_LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open stall log file");
        return;
    }
    struct tm *timeinfo;
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    fprintf(file, "%s", asctime(timeinfo));
    fprintf(file, "Stall detected\n");
    fclose(file);
}

static int read_sensor(int fd) {
    char buf[1];
    ssize_t bytes_read = read(fd, buf, 1);
    if (bytes_read != 1) {
        perror("Failed to read sensor");
        return -1;
    }
    return buf[0] - '0';
}

static void check_stall() {
    int sensor1_value = read_sensor(sensor1_fd);
    int sensor2_value = read_sensor(sensor2_fd);
    if (sensor1_value == 0 && sensor2_value == 0) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (stall_count == 0 || (current_time.tv_sec - last_stall_time.tv_sec) >= STALL_THRESHOLD) {
            last_stall_time = current_time;
            stalls[stall_index] = current_time.tv_sec;
            stall_index = (stall_index + 1) % MAX_STALLS;
            stall_count++;
            log_stall();
        }
    } else {
        stall_count = 0;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sensor1_fd = gpiod_line_request_input(gpiod_ctx, "sensor1", SENSOR1_PIN);
    if (sensor1_fd == -1) {
        perror("Failed to request GPIO line for sensor1");
        gpiod_close(gpiod_ctx);
        return 1;
    }

    sensor2_fd = gpiod_line_request_input(gpiod_ctx, "sensor2", SENSOR2_PIN);
    if (sensor2_fd == -1) {
        perror("Failed to request GPIO line for sensor2");
        gpiod_close(gpiod_ctx);
        close(sensor1_fd);
        return 1;
    }

    while (1) {
        check_stall();
        sleep(1);
    }

    gpiod_close(gpiod_ctx);
    close(sensor1_fd);
    close(sensor2_fd);

    return 0;
}

