#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libmraa.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define SENSOR_NAME "TMAG5170-Q1"
#define CSV_FILE "magnetic_log.csv"
#define MAX_READS 1000000
#define READ_INTERVAL 100000  // 100 ms in microseconds

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    printf("Program terminated by user.\n");
    exit(0);
}

static void write_register(int reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
    }
}

static uint8_t read_register(int reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return 0xFF;
    }
    if (read(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return 0xFF;
    }
    return buffer[0];
}

static void configure_sensor() {
    write_register(0x00, 0x00);  // Reset
    usleep(100000);  // Wait for reset to complete
    write_register(0x01, 0x00);  // Set continuous-conversion mode
    write_register(0x02, 0x00);  // Set all three axes enabled
    write_register(0x03, 0x00);  // Set 50 mT range
}

static void read_sensor() {
    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from sensor: %s\n", strerror(errno));
        return;
    }
    uint16_t x = (buffer[0] << 8) | buffer[1];
    uint16_t y = (buffer[2] << 8) | buffer[3];
    uint16_t z = (buffer[4] << 8) | buffer[5];
    fprintf(csv_file, "%s,%d,%d,%d\n", asctime(gmtime(&time(NULL))), x, y, z);
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }
    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    line = gpiod_chip_get_line(chip, 23);  // Assuming SDA is connected to GPIO 23
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(line, "TMAG5170-Q1") != 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    configure_sensor();

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    struct timespec sleep_time = {0, READ_INTERVAL};
    for (int i = 0; i < MAX_READS; i++) {
        read_sensor();
        nanosleep(&sleep_time, NULL);
    }

    fclose(csv_file);
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

