#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1000000 // 1 second in microseconds

static volatile int pulse_count = 0;
static volatile int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

static void sig_handler(int signum) {
    running = 0;
    gpiod_line_release(line);
    fclose(log_file);
    gpiod_chip_close(chip);
    exit(0);
}

static void timer_callback(void *data) {
    int rpm = pulse_count * 60000 / SAMPLE_INTERVAL;
    char timestamp[20];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s %d\n", timestamp, rpm);
    fflush(log_file);
    pulse_count = 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Request the line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Configure the line as an input with internal pull-up resistor
    int ret = gpiod_line_request_input(line, "rpm_sensor");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Set up the timer
    struct gpiod_line_event event;
    ret = gpiod_line_event_wait(line, &event, SAMPLE_INTERVAL);
    if (ret < 0) {
        perror("Failed to wait for GPIO event");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Install the callback
    ret = gpiod_line_event_register(line, &event, timer_callback, NULL);
    if (ret < 0) {
        perror("Failed to register callback");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        ret = gpiod_line_event_wait(line, &event, SAMPLE_INTERVAL);
        if (ret < 0) {
            perror("Failed to wait for GPIO event");
            break;
        }
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pulse_count++;
        }
    }

    // Clean up
    gpiod_line_event_unregister(line);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

