#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_A 17
#define GPIO_B 27
#define LOG_FILE "rotation_log.txt"
#define MAX_LOG_SIZE 1024 * 1024
#define MAX_LOG_ENTRIES 10000

struct quadrature_state {
    int a;
    int b;
    int previous_a;
    int previous_b;
    int direction;
};

static struct quadrature_state state;
static pthread_mutex_t mutex;
static pthread_cond_t cond;
static int running = 1;
static FILE *log_file;

static void *quadrature_thread(void *arg) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line_a = gpiod_chip_get_line(chip, GPIO_A);
    if (!line_a) {
        perror("Failed to get GPIO line A");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (!line_b) {
        perror("Failed to get GPIO line B");
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_edge_detection(line_a, "quadrature", GPIOD_EDGE_BOTH);
    if (ret) {
        perror("Failed to request edge detection on GPIO line A");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_edge_detection(line_b, "quadrature", GPIOD_EDGE_BOTH);
    if (ret) {
        perror("Failed to request edge detection on GPIO line B");
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        struct timespec ts;
        struct tm *tm;
        char timestamp[20];
        char log_entry[100];
        int a, b;

        clock_gettime(CLOCK_MONOTONIC, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        snprintf(log_entry, sizeof(log_entry), "%s.%03d", timestamp, (int)(ts.tv_nsec / 1000000));

        pthread_mutex_lock(&mutex);
        a = gpiod_line_get_value(line_a);
        b = gpiod_line_get_value(line_b);
        state.a = a;
        state.b = b;
        pthread_mutex_unlock(&mutex);

        if (a != state.previous_a || b != state.previous_b) {
            pthread_mutex_lock(&mutex);
            if (a == 1 && b == 0) {
                state.direction = 1; // Clockwise
            } else if (a == 0 && b == 1) {
                state.direction = -1; // Counter-clockwise
            }
            pthread_mutex_unlock(&mutex);

            pthread_mutex_lock(&mutex);
            if (state.direction != 0) {
                fprintf(log_file, "%s: %d\n", log_entry, state.direction);
                pthread_cond_signal(&cond);
            }
            pthread_mutex_unlock(&mutex);
        }

        state.previous_a = a;
        state.previous_b = b;

        nanosleep(&ts, NULL);
    }

    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return NULL;
}

static void signal_handler(int sig) {
    running = 0;
    pthread_cond_signal(&cond);
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    pthread_t thread;
    int ret;

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    ret = pthread_create(&thread, NULL, quadrature_thread, NULL);
    if (ret) {
        perror("Failed to create quadrature thread");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    while (running) {
        pthread_mutex_lock(&mutex);
        while (!pthread_cond_wait(&cond, &mutex)) {
            // Wait for a new log entry
        }
        pthread_mutex_unlock(&mutex);
    }

    pthread_join(thread, NULL);

    fclose(log_file);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);

    return 0;
}

