#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_SENSOR_PIN 23
#define GPIO_LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t should_exit = 0;

void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *led_line;
    struct gpiod_line_request_config config;
    struct timespec sleep_time;

    // Initialize logging
    openlog("touch_sensor_led", LOG_PID | LOG_CONS, LOG_USER);

    // Log startup
    syslog(LOG_INFO, "Touch sensor and LED monitoring started");

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        closelog();
        exit(EXIT_FAILURE);
    }

    // Request the input line for the sensor
    memset(&config, 0, sizeof(config));
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR_PIN);
    if (!sensor_line) {
        syslog(LOG_ERR, "Failed to get line %d: %s", GPIO_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(sensor_line, "touch_sensor", &config);
    if (ret) {
        syslog(LOG_ERR, "Failed to request line %d: %s", GPIO_SENSOR_PIN, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    // Request the output line for the LED
    led_line = gpiod_chip_get_line(chip, GPIO_LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Failed to get line %d: %s", GPIO_LED_PIN, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(led_line, "led", &config);
    if (ret) {
        syslog(LOG_ERR, "Failed to request line %d: %s", GPIO_LED_PIN, strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    // Install SIGINT and SIGTERM handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!should_exit) {
        // Read the sensor line
        int sensor_state = gpiod_line_get_value(sensor_line);
        if (sensor_state < 0) {
            syslog(LOG_ERR, "Failed to read line %d: %s", GPIO_SENSOR_PIN, strerror(errno));
            continue;
        }

        // Set the LED state based on the sensor state
        if (sensor_state) {
            ret = gpiod_line_set_value(led_line, 1);
            if (ret) {
                syslog(LOG_ERR, "Failed to set line %d: %s", GPIO_LED_PIN, strerror(errno));
            }
        } else {
            ret = gpiod_line_set_value(led_line, 0);
            if (ret) {
                syslog(LOG_ERR, "Failed to set line %d: %s", GPIO_LED_PIN, strerror(errno));
            }
        }

        // Log touch event
        if (sensor_state) {
            syslog(LOG_INFO, "Touch detected");
        }

        // Sleep for the specified interval
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Log shutdown
    syslog(LOG_INFO, "Touch sensor and LED monitoring stopped");

    // Release resources
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    closelog();

    return EXIT_SUCCESS;
}

