This C program uses the `libgpiod` library to interact with the GPIO bus on a Raspberry Pi 3 Model B+. It sets up a touch sensor connected to GPIO23 and an LED connected to GPIO18, polling the sensor every 50 milliseconds to control the LED's state based on the sensor's input. The program logs startup, shutdown, touch events, and errors to the system syslog. It also handles SIGINT and SIGTERM signals to perform a graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define GPIO_OUT 17
#define GPIO_LED 18
#define DEBOUNCE_TIME_MS 50

static struct gpiod_chip *chip;
static struct gpiod_line *line_out;
static struct gpiod_line *line_led;
static int debounced = 0;

static void handle_signal(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line_out) {
        gpiod_line_release(line_out);
    }
    if (line_led) {
        gpiod_line_release(line_led);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(gpiod_last_error()));
        return EXIT_FAILURE;
    }

    // Request the OUT line
    line_out = gpiod_chip_get_line(chip, GPIO_OUT);
    if (!line_out) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_OUT, gpiod_strerror(gpiod_last_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the LED line
    line_led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line_led) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LED, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(line_out);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the OUT line as an input
    if (gpiod_line_request_input(line_out, "touch_sensor")) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_OUT, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(line_out);
        gpiod_line_release(line_led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the LED line as an output
    if (gpiod_line_request_output(line_led, "led", 0)) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LED, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(line_out);
        gpiod_line_release(line_led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Enable the OUT line event detection for rising edges
    if (gpiod_line_event_enable(line_out, GPIOD_LINE_REQUEST_RISING_EDGE)) {
        fprintf(stderr, "Failed to enable rising edge detection on line %d: %s\n", GPIO_OUT, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(line_out);
        gpiod_line_release(line_led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        struct gpiod_line_event event;
        int ret;

        // Wait for a rising edge event
        ret = gpiod_line_event_wait(line_out, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", gpiod_strerror(gpiod_last_error()));
            break;
        }

        // Debounce the event
        if (debounced) {
            continue;
        }
        debounced = 1;

        // Toggle the LED
        if (gpiod_line_set_value(line_led, !gpiod_line_get_value(line_led))) {
            fprintf(stderr, "Failed to toggle LED: %s\n", gpiod_strerror(gpiod_last_error()));
            break;
        }

        // Wait for the debounce time
        usleep(DEBOUNCE_TIME_MS * 1000);
        debounced = 0;
    }

    // Release resources
    gpiod_line_event_disable(line_out);
    gpiod_line_release(line_out);
    gpiod_line_release(line_led);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

