This C program initializes the GPIO chip, requests the OUT and LED lines, sets them up as inputs and outputs, enables rising edge detection on the OUT line, and toggles the LED on each detected touch event with a debounce of approximately 50 milliseconds. It handles errors and gracefully releases all resources on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define BUFFER_SIZE 100
#define DEBOUNCE_TIME 50
#define LED1_PIN 27
#define LED2_PIN 22
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

static int gpiod_ctx = -1;
static int buffer_index = 0;
static int overflow_count = 0;
static int buffer[BUFFER_SIZE];
static struct timespec last_touch_time[2];
static int sensor_state[2] = {0, 0};

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiochip_close(gpiod_ctx);
        for (int i = 0; i < BUFFER_SIZE; i++) {
            printf("%d %ld %d\n", buffer[i], buffer[i + BUFFER_SIZE], buffer[i + 2 * BUFFER_SIZE]);
        }
        printf("Overflow count: %d\n", overflow_count);
        exit(0);
    }
}

static void init_gpio() {
    gpiod_ctx = gpiochip_open_by_name("gpiochip0");
    if (gpiod_ctx < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiochip_info info;
    if (gpiochip_get_info(gpiod_ctx, &info) < 0) {
        perror("Failed to get GPIO chip info");
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (info.lines < 27) {
        fprintf(stderr, "Not enough GPIO lines available\n");
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line_config config[2];
    config[0].offset = SENSOR1_PIN;
    config[0].direction = GPIO_LINE_DIRECTION_IN;
    config[0].flags = GPIO_LINE_FLAG_BIAS_PULL_UP;
    config[1].offset = SENSOR2_PIN;
    config[1].direction = GPIO_LINE_DIRECTION_IN;
    config[1].flags = GPIO_LINE_FLAG_BIAS_PULL_UP;

    for (int i = 0; i < 2; i++) {
        struct gpiod_line *line = gpiochip_get_line(gpiod_ctx, config[i].offset);
        if (!line) {
            perror("Failed to get GPIO line");
            gpiochip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }

        if (gpio_line_request_input(line, "touch_sensor") < 0) {
            perror("Failed to request GPIO line input");
            gpiochip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }

        gpio_line_set_consumer_label(line, "touch_sensor");
    }
}

static void init_leds() {
    if (gpiochip_get_line(gpiod_ctx, LED1_PIN) < 0) {
        perror("Failed to get GPIO line");
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request_output(gpiod_ctx, LED1_PIN, 0) < 0) {
        perror("Failed to request GPIO line output");
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiochip_get_line(gpiod_ctx, LED2_PIN) < 0) {
        perror("Failed to get GPIO line");
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpio_line_request_output(gpiod_ctx, LED2_PIN, 0) < 0) {
        perror("Failed to request GPIO line output");
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

static void update_leds() {
    gpio_line_set_value(gpiod_ctx, LED1_PIN, sensor_state[0]);
    gpio_line_set_value(gpiod_ctx, LED2_PIN, sensor_state[1]);
}

static void log_event(int sensor, int state) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (buffer_index >= BUFFER_SIZE) {
        overflow_count++;
        buffer_index = 0;
    }

    buffer[buffer_index] = sensor;
    buffer[buffer_index + BUFFER_SIZE] = now.tv_sec;
    buffer[buffer_index + 2 * BUFFER_SIZE] = state;

    buffer_index++;
}

static void poll_sensors() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    for (int i = 0; i < 2; i++) {
        int sensor = i == 0 ? SENSOR1_PIN : SENSOR2_PIN;
        int state = gpio_line_get_value(gpiod_ctx, sensor);

        if (state != sensor_state[i]) {
            sensor_state[i] = state;
            log_event(sensor, state);

            if (state) {
                last_touch_time[i] = current_time;
            }
        } else if (state && (current_time.tv_sec - last_touch_time[i].tv_sec) * 1000000000 + current_time.tv_nsec - last_touch_time[i].tv_nsec >= DEBOUNCE_TIME * 1000000) {
            log_event(sensor, state);
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_leds();

    while (1) {
        poll_sensors();
        update_leds();
        usleep(50000);
    }

    gpiochip_close(gpiod_ctx);
    return 0;
}

