        exit(EXIT_FAILURE);
    }

    // Set the line direction to input
    if (gpiod_line_request_input(line, "rain_sensor") < 0) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Enable the internal pull-up resistor
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Get the current time
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("Failed to get current time");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Read the line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Format the log message
        snprintf(buffer, sizeof(buffer), "%ld: %s\n", ts.tv_sec, value ? "No Rain" : "Rain Detected");

        // Write the log message to the file
        if (fprintf(log_file, buffer) < 0) {
            perror("Failed to write to log file");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Close the log file
    fclose(log_file);

    // Release the line and chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

