#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define DEBOUNCE_TIME_MS 5
#define LOG_FILE "shaft_log.txt"
#define MAX_LOG_ENTRIES 1000
#define RPM_CALCULATION_INTERVAL_MS 1000

static int gpio_fd;
static int log_fd;
static int log_entries = 0;
static struct timespec last_change_time[2];
static int sensor_states[2] = {0, 0};

static void handle_sigint(int signum) {
    if (gpio_fd >= 0) {
        gpio_close(gpio_fd);
    }
    if (log_fd >= 0) {
        fclose(log_fd);
    }
    printf("Exiting...\n");
    exit(0);
}

static void log_transition(int sensor, int state) {
    if (log_entries >= MAX_LOG_ENTRIES) {
        fprintf(stderr, "Log file is full, discarding entry.\n");
        return;
    }
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    fprintf(log_fd, "%ld,%d,%d\n", now.tv_sec * 1000000 + now.tv_nsec / 1000, sensor, state);
    log_entries++;
}

static void calculate_rpm() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    long elapsed_time_ms = (current_time.tv_sec - last_change_time[0].tv_sec) * 1000 +
                           (current_time.tv_nsec - last_change_time[0].tv_nsec) / 1000000;
    if (elapsed_time_ms < RPM_CALCULATION_INTERVAL_MS) {
        return;
    }
    long elapsed_time_s = elapsed_time_ms / 1000;
    long rpm = (2 * 3600000) / elapsed_time_s;
    printf("RPM: %ld\n", rpm);
    last_change_time[0] = last_change_time[1];
    last_change_time[1] = current_time;
}

static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line[2];
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line[0] = gpiod_chip_get_line(chip, GPIO17);
    line[1] = gpiod_chip_get_line(chip, GPIO18);
    if (!line[0] || !line[1]) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line[0], "shaft_sensor1");
    if (ret) {
        perror("Failed to request GPIO line 1");
        gpiod_line_release(line[0]);
        gpiod_line_release(line[1]);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line[1], "shaft_sensor2");
    if (ret) {
        perror("Failed to request GPIO line 2");
        gpiod_line_release(line[0]);
        gpiod_line_release(line[1]);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_chip_fd(chip);
    if (gpio_fd < 0) {
        perror("Failed to get GPIO file descriptor");
        gpiod_line_release(line[0]);
        gpiod_line_release(line[1]);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        gpiod_line_release(line[0]);
        gpiod_line_release(line[1]);
        gpiod_chip_close(chip);
        close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_log_file() {
    log_fd = fopen(LOG_FILE, "w");
    if (!log_fd) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(log_fd, "timestamp,sensor1_state,sensor2_state\n");
}

int main() {
    setup_gpio();
    setup_log_file();

    while (1) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        for (int i = 0; i < 2; i++) {
            int state = gpiod_line_get_value(gpio_fd, i);
            if (state != sensor_states[i]) {
                sensor_states[i] = state;
                log_transition(i, state);
                calculate_rpm();
            }
        }

        usleep(RPM_CALCULATION_INTERVAL_MS * 1000);
    }

    fclose(log_fd);
    gpiod_line_release(gpio_fd);
    gpiod_chip_close(gpio_fd);
    return 0;
}

