#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define LOG_FILE "biometric_log.txt"
#define MAX_BUFFER_SIZE 100

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct sigaction sa;

    // Install SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret == -1) {
        perror("ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read heart rate and SpO2 data
    while (!should_exit) {
        unsigned char data[6];
        ret = read(i2c_fd, data, sizeof(data));
        if (ret == -1) {
            perror("read");
            continue;
        }

        // Parse data
        unsigned int heart_rate = (data[0] << 8) | data[1];
        unsigned int spo2 = (data[2] << 8) | data[3];
        unsigned int timestamp = (data[4] << 8) | data[5];

        // Format log entry
        char log_entry[MAX_BUFFER_SIZE];
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
        snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), ", Heart Rate: %d BPM, SpO2: %d%%", heart_rate, spo2);

        // Write log entry to file
        ret = fputs(log_entry, log_file);
        if (ret == EOF) {
            perror("fputs");
            continue;
        }

        // Flush file
        ret = fflush(log_file);
        if (ret == EOF) {
            perror("fflush");
            continue;
        }

        // Sleep for one second
        sleep(1);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}
