#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define LOG_FILE "bridge_integrity.log"
#define POLL_INTERVAL 100000  // 100 ms in microseconds
#define THRESHOLD 2000000000  // 2 seconds in microseconds

static int gpiod_chip = -1;
static int gpiod_line1 = -1;
static int gpiod_line2 = -1;
static int alarm_pin = -1;
static FILE *log_file = NULL;

static void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s %s\n", timestamp, event_type);
    fflush(log_file);
}

static void handle_alarm(int signum) {
    gpio_set_value(alarm_pin, 0);
    log_event("Alarm deactivated");
    fclose(log_file);
    gpiochip_close(gpiod_chip);
    gpio_line_close(gpiod_line1);
    gpio_line_close(gpiod_line2);
    exit(0);
}

static void setup_gpio() {
    gpiod_chip = gpiochip_open_by_name("gpiochip0");
    if (gpiod_chip < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line1 = gpio_line_request_input(gpiod_chip, GPIO17, 0);
    if (gpiod_line1 < 0) {
        perror("Failed to request GPIO17");
        gpiochip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line2 = gpio_line_request_input(gpiod_chip, GPIO18, 0);
    if (gpiod_line2 < 0) {
        perror("Failed to request GPIO18");
        gpio_line_close(gpiod_line1);
        gpiochip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    alarm_pin = gpio_line_request_output(gpiod_chip, GPIO27, 0);
    if (alarm_pin < 0) {
        perror("Failed to request GPIO27");
        gpio_line_close(gpiod_line2);
        gpio_line_close(gpiod_line1);
        gpiochip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    gpio_set_value(alarm_pin, 0);
}

static void setup_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpio_line_close(gpiod_line2);
        gpio_line_close(gpiod_line1);
        gpiochip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_line_close(gpiod_line2);
    gpio_line_close(gpiod_line1);
    gpiochip_close(gpiod_chip);
}

int main() {
    signal(SIGINT, handle_alarm);
    signal(SIGTERM, handle_alarm);

    setup_gpio();
    setup_logging();

    while (1) {
        int value1 = gpio_line_get_value(gpiod_line1);
        int value2 = gpio_line_get_value(gpiod_line2);

        if (value1 == 1 && value2 == 1) {
            log_event("Tilt end");
            gpio_set_value(alarm_pin, 0);
        } else if (value1 == 1 || value2 == 1) {
            log_event("Tilt start");
            gpio_set_value(alarm_pin, 1);
        } else {
            log_event("Tilt end");
            gpio_set_value(alarm_pin, 0);
        }

        usleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

