This C program continuously monitors two digital tilt sensors connected to the Raspberry Pi Zero W's GPIO bus. It logs ISO-8601 timestamps to a file named `bridge_integrity.log` for tilt start, threshold exceeded, and tilt end events. The program uses the `libgpiod` library to handle GPIO operations and includes error handling for driver library initialization, log file opening, and API call return values. It also implements clean shutdown handling for `SIGINT` and `SIGTERM` that deactivates the alarm, closes the log file, calls the library's API cleanup, and guarantees the alarm is off on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define SDA_PIN 2
#define SCL_PIN 3
#define ALERT_PIN 17
#define THRESHOLD 500
#define MAX_RETRIES 3

static int i2c_fd;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t quit = 0;

static void handle_signal(int sig) {
    quit = 1;
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpio_fd = gpiochip_open(0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    int alert_line = gpio_find_line("GPIO17");
    if (alert_line < 0) {
        perror("Failed to find GPIO line");
        gpiochip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpio_claim_line(alert_line) < 0) {
        perror("Failed to claim GPIO line");
        gpiochip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpio_direction_output(alert_line, 0) < 0) {
        perror("Failed to set GPIO direction");
        gpiochip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_sensor() {
    uint8_t ctrl1 = 0x00; // Clear power-down bit
    if (write(i2c_fd, &ctrl1, 1) != 1) {
        perror("Failed to write to sensor");
        close(i2c_fd);
        gpiochip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

static void log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, magnitude);
    fflush(log_file);
}

static void check_sensor() {
    uint8_t status;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read(i2c_fd, &status, 1) == 1) {
            if (status & 0x01) {
                return;
            }
        }
        usleep(100000);
    }
    fprintf(stderr, "Sensor not detected\n");
    close(i2c_fd);
    gpiochip_close(gpio_fd);
    exit(EXIT_FAILURE);
}

static double read_vibration() {
    uint8_t data[6];
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read(i2c_fd, data, 6) == 6) {
            return (data[0] << 16) | (data[1] << 8) | data[2];
        }
        usleep(100000);
    }
    fprintf(stderr, "Failed to read from sensor\n");
    close(i2c_fd);
    gpiochip_close(gpio_fd);
    exit(EXIT_FAILURE);
}

static void main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_gpio();
    init_sensor();
    check_sensor();

    log_file = fopen("seismic_events.log", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiochip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    while (!quit) {
        double magnitude = read_vibration();
        if (magnitude > THRESHOLD) {
            log_event(magnitude);
            gpio_set_value(ALERT_PIN, 1);
            usleep(1000000);
            gpio_set_value(ALERT_PIN, 0);
        }
        usleep(100000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiochip_close(gpio_fd);
    exit(EXIT_SUCCESS);
}

