code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES 4
#define GPIO_OUT_PIN 18
#define GPIO_IN_PINS {4, 17, 27, 22}
#define POLL_INTERVAL_MS 50

static gpiod_chip *chip = NULL;
static gpiod_line *lines[GPIO_LINES] = {NULL};
static gpiod_line_request *requests[GPIO_LINES] = {NULL};
static int led_state = 0;

static void handle_signal(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < GPIO_LINES; i++) {
        if (requests[i]) {
            gpiod_line_request_free(requests[i]);
        }
    }
    exit(signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_IN_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        requests[i] = gpiod_line_request_input(lines[i], "obstacle_detector");
        if (!requests[i]) {
            perror("Failed to request GPIO line input");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set up the LED
    gpiod_line *led_line = gpiod_chip_get_line(chip, GPIO_OUT_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line for LED");
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(led_line, "led", 0);
    if (!led_line) {
        perror("Failed to request GPIO line output");
        gpiod_line_release(led_line);
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Check each sensor
        for (int i = 0; i < GPIO_LINES; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value == 0) {
                led_state = 1;
                break;
            }
        }

        // Set the LED state
        gpiod_line_set_value(led_line, led_state);

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(led_line);
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

