#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define PIN_MAP {2, 3, 4, 17, 27}
#define DEBOUNCE_DELAY 50
#define LOG_FILE "/var/log/flame_events.log"

static volatile sig_atomic_t should_exit = 0;
static gpiod_chip *chip;
static gpiod_line *lines[NUM_SENSORS];
static FILE *log_file;

static void sig_handler(int signum) {
    should_exit = 1;
}

static void open_chip() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        exit(EXIT_FAILURE);
    }
}

static void close_chip() {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void open_line(int pin) {
    lines[pin] = gpiod_chip_get_line(chip, pin);
    if (!lines[pin]) {
        syslog(LOG_ERR, "Failed to get line %d: %m", pin);
        exit(EXIT_FAILURE);
    }
}

static void close_line(int pin) {
    if (lines[pin]) {
        gpiod_line_release(lines[pin]);
    }
}

static void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGINT handler: %m");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler: %m");
        exit(EXIT_FAILURE);
    }
}

static void log_startup() {
    syslog(LOG_USER, "flame_monitor started");
}

static void log_shutdown() {
    syslog(LOG_USER, "flame_monitor shutting down");
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "Error: %s", msg);
}

static void log_event(const char *timestamp, int sensor_id, int pin) {
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s - Sensor ID: %d (GPIO %d) - Flame Detected", timestamp, sensor_id, pin);
    fprintf(log_file, "%s\n", log_entry);
    fflush(log_file);
}

static void read_sensor(int sensor_id, int pin) {
    int value;
    int debounce_count = 0;
    while (debounce_count < 2) {
        value = gpiod_line_get_value(lines[pin]);
        if (value == 0) {
            break;
        }
        usleep(DEBOUNCE_DELAY * 1000);
        debounce_count++;
    }
    if (value == 0) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        log_event(timestamp, sensor_id, pin);
    }
}

int main() {
    open_chip();
    setup_signals();
    log_startup();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        close_chip();
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        open_line(PIN_MAP[i]);
    }

    while (!should_exit) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            read_sensor(i, PIN_MAP[i]);
        }
        usleep(1000000);
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        close_line(PIN_MAP[i]);
    }
    fclose(log_file);
    close_chip();
    log_shutdown();
    closelog();

    return 0;
}

