#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES 8
#define GPIO_BASE_PIN 5
#define POLL_INTERVAL_MS 50

static gpiod_chip *chip;
static gpiod_line *lines[GPIO_LINES];
static int fd;
static int running = 1;

static void handle_sigint(int signum) {
    running = 0;
}

static void log_event(int line_num, int pin_num, int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    printf("%s, %d, %d, %s\n", timestamp, line_num, pin_num, state ? "touch" : "release");
}

static void read_touches() {
    for (int i = 0; i < GPIO_LINES; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value != -1) {
            log_event(i, GPIO_BASE_PIN + i, value);
        }
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_BASE_PIN + i);
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Request bulk lines
    fd = gpiod_chip_request_bulk(chip, "touch_sensor", lines, GPIO_LINES);
    if (fd == -1) {
        perror("Failed to request bulk lines");
        gpiod_chip_close(chip);
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        return EXIT_FAILURE;
    }

    // Poll for changes
    while (running) {
        read_touches();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources
    gpiod_chip_close(chip);
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_release(lines[i]);
    }

    return EXIT_SUCCESS;
}

