#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libveml7700.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define GPIO_PWM 18
#define PWM_FREQ 1000
#define LOG_FILE "grow_log.txt"
#define MAX_ERROR_CODE 255

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    int i2c_fd, pwm_fd;
    struct timespec sleep_time = {1, 0}; // 1 second
    struct veml7700_sensor sensor;
    struct veml7700_config config;
    struct veml7700_data data;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *log_file;
    int error_code = 0;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libveml7700
    if (veml7700_init(&sensor) != 0) {
        error_code = 1;
        goto cleanup;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        error_code = 2;
        goto cleanup;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        error_code = 3;
        goto cleanup;
    }

    // Configure sensor
    config.mode = VEML7700_MODE_CONTINUOUS;
    config.range = VEML7700_RANGE_1000;
    if (veml7700_set_config(&sensor, &config) != 0) {
        error_code = 4;
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        error_code = 5;
        goto cleanup;
    }

    // Initialize GPIO PWM
    pwm_fd = gpiochip_open(0);
    if (pwm_fd < 0) {
        error_code = 6;
        goto cleanup;
    }

    if (gpiochip_get_line(pwm_fd, GPIO_PWM) < 0) {
        error_code = 7;
        goto cleanup;
    }

    if (gpiochip_config_line(pwm_fd, GPIO_PWM, GPIO_CONFIG_OUTPUT) < 0) {
        error_code = 8;
        goto cleanup;
    }

    if (pwm_config(pwm_fd, GPIO_PWM, PWM_FREQ, 0) < 0) {
        error_code = 9;
        goto cleanup;
    }

    while (!should_exit) {
        // Read ambient light
        if (veml7700_read(&sensor, &data) != 0) {
            error_code = 10;
            goto cleanup;
        }

        // Map lux to PWM duty cycle
        int duty_cycle = 0;
        if (data.lux < 100) {
            duty_cycle = 100;
        } else if (data.lux < 500) {
            duty_cycle = 75;
        } else if (data.lux < 1000) {
            duty_cycle = 50;
        } else {
            duty_cycle = 25;
        }

        // Set PWM duty cycle
        if (pwm_set(pwm_fd, GPIO_PWM, duty_cycle) < 0) {
            error_code = 11;
            goto cleanup;
        }

        // Get current time
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%FT%T", timeinfo);

        // Log data
        fprintf(log_file, "%s, %d, %d, %d\n", timestamp, data.lux, duty_cycle, error_code);
        fflush(log_file);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (pwm_fd >= 0) {
        gpiochip_close(pwm_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (sensor.dev != NULL) {
        veml7700_close(&sensor);
    }

    return error_code;
}

