#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN_COUNT 8
#define GPIO_BASE 2
#define GPIO_ALERT 17
#define DEBOUNCE_DELAY 50000  // 50 ms in microseconds
#define LOG_FILE "touch_log.txt"

static int gpiod_ctx = -1;
static int alert_gpio = -1;
static FILE *log_file = NULL;
static int channel_states[GPIO_PIN_COUNT] = {0};
static int debouncing = 0;

static void signal_handler(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (alert_gpio != -1) {
        gpio_set_value(alert_gpio, 0);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static void init_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    alert_gpio = gpiod_chip_get_line(gpiod_ctx, GPIO_ALERT);
    if (alert_gpio == -1) {
        perror("Failed to get alert GPIO line");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpio_direction_output(alert_gpio, 0) != 0) {
        perror("Failed to set alert GPIO direction");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_PIN_COUNT; i++) {
        int line = gpiod_chip_get_line(gpiod_ctx, GPIO_BASE + i);
        if (line == -1) {
            perror("Failed to get touch GPIO line");
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }

        if (gpio_direction_input(line) != 0) {
            perror("Failed to set touch GPIO direction");
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }

        if (gpio_set_config(line, GPIO_CONFIG_INPUT | GPIO_CONFIG_PULL_DOWN) != 0) {
            perror("Failed to set touch GPIO pull-down");
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }
    }
}

static void log_touch(int channel) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s – Channel %d Touched\n", timestamp, channel + 1);
    fclose(log_file);
}

static void poll_sensor() {
    for (int i = 0; i < GPIO_PIN_COUNT; i++) {
        int value = gpio_get_value(gpiod_chip_get_line(gpiod_ctx, GPIO_BASE + i));
        if (value != channel_states[i]) {
            if (!debouncing) {
                debouncing = 1;
                usleep(DEBOUNCE_DELAY);
                value = gpio_get_value(gpiod_chip_get_line(gpiod_ctx, GPIO_BASE + i));
                if (value != channel_states[i]) {
                    log_touch(i);
                    channel_states[i] = value;
                    gpio_set_value(alert_gpio, 1);
                } else {
                    debouncing = 0;
                }
            }
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();

    while (1) {
        poll_sensor();
        usleep(50000);  // 50 ms
    }

    return 0;
}

