#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x04
#define CONFIG_MASK 0x0F
#define CONFIG_MODE_CONTINUOUS 0x01
#define CONFIG_RATE_100MS 0x00
#define CONFIG_RATE_200MS 0x01
#define CONFIG_RATE_400MS 0x02
#define CONFIG_RATE_800MS 0x03
#define CONFIG_RATE_1600MS 0x04
#define CONFIG_RATE_3200MS 0x05
#define CONFIG_RATE_6400MS 0x06
#define CONFIG_RATE_12800MS 0x07
#define CONFIG_RATE_25600MS 0x08
#define CONFIG_RATE_51200MS 0x09
#define CONFIG_RATE_102400MS 0x0A
#define CONFIG_RATE_204800MS 0x0B
#define CONFIG_RATE_409600MS 0x0C
#define CONFIG_RATE_819200MS 0x0D
#define CONFIG_RATE_1638400MS 0x0E
#define CONFIG_RATE_3276800MS 0x0F

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Initialize GPIO for I2C
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 23);
    if (!line) {
        perror("Failed to get GPIO line 23");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "i2c", 0);
    if (ret) {
        perror("Failed to request GPIO line 23 as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("light_data.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Configure OPT3001
    uint8_t config = (CONFIG_MODE_CONTINUOUS << 4) | CONFIG_RATE_100MS;
    ret = write(i2c_fd, &config, 1);
    if (ret != 1) {
        perror("Failed to write configuration to OPT3001");
        fclose(log_file);
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Read data loop
    while (!should_exit) {
        usleep(100000); // Wait 100ms

        // Read result
        uint8_t result[2];
        ret = read(i2c_fd, result, 2);
        if (ret != 2) {
            perror("Failed to read result from OPT3001");
            continue;
        }

        // Swap bytes
        uint16_t lux = (result[0] << 8) | result[1];

        // Format timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        // Write to log file
        fprintf(log_file, "%s, %.2f\n", timestamp, lux);

        // Print to stdout
        printf("%s, %.2f\n", timestamp, lux);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

