#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN_FIRE_SENSOR 4
#define GPIO_PIN_ALERT 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
}

int main() {
    int fd, ret;
    struct timespec sleep_time;
    struct sigaction sa;
    gpiod_chip *chip;
    gpiod_line *line_fire_sensor, *line_alert;
    char timestamp[20];

    // Set up signal handler for SIGINT
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Open lines
    line_fire_sensor = gpiod_chip_get_line(chip, GPIO_PIN_FIRE_SENSOR);
    if (!line_fire_sensor) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line_alert = gpiod_chip_get_line(chip, GPIO_PIN_ALERT);
    if (!line_alert) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line_fire_sensor);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request lines for input and output
    ret = gpiod_line_request_input(line_fire_sensor, "fire_sensor");
    if (ret) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line_fire_sensor);
        gpiod_line_release(line_alert);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line_alert, "alert", 0);
    if (ret) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line_fire_sensor);
        gpiod_line_release(line_alert);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd == -1) {
        perror("open");
        gpiod_line_release(line_fire_sensor);
        gpiod_line_release(line_alert);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read the fire sensor
        ret = gpiod_line_get_value(line_fire_sensor);
        if (ret == -1) {
            perror("gpiod_line_get_value");
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log the event
        if (ret == 0) {
            fprintf(fd, "%s: Flame detected\n", timestamp);
            // Set alert pin high for 1 second
            ret = gpiod_line_set_value(line_alert, 1);
            if (ret == -1) {
                perror("gpiod_line_set_value");
            }
            sleep(1);
            ret = gpiod_line_set_value(line_alert, 0);
            if (ret == -1) {
                perror("gpiod_line_set_value");
            }
        }

        // Sleep for the next poll interval
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    close(fd);

    // Reset GPIO pins to a safe state
    gpiod_line_release(line_fire_sensor);
    gpiod_line_release(line_alert);

    // Terminate libgpiod
    gpiod_chip_close(chip);

    return 0;
}

