        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read the fire sensor
        ret = gpiod_line_get_value(line_fire_sensor);
        if (ret == -1) {
            perror("gpiod_line_get_value");
            continue;
        }

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log the event
        if (ret == 0) {
            fprintf(fd, "%s: Flame detected\n", timestamp);
            // Set alert pin high for 1 second
            ret = gpiod_line_set_value(line_alert, 1);
            if (ret == -1) {
                perror("gpiod_line_set_value");
            }
            sleep(1);
            ret = gpiod_line_set_value(line_alert, 0);
            if (ret == -1) {
                perror("gpiod_line_set_value");
            }
        }

        // Sleep for the next poll interval
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    close(fd);

    // Reset GPIO pins to a safe state
    gpiod_line_release(line_fire_sensor);
    gpiod_line_release(line_alert);

    // Terminate libgpiod
    gpiod_chip_close(chip);

    return 0;
}
