#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define CRC8_POLYNOMIAL 0x07
#define CRC8_INITIAL_VALUE 0xFF
#define MAX_LOG_SIZE 1024
#define LOG_FILE "cooling_log.csv"

static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sda_line = NULL;
static struct gpiod_line *scl_line = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

static void log_data(const char *timestamp, float flow_rate, int flags, const char *status) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    fprintf(log_file, "%s,%f,%s\n", timestamp, flow_rate, status);
    fflush(log_file);
}

static int crc8(const unsigned char *data, size_t length) {
    int crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor() {
    unsigned char command = 0x01; // Start measurement command
    unsigned char data[3];
    int bytes_read;

    // Send command
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to send command");
        return -1;
    }

    // Wait at least 2 ms before reading
    usleep(2000);

    // Read data
    bytes_read = read(i2c_fd, data, 3);
    if (bytes_read != 3) {
        perror("Failed to read data");
        return -1;
    }

    // Calculate CRC
    unsigned char calculated_crc = crc8(data, 2);
    if (calculated_crc != data[2]) {
        fprintf(stderr, "CRC error: expected 0x%02x, got 0x%02x\n", calculated_crc, data[2]);
        return -1;
    }

    // Convert flow rate
    int16_t flow_rate = (data[0] << 8) | data[1];
    float flow_rate_ml_per_min = (float)flow_rate / 100.0;

    // Validate flow rate
    if (flow_rate_ml_per_min < 0.0 || flow_rate_ml_per_min > 100.0) {
        log_data(time(NULL), flow_rate_ml_per_min, 0, "INVALID");
        return -1;
    }

    // Log data
    log_data(time(NULL), flow_rate_ml_per_min, 0, "VALID");

    return 0;
}

int main() {
    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    sda_line = gpiod_chip_get_line(chip, 2);
    scl_line = gpiod_chip_get_line(chip, 3);
    if (sda_line == NULL || scl_line == NULL) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(sda_line, "cooling_sensor", 0) != 0 ||
        gpiod_line_request_output(scl_line, "cooling_sensor", 0) != 0) {
        perror("Failed to request GPIO lines");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sensor() != 0) {
            // Attempt recovery by re-initializing I2C handle
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd == -1) {
                perror("Failed to open I2C bus");
                gpiod_line_release(sda_line);
                gpiod_line_release(scl_line);
                gpiod_chip_close(chip);
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
                perror("Failed to set I2C address");
                close(i2c_fd);
                gpiod_line_release(sda_line);
                gpiod_line_release(scl_line);
                gpiod_chip_close(chip);
                return 1;
            }
        }
        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(chip);

    return 0;
}

