#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LEFT 17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22
#define LOG_FILE "path_log.csv"
#define SAMPLE_INTERVAL_MS 50

static gpiod_chip *chip = NULL;
static gpiod_line *left_line = NULL;
static gpiod_line *middle_line = NULL;
static gpiod_line *right_line = NULL;
static FILE *log_file = NULL;

static void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (middle_line) {
        gpiod_line_release(middle_line);
    }
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};
    struct tm *timeinfo;
    char timestamp[20];
    int left_value, middle_value, right_value;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for the sensors
    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!left_line) {
        perror("Failed to get left line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(left_line, "left_sensor") < 0) {
        perror("Failed to request left line as input");
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    middle_line = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    if (!middle_line) {
        perror("Failed to get middle line");
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(middle_line, "middle_sensor") < 0) {
        perror("Failed to request middle line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!right_line) {
        perror("Failed to get right line");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(right_line, "right_sensor") < 0) {
        perror("Failed to request right line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Write header to the log file
    fprintf(log_file, "timestamp,left,middle,right\n");

    while (true) {
        // Get the current time
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Read the sensor values
        left_value = gpiod_line_get_value(left_line);
        middle_value = gpiod_line_get_value(middle_line);
        right_value = gpiod_line_get_value(right_line);

        // Write the timestamped reading to the log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);

        // Sleep for the sample interval
        nanosleep(&sleep_time, NULL);
    }

    // Close the log file
    fclose(log_file);

    // Release the GPIO lines
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

