#define FLAME_SENSOR_PIN 4
#define FLAME_EVENT_FILE "flame_events.txt"
#define MAX_EVENT_LENGTH 256

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int signum) {
    keep_running = 0;
}

int main() {
    int fd;
    struct timespec ts;
    char event_message[MAX_EVENT_LENGTH];
    FILE *file;

