    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    fd = gpiod_chip_open_by_name("gpiochip0");
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line = gpiod_chip_get_line(fd, FLAME_SENSOR_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(fd);
        exit(EXIT_FAILURE);
    }

    // Request the line for input
    int request_result = gpiod_line_request_input(line, "flame_sensor");
    if (request_result < 0) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        exit(EXIT_FAILURE);
    }

    // Open the event file
    file = fopen(FLAME_EVENT_FILE, "a");
    if (file == NULL) {
        perror("Failed to open event file");
        gpiod_line_release(line);
        gpiod_chip_close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (keep_running) {
        // Wait for the falling edge
        request_result = gpiod_line_event_wait(line, &ts);
        if (request_result < 0) {
            perror("Failed to wait for line event");
            break;
        }

        // Read the line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read line value");
            break;
        }

        // Check if a flame is detected
        if (value == 0) {
            // Get the current timestamp
            time_t now;
            time(&now);
            struct tm *tm = localtime(&now);
            strftime(event_message, MAX_EVENT_LENGTH, "%Y-%m-%d %H:%M:%S", tm);

            // Append the event to the file
            fprintf(file, "%s: Flame detected\n", event_message);
            fflush(file);
        }
    }

    // Clean up
    fclose(file);
    gpiod_line_release(line);
    gpiod_chip_close(fd);

    return 0;
}

