#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP 4
#define GPIO_TOUCH 23
#define GPIO_LED 24
#define LOG_FILE "touch_log.txt"
#define TIMEOUT 1000000  // 1 second in microseconds

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    FILE *log_file;
    gpiod_chip *chip;
    gpiod_line *line_touch, *line_led;
    gpiod_line_event event;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO chip
    chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Request the touch and LED lines
    line_touch = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!line_touch) {
        perror("Failed to get touch line");
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    line_led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line_led) {
        perror("Failed to get LED line");
        gpiod_line_release(line_touch);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Set the touch line to input mode
    ret = gpiod_line_request_input(line_touch, "touch_sensor");
    if (ret) {
        perror("Failed to request touch line input");
        gpiod_line_release(line_led);
        gpiod_line_release(line_touch);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Set the LED line to output mode
    ret = gpiod_line_request_output(line_led, "led", 0);
    if (ret) {
        perror("Failed to request LED line output");
        gpiod_line_release(line_led);
        gpiod_line_release(line_touch);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Start polling for touch events
    while (!should_exit) {
        ret = gpiod_line_event_wait(line_touch, TIMEOUT);
        if (ret < 0) {
            perror("Failed to wait for touch event");
            break;
        }

        ret = gpiod_line_event_read(line_touch, &event);
        if (ret < 0) {
            perror("Failed to read touch event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Toggle the LED
            ret = gpiod_line_set_value(line_led, !gpiod_line_get_value(line_led));
            if (ret) {
                perror("Failed to set LED value");
                break;
            }

            // Get the current time
            clock_gettime(CLOCK_REALTIME, &ts);
            tm = localtime(&ts.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

            // Log the touch event
            fprintf(log_file, "%s - LED: %s\n", timestamp, gpiod_line_get_value(line_led) ? "ON" : "OFF");
            fflush(log_file);
        }
    }

    // Clean up resources
    gpiod_line_release(line_led);
    gpiod_line_release(line_touch);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

