#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define LOG_FILE "alert_log.txt"

static gpiod_chip *chip;
static gpiod_line *flame_sensor_line;
static gpiod_line *buzzer_line;
static FILE *log_file;
static int running = 1;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
        gpiod_line_release(buzzer_line);
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        printf("System stopped\n");
        exit(0);
    }
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s\n", timestamp, event);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request input from flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request output for buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return 1;
    }

    // Log system start
    log_event("System started");

    // Main loop
    while (running) {
        int flame_detected = gpiod_line_get_value(flame_sensor_line);
        if (flame_detected) {
            log_event("FLAME DETECTED");
            gpiod_line_set_value(buzzer_line, 1);
            usleep(BUZZER_DURATION_MS * 1000);
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Log system stop
    log_event("System stopped");

    // Clean up
    gpiod_line_release(buzzer_line);
    gpiod_line_release(flame_sensor_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

