        gpiod_line_release(flame_sensor_line);
        return 1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request input from flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request output for buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return 1;
    }

    // Log system start
    log_event("System started");

    // Main loop
    while (running) {
        int flame_detected = gpiod_line_get_value(flame_sensor_line);
        if (flame_detected) {
            log_event("FLAME DETECTED");
            gpiod_line_set_value(buzzer_line, 1);
            usleep(BUZZER_DURATION_MS * 1000);
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Log system stop
    log_event("System stopped");

    // Clean up
    gpiod_line_release(buzzer_line);
    gpiod_line_release(flame_sensor_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}
