                    fprintf(log_file, "%s\n", timestamp);
                    fflush(log_file);
                }
            }
        }
        usleep(10000); // Poll every 10 ms
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line_ttp223b);
    gpiod_line_release(line_led);
    gpiod_chip_close(fd);

    return EXIT_SUCCESS;
