#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "magnet_log.txt"
#define POLL_INTERVAL_MS 100

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

static void sig_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    exit(signum);
}

static void log_magnet_state(int sensor_id, int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(log_file, "%s, Sensor %d: %s\n", timestamp, sensor_id, state ? "Magnet Present" : "Magnet Removed");
}

static int read_sensor(int sensor_id) {
    int gpio = -1;
    int value = -1;

    switch (sensor_id) {
        case 1:
            gpio = GPIO4;
            break;
        case 2:
            gpio = GPIO17;
            break;
        case 3:
            gpio = GPIO27;
            break;
        default:
            fprintf(stderr, "Invalid sensor ID: %d\n", sensor_id);
            return -1;
    }

    if (gpiod_ctx == -1) {
        gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
        if (gpiod_ctx == -1) {
            perror("Failed to open GPIO chip");
            return -1;
        }
    }

    struct gpiod_line *line = gpiod_chip_get_line(gpiod_ctx, gpio);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_PULL_UP;
    int ret = gpiod_line_request(line, "magnet_sensor", flags);
    if (ret) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        return -1;
    }

    ret = gpiod_line_get_value(line, &value);
    if (ret) {
        perror("Failed to read GPIO line value");
        gpiod_line_release(line);
        return -1;
    }

    gpiod_line_release(line);

    return value;
}

int main() {
    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    int sensor_states[3] = {0, 0, 0};
    int initial_state = -1;

    while (1) {
        for (int i = 0; i < 3; i++) {
            int state = read_sensor(i + 1);
            if (state == -1) {
                continue;
            }

            if (initial_state == -1) {
                initial_state = state;
                continue;
            }

            if (state != initial_state) {
                log_magnet_state(i + 1, state);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpiod_chip_close(gpiod_ctx);

    return EXIT_SUCCESS;
}

