#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define PART_ID 0x01
#define HW_REV 0x02
#define CONFIG_REG 0x03
#define DATA_REG 0x04
#define FILTER_REG 0x05
#define MAX_SAMPLES 5
#define LOG_FILE "heart_rate.csv"

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 1000000000 / 1}; // 1 second

    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    if (i2cHandleOpen() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cHandleClose();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Read sensor ID and hardware revision
    uint8_t part_id, hw_rev;
    if (readSensorID(&part_id, &hw_rev) < 0) {
        fclose(log_file);
        i2cHandleClose();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Check sensor ID and hardware revision
    if (part_id != PART_ID || hw_rev != HW_REV) {
        fprintf(stderr, "Sensor ID or hardware revision mismatch\n");
        fclose(log_file);
        i2cHandleClose();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure sensor
    if (configureSensor() < 0) {
        fclose(log_file);
        i2cHandleClose();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up moving average filter
    uint16_t filter_buffer[MAX_SAMPLES];
    uint16_t filter_sum = 0;
    for (int i = 0; i < MAX_SAMPLES; i++) {
        filter_buffer[i] = 0;
    }

    // Main loop
    while (!should_exit) {
        // Read raw heart-rate data
        uint16_t raw_data;
        if (readRawData(&raw_data) < 0) {
            continue;
        }

        // Apply moving average filter
        filter_sum -= filter_buffer[0];
        filter_buffer[0] = raw_data;
        filter_sum += filter_buffer[0];
        uint16_t filtered_data = filter_sum / MAX_SAMPLES;

        // Validate filtered beats-per-minute value
        if (filtered_data >= 30 && filtered_data <= 220) {
            // Format and write to log file
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s,%d\n", timestamp, filtered_data);
            fflush(log_file);
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    i2cHandleClose();
    gpioTerminate();

    return EXIT_SUCCESS;
}

int i2cHandleOpen() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return -1;
    }
    return 0;
}

void i2cHandleClose() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
}

int readSensorID(uint8_t *part_id, uint8_t *hw_rev) {
    if (i2cWriteReg(i2c_handle, CONFIG_REG, 0x00) < 0) {
        return -1;
    }
    if (i2cReadReg(i2c_handle, PART_ID, part_id) < 0) {
        return -1;
    }
    if (i2cReadReg(i2c_handle, HW_REV, hw_rev) < 0) {
        return -1;
    }
    return 0;
}

int configureSensor() {
    // Set up configuration register
    uint8_t config = 0x01; // Example configuration
    if (i2cWriteReg(i2c_handle, CONFIG_REG, config) < 0) {
        return -1;
