    uint8_t config = 0x01; // Example configuration
    if (i2cWriteReg(i2c_handle, CONFIG_REG, config) < 0) {
        return -1;
    }
    return 0;
}

int readRawData(uint16_t *raw_data) {
    if (i2cReadReg(i2c_handle, DATA_REG, raw_data) < 0) {
        return -1;
    }
    return 0;
}
