#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
}

int main() {
    int fd, chip_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char timestamp[20];
    FILE *log_file;

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the GPIO chip
    chip_fd = gpiod_chip_open_by_name("gpiochip0");
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line
    chip = gpiod_chip_get_from_fd(chip_fd);
    if (!chip) {
        perror("Failed to get GPIO chip");
        close(chip_fd);
        exit(EXIT_FAILURE);
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Request the line as an input with an internal pull-up
    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(chip_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Wait for a falling edge
        if (gpiod_line_event_wait(line, POLL_INTERVAL_MS * 1000000) < 0) {
            perror("Failed to wait for falling edge");
            break;
        }

        // Read the line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        // Check if the line is low
        if (value == 0) {
            // Get the current timestamp
            clock_gettime(CLOCK_MONOTONIC, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

            // Print the alert to the console
            printf("FLAME DETECTED at %s\n", timestamp);

            // Append the alert to the log file
            fprintf(log_file, "FLAME DETECTED at %s\n", timestamp);
            fflush(log_file);

            // Wait for the line to go high again
            while (gpiod_line_get_value(line) == 0) {
                usleep(POLL_INTERVAL_MS * 1000);
            }
        }
    }

    // Close the log file
    fclose(log_file);

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    // Close the GPIO chip file descriptor
    close(chip_fd);

    return 0;
}

