#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 5
#define GPIO_COUNT 8
#define LOG_FILE "touch_log.txt"
#define STABILIZATION_DELAY 200
#define POLL_INTERVAL 10

static gpiod_chip *chip;
static gpiod_line *lines[NUM_CHANNELS];
static gpiod_line_bulk *bulk;
static FILE *log_file;
static int counter = 0;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            gpiod_line_set_value(lines[i], 0);
        }
        gpiod_line_bulk_release(bulk);
        gpiod_chip_close(chip);
        if (log_file) {
            fclose(log_file);
        }
        exit(0);
    }
}

static void log_event(int channel, int value) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, value);
    fprintf(stdout, "Touch on channel %d | Counter: %d\n", channel, value);
}

static void read_sensor() {
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value == 1) {
            counter = (counter + 1) % 256;
            log_event(i + 1, counter);
            for (int j = 0; j < NUM_CHANNELS; j++) {
                gpiod_line_set_value(lines[j], (counter >> j) & 1);
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    bulk = gpiod_line_bulk_open(chip, GPIO_BASE, GPIO_COUNT, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (!bulk) {
        fprintf(stderr, "Failed to open GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_line_bulk_get(bulk, i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", i + GPIO_BASE, strerror(errno));
            gpiod_line_bulk_release(bulk);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    usleep(STABILIZATION_DELAY * 1000);

    while (1) {
        read_sensor();
        usleep(POLL_INTERVAL * 1000);
    }

    gpiod_line_bulk_release(bulk);
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

