#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_BASE 32
#define GPIO_COUNT 4
#define GPIO_PINS {17, 18, 27, 22}
#define CSV_FILE "tracking_log.csv"
#define POLL_INTERVAL_MS 100

static gpiod_chip *chip;
static gpiod_line *lines[GPIO_COUNT];
static FILE *csv_file;
static volatile sig_atomic_t should_exit = 0;

static void handle_signal(int signum) {
    should_exit = 1;
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PINS[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
        int ret = gpiod_line_request_input(lines[i], "Tracking", flags);
        if (ret) {
            fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PINS[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }
}

static void close_gpio() {
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

static void init_csv() {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file %s\n", CSV_FILE);
        close_gpio();
        exit(EXIT_FAILURE);
    }

    if (fseek(csv_file, 0, SEEK_END) == 0) {
        char *header = "timestamp,sensor1,sensor2,sensor3,sensor4\n";
        if (fwrite(header, strlen(header), 1, csv_file) != 1) {
            fprintf(stderr, "Failed to write header to CSV file %s\n", CSV_FILE);
            fclose(csv_file);
            close_gpio();
            exit(EXIT_FAILURE);
        }
    }
}

static void close_csv() {
    fclose(csv_file);
}

static void write_csv(int timestamp, int sensor1, int sensor2, int sensor3, int sensor4) {
    char buffer[100];
    snprintf(buffer, sizeof(buffer), "%d,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
    if (fwrite(buffer, strlen(buffer), 1, csv_file) != 1) {
        fprintf(stderr, "Failed to write to CSV file %s\n", CSV_FILE);
    }
}

static void poll_sensors() {
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
    while (!should_exit) {
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        int sensor1 = gpiod_line_get_value(lines[0]);
        int sensor2 = gpiod_line_get_value(lines[1]);
        int sensor3 = gpiod_line_get_value(lines[2]);
        int sensor4 = gpiod_line_get_value(lines[3]);

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        long elapsed_time = (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec);
        if (elapsed_time < sleep_time.tv_nsec) {
            nanosleep(&sleep_time, NULL);
        }

        write_csv(start_time.tv_sec, sensor1, sensor2, sensor3, sensor4);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_csv();

    poll_sensors();

    close_csv();
    close_gpio();

    return 0;
}

