#define MAX_LOG_LINE 100

static gpiod_chip *chip;
static gpiod_line *line1, *line2;
static FILE *log_file;
static int running = 1;

static void log_tilt(int sensor, const char *timestamp) {
    char log_line[MAX_LOG_LINE];
    snprintf(log_line, MAX_LOG_LINE, "%s, Sensor %d tilted\n", timestamp, sensor);
    fprintf(log_file, log_line);
    fflush(log_file);
}

static void handle_signal(int signum) {
    running = 0;
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 100000000}; // 100 ms
    struct timespec debounce_time = {0, 50000000}; // 50 ms
    char timestamp[20];
    int sensor1_state, sensor2_state;
    int sensor1_last_state = 1;
    int sensor2_last_state = 1;

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        return 1;
    }

    // Request lines
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Failed to request line 1");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Failed to request line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Configure lines as inputs with active-low pull-up
    if (gpiod_line_request_input(line1, "tilt_sensor1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        perror("Failed to configure line 1");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    if (gpiod_line_request_input(line2, "tilt_sensor2", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        perror("Failed to configure line 2");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    while (running) {
        // Read sensor states
        sensor1_state = gpiod_line_get_value(line1);
        sensor2_state = gpiod_line_get_value(line2);

        // Check for transitions from inactive to active
        if (sensor1_state == 0 && sensor1_last_state == 1) {
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            log_tilt(1, timestamp);
        }
        if (sensor2_state == 0 && sensor2_last_state == 1) {
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            log_tilt(2, timestamp);
        }

        // Update last states
        sensor1_last_state = sensor1_state;
        sensor2_last_state = sensor2_state;

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

