#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define LOG_FILE "obstacle_log.csv"
#define POLL_INTERVAL 100000  // 100 ms in microseconds

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *led;
    int ret;
    FILE *log_file;
    struct timespec ts;
    char timestamp[20];

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for sensors and LED
    line1 = gpiod_chip_get_line(chip, GPIO17);
    line2 = gpiod_chip_get_line(chip, GPIO27);
    led = gpiod_chip_get_line(chip, GPIO22);

    // Request input for sensors and output for LED
    ret = gpiod_line_request_input(line1, "sensor1");
    if (ret) {
        perror("Failed to request input for sensor1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line2, "sensor2");
    if (ret) {
        perror("Failed to request input for sensor2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led, "led", 0);
    if (ret) {
        perror("Failed to request output for led");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Write header to log file
    fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");
    fflush(log_file);

    while (!should_exit) {
        // Read sensor states
        int sensor1_state = gpiod_line_get_value(line1);
        int sensor2_state = gpiod_line_get_value(line2);

        // Determine LED state
        int led_state = (sensor1_state == 0 && sensor2_state == 0) ? 1 : 0;

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Write data to log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1_state, sensor2_state, led_state);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(POLL_INTERVAL);
    }

    // Turn off LED
    gpiod_line_set_value(led, 0);

    // Release line resources
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(led);

    // Close the log file
    fclose(log_file);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

