This C program uses the `libgpiod` library to interact with the Raspberry Pi's GPIO pins. It sets up two TCRT5000 IR obstacle-avoidance sensors connected to GPIO17 and GPIO27, and an LED connected to GPIO22. The program polls both sensors every 100 ms, checks if both sensors are clear (i.e., both read 0), and turns the LED high only when both sensors are clear. The program logs each sample to a file named `obstacle_log.csv` with the columns timestamp, sensor1, sensor2, and led_state. It handles errors and performs a graceful shutdown on receiving a SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_MIC 4
#define GPIO_LED 17
#define SAMPLE_RATE 8000
#define SAMPLE_PERIOD 125
#define LED_ON_TIME 100

volatile sig_atomic_t stop_sampling = 0;

void handle_signal(int signum) {
    stop_sampling = 1;
    printf("Received SIGINT, stopping sampling...\n");
}

int main() {
    int fd;
    struct timespec ts;
    struct sigaction sa;
    gpiod_chip *chip;
    gpiod_line *line;
    gpiod_line_request *request;
    int result;

    // Set up signal handler for SIGINT
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get the line for GPIO4
    line = gpiod_chip_get_line(chip, GPIO_MIC);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as a digital input
    request = gpiod_line_request_input(line, "mic-sampling");
    if (!request) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize LED GPIO
    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(request->line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as a digital output
    request = gpiod_line_request_output(line, "led-control", 0);
    if (!request) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Start sampling
    while (!stop_sampling) {
        // Wait for the next sample period
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_PERIOD * 1000000;
        result = nanosleep(&ts, NULL);
        if (result == -1) {
            perror("nanosleep");
            break;
        }

        // Read the GPIO4 line
        result = gpiod_line_get_value(request->line);
        if (result == -1) {
            perror("gpiod_line_get_value");
            break;
        }

        // Check if it's a sound peak
        if (result == 1) {
            // Print the timestamp
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            printf("%ld.%03ld\n", now.tv_sec, now.tv_nsec / 1000000);

            // Turn on the LED
            result = gpiod_line_set_value(request->line, 1);
            if (result == -1) {
                perror("gpiod_line_set_value");
                break;
            }

            // Wait for 100 ms
            ts.tv_sec = 0;
            ts.tv_nsec = LED_ON_TIME * 1000000;
            result = nanosleep(&ts, NULL);
            if (result == -1) {
                perror("nanosleep");
                break;
            }

            // Turn off the LED
            result = gpiod_line_set_value(request->line, 0);
            if (result == -1) {
                perror("gpiod_line_set_value");
                break;
            }
        }
    }

    // Clean up
    gpiod_line_release(request->line);
    gpiod_chip_close(chip);

    return 0;
}

