    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    // Get the line for GPIO4
    line = gpiod_chip_get_line(chip, GPIO_MIC);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as a digital input
    request = gpiod_line_request_input(line, "mic-sampling");
    if (!request) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize LED GPIO
    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(request->line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as a digital output
    request = gpiod_line_request_output(line, "led-control", 0);
    if (!request) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Start sampling
    while (!stop_sampling) {
        // Wait for the next sample period
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_PERIOD * 1000000;
        result = nanosleep(&ts, NULL);
        if (result == -1) {
            perror("nanosleep");
            break;
        }

        // Read the GPIO4 line
        result = gpiod_line_get_value(request->line);
        if (result == -1) {
            perror("gpiod_line_get_value");
            break;
        }

        // Check if it's a sound peak
        if (result == 1) {
            // Print the timestamp
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            printf("%ld.%03ld\n", now.tv_sec, now.tv_nsec / 1000000);

            // Turn on the LED
            result = gpiod_line_set_value(request->line, 1);
            if (result == -1) {
                perror("gpiod_line_set_value");
                break;
            }

            // Wait for 100 ms
            ts.tv_sec = 0;
            ts.tv_nsec = LED_ON_TIME * 1000000;
            result = nanosleep(&ts, NULL);
            if (result == -1) {
                perror("nanosleep");
                break;
            }

            // Turn off the LED
            result = gpiod_line_set_value(request->line, 0);
            if (result == -1) {
                perror("gpiod_line_set_value");
                break;
            }
        }
    }

    // Clean up
    gpiod_line_release(request->line);
    gpiod_chip_close(chip);

    return 0;
}
