#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define LED_RED 17
#define LED_GREEN 18
#define LED_BLUE 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define INTERPOLATION_STEPS 50
#define INTERPOLATION_INTERVAL 5000000 // 5 seconds in microseconds

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *red_line, *green_line, *blue_line;
    struct gpiod_line_request request;
    struct timespec sleep_time = {0, INTERPOLATION_INTERVAL};

    // Initialize logging
    openlog("rgb_led_fade", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        closelog();
        return EXIT_FAILURE;
    }

    // Request lines for the RGB LEDs
    red_line = gpiod_chip_get_line(chip, LED_RED);
    green_line = gpiod_chip_get_line(chip, LED_GREEN);
    blue_line = gpiod_chip_get_line(chip, LED_BLUE);

    if (!red_line || !green_line || !blue_line) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %m");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Request PWM on the lines
    ret = gpiod_line_request_output(red_line, "red_pwm", 0);
    if (ret) {
        syslog(LOG_ERR, "Failed to request PWM on red line: %m");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(green_line, "green_pwm", 0);
    if (ret) {
        syslog(LOG_ERR, "Failed to request PWM on green line: %m");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(blue_line, "blue_pwm", 0);
    if (ret) {
        syslog(LOG_ERR, "Failed to request PWM on blue line: %m");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    // Seed rand() with /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (!urandom) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %m");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    unsigned int seed;
    fread(&seed, sizeof(seed), 1, urandom);
    srand(seed);
    fclose(urandom);

    while (!should_exit) {
        // Generate random hues
        unsigned int red = rand() % (PWM_RANGE + 1);
        unsigned int green = rand() % (PWM_RANGE + 1);
        unsigned int blue = rand() % (PWM_RANGE + 1);

        // Interpolate between the current and new hues
        for (int i = 0; i <= INTERPOLATION_STEPS; i++) {
            unsigned int t = i * 100 / INTERPOLATION_STEPS;
            unsigned int new_red = red + (t * (PWM_RANGE - red)) / 100;
            unsigned int new_green = green + (t * (PWM_RANGE - green)) / 100;
            unsigned int new_blue = blue + (t * (PWM_RANGE - blue)) / 100;

            // Clamp values to 0-255
            new_red = (new_red > PWM_RANGE) ? PWM_RANGE : new_red;
            new_green = (new_green > PWM_RANGE) ? PWM_RANGE : new_green;
            new_blue = (new_blue > PWM_RANGE) ? PWM_RANGE : new_blue;

            // Set PWM values
            ret = gpiod_line_set_value(red_line, new_red);
            if (ret) {
                syslog(LOG_ERR, "Failed to set PWM on red line: %m");
                break;
            }

            ret = gpiod_line_set_value(green_line, new_green);
            if (ret) {
                syslog(LOG_ERR, "Failed to set PWM on green line: %m");
                break;
            }

            ret = gpiod_line_set_value(blue_line, new_blue);
            if (ret) {
                syslog(LOG_ERR, "Failed to set PWM on blue line: %m");
                break;
            }

            // Sleep for the interpolation interval
            nanosleep(&sleep_time, NULL);
        }
    }

    // Turn off the LED
    ret = gpiod_line_set_value(red_line, 0);
    if (ret) {
        syslog(LOG_ERR, "Failed to turn off red line: %m");
    }

    ret = gpiod_line_set_value(green_line, 0);
    if (ret) {
        syslog(LOG_ERR, "Failed to turn off green line: %m");
    }

    ret = gpiod_line_set_value(blue_line, 0);
    if (ret) {
        syslog(LOG_ERR, "Failed to turn off blue line: %m");
    }

    // Release resources
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);

    // Close syslog
    closelog();

    return EXIT_SUCCESS;
}

