#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define PON 0x80
#define RGBC 0x01
#define INTEGRATION_TIME 0x81
#define CLEAR 0x83
#define RED 0x84
#define GREEN 0x85
#define BLUE 0x86
#define LED_PIN 17
#define THRESHOLD 200

static int i2c_fd;
static int led_line;
static volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void cleanup() {
    if (led_line != -1) {
        gpiod_line_release(led_line);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    // Power down the sensor
    unsigned char power_down[] = {PON, 0x00};
    if (write(i2c_fd, power_down, sizeof(power_down)) != sizeof(power_down)) {
        perror("Failed to power down sensor");
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    // Power on the sensor
    unsigned char power_on[] = {PON, 0x01};
    if (write(i2c_fd, power_on, sizeof(power_on)) != sizeof(power_on)) {
        perror("Failed to power on sensor");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    // Enable RGBC
    unsigned char rgbc[] = {RGBC, 0x01};
    if (write(i2c_fd, rgbc, sizeof(rgbc)) != sizeof(rgbc)) {
        perror("Failed to enable RGBC");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    // Set integration time to 154ms
    unsigned char integration_time[] = {INTEGRATION_TIME, 0x0A};
    if (write(i2c_fd, integration_time, sizeof(integration_time)) != sizeof(integration_time)) {
        perror("Failed to set integration time");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        cleanup();
        return EXIT_FAILURE;
    }

    while (!exit_flag) {
        // Read sensor data
        unsigned char data[8];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read sensor data");
            close(i2c_fd);
            gpiod_chip_close(chip);
            gpiod_line_release(led_line);
            cleanup();
            return EXIT_FAILURE;
        }

        // Extract calibrated values
        unsigned char clear = data[0];
        unsigned char red = data[1];
        unsigned char green = data[2];
        unsigned char blue = data[3];

        // Print values
        printf("Clear: %d, Red: %d, Green: %d, Blue: %d\n", clear, red, green, blue);

        // Control LED
        if (red > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 200ms
        usleep(200000);
    }

    // Clean up
    cleanup();
    return EXIT_SUCCESS;
}

