#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define BH1750_I2C_ADDR 0x23
#define APA102_SPI_DEV "/dev/spidev0.0"
#define APA102_NUM_LEDS 30
#define APA102_FRAME_SIZE 4
#define APA102_START_FRAME 0x00000000
#define APA102_END_FRAME 0xFFFFFFFF
#define APA102_BRIGHTNESS_MASK 0x000000FF
#define APA102_BLUE_MASK 0x0000FF00
#define APA102_GREEN_MASK 0x00FF0000
#define APA102_RED_MASK 0xFF000000

static int i2c_fd;
static int spi_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static struct gpiod_line_request line_request;
static struct spi_ioc_transfer spi_transfer;
static uint8_t apa102_data[APA102_NUM_LEDS * APA102_FRAME_SIZE];

void handle_sigint(int signum) {
    // Turn off all LEDs
    memset(apa102_data, 0, APA102_NUM_LEDS * APA102_FRAME_SIZE);
    spi_transfer.tx_buf = (unsigned long)apa102_data;
    spi_transfer.len = APA102_NUM_LEDS * APA102_FRAME_SIZE;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &spi_transfer) < 0) {
        perror("SPI_IOC_MESSAGE");
    }
    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Initialize SPI
    spi_fd = open(APA102_SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        exit(1);
    }
    spi_transfer.speed_hz = 1000000;
    spi_transfer.bits_per_word = 8;
    spi_transfer.cs_change = 0;
    spi_transfer.tx_buf = (unsigned long)apa102_data;
    spi_transfer.len = APA102_NUM_LEDS * APA102_FRAME_SIZE;

    // Initialize GPIO for LED control
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        close(spi_fd);
        exit(1);
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, 17); // Example GPIO pin for LED control
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        close(spi_fd);
        exit(1);
    }
    line_request.flags = GPIOD_LINE_REQUEST_FLAG_OUT_INIT_LOW;
    if (gpiod_line_request(gpio_line, &line_request) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        close(spi_fd);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read ambient light level from BH1750
        uint8_t command = 0x10; // Start measurement at high resolution
        if (write(i2c_fd, &command, 1) != 1) {
            perror("Failed to write to BH1750");
            continue;
        }
        usleep(120000); // Wait for conversion to complete

        uint8_t data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from BH1750");
            continue;
        }

        // Calculate brightness
        uint16_t lux = (data[0] << 8) | data[1];
        uint32_t brightness = (uint32_t)lux * 0xFF / 100; // Scale to 0-255

        // Construct APA102 data
        memset(apa102_data, 0, APA102_NUM_LEDS * APA102_FRAME_SIZE);
        for (int i = 0; i < APA102_NUM_LEDS; i++) {
            apa102_data[i * APA102_FRAME_SIZE] = APA102_START_FRAME;
            apa102_data[i * APA102_FRAME_SIZE + 1] = brightness;
            apa102_data[i * APA102_FRAME_SIZE + 2] = 0; // Blue
            apa102_data[i * APA102_FRAME_SIZE + 3] = 0; // Green
            apa102_data[i * APA102_FRAME_SIZE + 4] = brightness; // Red
            apa102_data[i * APA102_FRAME_SIZE + 5] = APA102_END_FRAME;
        }

        // Transmit APA102 data
        if (ioctl(spi_fd, SPI_IOC_MESSAGE, &spi_transfer) < 0) {
            perror("SPI_IOC_MESSAGE");
            continue;
        }

        // Turn on LED
        gpiod_line_set_value(gpio_line, 1);

        // Wait for a bit
        usleep(1000000);
    }

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

