#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x10
#define LED_PIN 18
#define MAX_RETRIES 3
#define DELAY_BETWEEN_READS 200
#define DELAY_BETWEEN_RETRIES 100
#define MAX_LUX 65535
#define GAMMA_CORRECTION 2.2

static int i2c_fd;
static int led_pin;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_signal(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (line) {
        gpiod_line_release(line);
    }
    exit(signum);
}

int read_ambient_light() {
    uint8_t data[2];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, data, 2) != 2) {
            retries++;
            usleep(DELAY_BETWEEN_RETRIES * 1000);
            continue;
        }
        return (data[0] << 8) | data[1];
    }
    fprintf(stderr, "Failed to read ambient light after %d retries\n", MAX_RETRIES);
    return -1;
}

float gamma_correct(float lux) {
    return pow(lux, GAMMA_CORRECTION);
}

void drive_led_strip(float brightness) {
    int duty_cycle = (int)(brightness * 255);
    for (int i = 0; i < duty_cycle; i++) {
        gpiod_line_set_value(line, 1);
        usleep(1000);
        gpiod_line_set_value(line, 0);
        usleep(1000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "LED", 0)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        int lux = read_ambient_light();
        if (lux < 0) {
            continue;
        }

        float brightness = gamma_correct(lux);
        drive_led_strip(brightness);

        printf("Lux: %d, Brightness: %.2f\n", lux, brightness);
        usleep(DELAY_BETWEEN_READS * 1000);
    }

    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

