#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define SELF_TEST_INTERVAL 1000000
#define MAIN_LOOP_INTERVAL 50000
#define ERROR_BLINK_INTERVAL 100000
#define ERROR_BEEP_INTERVALS 3
#define ERROR_BEEP_DURATIONS 200000, 200000, 600000, 200000

static gpiod_chip *chip;
static gpiod_line *flame_sensor_line, *buzzer_line, *led_line;
static int flame_sensor_value, led_state, buzzer_state;
static struct timespec start_time;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, cleaning up GPIO lines...\n");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(0);
    }
}

void log_event(const char *event) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    printf("%ld.%09ld: %s\n", current_time.tv_sec, current_time.tv_nsec, event);
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    // Request lines
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Failed to request input on flame sensor line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request output on buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request output on LED line");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Perform self-test
    printf("Performing self-test...\n");
    for (int i = 0; i < 5; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (clock_gettime(CLOCK_MONOTONIC, &current_time) == 0 && (current_time.tv_sec - start_time.tv_sec) * 1000000000 + (current_time.tv_nsec - start_time.tv_nsec) < SELF_TEST_INTERVAL) {
            usleep(10000);
        }
        flame_sensor_value = gpiod_line_get_value(flame_sensor_line);
        if (flame_sensor_value == 0) {
            printf("Flame detected on sample %d\n", i + 1);
            log_event("Flame detected");
        } else {
            printf("No flame detected on sample %d\n", i + 1);
            log_event("No flame detected");
        }
    }
    if (flame_sensor_value == 0) {
        printf("Error: Flame detected on all five samples\n");
        log_event("Error: Flame detected on all five samples");
        // Blink LED rapidly
        for (int i = 0; i < 5; i++) {
            gpiod_line_set_value(led_line, 1);
            usleep(ERROR_BLINK_INTERVAL);
            gpiod_line_set_value(led_line, 0);
            usleep(ERROR_BLINK_INTERVAL);
        }
        // Beep buzzer
