#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define GPIO17 17
#define BUFFER_SIZE 60
#define MAX_LUX 1000

static int i2c_fd;
static int gpio_fd;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int lux_average = 0;
static int last_lux = 0;
static int led_state = 0;
static int led_frequency = 0;

static void sigint_handler(int signum) {
    close(i2c_fd);
    close(gpio_fd);
    printf("Program terminated by user.\n");
    exit(0);
}

static void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }
}

static void init_gpio() {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }
    if (ioctl(gpio_fd, GPIO_GET_LINEINFO_IOCTL, &gpiochip_info) < 0) {
        perror("Failed to get GPIO line info");
        close(gpio_fd);
        exit(1);
    }
    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &line_handle) < 0) {
        perror("Failed to get GPIO line handle");
        close(gpio_fd);
        exit(1);
    }
    if (ioctl(line_handle.fd, GPIOHANDLE_REQUEST_OUTPUT, &gpiohandle_request) < 0) {
        perror("Failed to request GPIO line");
        close(gpio_fd);
        close(line_handle.fd);
        exit(1);
    }
}

static void read_lux() {
    uint8_t command = 0x10; // Start measurement at 1lx resolution
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write command to BH1750");
        return;
    }
    usleep(100000); // Wait for measurement to complete
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read data from BH1750");
        return;
    }
    int lux = (data[0] << 8) | data[1];
    if (lux > MAX_LUX) {
        lux = MAX_LUX;
    }
    buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    lux_average = (lux_average * (BUFFER_SIZE - 1) + lux) / BUFFER_SIZE;
    last_lux = lux;
}

static void update_led_frequency() {
    led_frequency = (last_lux + 1) * 0.5;
    if (led_frequency > 5) {
        led_frequency = 5;
    }
}

static void blink_led() {
    led_state = !led_state;
    if (ioctl(line_handle.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &gpiohandle_values) < 0) {
        perror("Failed to set GPIO line values");
    }
    usleep(led_frequency * 1000000 / 2);
    if (ioctl(line_handle.fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &gpiohandle_values) < 0) {
        perror("Failed to set GPIO line values");
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    init_i2c();
    init_gpio();
    while (1) {
        read_lux();
        update_led_frequency();
        blink_led();
        usleep(1000000); // Wait for 1 second
    }
    close(i2c_fd);
    close(gpio_fd);
    return 0;
}

