static struct gpiod_line *lines[GPIO_LINES];

void cleanup() {
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    printf("GPIO lines released and chip closed.\n");
}

int main() {
    // Initialize GPIO library
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Set lines as outputs
    for (int i = 0; i < GPIO_LINES; i++) {
        if (gpiod_line_request_output(lines[i], "74HC595", 0)) {
            perror("Failed to set GPIO line as output");
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    // Define the pattern for digit '5' (Q0, Q1, Q2, Q3, Q4, Q5, Q6, Q7)
    unsigned char pattern = 0b01000001; // a, b, c, d, e, f, g

    while (1) {
        // Shift out the pattern
        for (int i = 7; i >= 0; i--) {
            gpiod_line_set_value(lines[0], pattern & (1 << i));
            gpiod_line_set_value(lines[1], 1); // Clock high
            gpiod_line_set_value(lines[1], 0); // Clock low
        }
        gpiod_line_set_value(lines[2], 1); // Latch high
        gpiod_line_set_value(lines[2], 0); // Latch low

        // Wait for 500ms
        usleep(500000);

        // Shift out the pattern again to turn off the digit
        for (int i = 7; i >= 0; i--) {
            gpiod_line_set_value(lines[0], pattern & (1 << i));
            gpiod_line_set_value(lines[1], 1); // Clock high
            gpiod_line_set_value(lines[1], 0); // Clock low
        }
        gpiod_line_set_value(lines[2], 1); // Latch high
        gpiod_line_set_value(lines[2], 0); // Latch low

        // Wait for 500ms
        usleep(500000);
    }

    // Clean up on exit
    cleanup();
    return 0;
}

