#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define TIMEOUT_MS 1000

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    struct gpiod_line_request_config led_config, button_config;
    struct gpiod_event_consumer *consumer;
    struct gpiod_event event;
    struct timespec sleep_time = {1, 0}; // 1 second

    // Register signal handler for Ctrl-C
    signal(SIGINT, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request LED line as output initially set low
    led_config.consumer = "blink_button";
    led_config.offset = LED_PIN;
    led_config.flags = GPIOD_LINE_REQUEST_OUTPUT;
    led_config.default_value = 0;
    ret = gpiod_chip_request_line(chip, &led_config, &led_line);
    if (ret) {
        perror("Failed to request LED line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request button line as input with pull-up and event detection
    button_config.consumer = "blink_button";
    button_config.offset = BUTTON_PIN;
    button_config.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_PULL_UP | GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    ret = gpiod_chip_request_line(chip, &button_config, &button_line);
    if (ret) {
        perror("Failed to request button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
