#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_RED 24
#define GPIO_GREEN 23
#define GPIO_BLUE 18
#define PWM_PERIOD 100000000  // 100 Hz
#define PWM_DUTY_CYCLE_MAX 100000000  // 100% duty cycle

static int gpiod_chip = -1;
static int gpio_red_line = -1;
static int gpio_green_line = -1;
static int gpio_blue_line = -1;

static void signal_handler(int signum) {
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 1000000};  // 1 ms
    struct timespec remaining_time;
    int duty_cycle;
    int red, green, blue;

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    gpio_red_line = gpiod_chip_get_line(gpiod_chip, GPIO_RED);
    if (gpio_red_line == -1) {
        perror("Failed to get GPIO line for red");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    gpio_green_line = gpiod_chip_get_line(gpiod_chip, GPIO_GREEN);
    if (gpio_green_line == -1) {
        perror("Failed to get GPIO line for green");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    gpio_blue_line = gpiod_chip_get_line(gpiod_chip, GPIO_BLUE);
    if (gpio_blue_line == -1) {
        perror("Failed to get GPIO line for blue");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    // Request output mode
    if (gpiod_line_request_output(gpio_red_line, "red", 0) < 0) {
        perror("Failed to request output mode for red");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_green_line, "green", 0) < 0) {
        perror("Failed to request output mode for green");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_blue_line, "blue", 0) < 0) {
        perror("Failed to request output mode for blue");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    // Seed random number generator
    srand(time(NULL));

    while (1) {
        // Generate random duty cycle for each color
        red = rand() % PWM_DUTY_CYCLE_MAX;
        green = rand() % PWM_DUTY_CYCLE_MAX;
        blue = rand() % PWM_DUTY_CYCLE_MAX;

        // Set duty cycle for each color
        if (gpiod_line_set_value(gpio_red_line, red / (double)PWM_DUTY_CYCLE_MAX) < 0) {
            perror("Failed to set red duty cycle");
            break;
        }

        if (gpiod_line_set_value(gpio_green_line, green / (double)PWM_DUTY_CYCLE_MAX) < 0) {
            perror("Failed to set green duty cycle");
            break;
        }

        if (gpiod_line_set_value(gpio_blue_line, blue / (double)PWM_DUTY_CYCLE_MAX) < 0) {
            perror("Failed to set blue duty cycle");
            break;
        }

        // Busy-wait for 10 ms
        while (nanosleep(&sleep_time, &remaining_time) == -1 && errno == EINTR) {
            // Continue if interrupted by signal
        }
    }

    // Clean up
    gpiod_chip_close(gpiod_chip);

    return 0;
