        red = rand() % PWM_DUTY_CYCLE_MAX;
        green = rand() % PWM_DUTY_CYCLE_MAX;
        blue = rand() % PWM_DUTY_CYCLE_MAX;

        // Set duty cycle for each color
        if (gpiod_line_set_value(gpio_red_line, red / (double)PWM_DUTY_CYCLE_MAX) < 0) {
