#define ACCEL_ODR_200HZ 0x07

#define IMPACT_THRESHOLD 10.0
#define LOG_FILE "impact_log.txt"

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_handle = -1;
