    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(EXIT_SUCCESS);
}

static void init_i2c() {
    i2c_handle = i2c_open(I2C_BUS, FXOS8700CQ_ADDR, 0);
    if (i2c_handle == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line = gpiod_line_request_input(gpiod_chip, "impact_sensor", 0);
    if (gpiod_line == -1) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
}

static void check_who_am_i() {
    uint8_t who_am_i;
    if (i2c_read_byte_data(i2c_handle, WHO_AM_I_REG, &who_am_i) == -1) {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value (expected 0x2A, got 0x%02X)\n", who_am_i);
        exit(EXIT_FAILURE);
    }
}

