    if (i2c_write_byte_data(i2c_handle, CTRL_REG3, ctrl_reg3) == -1) {
        perror("Failed to configure CTRL_REG3");
        exit(EXIT_FAILURE);
    }
}

static void activate_sensor() {
    uint8_t ctrl_reg1 = ACCEL_RANGE_2G | ACCEL_ODR_200HZ | 0x01; // Activate the sensor
    if (i2c_write_byte_data(i2c_handle, CTRL_REG1, ctrl_reg1) == -1) {
        perror("Failed to activate sensor");
        exit(EXIT_FAILURE);
    }
}

static void read_acceleration() {
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;
    if (i2c_read_byte_data(i2c_handle, OUT_X_MSB_REG, &x_msb) == -1) {
        fprintf(stderr, "Failed to read X MSB\n");
        return;
    }
    if (i2c_read_byte_data(i2c_handle, OUT_X_LSB_REG, &x_lsb) == -1) {
        fprintf(stderr, "Failed to read X LSB\n");
        return;
    }
    if (i2c_read_byte_data(i2c_handle, OUT_Y_MSB_REG, &y_msb) == -1) {
        fprintf(stderr, "Failed to read Y MSB\n");
        return;
    }
    if (i2c_read_byte_data(i2c_handle, OUT_Y_LSB_REG, &y_lsb) == -1) {
        fprintf(stderr, "Failed to read Y LSB\n");
        return;
    }
    if (i2c_read_byte_data(i2c_handle, OUT_Z_MSB_REG, &z_msb) == -1) {
        fprintf(stderr, "Failed to read Z MSB\n");
        return;
    }
    if (i2c_read_byte_data(i2c_handle, OUT_Z_LSB_REG, &z_lsb) == -1) {
        fprintf(stderr, "Failed to read Z LSB\n");
        return;
    }

    int16_t x = (x_msb << 8) | x_lsb;
    int16_t y = (y_msb << 8) | y_lsb;
    int16_t z = (z_msb << 8) | z_lsb;

    double magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > IMPACT_THRESHOLD) {
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }

        fprintf(log_file, "%s,%d,%d,%d,%f\n", timestamp, x, y, z, magnitude);
        fclose(log_file);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    init_gpio();
    init_i2c();
    check_who_am_i();
    configure_sensor();
    activate_sensor();

    while (1) {
        read_acceleration();
        usleep(50000); // 50 ms interval
    }

    return 0;
}

