    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];
    double g = 16384.0;
    double x_g = x / g;
    double y_g = y / g;
    double z_g = z / g;
    write_log(x_g, y_g, z_g);
    if (fabs(x_g) > MAX_ACCEL || fabs(y_g) > MAX_ACCEL || fabs(z_g) > MAX_ACCEL) {
        gpiod_line_set_value(line, 1);
    } else {
        gpiod_line_set_value(line, 0);
    }
}

