    signal(SIGTERM, sig_handler);

    init_i2c();
    init_led();
    init_log();

    uint8_t id = 0x00;
    if (write(i2c_fd, &id, 1) != 1) {
        perror("Failed to write to I2C");
        exit(1);
    }
    if (read(i2c_fd, &id, 1) != 1) {
        perror("Failed to read from I2C");
        exit(1);
    }
    if (id != 0xE5) {
        fprintf(stderr, "Device ID mismatch, expected 0xE5, got 0x%02X\n", id);
        exit(1);
    }

    uint8_t config = 0x08; // Full resolution, ±2g range
    if (write(i2c_fd, &config, 1) != 1) {
        perror("Failed to write to I2C");
        exit(1);
    }

    struct timespec sleep_time = {0, 10000000}; // 100 ms
    for (int i = 0; i < MAX_SAMPLES; i++) {
        read_accel();
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    close(i2c_fd);
    close(led_fd);
    gpiod_chip_close(chip);
    gpiod_line_release(line);

    return 0;
}

