        perror("Failed to write CTRL_REG3");
        exit(EXIT_FAILURE);
    }
    data[0] = LSM303DLHC_CTRL_REG4;
    data[1] = 0x00; // Enable all axes
    if (ioctl(i2c_fd, I2C_RDWR, 2, data) < 0) {
        perror("Failed to write CTRL_REG4");
        exit(EXIT_FAILURE);
    }
    data[0] = LSM303DLHC_CTRL_REG5;
    data[1] = 0x00; // Enable all axes
    if (ioctl(i2c_fd, I2C_RDWR, 2, data) < 0) {
        perror("Failed to write CTRL_REG5");
        exit(EXIT_FAILURE);
    }
    data[0] = LSM303DLHC_CTRL_REG6;
    data[1] = 0x00; // Enable all axes
    if (ioctl(i2c_fd, I2C_RDWR, 2, data) < 0) {
        perror("Failed to write CTRL_REG6");
        exit(EXIT_FAILURE);
    }
}

