code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 16
#define STALL_TIME_US 40
#define SAMPLE_INTERVAL_MS 100
#define FILE_NAME "imu_data.csv"
#define HEADER_ROW "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z"

static volatile sig_atomic_t running = 1;
static int spi_fd;
static FILE *csv_file;

static void cleanup() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpiochip_close(gpiochip);
}

static void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct spi_ioc_transfer xfer[2];
    uint16_t command_word = 0x0000; // Command word for reading a register
    uint16_t register_address = 0x0000; // Register address to read
    uint16_t data;
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int ret;

    // Initialize GPIO
    struct gpiod_chip *gpiochip = gpiochip_open_by_name("gpiochip0");
    if (!gpiochip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiochip_close(gpiochip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiochip_close(gpiochip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        gpiochip_close(gpiochip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiochip_close(gpiochip);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(FILE_NAME, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        gpiochip_close(gpiochip);
        return EXIT_FAILURE;
    }

    // Write header row
    fprintf(csv_file, "%s\n", HEADER_ROW);

    // Install cleanup function
    atexit(cleanup);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Write command word
        xfer[0].tx_buf = (unsigned long)&command_word;
        xfer[0].rx_buf = NULL;
        xfer[0].len = sizeof(command_word);
        xfer[0].speed_hz = SPI_SPEED_HZ;
        xfer[0].delay_usecs = STALL_TIME_US;
        xfer[0].bits_per_word = SPI_BITS_PER_WORD;

        // Write register address
        xfer[1].tx_buf = (unsigned long)&register_address;
        xfer[1].rx_buf = NULL;
        xfer[1].len = sizeof(register_address);
        xfer[1].speed_hz = SPI_SPEED_HZ;
        xfer[1].delay_usecs = 0;
        xfer[1].bits_per_word = SPI_BITS_PER_WORD;

        // Read data
        xfer[2].tx_buf = NULL;
        xfer[2].rx_buf = (unsigned long)&data;
        xfer[2].len = sizeof(data);
        xfer[2].speed_hz = SPI_SPEED_HZ;
        xfer[2].delay_usecs = 0;
        xfer[2].bits_per_word = SPI_BITS_PER_WORD;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, xfer, 3);
        if (ret < 0) {
            perror("Failed to send SPI message");
            continue;
        }

        // Convert raw values to degrees/second and g
        float gyro_x = (float)data * 0.005;
        float gyro_y = (float)(data >> 8) * 0.005;
        float gyro_z = (float)(data >> 16) * 0.005;
        float accel_x = (float)(data >> 24) * 0.00025;
        float accel_y = (float)(data >> 32) * 0.00025;
        float accel_z = (float)(data >> 40) * 0.00025;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        ts.tv_nsec /= 1000000; // Convert nanoseconds to milliseconds

        // Log data to CSV file
        fprintf(csv_file, "%s,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Non-blocking delay
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Close CSV file
    fclose(csv_file);

    return EXIT_SUCCESS;
}

