    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the CS line as output
    ret = gpiod_line_request_output(cs_line, "ADIS16448", 0);
    if (ret) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(cs_line);
        exit(EXIT_FAILURE);
    }

