        gpiod_chip_close(chip);
        gpiod_line_release(cs_line);
        exit(EXIT_FAILURE);
    }

    // Set up SPI transfer
    tr[0].tx_buf = &reg_addr;
    tr[0].rx_buf = NULL;
    tr[0].len = 1;
    tr[0].speed_hz = spi_info.speed_hz;
