            perror("Failed to perform SPI transfer");
            close(spi_fd);
            gpiod_chip_close(chip);
            gpiod_line_release(cs_line);
            exit(EXIT_FAILURE);
        }

        // Set CS high
        ret = gpiod_line_set_value(cs_line, 1);
        if (ret) {
            perror("Failed to set CS high");
            close(spi_fd);
            gpiod_chip_close(chip);
            gpiod_line_release(cs_line);
            exit(EXIT_FAILURE);
        }

        // Log the data
        printf("Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n", data >> 8, data & 0xFF, data >> 8, data & 0xFF);
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", data >> 8, data & 0xFF, data >> 8, data & 0xFF);

        // Wait for 100 ms
        usleep(LOG_INTERVAL);
    }

    // Close SPI device and driver library chip
    close(spi_fd);
    gpiod_chip_close(chip);
    gpiod_line_release(cs_line);

    return 0;
