#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CE0 8
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_DELAY_USEC 40
#define SPI_READ_CMD 0x01
#define SPI_DUMMY_VALUE 0x0000
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025
#define NUM_READS 6
#define READ_INTERVAL_MS 100

static int spi_fd;
static int gpio_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_sigint(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    // Register signal handler for Ctrl-C
    signal(SIGINT, handle_sigint);

    // Initialize GPIO for CE0
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_CE0);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(line, "spi_ce0", 0);
    if (ret) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set CE0 high
    ret = gpiod_line_set_value(line, 1);
    if (ret) {
        perror("Failed to set CE0 high");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Read data from the ADIS16448
    while (1) {
        uint16_t data[NUM_READS];
        for (int i = 0; i < NUM_READS; i++) {
            // Send read command
            uint16_t cmd = SPI_READ_CMD | (i << 1);
            ret = write(spi_fd, &cmd, sizeof(cmd));
            if (ret != sizeof(cmd)) {
                perror("Failed to write to SPI");
                close(spi_fd);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }

            // Stall for 40 microseconds
            usleep(SPI_DELAY_USEC);

            // Send dummy value
            ret = write(spi_fd, &SPI_DUMMY_VALUE, sizeof(SPI_DUMMY_VALUE));
            if (ret != sizeof(SPI_DUMMY_VALUE)) {
                perror("Failed to write to SPI");
                close(spi_fd);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }

            // Read the 16-bit data
            ret = read(spi_fd, &data[i], sizeof(data[i]));
            if (ret != sizeof(data[i])) {
                perror("Failed to read from SPI");
                close(spi_fd);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
        }

        // Print the data
        printf("Gyro: x=%d, y=%d, z=%d\n", data[0], data[1], data[2]);
        printf("Accel: x=%d, y=%d, z=%d\n", data[3], data[4], data[5]);

        // Wait for 100 milliseconds
        usleep(READ_INTERVAL_MS * 1000);
    }

    // Close SPI and GPIO
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

