                exit(EXIT_FAILURE);
            }

            // Read the 16-bit data
            ret = read(spi_fd, &data[i], sizeof(data[i]));
            if (ret != sizeof(data[i])) {
                perror("Failed to read from SPI");
                close(spi_fd);
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
        }

        // Print the data
        printf("Gyro: x=%d, y=%d, z=%d\n", data[0], data[1], data[2]);
        printf("Accel: x=%d, y=%d, z=%d\n", data[3], data[4], data[5]);

        // Wait for 100 milliseconds
        usleep(READ_INTERVAL_MS * 1000);
    }

    // Close SPI and GPIO
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}
```

### Explanation:

1. **GPIO Initialization**: The program initializes the GPIO pin for CE0 using `libgpiod`. This pin is used to control the SPI chip select.

2. **SPI Initialization**: The program opens the SPI device `/dev/spidev0.0` and sets the SPI mode and speed. It also sets CE0 high to enable the SPI communication.

3. **Data Reading**: The program reads data from the ADIS16448 IMU in a loop. It sends a read command followed by a dummy value to read the 16-bit data. The data is scaled using the appropriate scales for the gyroscope and accelerometer.

4. **Error Handling**: The program includes error handling for all critical operations such as opening files, setting GPIO lines, and SPI transfers. It also handles the `SIGINT` signal to cleanly close the SPI handle and release resources.

5. **Output**: The program prints the gyroscope and accelerometer data to the console every 100 milliseconds.

This program should be compiled and run on a Raspberry Pi 4 Model B with the necessary libraries installed. Make sure to install `libgpiod` and `libspidev` using your package manager.

