static void release_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (led_fd >= 0) {
        gpio_close(led_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static int read_register(int reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("write");
        return -1;
    }
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("read");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

static int write_register(int reg, int value) {
    uint8_t buffer[3];
    buffer[0] = reg;
    buffer[1] = value >> 8;
    buffer[2] = value & 0xFF;
    if (write(i2c_fd, buffer, 3) != 3) {
        perror("write");
        return -1;
    }
    return 0;
}

static int check_device_id() {
    int id = read_register(0x0D);
    if (id != 0xE5) {
        fprintf(stderr, "Device ID mismatch, expected 0xE5, got 0x%02X\n", id);
        return -1;
    }
    return 0;
}

