    if (gpiochip_open(0) < 0) {
        perror("gpiochip_open");
        return EXIT_FAILURE;
    }
    led_fd = gpio_export(LED_GPIO, GPIO_OUTPUT);
    if (led_fd < 0) {
        perror("gpio_export");
        gpiochip_close(0);
        return EXIT_FAILURE;
    }
    if (gpio_set_value(led_fd, 0) < 0) {
        perror("gpio_set_value");
        gpio_unexport(led_fd);
        gpiochip_close(0);
        return EXIT_FAILURE;
    }
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        gpio_unexport(led_fd);
        gpiochip_close(0);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpio_unexport(led_fd);
        gpiochip_close(0);
        return EXIT_FAILURE;
    }
    if (check_device_id() < 0) {
        close(i2c_fd);
        gpio_unexport(led_fd);
        gpiochip_close(0);
        return EXIT_FAILURE;
    }
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        gpio_unexport(led_fd);
        gpiochip_close(0);
        return EXIT_FAILURE;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    while (running) {
        int magnitude = read_acceleration();
        if (magnitude > THRESHOLD) {
            gpio_set_value(led_fd, 1);
            log_impact(read_register(0x32), read_register(0x34), read_register(0x36), magnitude);
            usleep(500000);
            gpio_set_value(led_fd, 0);
        }
        usleep(10000);
    }
    release_resources();
    return EXIT_SUCCESS;
}

