#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libmraa.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1C
#define ACCEL_XOUT_H 0x01
#define ACCEL_XOUT_L 0x02
#define ACCEL_YOUT_H 0x03
#define ACCEL_YOUT_L 0x04
#define ACCEL_ZOUT_H 0x05
#define ACCEL_ZOUT_L 0x06
#define WHO_AM_I 0x0D
#define ACCEL_RANGE 0x0E
#define ACCEL_RANGE_2G 0x00
#define ACCEL_RANGE_4G 0x01
#define ACCEL_RANGE_8G 0x02
#define ACCEL_RANGE_16G 0x03
#define LED_PIN 17

static int i2c_fd;
static int led_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

void init_i2c() {
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void init_led() {
    led_fd = gpio_export(LED_PIN, GPIO_OUTPUT);
    if (led_fd < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", LED_PIN);
        exit(EXIT_FAILURE);
    }
}

void close_i2c() {
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
    }
}

void close_led() {
    if (led_fd >= 0) {
        gpio_unexport(LED_PIN);
    }
}

void close_log() {
    if (log_file) {
        fclose(log_file);
    }
}

void log_reading(int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
}

void read_accelerometer() {
    uint8_t data[6];
    if (i2c_read(i2c_fd, WHO_AM_I, data, 1) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return;
    }
    if (data[0] != 0x1A) {
        fprintf(stderr, "Incorrect WHO_AM_I value\n");
        return;
    }

    if (i2c_read(i2c_fd, ACCEL_RANGE, data, 1) != 1) {
        fprintf(stderr, "Failed to read ACCEL_RANGE register\n");
        return;
    }
    if (data[0] != ACCEL_RANGE_2G) {
        fprintf(stderr, "Incorrect ACCEL_RANGE value\n");
        return;
    }

    if (i2c_read(i2c_fd, ACCEL_XOUT_H, data, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return;
    }

    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    int z = (data[4] << 8) | data[5];

    log_reading(x, y, z);

    if (abs(x) > 1024 * 2 || abs(y) > 1024 * 2 || abs(z) > 1024 * 2) {
        gpio_set_value(led_fd, 1);
        usleep(500000);
        gpio_set_value(led_fd, 0);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_led();
    log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close_i2c();
        close_led();
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        read_accelerometer();
        usleep(100000);
    }

    close_log();
    close_led();
    close_i2c();

    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data msgset[1];

    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    msgset[0].msgs = msgs;
    msgset[0].nmsgs = 1;

    if (ioctl(fd, I2C_RDWR, msgset) < 0) {
        return -1;
    }

    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = I2C_M_RD;
    msgs[0].len = len;
    msgs[0].buf = data;

    if (ioctl(fd, I2C_RDWR, msgset) < 0) {
        return -1;
    }

    return 0;
}

