#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define INT1_PIN 17
#define LOG_FILE "freefall_log.csv"
#define HEADER "YYYY-MM-DD HH:MM:SS.mmm,X,Y,Z\n"

static int i2c_fd;
static int gpio_fd;
static int event_fd;
static int log_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct timespec ts;
static struct tm *tm;
static char timestamp[20];

void handle_sigint(int signum) {
    close(i2c_fd);
    close(gpio_fd);
    close(event_fd);
    close(log_fd);
    gpiod_chip_close(chip);
    printf("Interrupt received, exiting...\n");
    exit(0);
}

void write_log(const char *data) {
    if (log_fd == -1) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd == -1) {
            perror("Failed to open log file");
            exit(1);
        }
    }
    if (write(log_fd, data, strlen(data)) == -1) {
        perror("Failed to write to log file");
        exit(1);
    }
    fflush(log_fd);
}

void read_timestamp() {
    clock_gettime(CLOCK_REALTIME, &ts);
    tm = localtime(&ts.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", tm, &ts.tv_nsec / 1000000);
}

void read_device_id() {
    uint8_t id;
    if (i2c_smbus_read_byte_data(i2c_fd, 0x0D) == -1) {
        perror("Failed to read device ID");
        exit(1);
    }
    id = i2c_smbus_read_byte_data(i2c_fd, 0x0D);
    if (id != 0xE5) {
        fprintf(stderr, "Device ID mismatch, expected 0xE5, got 0x%02X\n", id);
        exit(1);
    }
}

void place_in_standby() {
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2D, 0x00) == -1) {
        perror("Failed to place in standby mode");
        exit(1);
    }
}

void read_acceleration() {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x32, 6, data) == -1) {
        perror("Failed to read acceleration data");
        exit(1);
    }
    read_timestamp();
    write_log(timestamp);
    write_log(",%d,%d,%d\n", data[0], data[1], data[2]);
}

void setup_gpio() {
