#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t exit_flag = 0;

static void sigint_handler(int signum) {
    exit_flag = 1;
}

static void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s – %s\n", timestamp, message);
    fclose(log_file);
}

static void cleanup() {
    if (exit_flag) {
        log_event("Program exited cleanly.");
    } else {
        log_event("Program terminated by signal.");
    }
    if (gpiod_chip_close(chip) < 0) {
        fprintf(stderr, "Failed to close GPIO chip\n");
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return EXIT_FAILURE;
    }

    gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_line *line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_config(line, NULL, GPIOD_LINE_CONFIG_PULL_UP, 0) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!exit_flag) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            log_event("Sensor read error");
        } else {
            char message[50];
            if (value == 0) {
                snprintf(message, sizeof(message), "Flame detected: YES");
                log_event(message);
                printf("FLAME DETECTED!\n");
            } else {
                snprintf(message, sizeof(message), "Flame detected: NO");
                log_event(message);
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    cleanup();

    return EXIT_SUCCESS;
}

