#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define SAMPLE_INTERVAL_MS 100
#define MAX_SAMPLES 10000
#define CSV_FILE "vibration_log.csv"

static int i2c_fd;
static FILE *csv_file;
static struct timespec last_sample_time;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    exit(0);
}

static void write_header() {
    fprintf(csv_file, "Timestamp,X,Y,Z\n");
}

static void write_sample(int x, int y, int z) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%fZ", gmtime(&now.tv_sec));
    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
}

static int read_sensor() {
    uint8_t data[6];
    int ret = read(i2c_fd, data, 6);
    if (ret != 6) {
        if (errno == EAGAIN) {
            return 0; // No data available
        }
        perror("read");
        return -1;
    }
    int x = (data[0] << 8) | data[1];
    int y = (data[2] << 8) | data[3];
    int z = (data[4] << 8) | data[5];
    return x;
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        exit(1);
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        exit(1);
    }

    if ((csv_file = fopen(CSV_FILE, "w")) == NULL) {
        perror("fopen");
        close(i2c_fd);
        exit(1);
    }

    write_header();

    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    last_sample_time = current_time;

    while (1) {
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);

        if (now.tv_sec - last_sample_time.tv_sec >= 1) {
            int x = read_sensor();
            if (x >= 0) {
                write_sample(x, 0, 0); // Assuming Y and Z are always 0 for simplicity
            }
            last_sample_time = now;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(csv_file);
    close(i2c_fd);

    return 0;
}

