#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "conveyor_log.txt"
#define LOG_INTERVAL_MS 50
#define MAX_LOG_ENTRIES 1000

static int gpio_chip;
static gpiod_line *hall_sensor1;
static gpiod_line *hall_sensor2;
static FILE *log_file;
static int log_entries = 0;
static volatile sig_atomic_t should_exit = 0;

static void signal_handler(int sig) {
    should_exit = 1;
}

static void log_state(int sensor, int state) {
    if (log_entries >= MAX_LOG_ENTRIES) {
        fclose(log_file);
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        log_entries = 0;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file, "%ld.%03ld,%d\n", (long)ts.tv_sec, (long)ts.tv_nsec / 1000000, state);
    log_entries++;
}

static void setup_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    hall_sensor1 = gpiod_chip_get_line(gpio_chip, GPIO17);
    if (hall_sensor1 == NULL) {
        perror("Failed to get GPIO line 17");
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    hall_sensor2 = gpiod_chip_get_line(gpio_chip, GPIO27);
    if (hall_sensor2 == NULL) {
        perror("Failed to get GPIO line 27");
        gpiod_line_release(hall_sensor1);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_BIAS_PULL_UP;
    int ret = gpiod_line_request_input(hall_sensor1, "hall_sensor1", flags);
    if (ret < 0) {
        perror("Failed to request GPIO line 17");
        gpiod_line_release(hall_sensor2);
        gpiod_line_release(hall_sensor1);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(hall_sensor2, "hall_sensor2", flags);
    if (ret < 0) {
        perror("Failed to request GPIO line 27");
        gpiod_line_release(hall_sensor1);
        gpiod_line_release(hall_sensor2);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }
}

static void setup_logging() {
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpiod_line_release(hall_sensor1);
    gpiod_line_release(hall_sensor2);
    gpiod_chip_close(gpio_chip);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_logging();

    while (!should_exit) {
        int state1 = gpiod_line_get_value(hall_sensor1);
        int state2 = gpiod_line_get_value(hall_sensor2);

        log_state(1, state1);
        log_state(2, state2);

        if (state1 == 1 && state2 == 1) {
            printf("Halt message: Both sensors read logic 1\n");
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

