#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define DATA_X_MSB 0x01
#define DATA_X_LSB 0x02
#define DATA_Y_MSB 0x03
#define DATA_Y_LSB 0x04
#define DATA_Z_MSB 0x05
#define DATA_Z_LSB 0x06
#define DATA_RATE_100HZ 0x0A

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set up I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    ret = read(i2c_fd, &who_am_i, 1);
    if (ret < 0) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", who_am_i);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize the device
    uint8_t ctrl_reg1 = 0x00; // Standby mode
    ret = write(i2c_fd, &ctrl_reg1, 1);
    if (ret < 0) {
        perror("Failed to write CTRL_REG1");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ctrl_reg1 = DATA_RATE_100HZ | 0x01; // Active mode
    ret = write(i2c_fd, &ctrl_reg1, 1);
    if (ret < 0) {
        perror("Failed to write CTRL_REG1");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct timespec sleep_time = {0, 10000000}; // 10 ms

    while (!should_exit) {
        // Read data registers in a single block
        uint8_t data[6];
        ret = read(i2c_fd, data, 6);
        if (ret < 0) {
            perror("Failed to read data registers");
            continue;
        }

        // Combine MSB and LSB to get signed 12-bit raw values
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Compute absolute tilt
        double tilt = atan2(sqrt(x * x + y * y), z) * 180.0 / M_PI;

        // Check for tilt exceeding 45 degrees
        if (tilt > 45.0 || tilt < -45.0) {
            // Get current timestamp
            time_t now;
            time(&now);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            // Append to log file
            fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
            fflush(log_file);
        }

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

