#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define MAGNETOMETER_REG_XOUT_L 0x28
#define MAGNETOMETER_REG_XOUT_H 0x29
#define MAGNETOMETER_REG_YOUT_L 0x2A
#define MAGNETOMETER_REG_YOUT_H 0x2B
#define MAGNETOMETER_REG_ZOUT_L 0x2C
#define MAGNETOMETER_REG_ZOUT_H 0x2D
#define MAGNETOMETER_REG_CTRL_REG1 0x20
#define MAGNETOMETER_REG_CTRL_REG2 0x21
#define MAGNETOMETER_REG_CTRL_REG3 0x22
#define MAGNETOMETER_REG_CTRL_REG4 0x23
#define MAGNETOMETER_REG_CTRL_REG5 0x24
#define MAGNETOMETER_REG_STATUS_REG 0x27
#define MAGNETOMETER_REG_OUT_X_L 0x28
#define MAGNETOMETER_REG_OUT_X_H 0x29
#define MAGNETOMETER_REG_OUT_Y_L 0x2A
#define MAGNETOMETER_REG_OUT_Y_H 0x2B
#define MAGNETOMETER_REG_OUT_Z_L 0x2C
#define MAGNETOMETER_REG_OUT_Z_H 0x2D
#define MAGNETOMETER_REG_INT1_CFG 0x30
#define MAGNETOMETER_REG_INT1_SRC 0x31
#define MAGNETOMETER_REG_INT1_THS_XH 0x32
#define MAGNETOMETER_REG_INT1_THS_XL 0x33
#define MAGNETOMETER_REG_INT1_THS_YH 0x34
#define MAGNETOMETER_REG_INT1_THS_YL 0x35
#define MAGNETOMETER_REG_INT1_THS_ZH 0x36
#define MAGNETOMETER_REG_INT1_THS_ZL 0x37
#define MAGNETOMETER_REG_INT1_DURATION 0x38
#define MAGNETOMETER_REG_INT2_CFG 0x39
#define MAGNETOMETER_REG_INT2_SRC 0x3A
#define MAGNETOMETER_REG_INT2_THS_XH 0x3B
#define MAGNETOMETER_REG_INT2_THS_XL 0x3C
#define MAGNETOMETER_REG_INT2_THS_YH 0x3D
#define MAGNETOMETER_REG_INT2_THS_YL 0x3E
#define MAGNETOMETER_REG_INT2_THS_ZH 0x3F
#define MAGNETOMETER_REG_INT2_THS_ZL 0x40
#define MAGNETOMETER_REG_INT2_DURATION 0x41
#define MAGNETOMETER_REG_FIFO_CTRL 0x3C
#define MAGNETOMETER_REG_FIFO_SRC 0x3D
#define MAGNETOMETER_REG_FIFO_THS 0x3E
#define MAGNETOMETER_REG_FIFO_MODE 0x3F
#define MAGNETOMETER_REG_OFFSET_X_L 0x63
#define MAGNETOMETER_REG_OFFSET_X_H 0x64
#define MAGNETOMETER_REG_OFFSET_Y_L 0x65
#define MAGNETOMETER_REG_OFFSET_Y_H 0x66
#define MAGNETOMETER_REG_OFFSET_Z_L 0x67
#define MAGNETOMETER_REG_OFFSET_Z_H 0x68
#define MAGNETOMETER_REG_SCALE 0x69
#define MAGNETOMETER_REG_MODE 0x6A
#define MAGNETOMETER_REG_SOFT_RESET 0x7F

#define CALIBRATION_OFFSET_X 0x00
#define CALIBRATION_OFFSET_Y 0x00
#define CALIBRATION_OFFSET_Z 0x00
#define CALIBRATION_SCALE 0x00

#define MAX_RETRIES 3
#define LOG_FILE "magnetic_log.txt"
#define ALERT_THRESHOLD 800

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t should_exit = 0;

static void handle_signal(int sig) {
    should_exit = 1;
}

static void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

static int read_magnetometer(int reg) {
    uint8_t buffer[2];
    int ret;

    ret = write(i2c_fd, &reg, 1);
    if (ret != 1) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("read");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

static void write_magnetometer(int reg, int value) {
    uint8_t buffer[3];
    int ret;

    buffer[0] = reg;
    buffer[1] = value >> 8;
    buffer[2] = value & 0xFF;

    ret = write(i2c_fd, buffer, 3);
    if (ret != 3) {
        perror("write");
        return;
    }
}

static void initialize_magnetometer() {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = write_magnetometer(MAGNETOMETER_REG_SOFT_RESET, 0x01);
        if (ret == -1) {
            retries++;
            continue;
        }

        usleep(100000); // Wait for reset to complete

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG1, 0x07); // 10 Hz, 8 Hz ODR, 100 Hz LPF
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG2, 0x00); // Normal mode
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG3, 0x00); // No interrupts
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG4, 0x00); // No interrupts
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG5, 0x00); // No interrupts
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_X_L, CALIBRATION_OFFSET_X);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_X_H, CALIBRATION_OFFSET_X >> 8);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Y_L, CALIBRATION_OFFSET_Y);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Y_H, CALIBRATION_OFFSET_Y >> 8);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Z_L, CALIBRATION_OFFSET_Z);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Z_H, CALIBRATION_OFFSET_Z >> 8);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_SCALE, CALIBRATION_SCALE);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_MODE, 0x01); // Continuous mode
        if (ret == -1) {
            retries++;
            continue;
        }

        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        exit(EXIT_FAILURE);
    }
}

static void read_magnetic_data() {
    int x, y, z;
    double magnitude;
    char buffer[100];

    x = read_magnetometer(MAGNETOMETER_REG_OUT_X_L);
    y = read_magnetometer(MAGNETOMETER_REG_OUT_Y_L);
    z = read_magnetometer(MAGNETOMETER_REG_OUT_Z_L);

    x = (x << 8) | x;
    y = (y << 8) | y;
    z = (z << 8) | z;

    x -= CALIBRATION_OFFSET_X;
    y -= CALIBRATION_OFFSET_Y;
    z -= CALIBRATION_OFFSET_Z;

    magnitude = sqrt(x * x + y * y + z * z);

    snprintf(buffer, sizeof(buffer), "%d,%d,%d\n", x, y, z);
    fprintf(log_file, "%s", buffer);
    fflush(log_file);

    if (magnitude > ALERT_THRESHOLD) {
        fprintf(stderr, "Metal-detector alert: %d mG\n", (int)magnitude);
    }
}

int main() {
    int ret;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    initialize_magnetometer();

    while (!should_exit) {
        read_magnetic_data();
        usleep(100000); // 10 Hz
    }

    close_resources();
    return 0;
}

