            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG2, 0x00); // Normal mode
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG3, 0x00); // No interrupts
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG4, 0x00); // No interrupts
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_CTRL_REG5, 0x00); // No interrupts
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_X_L, CALIBRATION_OFFSET_X);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_X_H, CALIBRATION_OFFSET_X >> 8);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Y_L, CALIBRATION_OFFSET_Y);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Y_H, CALIBRATION_OFFSET_Y >> 8);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Z_L, CALIBRATION_OFFSET_Z);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_OFFSET_Z_H, CALIBRATION_OFFSET_Z >> 8);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_SCALE, CALIBRATION_SCALE);
        if (ret == -1) {
            retries++;
            continue;
        }

        ret = write_magnetometer(MAGNETOMETER_REG_MODE, 0x01); // Continuous mode
        if (ret == -1) {
            retries++;
            continue;
        }

        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        exit(EXIT_FAILURE);
    }
}

static void read_magnetic_data() {
    int x, y, z;
    double magnitude;
    char buffer[100];

    x = read_magnetometer(MAGNETOMETER_REG_OUT_X_L);
    y = read_magnetometer(MAGNETOMETER_REG_OUT_Y_L);
    z = read_magnetometer(MAGNETOMETER_REG_OUT_Z_L);

    x = (x << 8) | x;
    y = (y << 8) | y;
    z = (z << 8) | z;

    x -= CALIBRATION_OFFSET_X;
    y -= CALIBRATION_OFFSET_Y;
    z -= CALIBRATION_OFFSET_Z;

    magnitude = sqrt(x * x + y * y + z * z);

    snprintf(buffer, sizeof(buffer), "%d,%d,%d\n", x, y, z);
    fprintf(log_file, "%s", buffer);
    fflush(log_file);

    if (magnitude > ALERT_THRESHOLD) {
        fprintf(stderr, "Metal-detector alert: %d mG\n", (int)magnitude);
    }
}

int main() {
    int ret;
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret == -1) {
        perror("ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    initialize_magnetometer();

    while (!should_exit) {
        read_magnetic_data();
        usleep(100000); // 10 Hz
    }

    close_resources();
    return 0;
}
