#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USEC 0
#define SPI_MAX_RETRIES 10
#define SPI_TIMEOUT_USEC 1000000
#define CSV_FILE "imu_log.csv"
#define HEADER "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n"

static int spi_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t should_exit = 0;

static void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct spi_ioc_transfer xfer[2];
    uint8_t address = 0x00; // ADIS16362 address
    uint8_t dummy = 0x00;
    uint16_t data[6];
    struct timespec ts;
    char buffer[256];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize libgpiod
    ret = gpiod_chip_open_by_name("gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(-ret));
        return EXIT_FAILURE;
    }

    // Initialize SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(-spi_fd));
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Set SPI mode, speed, and bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(-ret));
        close(spi_fd);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(-ret));
        close(spi_fd);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(-ret));
        close(spi_fd);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Write header to CSV file
    ret = fprintf(csv_file, HEADER);
    if (ret < 0) {
        fprintf(stderr, "Failed to write header to CSV file: %s\n", strerror(errno));
        fclose(csv_file);
        close(spi_fd);
        gpiod_chip_close(ret);
        return EXIT_FAILURE;
    }

    // Perform SPI transfers
    while (!should_exit) {
        // Send address byte with MSB set
        xfer[0].tx_buf = (unsigned long)&address;
        xfer[0].rx_buf = (unsigned long)&dummy;
        xfer[0].len = 1;
        xfer[0].delay_usecs = SPI_DELAY_USEC;
        xfer[0].speed_hz = SPI_SPEED_HZ;
        xfer[0].bits_per_word = SPI_BITS_PER_WORD;
        xfer[0].cs_change = 0;

        // Send dummy byte
        xfer[1].tx_buf = (unsigned long)&dummy;
        xfer[1].rx_buf = (unsigned long)&data[0];
        xfer[1].len = 2;
        xfer[1].delay_usecs = SPI_DELAY_USEC;
        xfer[1].speed_hz = SPI_SPEED_HZ;
        xfer[1].bits_per_word = SPI_BITS_PER_WORD;
        xfer[1].cs_change = 1;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, xfer, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to perform SPI transfer: %s\n", strerror(-ret));
            continue;
        }

        // Read data from ADIS16362
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, xfer, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to perform SPI transfer: %s\n", strerror(-ret));
            continue;
        }

        // Calculate timestamp
        ret = clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            continue;
        }

        // Format data as CSV
        snprintf(buffer, sizeof(buffer), "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                (long)ts.tv_sec, (long)ts.tv_nsec / 1000, data[0], data[1], data[2], data[3], data[4], data[5]);

        // Write data to CSV file
        ret = fprintf(csv_file, buffer);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to CSV file: %s\n", strerror(errno));
            continue;
        }

        // Insert 10 ms delay
        usleep(10000);
    }

    // Close CSV file
    fclose(csv_file);

    // Close SPI device
    close(spi_fd);

    // Cleanup libgpiod
    gpiod_chip_close(ret);

    return EXIT_SUCCESS;
}

