This C program initializes the Raspberry Pi Zero W to read gyroscope and accelerometer data from an ADIS16362 IMU over SPI channel 0 using CE0 on GPIO 8. It uses the `libgpiod` library for GPIO operations and the `pigpio` library for SPI communication. The program handles errors and gracefully exits on SIGINT. The data is logged to a CSV file with high-precision timestamps.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP 4
#define GPIO_LINE 17
#define DETECTION_THRESHOLD 30  // in cm

static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line for input
    ret = gpiod_line_request_input(line, "Self-parking sequence");
    if (ret) {
        perror("Failed to request GPIO line for input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up a timer to poll the line every second
    struct itimerval timer;
    timer.it_value.tv_sec = 1;
    timer.it_value.tv_usec = 0;
    timer.it_interval.tv_sec = 1;
    timer.it_interval.tv_usec = 0;
    if (setitimer(ITIMER_REAL, &timer, NULL) == -1) {
        perror("Failed to set timer");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read the line value
        int value;
        ret = gpiod_line_get_value(line, &value);
        if (ret) {
            perror("Failed to read GPIO line value");
            continue;
        }

        // Check if the sensor reports a LOW level
        if (value == 0) {
            // Log the start of the self-parking sequence
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            printf("%s: Self-parking sequence started\n", timestamp);

            // Simulate the self-parking routine
            sleep(5);  // Simulate 5 seconds of parking

            // Log the completion of the self-parking sequence
            printf("%s: Self-parking sequence completed\n", timestamp);
        }
    }

    // Clean up resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

