#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE1 17
#define GPIO_LINE2 27
#define POLL_INTERVAL_MS 100
#define MAX_LOG_LENGTH 256

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;
    char log_buffer[MAX_LOG_LENGTH];
    struct timespec sleep_time;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the lines
    line1 = gpiod_chip_get_line(chip, GPIO_LINE1);
    if (!line1) {
        perror("Failed to get line 1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE2);
    if (!line2) {
        perror("Failed to get line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the lines for input
    ret = gpiod_line_request_input(line1, "obstacle_sensor1");
    if (ret) {
        perror("Failed to request line 1 for input");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line2, "obstacle_sensor2");
    if (ret) {
        perror("Failed to request line 2 for input");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the line events
    ret = gpiod_line_event_config_set(line1, GPIOD_LINE_EVENT_RISING_EDGE | GPIOD_LINE_EVENT_FALLING_EDGE, 0);
    if (ret) {
        perror("Failed to set event config for line 1");
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_event_config_set(line2, GPIOD_LINE_EVENT_RISING_EDGE | GPIOD_LINE_EVENT_FALLING_EDGE, 0);
    if (ret) {
