    msgs[8].len = 1;
    msgs[8].buf = &FXOS8700_REG_CTRL_REG5;
    msgs[9].addr = I2C_ADDR;
    msgs[9].flags = 0;
    msgs[9].len = 1;
    msgs[9].buf = &0x00; // Set magnetometer data rate to 100Hz
    msgset.msgs = msgs;
