    ret = ioctl(i2c_fd, I2C_RDWR, &msgset);
    if (ret < 0) {
        perror("Failed to initialize sensor");
        gpiod_line_release(sda_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read data loop
    while (1) {
        msgs[0].addr = I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = &FXOS8700_REG_OUT_X_MSB;
        msgs[1].addr = I2C_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 12;
        msgs[1].buf = data;
        msgset.msgs = msgs;
        msgset.nmsgs = 2;
        ret = ioctl(i2c_fd, I2C_RDWR, &msgset);
        if (ret < 0) {
            perror("Failed to read data");
            continue;
        }

        // Extract raw X, Y, Z values for accelerometer
        int16_t ax = (data[0] << 8) | data[1];
        int16_t ay = (data[2] << 8) | data[3];
        int16_t az = (data[4] << 8) | data[5];

        // Extract raw X, Y, Z values for magnetometer
        int16_t mx = (data[6] << 8) | data[7];
        int16_t my = (data[8] << 8) | data[9];
        int16_t mz = (data[10] << 8) | data[11];

        // Print raw values
        printf("Accelerometer: X=%d, Y=%d, Z=%d\n", ax, ay, az);
        printf("Magnetometer: X=%d, Y=%d, Z=%d\n", mx, my, mz);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(sda_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

