#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_MS 100

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpiod_line != -1) {
        gpiod_line_close(gpiod_line);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(signum);
}

int main() {
    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        gpioTerminate();
        return 1;
    }
    gpiod_line = gpiod_line_request_by_offset(gpiod_chip, 0, "tilt_sensor");
    if (gpiod_line == -1) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(gpiod_chip);
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_handle);
        gpiod_line_close(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};
    while (1) {
        // Read acceleration data from ADXL345
        uint8_t data[6];
        if (i2cReadData(i2c_handle, 0x32, data, 6) != 6) {
            fprintf(stderr, "Failed to read data from ADXL345\n");
            continue;
        }

        // Calculate tilt angle
        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];
        float tilt_angle = atan2(sqrt(x * x + y * y), z) * 180.0 / M_PI;

        // Check if tilt exceeds threshold
        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            // Get current timestamp
            time_t now;
            struct tm *tm_info;
            time(&now);
            tm_info = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

            // Log tilt event
            fprintf(log_file, "%s: Tilt angle exceeded %f degrees\n", timestamp, tilt_angle);
            fflush(log_file);
        }

        // Sleep for the next sample interval
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    i2c_close(i2c_handle);
    gpiod_line_close(gpiod_line);
    gpiod_chip_close(gpiod_chip);
    gpioTerminate();

    return 0;
}

