#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define WINDOW_DURATION 5000
#define SAMPLE_INTERVAL 1000
#define MAX_SAMPLES (WINDOW_DURATION / SAMPLE_INTERVAL)

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main(int argc, char *argv[]) {
    struct timespec start_time, end_time;
    struct timespec sleep_time;
    int threshold, high_count = 0;
    int gpio_fd;
    gpiod_chip *chip;
    gpiod_line *line;
    int ret;

    // Check for threshold argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Parse threshold argument
    threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Threshold must be a positive integer.\n");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line.\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "sound_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as input.\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        // Start timing
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Read GPIO line
        while (clock_gettime(CLOCK_MONOTONIC, &end_time) == 0 && (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec) < WINDOW_DURATION) {
            if (gpiod_line_get_value(line) == 1) {
                high_count++;
            }
            usleep(SAMPLE_INTERVAL);
        }

        // Print result
        if (high_count >= threshold) {
            fprintf(stdout, "%ld: ALERT\n", (long)start_time.tv_sec * 1000000 + start_time.tv_nsec / 1000);
        } else {
            fprintf(stdout, "%ld: OK\n", (long)start_time.tv_sec * 1000000 + start_time.tv_nsec / 1000);
        }

        // Reset high count
        high_count = 0;

        // Sleep for 1 second
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

