#include <gpiod.h>

#define GPIO_A 17
#define GPIO_B 27
#define LOG_FILE "access_log.txt"
#define MAX_CODE_LENGTH 7

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int signum) {
    exit_flag = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 500000000}; // 5 seconds
    FILE *log_file;
    char code[MAX_CODE_LENGTH];
    char input[MAX_CODE_LENGTH];
    char timestamp[20];
    struct tm *tm_info;

    // Initialize GPIO
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip = gpiod_chip_open(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_a = gpiod_chip_get_line(chip, GPIO_A);
    if (!line_a) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_A);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (!line_b) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_B);
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_a, "Door A", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_A);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_b, "Door B", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_B);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial state to keep doors locked
    gpiod_line_set_value(line_a, 0);
    gpiod_line_set_value(line_b, 0);

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        // Generate random code
        srand(time(NULL));
        snprintf(code, MAX_CODE_LENGTH, "%06d", rand() % 900000 + 100000);

        // Print code and read input
        printf("Security code: %s\n", code);
        fgets(input, MAX_CODE_LENGTH, stdin);

        // Clear input buffer if non-numeric
        if (sscanf(input, "%6d", (int *)&input[0]) != 1) {
            fprintf(stderr, "Invalid input. Please enter a six-digit number.\n");
            continue;
        }

        // Compare input with generated code
        if (strcmp(code, input) == 0) {
            // Log access
            time_t now = time(NULL);
            tm_info = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            fprintf(log_file, "%s,%s\n", timestamp, code);

            // Unlock doors
            gpiod_line_set_value(line_a, 1);
            gpiod_line_set_value(line_b, 1);

            // Sleep for 5 seconds
            nanosleep(&sleep_time, NULL);

            // Lock doors
            gpiod_line_set_value(line_a, 0);
            gpiod_line_set_value(line_b, 0);
        } else {
            // Access denied
            printf("Access denied\n");
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

