void stop_tone() {
    gpioPWMWrite(pwm_handle, 0);
}

int main() {
    int ret;
    struct sigaction sa;
    char buffer[MAX_MESSAGE_LENGTH];
    struct sockaddr_in server_addr;
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    float frequency;

    // Initialize GPIO
    ret = gpioInitialise();
    if (ret < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    // Initialize PWM
    init_pwm();

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Initialize MPR121
    init_mpr121();

    // Initialize TCP server
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    ret = bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (ret < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    ret = listen(socket_fd, 5);
    if (ret < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    sa.sa_handler = handle_sigterm;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    printf("Theremin server started on port 12345\n");

    while (running) {
        ret = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
        if (ret < 0) {
            perror("accept");
            continue;
        }

        ret = read(ret, buffer, MAX_MESSAGE_LENGTH - 1);
        if (ret < 0) {
            perror("read");
            close(ret);
            continue;
        }
        buffer[ret] = '\0';

        if (strncmp(buffer, "MOTION_DETECTED:", 15) == 0) {
            char *key = buffer + 15;
            if (strcmp(key, SECRET_KEY) == 0) {
                printf("Motion detected, playing tone\n");

                // Read touch values
                for (int i = 0; i < 12; i++) {
                    uint8_t data[2];
                    data[0] = 0x00 + i;
                    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 2, data);
                    if (ret < 0) {
                        perror("i2c_smbus_read_i2c_block_data");
                        close(ret);
                        continue;
                    }

                    float touch_value = (data[0] << 8) | data[1];
                    frequency = 440.0 * pow(2.0, (touch_value - 4095.0) / 4096.0);
                    log_frequency(frequency);
                    play_tone(frequency);

                    usleep(SAMPLE_INTERVAL);
                }

                stop_tone();
            } else {
                printf("Invalid secret key\n");
            }
        } else {
            printf("Invalid message\n");
        }

        close(ret);
    }

    // Clean up
    stop_tone();
    gpioPWMWrite(pwm_handle, 0);
    gpioTerminate();
    close(i2c_fd);
    close(socket_fd);
    unlink(LOG_FILE);

    return 0;
}
