#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define SAMPLES 100
#define OFFSETS_SIZE 3

static int i2c_fd;
static int offsets[OFFSETS_SIZE];
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_offsets() {
    uint8_t cmd[2] = {0x03, 0x00};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to write to I2C");
        return;
    }
    if (read(i2c_fd, offsets, 6) != 6) {
        perror("Failed to read from I2C");
        return;
    }
}

void apply_offsets(int *data) {
    data[0] -= offsets[0];
    data[1] -= offsets[1];
    data[2] -= offsets[2];
}

void print_data(int *data) {
    printf("X: %d, Y: %d, Z: %d\n", data[0], data[1], data[2]);
}

void calculate_average(int *data) {
    static int sum[OFFSETS_SIZE] = {0};
    static int count = 0;

    for (int i = 0; i < OFFSETS_SIZE; i++) {
        sum[i] += data[i];
    }
    count++;

    if (count == SAMPLES) {
        for (int i = 0; i < OFFSETS_SIZE; i++) {
            offsets[i] = sum[i] / SAMPLES;
        }
        count = 0;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    init_i2c();
    read_offsets();
    calculate_average(offsets);

    while (!should_exit) {
        int data[3];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read from I2C");
            continue;
        }
        apply_offsets(data);
        calculate_average(data);
        print_data(data);
        usleep(500000);
    }

    close(i2c_fd);
    return 0;
}

