```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LSM303D_I2C_ADDR 0x19
#define LSM303D_ACCEL_XOUT_H 0x28
#define LSM303D_ACCEL_XOUT_L 0x29
#define LSM303D_ACCEL_YOUT_H 0x2A
#define LSM303D_ACCEL_YOUT_L 0x2B
#define LSM303D_ACCEL_ZOUT_H 0x2C
#define LSM303D_ACCEL_ZOUT_L 0x2D
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG2_A 0x21
#define LSM303D_CTRL_REG3_A 0x22
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_CTRL_REG5_A 0x24
#define LSM303D_CTRL_REG6_A 0x25
#define LSM303D_CTRL_REG7_A 0x26
#define LSM303D_CTRL_REG8_A 0x27
#define LSM303D_INT1_CFG 0x30
#define LSM303D_INT1_SRC 0x31
#define LSM303D_INT1_THS 0x32
#define LSM303D_INT1_DURATION 0x33
#define LSM303D_ACCEL_SENSITIVITY 0.061f

#define BUFFER_SIZE 64
#define SAMPLE_INTERVAL_MS 10

static int gpiod_chip_fd;
static int i2c_fd;
static int buffer_index = 0;
static int buffer[BUFFER_SIZE];
static struct timespec last_dump_time;
static int interrupt_enabled = 0;

static void handle_sigint(int signum) {
    if (interrupt_enabled) {
        // Disable the accelerometer
        uint8_t control_reg1 = 0x00;
        if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, LSM303D_I2C_ADDR, LSM303D_CTRL_REG1_A, control_reg1) < 0) {
            perror("Failed to disable accelerometer");
        }
    }
    close(i2c_fd);
    close(gpiod_chip_fd);
    exit(0);
}

static void read_accelerometer() {
    uint8_t data[6];
    if (ioctl(i2c_fd, I2C_SMBUS_READ_BLOCK_DATA, LSM303D_I2C_ADDR, LSM303D_ACCEL_XOUT_H, data, 6) < 0) {
        perror("Failed to read accelerometer data");
        return;
    }

    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];

    // Convert to mg
    x *= LSM303D_ACCEL_SENSITIVITY;
    y *= LSM303D_ACCEL_SENSITIVITY;
    z *= LSM303D_ACCEL_SENSITIVITY;

    // Store in buffer
    buffer[buffer_index] = x;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void check_device_identity() {
    uint8_t id;
    if (ioctl(i2c_fd, I2C_SMBUS_READ_BYTE_DATA, LSM303D_I2C_ADDR, 0x0F, &id) < 0) {
        perror("Failed to read device identity");
        exit(1);
    }

    if (id != 0x33) {
        fprintf(stderr, "Device identity register does not match expected value\n");
        exit(1);
    }
}

static void configure_interrupt() {
    uint8_t int1_cfg = 0x01; // Enable INT1 on ZOUT > INT1_THS
    uint8_t int1_ths = 0x04; // Threshold of 2000 mg
    uint8_t int1_duration = 0x00; // Immediate triggering

    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, LSM303D_I2C_ADDR, LSM303D_INT1_CFG, int1_cfg) < 0) {
        perror("Failed to configure INT1_CFG");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, LSM303D_I2C_ADDR, LSM303D_INT1_THS, int1_ths) < 0) {
        perror("Failed to configure INT1_THS");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, LSM303D_I2C_ADDR, LSM303D_INT1_DURATION, int1_duration) < 0) {
        perror("Failed to configure INT1_DURATION");
        exit(1);
    }
}

static void enable_interrupt() {
    uint8_t control_reg1 = 0x01; // Enable INT1
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, LSM303D_I2C_ADDR, LSM303D_CTRL_REG1_A, control_reg1) < 0) {
        perror("Failed to enable INT1");
        exit(1);
    }
    interrupt_enabled = 1;
}

static void disable_interrupt() {
    uint8_t control_reg1 = 0x00; // Disable INT1
    if (ioctl(i2c_fd, I2C_SMBUS_WRITE_BYTE_DATA, LSM303D_I2C_ADDR, LSM303D_CTRL_REG1_A, control_reg1) < 0) {
        perror("Failed to disable INT1");
        exit(1);
    }
    interrupt_enabled = 0;
}

static void dump_buffer() {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    if (now.tv_sec - last_dump_time.tv_sec > 1) {
        // Print timestamp
        printf("%ld.%09ld ", now.tv_sec, now.tv_nsec);

        // Print last 10 samples
        for (int i = 0; i < 10; i++) {
            printf("%d ", buffer[(buffer_index + BUFFER_SIZE - i - 1) % BUFFER_SIZE]);
        }
        printf("\n");

        last_dump_time = now;
    }
}

int main() {
    // Initialize GPIO
    gpiod_chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
