#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define DELAY_MS 500

static volatile sig_atomic_t should_exit = 0;

void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    struct timespec delay;

    // Initialize signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the lines
    line1 = gpiod_chip_get_line(chip, GPIO17);
    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line1 || !line2) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the lines for output
    ret = gpiod_line_request_output(line1, "solenoid1", 0);
    if (ret) {
        perror("Failed to request GPIO line 1");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line2, "solenoid2", 0);
    if (ret) {
        perror("Failed to request GPIO line 2");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set both lines LOW
    ret = gpiod_line_set_value(line1, 0);
    if (ret) {
        perror("Failed to set GPIO line 1 LOW");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_value(line2, 0);
    if (ret) {
        perror("Failed to set GPIO line 2 LOW");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Switch solenoid 1
        ret = gpiod_line_set_value(line1, 1);
        if (ret) {
            perror("Failed to set GPIO line 1 HIGH");
            break;
        }

        // Delay
        delay.tv_sec = DELAY_MS / 1000;
        delay.tv_nsec = (DELAY_MS % 1000) * 1000000;
        ret = nanosleep(&delay, NULL);
        if (ret) {
            perror("Failed to sleep");
            break;
        }

        // Switch solenoid 2
        ret = gpiod_line_set_value(line2, 1);
        if (ret) {
            perror("Failed to set GPIO line 2 HIGH");
            break;
        }

        // Delay
        ret = nanosleep(&delay, NULL);
        if (ret) {
            perror("Failed to sleep");
            break;
        }

        // Switch solenoid 1 back
        ret = gpiod_line_set_value(line1, 0);
        if (ret) {
            perror("Failed to set GPIO line 1 LOW");
            break;
        }

        // Delay
        ret = nanosleep(&delay, NULL);
        if (ret) {
            perror("Failed to sleep");
            break;
        }

        // Switch solenoid 2 back
        ret = gpiod_line_set_value(line2, 0);
        if (ret) {
            perror("Failed to set GPIO line 2 LOW");
            break;
        }

        // Delay
        ret = nanosleep(&delay, NULL);
        if (ret) {
            perror("Failed to sleep");
            break;
        }
    }

    // Clean up
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

