#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define EXPECTED_CODE "123456"
#define TIMEOUT 5000
#define BAUDRATE 9600
#define UART1 "/dev/serial0"
#define UART2 "/dev/serial1"
#define GPIO17 17
#define GPIO27 27

static int uart_fd1 = -1;
static int uart_fd2 = -1;
static struct gpiod_chip *chip;
static struct gpiod_line *line1;
static struct gpiod_line *line2;
static int lock_state = 0;

static void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        lock_state = 1;
        gpiod_line_set_value(chip, GPIO17, 0);
        gpiod_line_set_value(chip, GPIO27, 0);
        if (uart_fd1 != -1) {
            close(uart_fd1);
        }
        if (uart_fd2 != -1) {
            close(uart_fd2);
        }
        if (chip != NULL) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

static void init_uart(int fd, const char *port) {
    struct termios options;
    if (tcgetattr(fd, &options) != 0) {
        fprintf(stderr, "Failed to get termios options for %s: %s\n", port, strerror(errno));
        exit(EXIT_FAILURE);
    }
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag |= CREAD;
    options.c_cflag |= CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    if (tcsetattr(fd, TCSANOW, &options) != 0) {
        fprintf(stderr, "Failed to set termios options for %s: %s\n", port, strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (fcntl(fd, F_SETFL, O_NONBLOCK) != 0) {
        fprintf(stderr, "Failed to set non-blocking mode for %s: %s\n", port, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (line1 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO17, strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line1, "lock1", 0) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO17, strerror(errno));
        exit(EXIT_FAILURE);
    }
    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO27, strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line2, "lock2", 0) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO27, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void unlock() {
    gpiod_line_set_value(chip, GPIO17, 1);
    gpiod_line_set_value(chip, GPIO27, 1);
    usleep(2000000);
    gpiod_line_set_value(chip, GPIO17, 0);
    gpiod_line_set_value(chip, GPIO27, 0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_uart(uart_fd1, UART1);
    init_uart(uart_fd2, UART2);

    char buffer1[7] = {0};
    char buffer2[7] = {0};
    int len1 = 0;
    int len2 = 0;

    while (!lock_state) {
        len1 = read(uart_fd1, buffer1 + len1, 1);
        if (len1 > 0 && buffer1[len1 - 1] == '\n') {
            buffer1[len1 - 1] = '\0';
            len1 = 0;
        }
        len2 = read(uart_fd2, buffer2 + len2, 1);
        if (len2 > 0 && buffer2[len2 - 1] == '\n') {
            buffer2[len2 - 1] = '\0';
            len2 = 0;
        }

        if (len1 > 0 && len2 > 0) {
            if (strcmp(buffer1, buffer2) == 0 && strcmp(buffer1, EXPECTED_CODE) == 0) {
                unlock();
            } else {
                fprintf(stderr, "Invalid or mismatched codes\n");
            }
        }

        usleep(100000);
    }

    gpiod_line_set_value(chip, GPIO17, 0);
    gpiod_line_set_value(chip, GPIO27, 0);
    if (uart_fd1 != -1) {
        close(uart_fd1);
    }
    if (uart_fd2 != -1) {
        close(uart_fd2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return 0;
}

