#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {18, 23, 24, 25}
#define INTERVALS {2, 3, 5, 7}

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static struct timespec start_time;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        printf("Program terminated.\n");
        exit(EXIT_SUCCESS);
    }
}

void toggle_relay(int pin, int interval) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000000 + (current_time.tv_nsec - start_time.tv_nsec);
    if (elapsed_time >= interval * 1000000000) {
        gpiod_line_set_value(lines[pin], !gpiod_line_get_value(lines[pin]));
        start_time = current_time;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "relay", 0)) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    start_time = (struct timespec){0, 0};
    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            toggle_relay(i, INTERVALS[i]);
        }
        sleep(1); // Ensure the main loop doesn't run too fast
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

