    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "relay", 0)) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    start_time = (struct timespec){0, 0};
    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            toggle_relay(i, INTERVALS[i]);
        }
        sleep(1); // Ensure the main loop doesn't run too fast
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
