#include <the.h> // Assuming the driver library is named 'the'

#define UART_DEVICE "/dev/serial0"
#define UART_BAUDRATE 9600
#define UART_TIMEOUT 1000 // Timeout in milliseconds
#define UART_BUFFER_SIZE 9
#define CHECKSUM_OFFSET 7
#define CHECKSUM_LENGTH 1
#define MAX_READ_ATTEMPTS 10
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

static int uart_fd = -1;
static int gpio_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *tx_line = NULL;
static struct gpiod_line *rx_line = NULL;

static void handle_sigint(int signum) {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (gpio_fd != -1) {
        gpiod_line_release(tx_line);
        gpiod_line_release(rx_line);
        gpiod_chip_close(chip);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (uart_fd != -1) {
        fclose(stderr);
    }
    if (uart_fd != -1) {
        fclose(stdout);
    }
    exit(EXIT_SUCCESS);
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(stderr, "%s: %s\n", timestamp, message);
    if (uart_fd != -1) {
        fclose(stderr);
    }
    if (uart_fd != -1) {
        fclose(stdout);
    }
    exit(EXIT_FAILURE);
}

static void log_reading(const char *timestamp, int ppm, int error) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
    }
    fprintf(log_file, "{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": %d}\n", timestamp, ppm, error);
    fclose(log_file);
    if (uart_fd != -1) {
        fclose(stderr);
    }
    if (uart_fd != -1) {
        fclose(stdout);
    }
}

static void log_error_reading(const char *timestamp, const char *message) {
    FILE *log_file = fopen(ERROR_LOG_FILE, "a");
    if (log_file == NULL) {
