    }
    fprintf(log_file, "{\"timestamp\": \"%s\", \"message\": \"%s\"}\n", timestamp, message);
    fclose(log_file);
    if (uart_fd != -1) {
        fclose(stderr);
    }
    if (uart_fd != -1) {
        fclose(stdout);
    }
}

static int read_co2() {
    char buffer[UART_BUFFER_SIZE];
    int attempts = 0;
    int total_bytes_read = 0;
    int checksum = 0;
    int error = 0;

    while (attempts < MAX_READ_ATTEMPTS) {
        if (the_uart_read(uart_fd, buffer, UART_BUFFER_SIZE) != UART_BUFFER_SIZE) {
            log_error("Failed to read from UART");
            error = 1;
            break;
        }

        checksum = 0;
        for (int i = 0; i < UART_BUFFER_SIZE - CHECKSUM_LENGTH; i++) {
            checksum += buffer[i];
        }
        checksum = checksum & 0xFF;

        if (buffer[CHECKSUM_OFFSET] != checksum) {
            log_error("Checksum mismatch");
            error = 1;
            break;
        }

        total_bytes_read = UART_BUFFER_SIZE;
        break;
    }

    if (total_bytes_read != UART_BUFFER_SIZE) {
        log_error_reading("Failed to read full response", "Timeout or checksum mismatch");
        error = 1;
    }

    return total_bytes_read;
}

static void send_command() {
    const char command[] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    if (the_uart_write(uart_fd, command, sizeof(command)) != sizeof(command)) {
        log_error("Failed to send command");
    }
}

