    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        log_error("Failed to set SIGINT handler");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        log_error("Failed to set SIGTERM handler");
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        log_error("Failed to open GPIO chip");
    }

    tx_line = gpiod_chip_get_line(chip, 14);
    if (tx_line == NULL) {
        log_error("Failed to get TXD line");
    }
    if (gpiod_line_request_output(tx_line, "TXD", 0) != 0) {
        log_error("Failed to request TXD line");
    }

    rx_line = gpiod_chip_get_line(chip, 15);
    if (rx_line == NULL) {
        log_error("Failed to get RXD line");
    }
    if (gpiod_line_request_input(rx_line, "RXD") != 0) {
        log_error("Failed to request RXD line");
    }

    uart_fd = the_uart_open(UART_DEVICE, UART_BAUDRATE);
    if (uart_fd == -1) {
        log_error("Failed to open UART");
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        send_command();
        usleep(100000); // Wait for 100ms

        int total_bytes_read = read_co2();
        if (total_bytes_read == UART_BUFFER_SIZE) {
            int ppm = (buffer[2] << 8) | buffer[3];
            log_reading(timestamp, ppm, 0);
            printf("{\"timestamp\": \"%s\", \"ppm\": %d, \"error\": 0}\n", timestamp, ppm);
        } else {
            log_error_reading(timestamp, "Failed to read CO2 concentration");
        }

        sleep(5); // Sample every 5 seconds
    }

    return 0;
}

