#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <gpiod.h>
#include <i2c-dev.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define GPIO_PIN 17

static int gpiod_chip_fd = -1;
static int gpiod_line_fd = -1;
static int i2c_fd = -1;
static int buffer_head = 0;
static int buffer_tail = 0;
static float buffer[BUFFER_SIZE];
static float target_heading = TARGET_HEADING;
static float deviation_threshold = DEVIATION_THRESHOLD;
static float x_offset = 100.0;
static float y_offset = -50.0;
static int running = 1;

static void handle_signal(int signum) {
    running = 0;
}

static void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(line, "heading_sensor", 0);
    gpiod_line_close(line);
    gpiod_chip_close(chip);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_magnetometer() {
    uint8_t data[6];
    int ret;

    ret = read(i2c_fd, data, 6);
    if (ret != 6) {
        perror("Failed to read from I2C device");
        return;
    }

    float x = (data[0] << 8) | data[1];
    float y = (data[2] << 8) | data[3];
    float z = (data[4] << 8) | data[5];

    x -= x_offset;
    y -= y_offset;

    float heading = atan2(y, x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }

    buffer[buffer_head] = heading;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

static void update_gpio() {
    float current_heading = buffer[buffer_tail];
    buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;

    float deviation = fabs(current_heading - target_heading);
    if (deviation > deviation_threshold) {
        gpiod_line_set_value(gpiod_line_fd, 1);
    } else {
        gpiod_line_set_value(gpiod_line_fd, 0);
    }
}

static void cleanup() {
    if (gpiod_line_fd >= 0) {
        gpiod_line_close(gpiod_line_fd);
    }
    if (gpiod_chip_fd >= 0) {
        gpiod_chip_close(gpiod_chip_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    init_gpio();
    init_i2c();

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        read_magnetometer();
        update_gpio();
        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

