#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define RED_RELAY 17
#define GREEN_RELAY 27
#define BLUE_RELAY 22
#define LOG_FILE "lighting_log.txt"
#define MAX_LUX 300
#define MIN_LUX 50
#define MAX_WAIT 120

int main() {
    int i2c_fd, gpio_fd;
    struct timespec sleep_time;
    struct tm *timeinfo;
    char log_entry[256];
    int lux;
    int red_state = 0, green_state = 0, blue_state = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize libgpiod
    gpio_fd = gpioOpen(RED_RELAY, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", RED_RELAY, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpio_fd = gpioOpen(GREEN_RELAY, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GREEN_RELAY, strerror(errno));
        gpioClose(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpio_fd = gpioOpen(BLUE_RELAY, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", BLUE_RELAY, strerror(errno));
        gpioClose(gpio_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioClose(gpio_fd);
        gpioClose(gpio_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up sleep time
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = MAX_WAIT * 1000000;

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_fd);
        gpioClose(gpio_fd);
        gpioClose(gpio_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Read lux from BH1750 sensor
        if (i2cWriteByte(i2c_fd, 0x10) < 0) {
            fprintf(stderr, "Failed to write to BH1750 sensor: %s\n", strerror(errno));
            break;
        }
        usleep(120000); // Wait for conversion

        if (i2cReadBytes(i2c_fd, 2, (unsigned char *)&lux) < 0) {
            fprintf(stderr, "Failed to read from BH1750 sensor: %s\n", strerror(errno));
            break;
        }

        // Convert raw data to lux
        lux = (lux << 8) | (lux >> 8);

        // Determine relay states based on lux value
        if (lux < MIN_LUX) {
            red_state = 1;
            green_state = 0;
            blue_state = 0;
        } else if (lux < MAX_LUX) {
            red_state = 0;
            green_state = 1;
            blue_state = 0;
        } else if (lux < MAX_LUX * 2) {
            red_state = 0;
            green_state = 0;
            blue_state = 1;
        } else {
            red_state = 1;
            green_state = 1;
            blue_state = 1;
        }

        // Set relay states
        gpioWrite(gpio_fd, RED_RELAY, red_state);
        gpioWrite(gpio_fd, GREEN_RELAY, green_state);
        gpioWrite(gpio_fd, BLUE_RELAY, blue_state);

        // Log the current timestamp, lux value, and relay states
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s, %d, %d, %d\n", log_entry, lux, red_state, green_state, blue_state);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Clean up resources
    i2cClose(i2c_fd);
    gpioClose(gpio_fd);
    gpioClose(gpio_fd);
    gpioClose(gpio_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

