#define MIN_DISTANCE 10
#define MAX_DISTANCE 100
#define MIN_SPEED 0
#define MAX_SPEED 255

static int gpiod_chip_fd = -1;
static int gpiod_line_fd1 = -1;
static int gpiod_line_fd2 = -1;
static int gpiod_line_fd3 = -1;
static int gpiod_line_fd4 = -1;
static int pwm_fd = -1;

static void cleanup(void) {
    if (pwm_fd != -1) {
        close(pwm_fd);
    }
    if (gpiod_line_fd1 != -1) {
        gpiod_line_release(gpiod_line_fd1);
    }
    if (gpiod_line_fd2 != -1) {
        gpiod_line_release(gpiod_line_fd2);
    }
    if (gpiod_line_fd3 != -1) {
        gpiod_line_release(gpiod_line_fd3);
    }
    if (gpiod_line_fd4 != -1) {
        gpiod_line_release(gpiod_line_fd4);
    }
    if (gpiod_chip_fd != -1) {
        gpiod_chip_close(gpiod_chip_fd);
    }
}

static void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_motor_a> <distance_motor_b>\n", argv[0]);
        return 1;
    }

    int distance_motor_a = atoi(argv[1]);
    int distance_motor_b = atoi(argv[2]);

    if (distance_motor_a < MIN_DISTANCE || distance_motor_a > MAX_DISTANCE ||
        distance_motor_b < MIN_DISTANCE || distance_motor_b > MAX_DISTANCE) {
        fprintf(stderr, "Distance must be between %d and %d cm\n", MIN_DISTANCE, MAX_DISTANCE);
        return 1;
    }

    // Initialize GPIO
    gpiod_chip_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip_fd == -1) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpiod_line_fd1 = gpiod_chip_get_line(gpiod_chip_fd, GPIO17);
    if (gpiod_line_fd1 == -1) {
        perror("Failed to get GPIO line 17");
        cleanup();
        return 1;
    }

    gpiod_line_fd2 = gpiod_chip_get_line(gpiod_chip_fd, GPIO18);
    if (gpiod_line_fd2 == -1) {
        perror("Failed to get GPIO line 18");
        cleanup();
        return 1;
    }

    gpiod_line_fd3 = gpiod_chip_get_line(gpiod_chip_fd, GPIO22);
    if (gpiod_line_fd3 == -1) {
        perror("Failed to get GPIO line 22");
        cleanup();
        return 1;
    }

    gpiod_line_fd4 = gpiod_chip_get_line(gpiod_chip_fd, GPIO23);
    if (gpiod_line_fd4 == -1) {
        perror("Failed to get GPIO line 23");
        cleanup();
        return 1;
    }

    int ret = gpiod_line_request_output(gpiod_line_fd1, "Motor A IN1", 0);
    if (ret != 0) {
        perror("Failed to request GPIO line 17 as output");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(gpiod_line_fd2, "Motor A IN2", 0);
    if (ret != 0) {
        perror("Failed to request GPIO line 18 as output");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(gpiod_line_fd3, "Motor B IN3", 0);
    if (ret != 0) {
        perror("Failed to request GPIO line 22 as output");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(gpiod_line_fd4, "Motor B IN4", 0);
    if (ret != 0) {
        perror("Failed to request GPIO line 23 as output");
