#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define STEPPER_PINS {17, 18, 27, 22}
#define LOCK_PIN 24
#define UNLOCK_PIN 23
#define STEPPER_STEPS 512
#define STEPPER_DELAY 2000000 // 2ms in microseconds
#define MAX_RETRIES 5

static int gpiod_ctx = -1;
static int lock_pressed = 0;
static int unlock_pressed = 0;

void handle_signal(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    exit(EXIT_SUCCESS);
}

void init_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 4; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(gpiod_ctx, STEPPER_PINS[i]);
        if (line == NULL) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }

        int ret = gpiod_line_request_input(line, "stepper");
        if (ret != 0) {
            perror("Failed to request GPIO line input");
            gpiod_line_release(line);
            gpiod_chip_close(gpiod_ctx);
            exit(EXIT_FAILURE);
        }
    }

    struct gpiod_line *lock_line = gpiod_chip_get_line(gpiod_ctx, LOCK_PIN);
    if (lock_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(lock_line, "lock");
    if (ret != 0) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(lock_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *unlock_line = gpiod_chip_get_line(gpiod_ctx, UNLOCK_PIN);
    if (unlock_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_line_release(lock_line);
        gpiod_line_release(unlock_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(unlock_line, "unlock");
    if (ret != 0) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(lock_line);
        gpiod_line_release(unlock_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

void deinit_gpio() {
    for (int i = 0; i < 4; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(gpiod_ctx, STEPPER_PINS[i]);
        if (line != NULL) {
            gpiod_line_release(line);
        }
    }

    struct gpiod_line *lock_line = gpiod_chip_get_line(gpiod_ctx, LOCK_PIN);
    if (lock_line != NULL) {
        gpiod_line_release(lock_line);
    }

    struct gpiod_line *unlock_line = gpiod_chip_get_line(gpiod_ctx, UNLOCK_PIN);
    if (unlock_line != NULL) {
        gpiod_line_release(unlock_line);
    }

    gpiod_chip_close(gpiod_ctx);
}

void step_motor(int steps, int direction) {
    for (int i = 0; i < steps; i++) {
        for (int j = 0; j < 4; j++) {
            struct gpiod_line *line = gpiod_chip_get_line(gpiod_ctx, STEPPER_PINS[j]);
            if (line != NULL) {
                int ret = gpiod_line_set_value(line, direction);
                if (ret != 0) {
                    perror("Failed to set GPIO line value");
                    deinit_gpio();
                    exit(EXIT_FAILURE);
                }
            }
        }
        usleep(STEPPER_DELAY);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();

    while (1) {
        if (gpiod_line_get_value(gpiod_chip_get_line(gpiod_ctx, LOCK_PIN)) == 0) {
            if (!lock_pressed) {
                lock_pressed = 1;
                printf("Lock pressed\n");
                step_motor(STEPPER_STEPS, 1); // Clockwise
            }
        } else {
            lock_pressed = 0;
        }

        if (gpiod_line_get_value(gpiod_chip_get_line(gpiod_ctx, UNLOCK_PIN)) == 0) {
            if (!unlock_pressed) {
                unlock_pressed = 1;
                printf("Unlock pressed\n");
                step_motor(STEPPER_STEPS, -1); // Counter-clockwise
            }
        } else {
            unlock_pressed = 0;
        }

        usleep(100000); // Check every 100ms
    }

    deinit_gpio();
    return 0;
}

