    struct tm *timeinfo;
    char timestamp[20];
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_fd, "%s,%f,%f,%d\n", timestamp, pitch, roll, position);
    fflush(log_fd);
