#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define GPIO_BASE 4
#define PWM_FREQUENCY 100
#define PWM_PERIOD 1000000 / PWM_FREQUENCY
#define FADE_TIME 1800000 // 30 minutes in microseconds

static int gpiod_ctx;
static int relays[NUM_RELAYS] = {4, 17, 27, 22};
static int current_time;
static int current_relay;
static int current_state;
static int next_time;
static int next_relay;
static int next_state;
static int schedule_fd;
static struct timespec sleep_time = {0, 1000000}; // 1 second

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpio_set_value(gpiod_ctx, relays[i], 0);
        }
        gpio_close(gpiod_ctx);
        close(schedule_fd);
        exit(0);
    }
}

static void setup_gpio() {
    gpiod_ctx = gpiochip_open(0);
    if (gpiod_ctx < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        int gpio = GPIO_BASE + i;
        if (gpio_export(gpio) < 0) {
            perror("Failed to export GPIO");
            gpio_close(gpiod_ctx);
            exit(1);
        }
        if (gpio_direction_output(gpio, 0) < 0) {
            perror("Failed to set GPIO direction");
            gpio_unexport(gpio);
            gpio_close(gpiod_ctx);
            exit(1);
        }
        if (gpio_set_pwm_frequency(gpio, PWM_FREQUENCY) < 0) {
            perror("Failed to set PWM frequency");
            gpio_unexport(gpio);
            gpio_close(gpiod_ctx);
            exit(1);
        }
        if (gpio_set_pwm_range(gpio, 100) < 0) {
            perror("Failed to set PWM range");
            gpio_unexport(gpio);
            gpio_close(gpiod_ctx);
            exit(1);
        }
    }
}

static void setup_schedule() {
    schedule_fd = open("lighting_schedule.txt", O_RDONLY);
    if (schedule_fd < 0) {
        perror("Failed to open schedule file");
        exit(1);
    }

    char line[256];
    while (fgets(line, sizeof(line), schedule_fd) != NULL) {
        char *time_str = strtok(line, ",");
        if (time_str == NULL) {
            continue;
        }

        struct tm tm;
        if (strptime(time_str, "%H:%M:%S", &tm) == NULL) {
            fprintf(stderr, "Invalid time format in schedule file: %s\n", time_str);
            continue;
        }

        int hour = tm.tm_hour;
        int minute = tm.tm_min;
        int second = tm.tm_sec;

        int relay = atoi(strtok(NULL, ","));
        if (relay < 0 || relay >= NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number in schedule file: %s\n", line);
            continue;
        }

        int state = atoi(strtok(NULL, ";"));
        if (state != 0 && state != 1) {
            fprintf(stderr, "Invalid state in schedule file: %s\n", line);
            continue;
        }

        if (current_time == 0) {
            current_time = hour * 3600 + minute * 60 + second;
            current_relay = relay;
            current_state = state;
        } else if (next_time == 0) {
            next_time = hour * 3600 + minute * 60 + second;
            next_relay = relay;
            next_state = state;
        } else {
            if (current_time > next_time) {
                current_time = hour * 3600 + minute * 60 + second;
                current_relay = relay;
                current_state = state;
            } else if (next_time > current_time) {
                next_time = hour * 3600 + minute * 60 + second;
                next_relay = relay;
                next_state = state;
            }
        }
    }

    if (next_time == 0) {
        fprintf(stderr, "No valid schedule entries found in file\n");
        exit(1);
    }
}

static void update_schedule() {
    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);

    int hour = tm.tm_hour;
    int minute = tm.tm_min;
    int second = tm.tm_sec;

    current_time = hour * 3600 + minute * 60 + second;

    if (current_time >= next_time) {
        current_relay = next_relay;
        current_state = next_state;
        next_time = 0;
        next_relay = 0;
        next_state = 0;
    }
}

static void fade(int relay, int start, int end) {
    int step = (end - start) / 100;
    for (int i = start; i <= end; i += step) {
        gpio_set_pwm_duty_cycle(gpiod_ctx, relays[relay], i);
        usleep(PWM_PERIOD);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_schedule();

    while (1) {
        update_schedule();

        if (current_relay != next_relay || current_state != next_state) {
            if (current_state == 1) {
                fade(current_relay, 0, 100);
            } else {
                fade(current_relay, 100, 0);
            }
            current_relay = next_relay;
            current_state = next_state;
        }

        nanosleep(&sleep_time, NULL);
    }

    gpio_close(gpiod_ctx);
    close(schedule_fd);
    return 0;
}

