#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MAX_DISTANCE 4000  // Maximum distance in mm
#define MIN_DISTANCE 10   // Minimum distance in mm
#define MIN_FREQUENCY 200  // Minimum frequency in Hz
#define MAX_FREQUENCY 20000 // Maximum frequency in Hz
#define LOOP_DELAY 20000  // Loop delay in microseconds
#define TIMEOUT 1000000  // Timeout in microseconds

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static int trigger_fd;
static int echo_fd;
static int buzzer_fd;
static int trigger_state;
static int echo_state;
static int trigger_pulse_width;
static int echo_pulse_width;
static int frequency;
static int loop_count;
static int running;

static void handle_sigint(int signum) {
    running = 0;
    gpio_set_value(buzzer_line, 0);
    gpiod_chip_close(chip);
    exit(0);
}

static void init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    trigger_fd = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (trigger_fd < 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_chip_close(chip);
        exit(1);
    }

    echo_fd = gpiod_line_request_input(echo_line, "echo");
    if (echo_fd < 0) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_fd);
        gpiod_chip_close(chip);
        exit(1);
    }

    buzzer_fd = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (buzzer_fd < 0) {
        fprintf(stderr, "Failed to request buzzer line\n");
        gpiod_line_release(trigger_fd);
        gpiod_line_release(echo_fd);
        gpiod_chip_close(chip);
        exit(1);
    }
}

static void deinit_gpio() {
    gpio_line_release(trigger_fd);
    gpio_line_release(echo_fd);
    gpio_line_release(buzzer_fd);
    gpiod_chip_close(chip);
}

static void trigger_sensor() {
    trigger_state = 1;
    gpio_set_value(trigger_line, trigger_state);
    usleep(trigger_pulse_width);
    trigger_state = 0;
    gpio_set_value(trigger_line, trigger_state);
}

static int read_echo() {
    struct timespec start, end;
    int echo_state = 0;
    int echo_pulse_width = 0;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (echo_state == 0) {
        echo_state = gpio_get_value(echo_line);
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            fprintf(stderr, "Failed to get echo time\n");
            return -1;
        }
        if (end.tv_nsec - start.tv_nsec < 0) {
            end.tv_sec--;
            end.tv_nsec += 1000000000;
        }
        echo_pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (echo_state == 1) {
        echo_state = gpio_get_value(echo_line);
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            fprintf(stderr, "Failed to get echo time\n");
            return -1;
        }
        if (end.tv_nsec - start.tv_nsec < 0) {
            end.tv_sec--;
            end.tv_nsec += 1000000000;
        }
        echo_pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    }

    return echo_pulse_width;
}

static int calculate_frequency(int echo_pulse_width) {
    int distance = echo_pulse_width / 58.2;  // Convert pulse width to distance in mm
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }
    frequency = 1000000 / distance;  // Convert distance to frequency in Hz
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        return -1;
    }
    return frequency;
}

int main() {
    signal(SIGINT, handle_sigint);
    init_gpio();

    trigger_pulse_width = 10000;  // 10 µs trigger pulse width
    loop_count = 0;

    running = 1;
    while (running) {
        trigger_sensor();
        usleep(LOOP_DELAY);

        int echo_pulse_width = read_echo();
        if (echo_pulse_width < 0) {
            fprintf(stderr, "Failed to read echo\n");
            continue;
        }

        int frequency = calculate_frequency(echo_pulse_width);
        if (frequency < 0) {
            fprintf(stderr, "Invalid frequency calculated\n");
            continue;
        }

        gpio_set_value(buzzer_line, 1);
        usleep(frequency);
        gpio_set_value(buzzer_line, 0);

        loop_count++;
        if (loop_count % 10 == 0) {
            printf("Loop count: %d\n", loop_count);
        }
    }

    deinit_gpio();
    return 0;
}

