        echo_pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
    }

    return echo_pulse_width;
}

static int calculate_frequency(int echo_pulse_width) {
    int distance = echo_pulse_width / 58.2;  // Convert pulse width to distance in mm
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }
    frequency = 1000000 / distance;  // Convert distance to frequency in Hz
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        return -1;
    }
    return frequency;
}

int main() {
    signal(SIGINT, handle_sigint);
    init_gpio();

    trigger_pulse_width = 10000;  // 10 µs trigger pulse width
    loop_count = 0;

    running = 1;
    while (running) {
        trigger_sensor();
        usleep(LOOP_DELAY);

        int echo_pulse_width = read_echo();
        if (echo_pulse_width < 0) {
            fprintf(stderr, "Failed to read echo\n");
            continue;
        }

        int frequency = calculate_frequency(echo_pulse_width);
        if (frequency < 0) {
            fprintf(stderr, "Invalid frequency calculated\n");
            continue;
        }

        gpio_set_value(buzzer_line, 1);
        usleep(frequency);
        gpio_set_value(buzzer_line, 0);

        loop_count++;
        if (loop_count % 10 == 0) {
            printf("Loop count: %d\n", loop_count);
        }
    }

    deinit_gpio();
    return 0;
}
