#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <string.h>

#define GPIO_BUTTON 17
#define GPIO_BUZZER 18
#define DEBOUNCE_TIME 50
#define BUZZER_FREQ 1000
#define BUZZER_DUTY_CYCLE 50
#define BUZZER_PERIOD (1000000 / BUZZER_FREQ)
#define BUZZER_DELAY (BUZZER_PERIOD * (100 - BUZZER_DUTY_CYCLE) / 100)

#define MELody_LENGTH 10
const int melody[MELody_LENGTH] = {523, 587, 659, 698, 783, 880, 988, 1046, 1109, 1175};

volatile sig_atomic_t stop_melody = 0;

static void handle_signal(int sig) {
    stop_melody = 1;
    gpio_set_line_value(gpio_handle, GPIO_BUZZER, 0);
    gpio_close(gpio_handle);
    exit(EXIT_SUCCESS);
}

static void play_melody(int *melody, int length) {
    for (int i = 0; i < length; i++) {
        gpio_set_line_value(gpio_handle, GPIO_BUZZER, 1);
        usleep(melody[i] * 1000);
        gpio_set_line_value(gpio_handle, GPIO_BUZZER, 0);
        usleep(BUZZER_DELAY);
        if (stop_melody) {
            return;
        }
    }
}

static void gpio_callback(const struct gpiod_line_event *event) {
    if (event->flags & GPIOD_LINE_EVENT_RISING_EDGE) {
        if (gpio_get_line_value(gpio_handle, GPIO_BUTTON) == 0) {
            play_melody(melody, MELody_LENGTH);
        }
    }
}

int main() {
    int gpio_handle;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event_callback callback;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request the button line
    line = gpiod_chip_get_line(chip, GPIO_BUTTON);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the buzzer line
    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, GPIO_BUZZER);
    if (!buzzer_line) {
        perror("Failed to get GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the button line to input with pull-up
    if (gpiod_line_request_input(line, "button", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the buzzer line to output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0)) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up the callback
    callback.event_mask = GPIOD_LINE_EVENT_RISING_EDGE;
    callback.callback = gpio_callback;
    if (gpiod_line_request_edge_event(line, &callback, DEBOUNCE_TIME)) {
        perror("Failed to request edge event");
        gpiod_line_release(line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpio_handle = gpiod_chip_fd(chip);

    while (1) {
        if (stop_melody) {
            break;
        }
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    close(gpio_handle);

    return EXIT_SUCCESS;
}

