#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT 1000
#define WINDOW_SIZE 5

volatile sig_atomic_t exit_flag = 0;

static void sig_handler(int signum) {
    exit_flag = 1;
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;
    struct timespec ts;
    struct sigaction sa;
    FILE *log_file;
    gpiod_chip *chip;
    gpiod_line *line;
    gpiod_line_event event;
    int event_count = 0;
    int event_window[WINDOW_SIZE];
    int i;

    // Set up signal handler
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        exit(EXIT_FAILURE);
    }

    // Parse timeout from command line argument
    if (argc > 1) {
        timeout = atoi(argv[1]);
        if (timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default.\n");
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(LOG_FILE)");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Initialize event window
    for (i = 0; i < WINDOW_SIZE; i++) {
        event_window[i] = 0;
    }

    // Main loop
    while (!exit_flag) {
        // Read edge event
        if (gpiod_line_event_wait(line, &ts, timeout) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        // Update event window
        event_window[event_count % WINDOW_SIZE] = event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0;
        event_count++;

        // Check for earthquake alert
        int earthquake_detected = 0;
        for (i = 0; i < WINDOW_SIZE; i++) {
            if (event_window[i] == 1) {
                earthquake_detected = 1;
                break;
            }
        }
        if (earthquake_detected) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            fprintf(log_file, "%s,1\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "EARTHQUAKE ALERT at %s\n", timestamp);
        }

        // Log event
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
        fprintf(log_file, "%s,%d\n", timestamp, event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0);
        fflush(log_file);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

