This C program continuously reads edge events from an SW-420 vibration sensor module connected to GPIO17 on a Raspberry Pi 3 Model B+. It uses the `libgpiod` library for GPIO operations and edge-triggered polling. The program maintains a sliding window of the last five events and prints an "EARTHQUAKE ALERT" message whenever three or more of those events are HIGH. It logs every edge event to a file named `vibration_events.log` with an ISO-8601 timestamp and the raw value (0 or 1). The program handles errors gracefully and installs a SIGINT/SIGTERM handler to exit cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <json-c/json.h>

#define GPIO_TTP223 4
#define GPIO_RELAY 17
#define DEBOUNCE_TIME_MS 200
#define LOG_FILE "relay_log.json"

static int gpiod_ctx = -1;
static int relay_state = 0;
static time_t last_touch_time = 0;
static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Relay turned off and log entry added.\n");
    exit(EXIT_SUCCESS);
}

static void log_state(const char *state) {
    json_object *root = json_object_new_object();
    json_object_object_add(root, "timestamp", json_object_new_string(gmtime_r(&last_touch_time, NULL), 1));
    json_object_object_add(root, "relay_state", json_object_new_string(state));
    json_object *json_str = json_object_to_json_string(root);
    fprintf(log_file, "%s\n", json_str);
    json_object_put(root);
    free(json_str);
}

static void gpio_callback(const struct gpiod_line_event *event) {
    if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
        time_t current_time = time(NULL);
        if (current_time - last_touch_time >= DEBOUNCE_TIME_MS / 1000) {
            last_touch_time = current_time;
            relay_state = !relay_state;
            log_state(relay_state ? "ON" : "OFF");
            gpio_set_value(gpiod_ctx, GPIO_RELAY, relay_state);
        }
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event_callback callback;
    struct sigaction sa;

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    gpiod_ctx = gpiod_chip_fd(chip);

    // Request line
    line = gpiod_chip_get_line(chip, GPIO_TTP223);
    if (line == NULL) {
        perror("Failed to get line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request event
    if (gpiod_line_request_edge_detection(line, "touch_sensor", GPIOD_EDGE_RISING) < 0) {
        perror("Failed to request edge detection");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up callback
    callback.event_type = GPIOD_LINE_EVENT_RISING_EDGE;
    callback.callback = gpio_callback;
    if (gpiod_line_request_event(line, &callback) < 0) {
        perror("Failed to request event");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        usleep(100000); // Sleep for 100ms
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

