This C program uses the `libgpiod` library to monitor a TTP223 capacitive touch sensor connected to GPIO4 and toggles a 5V relay connected to GPIO17. It implements software debounce to ensure that only valid touches are processed. The program logs every state change to a file named `relay_log.json` as a JSON object containing an ISO 8601 timestamp and the relay state. It also installs a SIGINT handler to ensure that the relay is turned off and a final log entry is added upon termination.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_BASE 17
#define NUM_RELAYS 4
#define DELAY_BETWEEN_RELAYS 1000000  // 1 second in microseconds
#define DELAY_BETWEEN_IRRIGATIONS 10000000  // 10 seconds in microseconds
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static FILE *log_file;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], 1);  // Deactivate all relays
        }
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_BASE + i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "irrigation", 1) < 0) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Seed random number generator
    srand(time(NULL));

    while (1) {
        // Simulate soil moisture value
        int moisture = rand() % 101;

        // Log moisture reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
        fprintf(log_file, "%s,Relay %d,Moisture %d\n", timestamp, moisture);
        fflush(log_file);

        // Activate relays if moisture is below threshold
        if (moisture < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                gpiod_line_set_value(lines[i], 0);  // Activate relay
                usleep(5000000);  // 5 seconds
                gpiod_line_set_value(lines[i], 1);  // Deactivate relay
                usleep(1000000);  // 1 second gap
            }
        }

        // Wait for next irrigation
        usleep(DELAY_BETWEEN_IRRIGATIONS);
    }

    // Close log file and release GPIO lines
    fclose(log_file);
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

