#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <libgpiod.h>

#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define MOISTURE_SEQUENCE 20, 40, 60, 80, 100
#define MOISTURE_THRESHOLD 50
#define NOZZLE_STEPS 5
#define NOZZLE_DELAY 2000000
#define VALVE_DELAY 5000000
#define MAX_RETRIES 3
#define RETRY_DELAY 100000

volatile sig_atomic_t sigint_received = 0;
volatile sig_atomic_t sigterm_received = 0;

static void signal_handler(int signum) {
    sigint_received = 1;
    sigterm_received = 1;
}

static void cleanup() {
    gpiod_chip_close(chip);
    gpiod_line_release(line_valve);
    gpiod_line_release(line_nozzle);
}

static int set_servo(gpiod_chip *chip, gpiod_line *line, int angle) {
    int retries = MAX_RETRIES;
    int ret;

    while (retries > 0) {
        ret = gpiod_line_set_value(line, angle);
        if (ret == 0) {
            return 0;
        }
        usleep(RETRY_DELAY);
        retries--;
    }

    fprintf(stderr, "Failed to set servo to angle %d\n", angle);
    return -1;
}

