#define UNLOCK_PIN 23
#define STEPS 512
#define DELAY 3000 // 3 ms
#define DEBOUNCE_DELAY 100 // 100 ms

static int gpiod_ctx = -1;
static int lock_pin = -1;
static int unlock_pin = -1;
static int step_count = 0;
static int step_direction = 1; // 1 for clockwise, -1 for counter-clockwise

static void handle_signal(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    exit(EXIT_SUCCESS);
}

static void unlock_door() {
    step_count = 0;
    step_direction = -1;
    while (step_count < STEPS) {
        for (int i = 0; i < 4; i++) {
            int pin = STEPPER_PINS[i];
            int value = step_direction == 1 ? 1 : 0;
            if (gpiod_line_set_value(gpiod_ctx, pin, value) < 0) {
                fprintf(stderr, "Error setting GPIO value for pin %d\n", pin);
                exit(EXIT_FAILURE);
            }
            usleep(DELAY);
        }
        step_count++;
    }
    step_count = 0;
    step_direction = 1;
    while (step_count < STEPS) {
        for (int i = 0; i < 4; i++) {
            int pin = STEPPER_PINS[i];
            int value = step_direction == 1 ? 0 : 1;
            if (gpiod_line_set_value(gpiod_ctx, pin, value) < 0) {
                fprintf(stderr, "Error setting GPIO value for pin %d\n", pin);
                exit(EXIT_FAILURE);
            }
            usleep(DELAY);
        }
        step_count++;
    }
    printf("Door unlocked\n");
}

static void lock_door() {
    step_count = 0;
    step_direction = 1;
    while (step_count < STEPS) {
        for (int i = 0; i < 4; i++) {
            int pin = STEPPER_PINS[i];
            int value = step_direction == 1 ? 0 : 1;
            if (gpiod_line_set_value(gpiod_ctx, pin, value) < 0) {
