            if (gpiod_line_set_value(gpiod_ctx, pin, value) < 0) {
                fprintf(stderr, "Error setting GPIO value for pin %d\n", pin);
                exit(EXIT_FAILURE);
            }
            usleep(DELAY);
        }
        step_count++;
    }
    printf("Door locked\n");
}

static void debounced_read(int pin, int *value) {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_DELAY * 1000000;
    nanosleep(&ts, NULL);
    *value = gpiod_line_get_value(gpiod_ctx, pin);
}

int main() {
    signal(SIGINT, handle_signal);

    gpiod_ctx = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_ctx < 0) {
        fprintf(stderr, "Error opening GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    lock_pin = gpiod_chip_get_line(gpiod_ctx, LOCK_PIN);
    if (lock_pin < 0) {
        fprintf(stderr, "Error getting GPIO line for lock button\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(lock_pin, "lock_button") < 0) {
        fprintf(stderr, "Error requesting input for lock button\n");
        exit(EXIT_FAILURE);
    }

    unlock_pin = gpiod_chip_get_line(gpiod_ctx, UNLOCK_PIN);
    if (unlock_pin < 0) {
        fprintf(stderr, "Error getting GPIO line for unlock button\n");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(unlock_pin, "unlock_button") < 0) {
        fprintf(stderr, "Error requesting input for unlock button\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        int lock_value = 0;
        int unlock_value = 0;
        debounced_read(lock_pin, &lock_value);
        debounced_read(unlock_pin, &unlock_value);

        if (lock_value) {
            lock_door();
        } else if (unlock_value) {
            unlock_door();
        }
    }

    return 0;
}

