This C program uses the `libgpiod` library to control the GPIO pins on a Raspberry Pi. It sets up the necessary GPIO lines for the L293D stepper motor driver and the buttons for locking and unlocking the door. The program debounces the button reads to ensure that only a single press triggers a rotation. It then rotates the motor 512 steps clockwise for a lock press and 512 steps counter-clockwise for an unlock press, with a 3 ms inter-step delay. The program also handles the SIGINT signal to de-energize the coils and exit gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 1000
#define MAX_TIMEOUT_MS 500
#define MAX_SAMPLES 1000000

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

static void handle_signal(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void setup_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *trigger_line = gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN);
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Failed to request trigger line");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *echo_line = gpiod_chip_get_line(gpiod_ctx, ECHO_PIN);
    if (gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

static void release_gpio() {
    gpiod_line_release(gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN));
    gpiod_line_release(gpiod_chip_get_line(gpiod_ctx, ECHO_PIN));
    gpiod_chip_close(gpiod_ctx);
}

static void log_distance(int distance) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }
    fprintf(log_file, "%d\n", distance);
    fflush(log_file);
}

static int measure_distance() {
    struct timespec start, end;
    long duration_ns;
    int distance;

    // Generate a 10µs trigger pulse
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN), 1);
    usleep(10);
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_ctx, TRIGGER_PIN), 0);

    // Wait for the rising edge of the echo
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(gpiod_chip_get_line(gpiod_ctx, ECHO_PIN)) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get current time");
            return -1;
        }
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (duration_ns > MAX_TIMEOUT_MS * 1000000) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
    }

    // Wait for the falling edge of the echo
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(gpiod_chip_get_line(gpiod_ctx, ECHO_PIN)) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get current time");
            return -1;
        }
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (duration_ns > MAX_TIMEOUT_MS * 1000000) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    }

    // Calculate the distance
    duration_ns /= 2;
    distance = (int)(duration_ns / 58.2);

    return distance;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (1) {
        int distance = measure_distance();
        if (distance != -1) {
            log_distance(distance);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    release_gpio();
    return 0;
}

