        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            perror("Failed to get current time");
            return -1;
        }
        duration_ns = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
        if (duration_ns > MAX_TIMEOUT_MS * 1000000) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
    }

    // Calculate the distance
    duration_ns /= 2;
    distance = (int)(duration_ns / 58.2);

    return distance;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (1) {
        int distance = measure_distance();
        if (distance != -1) {
            log_distance(distance);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    release_gpio();
    return 0;
}
