#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define RELAY_PIN 18
#define POLL_INTERVAL 100000  // 100 ms

static int i2c_fd;
static int relay_fd;
static struct gpiod_chip *relay_chip;
static struct gpiod_line *relay_line;

static void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (relay_fd >= 0) {
        gpiod_line_set_value(relay_line, 0);
        close(relay_fd);
    }
    if (relay_chip) {
        gpiod_chip_close(relay_chip);
    }
    exit(0);
}

static void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int main() {
    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open relay GPIO
    relay_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!relay_chip) {
        log_error("Failed to open relay GPIO chip");
        close(i2c_fd);
        return 1;
    }

    relay_line = gpiod_chip_get_line(relay_chip, RELAY_PIN);
    if (!relay_line) {
        log_error("Failed to get relay GPIO line");
        gpiod_chip_close(relay_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        log_error("Failed to request relay GPIO line");
        gpiod_chip_close(relay_chip);
        close(i2c_fd);
        gpiod_line_release(relay_line);
        return 1;
    }

    // Initialize VL53L1X sensor
    uint8_t init_cmd[] = {0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (write(i2c_fd, init_cmd, sizeof(init_cmd)) != sizeof(init_cmd)) {
        log_error("Failed to initialize VL53L1X sensor");
        gpiod_line_release(relay_line);
        gpiod_chip_close(relay_chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read distance from VL53L1X sensor
        uint8_t distance_cmd[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
        if (write(i2c_fd, distance_cmd, sizeof(distance_cmd)) != sizeof(distance_cmd)) {
            log_error("Failed to read distance from VL53L1X sensor");
            continue;
        }

        uint8_t distance_data[2];
        if (read(i2c_fd, distance_data, sizeof(distance_data)) != sizeof(distance_data)) {
            log_error("Failed to read distance data from VL53L1X sensor");
            continue;
        }

        uint16_t distance = (distance_data[0] << 8) | distance_data[1];
        printf("Distance: %d cm\n", distance);

        // Set relay based on distance
        if (distance <= 50) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        // Sleep for 100 ms
        usleep(POLL_INTERVAL);
    }

    // Clean up
    gpiod_line_release(relay_line);
    gpiod_chip_close(relay_chip);
    close(i2c_fd);

    return 0;
}

