#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPU6050_ADDR 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_XOUT_L 0x3C
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_YOUT_L 0x3E
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_ZOUT_L 0x40
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_PWR_MGMT_2 0x6C
#define MPU6050_CONFIG 0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_FS_SEL 0x1D
#define MPU6050_GYRO_FS_SEL 0x1E
#define MPU6050_INT_PIN_CFG 0x37
#define MPU6050_INT_ENABLE 0x38
#define MPU6050_INT_STATUS 0x3A
#define MPU6050_FIFO_EN 0x38
#define MPU6050_FIFO_COUNT_H 0x72
#define MPU6050_FIFO_COUNT_L 0x73
#define MPU6050_FIFO_R_W 0x74
#define MPU6050_WHO_AM_I 0x75

#define SDA_PIN 2
#define SCL_PIN 3

static int i2c_fd;
static int gpio_fd;
static int accel_fs_sel = 0x08; // 2g full scale
static int gyro_fs_sel = 0x08; // 250dps full scale

void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_close(gpio_fd);
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sda_line, *scl_line;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Get the SDA and SCL lines
    sda_line = gpiod_chip_get_line(chip, SDA_PIN);
    scl_line = gpiod_chip_get_line(chip, SCL_PIN);
    if (!sda_line || !scl_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request the lines for output
    ret = gpiod_line_request_output(sda_line, "mpu6050_sda", 0);
    if (ret < 0) {
        perror("Failed to request SDA line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(scl_line, "mpu6050_scl", 0);
    if (ret < 0) {
        perror("Failed to request SCL line");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set the I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure the MPU-6050
    ret = write(i2c_fd, &gyro_fs_sel, 1);
    if (ret < 0) {
        perror("Failed to write gyro full scale");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = write(i2c_fd, &accel_fs_sel, 1);
    if (ret < 0) {
        perror("Failed to write accel full scale");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Enable the gyroscope and accelerometer
    ret = write(i2c_fd, &gyro_fs_sel, 1);
    if (ret < 0) {
        perror("Failed to write gyro full scale");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ret = write(i2c_fd, &accel_fs_sel, 1);
    if (ret < 0) {
        perror("Failed to write accel full scale");
        gpiod_line_release(sda_line);
        gpiod_line_release(scl_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read the gyroscope and accelerometer data
    while (1) {
        uint8_t data[14];
        int16_t accel_x, accel_y, accel_z;
        int16_t gyro_x, gyro_y, gyro_z;

        // Read the accelerometer data
        ret = read(i2c_fd, data, 14);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            continue;
        }

        // Convert the data to signed 16-bit integers
        accel_x = (data[0] << 8) | data[1];
        accel_y = (data[2] << 8) | data[3];
        accel_z = (data[4] << 8) | data[5];

        gyro_x = (data[8] << 8) | data[9];
        gyro_y = (data[10] << 8) | data[11];
        gyro_z = (data[12] << 8) | data[13];

        // Print the data
        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);

        // Sleep for a short period
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

