#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES 4
#define GPIO_PINS {17, 18, 27, 22}
#define LOG_FILE "watering_log.txt"
#define CYCLE_INTERVAL 86400 // 24 hours in seconds
#define POLL_INTERVAL 60 // 1 minute in seconds

static gpiod_chip *chip;
static gpiod_line *lines[GPIO_LINES];
static FILE *log_file;
static time_t start_time;

static void sigint_handler(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

static void log_start_time() {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char log_entry[80];
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s\n", log_entry);
}

int main() {
    // Register signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines as outputs with active-low semantics
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        int flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
        int ret = gpiod_line_request_output(lines[i], "watering", flags);
        if (ret) {
            perror("Failed to request GPIO line");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set all lines HIGH (inactive) at startup
    for (int i = 0; i < GPIO_LINES; i++) {
        int ret = gpiod_line_set_value(lines[i], 1);
        if (ret) {
            perror("Failed to set GPIO line value");
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Log start time
    log_start_time();

    // Main loop
    while (1) {
        for (int i = 0; i < GPIO_LINES; i++) {
            int ret = gpiod_line_set_value(lines[i], 0); // Activate relay
            if (ret) {
                perror("Failed to set GPIO line value");
                for (int j = 0; j < i; j++) {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            sleep(5); // Wait for 5 seconds
            ret = gpiod_line_set_value(lines[i], 1); // Deactivate relay
            if (ret) {
                perror("Failed to set GPIO line value");
                for (int j = 0; j < i; j++) {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
        }
        sleep(CYCLE_INTERVAL - POLL_INTERVAL); // Wait for the next cycle
    }

    // Close log file
    fclose(log_file);

    // Release GPIO lines
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

