#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define LOG_FILE "smart_lighting.log"
#define NUM_RELAYS 4
#define GPIO_PINS {17, 18, 27, 22}
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE_MAX 255
#define DURATION_SECONDS 1800 // 30 minutes

static int gpiod_ctx = -1;
static int pwm_fd[NUM_RELAYS] = {-1};
static FILE *log_file = NULL;

static void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s\n", timestamp, event);
}

static void handle_signal(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (pwm_fd[i] != -1) {
            close(pwm_fd[i]);
        }
    }
    exit(signum);
}

static void setup_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        int pin = GPIO_PINS[i];
        struct gpiod_line *line = gpiod_chip_get_line(gpiod_ctx, pin);
        if (line == NULL) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }

        int mode = gpiod_line_get_direction(line);
        if (mode != GPIOD_LINE_DIRECTION_OUTPUT) {
            fprintf(stderr, "GPIO line %d is not in output mode\n", pin);
            exit(EXIT_FAILURE);
        }

        int ret = gpiod_line_request_output(line, "smart_lighting", 0);
        if (ret != 0) {
            perror("Failed to request GPIO line output");
            exit(EXIT_FAILURE);
        }
    }
}

static void setup_pwm(int pin) {
    pwm_fd[pin] = open("/dev/pwm", O_WRONLY);
    if (pwm_fd[pin] == -1) {
        perror("Failed to open PWM device");
        exit(EXIT_FAILURE);
    }

    struct pwmchip_info chip_info;
    if (ioctl(pwm_fd[pin], PWM_GETCHIPINFO, &chip_info) == -1) {
        perror("Failed to get PWM chip info");
        exit(EXIT_FAILURE);
    }

    struct pwm_config config;
    config.period = 1000000 / PWM_FREQUENCY;
    config.duty_cycle = 0;
    config.enabled = 1;

    if (ioctl(pwm_fd[pin], PWM_CONFIG, &config) == -1) {
        perror("Failed to configure PWM");
        exit(EXIT_FAILURE);
    }
}

static void set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_DUTY_CYCLE_MAX) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        exit(EXIT_FAILURE);
    }

    struct pwm_config config;
    if (ioctl(pwm_fd[pin], PWM_GETCONFIG, &config) == -1) {
        perror("Failed to get PWM config");
        exit(EXIT_FAILURE);
    }

    config.duty_cycle = duty_cycle;
    if (ioctl(pwm_fd[pin], PWM_SETCONFIG, &config) == -1) {
        perror("Failed to set PWM config");
        exit(EXIT_FAILURE);
    }
}

static void release_resources() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (pwm_fd[i] != -1) {
            close(pwm_fd[i]);
        }
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    for (int i = 0; i < NUM_RELAYS; i++) {
        setup_pwm(GPIO_PINS[i]);
    }

    log_event("Starting smart lighting effect");

    for (int i = 0; i <= PWM_DUTY_CYCLE_MAX; i++) {
        for (int j = 0; j < NUM_RELAYS; j++) {
            set_pwm_duty_cycle(GPIO_PINS[j], i);
        }
        log_event("Set duty cycle to %d", i);
        sleep(1);
    }

    log_event("Smart lighting effect completed");

    release_resources();

    return 0;
}

