        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_led() {
    led_fd = gpiochip_open(0);
    if (led_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    if (gpio_claim_line(led_fd, LED_PIN) < 0) {
        perror("Failed to claim GPIO line");
        gpiochip_close(led_fd);
        exit(EXIT_FAILURE);
    }
    gpio_set_value(led_fd, 0);
}

static void read_gyro() {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int ret = mpu6050_read_gyro(&mpu);
        if (ret == 0) {
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            buffer[buffer_index][0] = mpu.gyro.x;
            buffer[buffer_index][1] = mpu.gyro.y;
            buffer[buffer_index][2] = mpu.gyro.z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            buffer_full = buffer_index == 0;
            if (buffer_full) {
                gpio_set_value(led_fd, 1);
            } else {
                gpio_set_value(led_fd, 0);
            }
            last_read_time = current_time;
            return;
        } else {
            retries++;
            usleep(100000); // Wait for 100ms before retrying
        }
    }
    perror("Failed to read gyro data");
    exit(EXIT_FAILURE);
}

static void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Timestamp: %ld.%09ld, X: %d, Y: %d, Z: %d\n",
               last_read_time.tv_sec, last_read_time.tv_nsec,
               buffer[i][0], buffer[i][1], buffer[i][2]);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    init_led();
    mpu6050_init(&mpu, i2c_fd);

    while (1) {
        read_gyro();
        if (buffer_full) {
            print_buffer();
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    mpu6050_cleanup(&mpu);
    close(i2c_fd);
    gpio_set_value(led_fd, 0);
    gpiochip_close(led_fd);

    return 0;
}
