    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        perror("Failed to read SPI mode");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_MODE) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_MODE) < 0) {
        perror("Failed to read SPI bits per word");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to read SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

static int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "warning_led", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

static int read_gyro() {
    unsigned char tx[6] = {0x43, 0x00, 0x00, 0x00, 0x00, 0x00};
    unsigned char rx[6];

    if (write(spi_fd, tx, 6) != 6) {
        perror("Failed to write to SPI");
        return -1;
    }

    if (read(spi_fd, rx, 6) != 6) {
        perror("Failed to read from SPI");
        return -1;
    }

    int x = (rx[0] << 8) | rx[1];
    int y = (rx[2] << 8) | rx[3];
    int z = (rx[4] << 8) | rx[5];

    if (x == 0 || y == 0 || z == 0) {
        perror("Invalid data received from sensor");
        return -1;
    }

    return x, y, z;
}

static void blink_led() {
    gpiod_line_set_value(line, 1);
    usleep(500000);
    gpiod_line_set_value(line, 0);
    usleep(500000);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        return 1;
    }

    while (running) {
        int x, y, z;
        if ((x, y, z) = read_gyro()) {
            if (x > THRESHOLD || x < -THRESHOLD || y > THRESHOLD || y < -THRESHOLD || z > THRESHOLD || z < -THRESHOLD) {
                blink_led();
            }

            buffer[buffer_index][0] = time(NULL);
            buffer[buffer_index][1] = x;
            buffer[buffer_index][2] = y;
            buffer[buffer_index][3] = z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        }

        usleep(100000);
    }

    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    FILE *fp = fopen("gyro_data.csv", "w");
    if (!fp) {
        perror("Failed to open CSV file");
        return 1;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        fprintf(fp, "%ld,%d,%d,%d\n", buffer[i][0], buffer[i][1], buffer[i][2], buffer[i][3]);
    }

    fclose(fp);

    return 0;
}
```

This C program initializes the SPI and GPIO interfaces, reads angular velocity from the MPU-6050 gyroscope, and stores each sample in a circular buffer. It also monitors the data for any axis exceeding ±200 deg/s and blinks a warning LED connected to GPIO17. The program handles SPI initialisation failures, sensor read failures, and SIGINT (Ctrl-C) by releasing resources and printing the entire circular buffer as CSV.

