static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void init_led() {
    led_fd = gpiochip_open(0);
    if (led_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    gpio_direction_output(led_fd, 0);
}

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void close_led() {
    if (led_fd >= 0) {
        gpio_close(led_fd);
    }
}

void read_mpu6050() {
    uint8_t buffer[14];
    int ret;

    ret = i2c_smbus_read_block_data(i2c_fd, MPU6050_ACCEL_XOUT_H, buffer, 14);
    if (ret < 0) {
        perror("Failed to read MPU6050 data");
        return;
    }

    int16_t accel_x = (buffer[0] << 8) | buffer[1];
    int16_t accel_y = (buffer[2] << 8) | buffer[3];
    int16_t accel_z = (buffer[4] << 8) | buffer[5];
    int16_t gyro_x = (buffer[6] << 8) | buffer[7];
    int16_t gyro_y = (buffer[8] << 8) | buffer[9];
    int16_t gyro_z = (buffer[10] << 8) | buffer[11];

    double accel_x_g = accel_x / 16384.0;
    double accel_y_g = accel_y / 16384.0;
    double accel_z_g = accel_z / 16384.0;
    double gyro_x_rps = gyro_x / 131.0;
    double gyro_y_rps = gyro_y / 131.0;
    double gyro_z_rps = gyro_z / 131.0;

    double roll = atan2(accel_y_g, accel_z_g) * 180.0 / M_PI;
    double pitch = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180.0 / M_PI;

    printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

    FILE *log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open tilt_log.txt");
        return;
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fclose(log_file);

    if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
        gpio_set_value(led_fd, 1);
    } else {
        gpio_set_value(led_fd, 0);
    }
}

