#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USEC 0
#define SPI_MAX_RETRIES 3
#define FILE_NAME "gyro_data.csv"
#define MAX_BUFFER_SIZE 1024

static int spi_fd = -1;
static FILE *file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ce0_line = NULL;
static struct gpiod_line_request ce0_request = {
    .offset = 8,
    .direction = GPIOD_OUT_LOW,
    .flags = GPIOD_OPEN_DRAIN,
};

static void sigint_handler(int signum) {
    if (file) {
        fclose(file);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .delay_usecs = SPI_DELAY_USEC,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
    };
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    int ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

static int gpio_init() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ce0_line = gpiod_chip_get_line(chip, ce0_request.offset);
    if (!ce0_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request(ce0_line, &ce0_request);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(ce0_line);
        return -1;
    }

    return 0;
}

static int write_to_file(const char *format, ...) {
    va_list args;
    va_start(args, format);
    int ret = vfprintf(file, format, args);
    va_end(args);
    if (ret < 0) {
        perror("Failed to write to file");
        return -1;
    }
    return 0;
}

static int read_gyro_data() {
    uint8_t tx[2];
    uint8_t rx[2];
    int ret;

    for (int i = 0; i < 2; i++) {
        tx[0] = 0x40 | (i << 4); // Read from X or Y axis
        tx[1] = 0x00; // Dummy byte

        for (int retry = 0; retry < SPI_MAX_RETRIES; retry++) {
            ret = spi_transfer(tx, rx, sizeof(tx));
            if (ret == 0) {
                break;
            }
            usleep(10000); // Wait 10 ms before retrying
        }

        if (ret != 0) {
            return -1;
        }

        int16_t raw_value = (rx[0] << 8) | rx[1];
        write_to_file("%lu,%d,%d\n", time(NULL), raw_value, raw_value);
    }

    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);

    if (gpio_init() != 0) {
        return EXIT_FAILURE;
    }

    if (spi_init() != 0) {
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = fopen(FILE_NAME, "w");
    if (!file) {
        perror("Failed to open file");
        close(spi_fd);
        gpiod_line_release(ce0_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    write_to_file("timestamp,x_rate,y_rate\n");

    while (1) {
        if (read_gyro_data() != 0) {
            close(spi_fd);
            fclose(file);
            gpiod_line_release(ce0_line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        usleep(100000); // Wait 100 ms between samples
    }

    fclose(file);
    close(spi_fd);
    gpiod_line_release(ce0_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

