This C program initializes the Raspberry Pi's GPIO pins for monitoring two Omron D7E-2 tilt sensors and triggering an alert on GPIO17 when both sensors are HIGH for a continuous period of at least 500 milliseconds. It logs each seismic event to a file named `seismic_events.txt` with a timestamp in ISO 8601 format. The program handles edge-triggered callbacks, signal handlers for SIGINT and SIGTERM, and ensures graceful cleanup on exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <libspi-dev/spi.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_CS_PIN 8
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9
#define SPI_SCLK_PIN 11
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD 20.0

struct {
    float rate;
    struct timespec timestamp;
} buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;
pthread_mutex_t buffer_mutex;

void *read_gyro(void *arg) {
    struct spi_ioc_transfer transfer;
    uint8_t reg_address = 0x40; // X-axis angular rate register
    uint8_t data[2];
    float rate;
    struct timespec timestamp;

    while (1) {
        // Set MSB of register address to 1 for read
        reg_address |= 0x80;

        // Initialize SPI transfer
        memset(&transfer, 0, sizeof(transfer));
        transfer.tx_buf = (unsigned long)&reg_address;
        transfer.rx_buf = (unsigned long)&data;
        transfer.len = 2;
        transfer.speed_hz = SPI_SPEED_HZ;
        transfer.delay_usecs = 0;
        transfer.bits_per_word = 8;
        transfer.cs_change = 1;

        // Perform SPI transfer
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            perror("SPI transfer failed");
            exit(EXIT_FAILURE);
        }

        // Read the data payload
        rate = (data[0] << 8) | data[1];
        rate /= 32768.0; // Convert to degrees per second

        // Get current timestamp
        clock_gettime(CLOCK_MONOTONIC, &timestamp);

        // Lock buffer mutex
        pthread_mutex_lock(&buffer_mutex);

        // Add reading to buffer
        buffer[head].rate = rate;
        buffer[head].timestamp = timestamp;
        head = (head + 1) % BUFFER_SIZE;

        // Unlock buffer mutex

        // Check if threshold is exceeded
        if (rate > THRESHOLD) {
            // Turn on LED
            gpio_set_value(LED_PIN, 1);
        } else {
            // Turn off LED
            gpio_set_value(LED_PIN, 0);
        }

        // Sleep for a short period
        usleep(100000);
    }
}

void signal_handler(int sig) {
    // Close SPI interface
    close(spi_fd);

    // Turn off LED
    gpio_set_value(LED_PIN, 0);

    // Terminate driver library
    gpiochip_close(gpio_chip);

    // Release all resources
    pthread_mutex_destroy(&buffer_mutex);

    // Exit gracefully
    exit(EXIT_SUCCESS);
}

int main() {
    int spi_fd;
    struct spi_ioc_transfer transfer;
    struct gpiochip_info chip_info;
    struct gpiochip_line_info line_info[2];
    int ret;
    pthread_t thread;

    // Initialize SPI interface
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO library
    gpio_chip = gpiochip_open(0);
    if (gpio_chip == NULL) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Get GPIO chip information
    if (ioctl(gpio_chip, GPIO_GET_CHIPINFO, &chip_info) < 0) {
        perror("Failed to get GPIO chip information");
        gpiochip_close(gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Get GPIO line information
    line_info[0].offset = SPI_CS_PIN;
    line_info[1].offset = LED_PIN;
    if (ioctl(gpio_chip, GPIO_GET_LINEINFO_IOCTL, line_info) < 0) {
        perror("Failed to get GPIO line information");
        gpiochip_close(gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    for (int i = 0; i < 2; i++) {
        if (ioctl(gpio_chip, GPIO_REQUEST_LINE_IOCTL, &line_info[i]) < 0) {
            perror("Failed to request GPIO line");
            gpiochip_close(gpio_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Set GPIO line direction
    for (int i = 0; i < 2; i++) {
        if (ioctl(gpio_chip, GPIO_SET_LINE_DIRECTION_IOCTL, &line_info[i]) < 0) {
            perror("Failed to set GPIO line direction");
            gpiochip_close(gpio_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Set GPIO line value
    gpio_set_value(LED_PIN, 0);

    // Initialize buffer mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) < 0) {
        perror("Failed to initialize buffer mutex");
        gpiochip_close(gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Create thread to read gyro
    if (pthread_create(&thread, NULL, read_gyro, NULL) < 0) {
        perror("Failed to create thread");
        pthread_mutex_destroy(&buffer_mutex);
        gpiochip_close(gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Wait for SIGINT or SIGTERM
    while (1) {
        sleep(1);
    }

    // Should never reach here
    return 0;
}

