        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    for (int i = 0; i < 2; i++) {
        if (ioctl(gpio_chip, GPIO_REQUEST_LINE_IOCTL, &line_info[i]) < 0) {
            perror("Failed to request GPIO line");
            gpiochip_close(gpio_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Set GPIO line direction
    for (int i = 0; i < 2; i++) {
        if (ioctl(gpio_chip, GPIO_SET_LINE_DIRECTION_IOCTL, &line_info[i]) < 0) {
            perror("Failed to set GPIO line direction");
            gpiochip_close(gpio_chip);
            close(spi_fd);
            exit(EXIT_FAILURE);
        }
    }

    // Set GPIO line value
    gpio_set_value(LED_PIN, 0);

    // Initialize buffer mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) < 0) {
        perror("Failed to initialize buffer mutex");
        gpiochip_close(gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Create thread to read gyro
    if (pthread_create(&thread, NULL, read_gyro, NULL) < 0) {
        perror("Failed to create thread");
        pthread_mutex_destroy(&buffer_mutex);
        gpiochip_close(gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Wait for SIGINT or SIGTERM
    while (1) {
        sleep(1);
    }

    // Should never reach here
    return 0;
}
