#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 3
#define PWM_PIN 17
#define PWM_PERIOD 1000000 / 100 // 100 Hz
#define MAX_DUTY_CYCLE 255

static int gpiod_ctx = -1;
static int pwm_fd[NUM_RELAYS];
static int total_duration = 0;
static int current_lamp = 0;
static int fade_step = 0;
static int fade_direction = 1;
static int fade_complete = 0;

static void handle_sigint(int signum) {
    printf("Received SIGINT, turning off all lamps and exiting...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpio_set_value(gpiod_ctx, pwm_fd[i], 0);
    }
    gpiochip_close(gpiod_ctx);
    exit(EXIT_SUCCESS);
}

static void handle_sigterm(int signum) {
    printf("Received SIGTERM, turning off all lamps and exiting...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpio_set_value(gpiod_ctx, pwm_fd[i], 0);
    }
    gpiochip_close(gpiod_ctx);
    exit(EXIT_SUCCESS);
}

static void init_pwm(int pin) {
    struct gpiochip_info info;
    struct gpiochip_config config;
    int ret;

    ret = gpiochip_get_info_by_number(pin, &info);
    if (ret < 0) {
        perror("Failed to get GPIO chip info");
        exit(EXIT_FAILURE);
    }

    config.lines = info.lines;
    config.line_config = NULL;
    config.owner = NULL;
    config.label = "smart_sunset";
    config.irq_base = -1;
    config.irq_flags = 0;
    config.consumer_label = NULL;

    ret = gpiochip_config(gpiod_ctx, &config);
    if (ret < 0) {
        perror("Failed to configure GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiochip_get_line(gpiod_ctx, pin);
    if (ret < 0) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiochip_line_request(gpiod_ctx, ret, GPIOHANDLE_REQUEST_OUTPUT);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiochip_line_set_config(gpiod_ctx, ret, GPIOHANDLE_CONFIG_OUTPUT_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to set GPIO line config");
        exit(EXIT_FAILURE);
    }

    ret = gpiochip_line_set_value(gpiod_ctx, ret, 0);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
        exit(EXIT_FAILURE);
    }

    ret = gpiochip_line_request_pwm(gpiod_ctx, ret, PWM_PERIOD, MAX_DUTY_CYCLE);
    if (ret < 0) {
        perror("Failed to request PWM");
        exit(EXIT_FAILURE);
    }

    pwm_fd[pin] = ret;
}

static void start_fade() {
    fade_complete = 0;
    fade_step = 0;
    fade_direction = 1;
    current_lamp = 0;
    printf("Starting sunset simulation...\n");
}

static void fade_lamp() {
    if (fade_complete) {
        return;
    }

    if (fade_step == 0) {
        gpio_set_value(gpiod_ctx, pwm_fd[current_lamp], 1);
    }

    if (fade_step < MAX_DUTY_CYCLE) {
        gpio_set_value(gpiod_ctx, pwm_fd[current_lamp], fade_step);
        fade_step += fade_direction;
    } else {
        fade_step = MAX_DUTY_CYCLE;
        fade_direction = -1;
    }

    if (fade_step == 0) {
        gpio_set_value(gpiod_ctx, pwm_fd[current_lamp], 0);
        current_lamp++;
        if (current_lamp == NUM_RELAYS) {
            fade_complete = 1;
            printf("Sunset simulation complete.\n");
        } else {
            start_fade();
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_in_seconds>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    total_duration = atoi(argv[1]);
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Total duration must be between 1 and 3600 seconds.\n");
        exit(EXIT_FAILURE);
    }

    gpiod_ctx = gpiochip_open_by_name("gpiochip0");
    if (gpiod_ctx < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        init_pwm(i);
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    start_fade();

    while (!fade_complete) {
        fade_lamp();
        usleep(100000); // 100 Hz
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpio_set_value(gpiod_ctx, pwm_fd[i], 0);
    }

    gpiochip_close(gpiod_ctx);

    return EXIT_SUCCESS;
}

