#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_RED 17
#define GPIO_YELLOW 22
#define GPIO_GREEN 23
#define GPIO_AMBER 24

#define RED 0
#define YELLOW 1
#define GREEN 2
#define AMBER 3

static gpiod_chip *chip;
static gpiod_line *lines[4];
static int state = RED;
static int delay[4] = {10, 2, 10, 3};

void signal_handler(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    exit(signum);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    lines[RED] = gpiod_chip_get_line(chip, GPIO_RED);
    lines[YELLOW] = gpiod_chip_get_line(chip, GPIO_YELLOW);
    lines[GREEN] = gpiod_chip_get_line(chip, GPIO_GREEN);
    lines[AMBER] = gpiod_chip_get_line(chip, GPIO_AMBER);

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "traffic_light", 0)) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    while (1) {
        // Set the current state
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value(lines[i], (state == i));
        }

        // Print the current state
        printf("State: %d\n", state);

        // Wait for the current state duration
        sleep(delay[state]);

        // Move to the next state
        state = (state + 1) % 4;
    }

    // This line should never be reached
    return EXIT_FAILURE;
}

