#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY 100
#define LOG_FILE "touch_relay.log"
#define MAX_TOUCH_EVENTS 12

static int i2c_fd;
static int gpio_fd;
static int gpio_chip;
static int gpio_line;
static FILE *log_file;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%02d:%02d:%02d - %s\n", tm->tm_hour, tm->tm_min, tm->tm_sec, message);
}

static void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_FAILURE);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        handle_signal(SIGINT);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        log_error("Failed to set I2C address");
        handle_signal(SIGINT);
    }
}

static void init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        log_error("Failed to open GPIO chip");
        handle_signal(SIGINT);
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_RELAY);
    if (!gpio_line) {
        log_error("Failed to get GPIO line");
        handle_signal(SIGINT);
    }
    if (gpiod_line_request_output(gpio_line, "touch_relay", 0) < 0) {
        log_error("Failed to request GPIO line");
        handle_signal(SIGINT);
    }
}

static void init_log() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        handle_signal(SIGINT);
    }
}

static void close_log() {
    if (log_file) {
        fclose(log_file);
    }
}

static void close_gpio() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

static void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void read_touch_events() {
    uint8_t data[13];
    if (read(i2c_fd, data, 13) != 13) {
        log_error("Failed to read touch events");
        return;
    }
    for (int i = 0; i < MAX_TOUCH_EVENTS; i++) {
        if (data[i] & 0x01) {
            log_error("Electrode 0 touched");
            gpiod_line_set_value(gpio_line, 1);
            usleep(DEBOUNCE_DELAY * 1000);
            gpiod_line_set_value(gpio_line, 0);
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_log();
    init_i2c();
    init_gpio();

    while (1) {
        read_touch_events();
        usleep(10000);
    }

    close_log();
    close_gpio();
    close_i2c();

    return 0;
}

