#define LOG_FILE "dispense_log.txt"

static int gpiod_handle = -1;
static int solenoid1_pin = GPIO17;
static int solenoid2_pin = GPIO27;

static void sigint_handler(int signum) {
    if (gpiod_handle != -1) {
        gpiod_line_set_value(gpiod_handle, solenoid1_pin, 0);
        gpiod_line_set_value(gpiod_handle, solenoid2_pin, 0);
        gpiod_close(gpiod_handle);
    }
    exit(EXIT_SUCCESS);
}

static int init_gpiod() {
    gpiod_handle = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_handle == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpiod_line *line1 = gpiod_chip_get_line(gpiod_handle, solenoid1_pin);
    if (gpiod_line_request_output(line1, "solenoid1", 0) != 0) {
        perror("Failed to request GPIO line for solenoid1");
        gpiod_close(gpiod_handle);
        return -1;
    }

    gpiod_line *line2 = gpiod_chip_get_line(gpiod_handle, solenoid2_pin);
    if (gpiod_line_request_output(line2, "solenoid2", 0) != 0) {
        perror("Failed to request GPIO line for solenoid2");
        gpiod_line_release(line1);
        gpiod_close(gpiod_handle);
        return -1;
    }

    return 0;
}

static int log_dispense(int solenoid, int duration) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(file, "%s, %d, %d\n", timestamp, solenoid, duration);
    fclose(file);

    return 0;
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    if (init_gpiod() != 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(gpiod_handle, solenoid1_pin, 1);
        gpiod_line_set_value(gpiod_handle, solenoid2_pin, 0);
        usleep(500000); // 500 ms
        gpiod_line_set_value(gpiod_handle, solenoid1_pin, 0);
        gpiod_line_set_value(gpiod_handle, solenoid2_pin, 1);
        usleep(500000); // 500 ms
        log_dispense(1, 500);
        log_dispense(2, 500);
        usleep(500000); // 500 ms
    }

    gpiod_line_set_value(gpiod_handle, solenoid1_pin, 0);
    gpiod_line_set_value(gpiod_handle, solenoid2_pin, 0);
    gpiod_close(gpiod_handle);

    return EXIT_SUCCESS;
}

