#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_PIN_TOUCH 4
#define GPIO_PIN_RELAY 17
#define DEBOUNCE_DELAY_MS 50
#define MAX_RETRIES 10

static int gpiod_handle = -1;
static int relay_state = 0;

static void handle_signal(int signum) {
    if (gpiod_handle != -1) {
        gpiod_chip_close(gpiod_handle);
    }
    exit(signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    gpiod_handle = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_handle == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *touch_line = gpiod_chip_get_line(gpiod_handle, GPIO_PIN_TOUCH);
    if (touch_line == NULL) {
        perror("Failed to get touch line");
        gpiod_chip_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(gpiod_handle, GPIO_PIN_RELAY);
    if (relay_line == NULL) {
        perror("Failed to get relay line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    // Request lines for input and output
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        perror("Failed to request touch line as input");
        gpiod_line_release(touch_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(touch_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    // Enable pull-down resistor on touch line
    if (gpiod_line_set_config(touch_line, NULL, GPIO_LINE_CONFIG_VAL_LOW) < 0) {
        perror("Failed to set pull-down resistor on touch line");
        gpiod_line_release(touch_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int touch_detected = 0;
        for (int i = 0; i < MAX_RETRIES; i++) {
            int value = gpiod_line_get_value(touch_line);
            if (value == 1) {
                touch_detected = 1;
                break;
            }
            usleep(1000);
        }

        if (touch_detected) {
            relay_state = !relay_state;
            gpiod_line_set_value(relay_line, relay_state);
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        usleep(1000); // Check for touch every 1ms
    }

    // Cleanup
    gpiod_line_release(touch_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(gpiod_handle);

    return 0;
}

