    unsigned char buffer[period_size * 2];
    unsigned int last_amplitude = 0;

    while (1) {
        if (snd_pcm_readi(handle, buffer, period_size) < 0) {
            if (errno == EPIPE) {
                fprintf(stderr, "Buffer overrun, preparing PCM device...\n");
                snd_pcm_prepare(handle);
            } else if (errno == ESTRPIPE) {
                fprintf(stderr, "PCM device suspended, resuming...\n");
                snd_pcm_resume(handle);
            } else {
                fprintf(stderr, "Error reading from PCM device: %s\n", snd_strerror(errno));
                cleanup_audio();
                cleanup_gpio();
                exit(EXIT_FAILURE);
            }
        } else {
            unsigned int amplitude = calculate_rms(buffer, period_size);
            if (amplitude != last_amplitude) {
                last_amplitude = amplitude;
                map_to_color(amplitude);
            }
        }

        usleep(period);
    }

    cleanup_audio();
    cleanup_gpio();
    return 0;
