#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define SENSOR_REG_ENABLE 0x00
#define SENSOR_REG_CONFIG 0x01
#define SENSOR_REG_RED 0x04
#define SENSOR_REG_GREEN 0x05
#define SENSOR_REG_BLUE 0x06
#define SENSOR_REG_CLEAR 0x07
#define SENSOR_REG_ID 0x12
#define SENSOR_ID_TCS34725 0x10

#define CSV_FILE "color_data.csv"
#define MAX_READS 1000000
#define READ_INTERVAL_MS 500

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t should_exit = 0;

static void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    uint8_t id;
    uint16_t red, green, blue, clear;
    struct timespec sleep_time;
    time_t now;

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Read sensor ID
    ret = write(i2c_fd, &SENSOR_REG_ID, 1);
    if (ret < 0) {
        perror("Failed to write to sensor ID register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = read(i2c_fd, &id, 1);
    if (ret < 0) {
        perror("Failed to read from sensor ID register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (id != SENSOR_ID_TCS34725) {
        fprintf(stderr, "Invalid sensor ID: 0x%02x\n", id);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure sensor
    ret = write(i2c_fd, &SENSOR_REG_ENABLE, 1);
    if (ret < 0) {
        perror("Failed to write to sensor enable register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    ret = write(i2c_fd, &SENSOR_REG_CONFIG, 1);
    if (ret < 0) {
        perror("Failed to write to sensor config register");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header row
    fprintf(csv_file, "timestamp,red,green,blue\n");

    // Main loop
    for (int i = 0; i < MAX_READS && !should_exit; i++) {
        // Start integration
        ret = write(i2c_fd, &SENSOR_REG_ENABLE, 1);
        if (ret < 0) {
            perror("Failed to write to sensor enable register");
            continue;
        }

        // Wait for integration time
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = READ_INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);

        // Read sensor values
        ret = write(i2c_fd, &SENSOR_REG_ENABLE, 1);
        if (ret < 0) {
            perror("Failed to write to sensor enable register");
            continue;
        }

        ret = read(i2c_fd, &red, 2);
        if (ret < 0) {
            perror("Failed to read from sensor red register");
            continue;
        }

        ret = read(i2c_fd, &green, 2);
        if (ret < 0) {
            perror("Failed to read from sensor green register");
            continue;
        }

        ret = read(i2c_fd, &blue, 2);
        if (ret < 0) {
            perror("Failed to read from sensor blue register");
            continue;
        }

        ret = read(i2c_fd, &clear, 2);
        if (ret < 0) {
            perror("Failed to read from sensor clear register");
            continue;
        }

        // Write to CSV file
        now = time(NULL);
        fprintf(csv_file, "%ld,%d,%d,%d\n", now, red, green, blue);

        // Sleep for a bit
        sleep(1);
    }

    // Close CSV file
    fclose(csv_file);

    // Close I2C bus
    close(i2c_fd);

    return EXIT_SUCCESS;
}

