        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

static void start_video_capture(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_CAPTURE_INTERVAL);
    if (system(command) != 0) {
        fprintf(stderr, "Error starting video capture: %s\n", command);
        exit(1);
    }
}

int main() {
    struct timespec last_trigger_time;
    struct timespec current_time;
    struct tm *tm_info;
    char timestamp[20];
    char filename[100];
    int debounced = 0;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize gpiod
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (gpiod_line == -1) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        exit(1);
    }

    if (gpiod_line_request_input(gpiod_line, "motion_sensor") != 0) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(gpiod_chip, gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(1);
    }

    // Main loop
    while (1) {
        int value = gpiod_line_get_value(gpiod_line);
        if (value == 0) { // Motion detected
            if (debounced == 0) {
                debounced = 1;
                clock_gettime(CLOCK_MONOTONIC, &last_trigger_time);
                start_video_capture(filename);
                tm_info = localtime(&last_trigger_time.tv_sec);
                strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", tm_info);
                fprintf(log_file, "%s\n", timestamp);
            }
        } else {
            debounced = 0;
        }

        // Debounce
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_sec - last_trigger_time.tv_sec > 0) {
            debounced = 0;
        }
    }

    // Close log file
    fclose(log_file);

    // Release resources
    gpiod_line_release(gpiod_chip, gpiod_line);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

