#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define MPU6050_I2C_ADDR 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_XOUT_L 0x3C
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_YOUT_L 0x3E
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_ZOUT_L 0x40
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_CONFIG 0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_FS_SEL 0x1C
#define MPU6050_GYRO_FS_SEL 0x1B
#define MPU6050_PWR_MGMT_2 0x6C
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_DEVICE_ID 0x68

#define MAX_RETRIES 3

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int signum) {
    should_exit = 1;
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(signum);
}

void init_mpu6050() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Request I2C line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 23); // SDA
    if (!line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 24); // SCL
    if (!line) {
        perror("Failed to get SCL line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_bulk(line, "mpu6050", GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN);
    if (ret) {
        perror("Failed to request I2C lines");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set I2C speed
    ret = ioctl(i2c_fd, I2C_SET_SPEED, 400000);
    if (ret) {
        perror("Failed to set I2C speed");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Wake up and configure MPU6050
    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_PWR_MGMT_1, 0x00);
        if (ret < 0) {
            perror("Failed to wake up MPU6050");
            continue;
        }

        ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_CONFIG, 0x00);
        if (ret < 0) {
            perror("Failed to configure MPU6050");
            continue;
        }

        ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_GYRO_CONFIG, 0x00);
        if (ret < 0) {
            perror("Failed to configure MPU6050");
            continue;
        }

        ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_ACCEL_CONFIG, 0x00);
        if (ret < 0) {
            perror("Failed to configure MPU6050");
            continue;
        }

        ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_ACCEL_FS_SEL, 0x00);
        if (ret < 0) {
            perror("Failed to configure MPU6050");
            continue;
        }

        ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_GYRO_FS_SEL, 0x00);
        if (ret < 0) {
            perror("Failed to configure MPU6050");
            continue;
        }

        ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_PWR_MGMT_2, 0x00);
        if (ret < 0) {
            perror("Failed to configure MPU6050");
            continue;
        }

        ret = i2c_smbus_read_byte_data(i2c_fd, MPU6050_WHO_AM_I);
        if (ret == MPU6050_DEVICE_ID) {
            break;
        }

        usleep(100000); // Wait for 100ms
    }

    if (i == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize MPU6050\n");
        close(i2c_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data() {
    uint8_t data[14];
    int ret;

    for (int i = 0; i < 14; i++) {
        ret = i2c_smbus_read_byte_data(i2c_fd, MPU6050_GYRO_XOUT_H + i);
        if (ret < 0) {
            perror("Failed to read gyro data");
            return;
        }
        data[i] = ret;
    }

    uint16_t x = (data[0] << 8) | data[1];
    uint16_t y = (data[2] << 8) | data[3];
