#define GPIO4 4
#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define LOG_FILE "irrigation_log.txt"
#define INTERVAL 5

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Exiting due to signal %d\n", signum);
    exit(EXIT_FAILURE);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO pins
    struct gpiod_line *lines[4];
    lines[0] = gpiod_chip_get_line(gpiod_ctx, GPIO4);
    lines[1] = gpiod_chip_get_line(gpiod_ctx, GPIO17);
    lines[2] = gpiod_chip_get_line(gpiod_ctx, GPIO27);
    lines[3] = gpiod_chip_get_line(gpiod_ctx, GPIO22);

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "irrigation", 1) < 0) {
            perror("Failed to request GPIO line");
            gpiod_line_release(lines[i]);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(gpiod_ctx);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
    }

    while (1) {
        // Generate random moisture value
        int moisture = rand() % 100 + 1;

        // Determine relay state
        int relay_state[4] = {1, 1, 1, 1};
        if (moisture < 30) {
            relay_state[0] = 0;
            relay_state[1] = 0;
            relay_state[2] = 0;
            relay_state[3] = 0;
        }

        // Write to log file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%d, %d, %d, %d, %s\n", moisture, relay_state[0], relay_state[1], relay_state[2], relay_state[3], timestamp);

        // Set GPIO pins
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], relay_state[i]) < 0) {
                perror("Failed to set GPIO line value");
                gpiod_line_release(lines[i]);
                for (int j = 0; j < i; j++) {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(gpiod_ctx);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
        }

        // Sleep for 5 seconds
        sleep(INTERVAL);
    }

    // Close GPIO pins and log file
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return 0;
}

