#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define GPIO_ALARM 27
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 500
#define LOG_FILE "freefall.log"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%3.3f,%3.3f,%3.3f\n"

static int i2c_fd;
static int gpio_alarm_fd;
static int alarm_state = 0;
static int freefall_count = 0;
static struct timespec last_freefall_time;
static struct timespec current_time;

static void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_alarm_fd >= 0) {
        gpio_set_value(gpio_alarm_fd, 0);
        close(gpio_alarm_fd);
    }
    exit(0);
}

static void log_freefall(float x, float y, float z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, LOG_FORMAT, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, x, y, z);
    fclose(log_file);
}

static int read_accelerometer(float *x, float *y, float *z) {
    uint8_t buffer[6];
    if (ioctl(i2c_fd, I2C_RDWR, 1) < 0) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }
    if (write(i2c_fd, &I2C_ADDR, 1) < 0) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }
    if (read(i2c_fd, buffer, 6) < 0) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }
    *x = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
    *y = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    *z = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    *x = *x / 256.0;
    *y = *y / 256.0;
    *z = *z / 256.0;
    return 0;
}

static int check_freefall() {
    float x, y, z;
    if (read_accelerometer(&x, &y, &z) < 0) {
        return -1;
    }
    if (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD) {
        if (alarm_state == 0) {
            alarm_state = 1;
            gpio_set_value(gpio_alarm_fd, 1);
            clock_gettime(CLOCK_MONOTONIC, &last_freefall_time);
        }
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_sec - last_freefall_time.tv_sec >= 0.5) {
            if (read_accelerometer(&x, &y, &z) < 0) {
                return -1;
            }
            if (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD) {
                freefall_count++;
                log_freefall(x, y, z);
                alarm_state = 0;
                gpio_set_value(gpio_alarm_fd, 0);
            }
        }
    } else {
        alarm_state = 0;
        gpio_set_value(gpio_alarm_fd, 0);
    }
    return 0;
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        return 1;
    }

    if ((gpio_alarm_fd = gpio_open(GPIO_ALARM, GPIO_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO alarm\n");
        close(i2c_fd);
        return 1;
    }

    gpio_set_value(gpio_alarm_fd, 0);

    while (1) {
        if (check_freefall() < 0) {
            fprintf(stderr, "Failed to read accelerometer\n");
            close(i2c_fd);
            gpio_close(gpio_alarm_fd);
            return 1;
        }
        usleep(100000);
    }

    close(i2c_fd);
    gpio_close(gpio_alarm_fd);
    return 0;
}

