#include <errno.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 4000  // 4 meters in cm
#define TIMEOUT_MS 100
#define MAX_PULSE_WIDTH 23200  // 23.2 milliseconds in microseconds
#define TICK_PERIOD_NS 1000000000 / 1000  // 100 Hz
#define LOG_FILE "distance_log.txt"

static int gpiod_ctx = -1;
static int trigger_fd = -1;
static int echo_fd = -1;
static struct gpiod_line *trigger_line = NULL;
static struct gpiod_line *echo_line = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line_event *event = NULL;
static struct timespec tick_start;
static struct timespec tick_end;
static struct timespec tick_diff;
static uint32_t tick_counter = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile sig_atomic_t should_exit = 0;

static void sigint_handler(int signum) {
    should_exit = 1;
}

static void log_distance(uint64_t timestamp_ns, int distance_cm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%llu,%d\n", timestamp_ns, distance_cm);
    fclose(file);
}

static void *trigger_callback(void *arg) {
    struct timespec trigger_time;
    struct timespec sleep_time;
    struct timespec remaining_time;

    while (!should_exit) {
        clock_gettime(CLOCK_MONOTONIC, &trigger_time);
        trigger_time.tv_nsec += 1000000;  // 10 microseconds
        if (trigger_time.tv_nsec >= 1000000000) {
            trigger_time.tv_nsec -= 1000000000;
            trigger_time.tv_sec++;
        }

        if (clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &trigger_time, &remaining_time) == 0) {
            if (gpiod_line_set_value(trigger_line, 1) == 0) {
                usleep(200000);  // 200 milliseconds
                gpiod_line_set_value(trigger_line, 0);
            } else {
                perror("Failed to set trigger line high");
            }
        } else {
            perror("Failed to sleep before triggering");
        }
    }

    return NULL;
}

static void *echo_callback(void *arg) {
    struct timespec echo_time;
    struct timespec sleep_time;
    struct timespec remaining_time;
    uint64_t timestamp_ns;
    int distance_cm;

    while (!should_exit) {
        if (gpiod_line_event_read(echo_line, &event) == 0) {
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                clock_gettime(CLOCK_MONOTONIC, &tick_start);
            } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                clock_gettime(CLOCK_MONOTONIC, &tick_end);
                timespec_subtract(&tick_diff, &tick_end, &tick_start);
                timestamp_ns = (uint64_t)tick_diff.tv_sec * 1000000000 + tick_diff.tv_nsec;

                if (tick_diff.tv_nsec > MAX_PULSE_WIDTH) {
                    log_distance(timestamp_ns, -1);  // Invalid pulse width
                } else {
                    distance_cm = (int)(tick_diff.tv_nsec / 58.26);  // 343.2 meters per second, 1 cm = 58.26 ns
                    if (distance_cm > MAX_DISTANCE) {
                        log_distance(timestamp_ns, -1);  // Out of range
                    } else {
                        log_distance(timestamp_ns, distance_cm);
                    }
                }
            }
        } else {
            perror("Failed to read echo line event");
        }
    }

    return NULL;
}

static void timespec_subtract(struct timespec *result, const struct timespec *a, const struct timespec *b) {
    result->tv_sec = a->tv_sec - b->tv_sec;
    result->tv_nsec = a->tv_nsec - b->tv_nsec;
    if (result->tv_nsec < 0) {
        result->tv_sec--;
        result->tv_nsec += 1000000000;
    }
}

int main() {
    struct sigaction sa;
    int ret;

    // Initialize signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_get(gpiod_ctx, "gpiochip0");
    if (!chip) {
        perror("Failed to get GPIO chip");
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret) {
        perror("Failed to request trigger line");
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "echo", 0);
    if (ret) {
        perror("Failed to request echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Initialize tick counter
    clock_gettime(CLOCK_MONOTONIC, &tick_start);
    tick_counter = 0;

    // Start trigger and echo callbacks
    pthread_t trigger_thread;
    pthread_t echo_thread;
    if (pthread_create(&trigger_thread, NULL, trigger_callback, NULL) != 0) {
        perror("Failed to create trigger thread");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    if (pthread_create(&echo_thread, NULL, echo_callback, NULL) != 0) {
        perror("Failed to create echo thread");
        pthread_cancel(trigger_thread);
        pthread_join(trigger_thread, NULL);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(gpiod_ctx);
        return EXIT_FAILURE;
    }

    // Log initial timestamp
    clock_gettime(CLOCK_MONOTONIC, &tick_start);
    log_distance(tick_start.tv_sec * 1000000000 + tick_start.tv_nsec, -1);

    // Wait for termination
    while (!should_exit) {
        usleep(1000000);  // 1 second
    }

    // Cancel threads
    pthread_cancel(trigger_thread);
    pthread_join(trigger_thread, NULL);
    pthread_cancel(echo_thread);
    pthread_join(echo_thread, NULL);

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(gpiod_ctx);

    return EXIT_SUCCESS;
}

