#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <string.h>

#define BUFFER_SIZE 5
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22
#define POLL_INTERVAL 10000000 // 10 ms

static int gpiod_ctx = -1;
static int alert_pin_fd = -1;
static int sensor_pins[3] = {LEFT_SENSOR, CENTER_SENSOR, RIGHT_SENSOR};
static int sensor_values[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;

static void handle_signal(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (alert_pin_fd != -1) {
        close(alert_pin_fd);
    }
    exit(EXIT_SUCCESS);
}

static void init_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    alert_pin_fd = gpiod_line_request_output(gpiod_ctx, "alert", ALERT_PIN, 0);
    if (alert_pin_fd == -1) {
        perror("Failed to request alert pin");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < 3; i++) {
        int line = gpiod_line_request_input(gpiod_ctx, "sensor", sensor_pins[i], 0);
        if (line == -1) {
            perror("Failed to request sensor pin");
            gpiod_chip_close(gpiod_ctx);
            close(alert_pin_fd);
            exit(EXIT_FAILURE);
        }
    }
}

static void log_sensor_reading(int value) {
    sensor_values[buffer_head] = value;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

static void check_sensor_absent() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_values[i] == 0) {
            return;
        }
    }
    printf("All sensors absent\n");
    exit(EXIT_FAILURE);
}

static void check_bus_error() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (sensor_values[i] == -1) {
            printf("Bus error detected\n");
            exit(EXIT_FAILURE);
        }
    }
}

static void drive_robot() {
    int left = 0, center = 0, right = 0;

    while (1) {
        for (int i = 0; i < 3; i++) {
            int value = gpiod_line_get_value(sensor_pins[i]);
            if (value == -1) {
                perror("Failed to read sensor value");
                check_bus_error();
            }
            log_sensor_reading(value);
            if (i == 0) {
                left = value;
            } else if (i == 1) {
                center = value;
            } else {
                right = value;
            }
        }

        if (center == 1) {
            printf("Center sensor detected line\n");
            // Placeholder for motor control function to move forward
            // move_forward();
        } else if (left == 1) {
            printf("Left sensor detected line\n");
            // Placeholder for motor control function to turn left
            // turn_left();
        } else if (right == 1) {
            printf("Right sensor detected line\n");
            // Placeholder for motor control function to turn right
            // turn_right();
        } else {
            printf("All sensors detected no line\n");
            // Placeholder for motor control function to stop
            // stop();
            check_sensor_absent();
        }

        usleep(POLL_INTERVAL);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();

    drive_robot();

    return 0;
}

