#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libgpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define RELAY_PIN 17
#define THRESHOLD 5.0
#define MAX_RETRIES 50
#define TIMEOUT 500000000 // 500ms in nanoseconds

static int i2c_fd;
static int relay_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct timespec last_read;
static FILE *log_file;

void sigint_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (relay_fd >= 0) {
        gpiod_line_set_value(chip, line, 0);
        close(relay_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpiod_chip_close(chip);
    exit(0);
}

void log_error(const char *msg) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, msg);
}

void log_event(const char *msg) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, msg);
}

int read_magnetic_field() {
    uint8_t buffer[2];
    int ret;

    ret = i2c_smbus_read_word_data(i2c_fd, 0x00);
    if (ret < 0) {
        log_error("Failed to read magnetic field data");
        return -1;
    }

    buffer[0] = ret >> 8;
    buffer[1] = ret & 0xFF;

    return (buffer[0] << 8) | buffer[1];
}

int write_register(uint8_t reg, uint8_t value) {
    int ret;

    ret = i2c_smbus_write_byte_data(i2c_fd, reg, value);
    if (ret < 0) {
        log_error("Failed to write to register");
        return -1;
    }

    return 0;
}

int register_clear() {
    int ret;
    uint8_t buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        ret = i2c_smbus_read_word_data(i2c_fd, 0x00);
        if (ret < 0) {
            log_error("Failed to read register");
            return -1;
        }

        buffer[0] = ret >> 8;
        buffer[1] = ret & 0xFF;

        if (buffer[0] == 0 && buffer[1] == 0) {
            return 0;
        }

        usleep(TIMEOUT);
        retries++;
    }

    log_error("Register did not clear after 50 poll attempts");
    return -1;
}

int main() {
    int ret;
    uint8_t reg_value;
    float magnetic_field;
    struct timespec current_time;

    signal(SIGINT, sigint_handler);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    ret = gpiod_line_request_output(line, "relay", 0);
    if (ret < 0) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize log file
    log_file = fopen("magnetic_events.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Set register value
    reg_value = 0x01; // Example register value
    ret = write_register(0x01, reg_value);
    if (ret < 0) {
        log_error("Failed to set register value");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        ret = clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (ret < 0) {
            log_error("Failed to get current time");
            continue;
        }

        if (current_time.tv_sec - last_read.tv_sec >= 1) {
            magnetic_field = read_magnetic_field();
            if (magnetic_field < 0) {
                continue;
            }

            log_event("Magnetic field: %.2f mT", magnetic_field);

            if (magnetic_field > THRESHOLD) {
                gpiod_line_set_value(chip, line, 1);
                log_event("Relay activated");
            } else {
                gpiod_line_set_value(chip, line, 0);
                log_event("Relay deactivated");
            }

            last_read = current_time;
        }

        usleep(100000); // 100ms
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

