#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static int gpiod_handle = -1;
static int socket_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char timestamp[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

static void handle_signal(int signum) {
    if (gpiod_handle != -1) {
        gpiod_line_release(gpiod_handle, GPIO_PIN);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void init_gpio() {
    int ret;

    gpiod_handle = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_handle < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(gpiod_handle, GPIO_PIN, 0);
    if (gpiod_line_is_requested(gpiod_handle, GPIO_PIN) != 1) {
        perror("Failed to request GPIO pin");
        gpiod_chip_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }
}

static void init_socket() {
    struct sockaddr_in server_addr;

    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    if (listen(socket_fd, 5) < 0) {
        perror("Failed to listen on socket");
        close(socket_fd);
        exit(EXIT_FAILURE);
    }
}

static void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while ((bytes_read = read(client_fd, buffer, BUFFER_SIZE - 1)) > 0) {
        buffer[bytes_read] = '\0';
        char *trimmed = strtrim(buffer);
        if (strcmp(trimmed, "ON") == 0) {
            log_event("Relay turned ON");
            gpiod_line_set_value(gpiod_handle, GPIO_PIN, 1);
        } else if (strcmp(trimmed, "OFF") == 0) {
            log_event("Relay turned OFF");
            gpiod_line_set_value(gpiod_handle, GPIO_PIN, 0);
        } else {
            log_event("Invalid command received: %s", trimmed);
        }
        free(trimmed);
    }

    close(client_fd);
}

static char *strtrim(const char *str) {
    if (str == NULL) {
        return NULL;
    }

    char *start = str;
    char *end = str + strlen(str) - 1;

    while (start <= end && isspace((unsigned char)*start)) {
        start++;
    }
    while (end >= start && isspace((unsigned char)*end)) {
        end--;
    }

    if (start > end) {
        return strdup("");
    }

    char *result = malloc(end - start + 2);
    if (result == NULL) {
        return NULL;
    }

    strncpy(result, start, end - start + 1);
    result[end - start + 1] = '\0';

    return result;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_socket();

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(socket_fd);
        gpiod_chip_close(gpiod_handle);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);

    while (1) {
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Failed to accept connection");
            continue;
        }

        handle_client(client_fd);
    }

    fclose(log_file);
    close(socket_fd);
    gpiod_chip_close(gpiod_handle);

    return 0;
}

