#define SLF3S1300F_ADDR1 0x48
#define SLF3S1300F_ADDR2 0x49
#define GPIO_RELAY 18
#define CRC8_POLYNOMIAL 0x07
#define CRC8_INITIAL_VALUE 0xFF
#define CRC8_FINAL_XOR 0x00
#define POLL_INTERVAL 100
#define MIN_FLOW 5.0

static int gpiod_chip = -1;
static int gpiod_line = -1;
static int i2c_bus = -1;
static int i2c_fd1 = -1;
static int i2c_fd2 = -1;

static void handle_signal(int signum) {
    if (gpiod_line != -1) {
        gpiod_line_release(gpiod_chip, gpiod_line);
    }
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    printf("Shutting down...\n");
    exit(0);
