static void log_flow(float flow, const char *sensor_name) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *file = fopen("flow_log.txt", "a");
    if (file == NULL) {
        perror("Failed to open flow_log.txt");
        return;
    }
    fprintf(file, "%s, %s, %.2f\n", timestamp, sensor_name, flow);
    fclose(file);
}

static int crc8(const unsigned char *data, size_t length) {
    int crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor(int i2c_fd, unsigned char *data, size_t length) {
    if (write(i2c_fd, data, length) != length) {
        perror("Failed to write to sensor");
        return -1;
    }
