#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL_MS 200
#define RAIN_DETECTION_THRESHOLD 3

static int gpiod_ctx = -1;
static int motor_ena_pin = -1;
static int motor_in1_pin = -1;
static int motor_in2_pin = -1;
static int rain_detected = 0;
static int consecutive_dry_polls = 0;

static void handle_signal(int signum) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    gpio_set_value(motor_ena_pin, 0);
    gpio_set_value(motor_in1_pin, 0);
    gpio_set_value(motor_in2_pin, 0);
    gpio_close(gpiod_ctx);
    closelog();
    exit(EXIT_SUCCESS);
}

static void setup_gpio() {
    gpiod_ctx = gpiochip_open_by_name("gpiochip0");
    if (gpiod_ctx < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    motor_ena_pin = gpiochip_get_line(gpiod_ctx, MOTOR_ENA_PIN);
    motor_in1_pin = gpiochip_get_line(gpiod_ctx, MOTOR_IN1_PIN);
    motor_in2_pin = gpiochip_get_line(gpiod_ctx, MOTOR_IN2_PIN);

    if (gpiochip_line_request_output(motor_ena_pin, "motor_ena", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d: %s", MOTOR_ENA_PIN, strerror(errno));
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiochip_line_request_output(motor_in1_pin, "motor_in1", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d: %s", MOTOR_IN1_PIN, strerror(errno));
        gpiochip_line_release(motor_ena_pin);
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    if (gpiochip_line_request_output(motor_in2_pin, "motor_in2", 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO %d: %s", MOTOR_IN2_PIN, strerror(errno));
        gpiochip_line_release(motor_ena_pin);
        gpiochip_line_release(motor_in1_pin);
        gpiochip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    gpiochip_line_config(motor_ena_pin, GPIO_LINE_CONFIG_OUTPUT_ACTIVE_LOW);
    gpiochip_line_config(motor_in1_pin, GPIO_LINE_CONFIG_OUTPUT_ACTIVE_LOW);
    gpiochip_line_config(motor_in2_pin, GPIO_LINE_CONFIG_OUTPUT_ACTIVE_LOW);

    gpiochip_line_request_input(GPIO_PIN, "rain_sensor", GPIO_LINE_CONFIG_INPUT_PULL_UP);
}

static void close_gpio() {
    gpiochip_line_release(motor_ena_pin);
    gpiochip_line_release(motor_in1_pin);
    gpiochip_line_release(motor_in2_pin);
    gpiochip_close(gpiod_ctx);
}

static void start_motor() {
    gpio_set_value(motor_ena_pin, 1);
    gpio_set_value(motor_in1_pin, 1);
    gpio_set_value(motor_in2_pin, 0);
    usleep(5000000); // 5 seconds
    gpio_set_value(motor_ena_pin, 0);
    gpio_set_value(motor_in1_pin, 0);
    gpio_set_value(motor_in2_pin, 0);
}

static void check_rain() {
    int current_state = gpiochip_line_get_value(GPIO_PIN);
    if (current_state == 0 && rain_detected == 0) {
        syslog(LOG_INFO, "Rain detected!");
        rain_detected = 1;
        start_motor();
    } else if (current_state == 1 && rain_detected == 1) {
        syslog(LOG_INFO, "Rain stopped.");
        rain_detected = 0;
        consecutive_dry_polls = 0;
    } else if (current_state == 0 && rain_detected == 1) {
        consecutive_dry_polls++;
        if (consecutive_dry_polls >= RAIN_DETECTION_THRESHOLD) {
            syslog(LOG_INFO, "No rain detected for %d consecutive polls, stopping motor.", RAIN_DETECTION_THRESHOLD);
            rain_detected = 0;
            consecutive_dry_polls = 0;
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    openlog("rain_window", LOG_PID, LOG_USER);

    setup_gpio();

    syslog(LOG_INFO, "Rain window system started.");

    while (1) {
        check_rain();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    close_gpio();
    closelog();

    return EXIT_SUCCESS;
}

