static int lock_button_fd = -1;
static int unlock_button_fd = -1;

static void sigint_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (lock_button_fd != -1) {
        close(lock_button_fd);
    }
    if (unlock_button_fd != -1) {
        close(unlock_button_fd);
    }
    printf("Exiting...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize GPIO context
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for servo and buttons
    struct gpiod_line *servo_line = gpiod_chip_get_line(gpiod_ctx, SERVO_PIN);
    struct gpiod_line *lock_button_line = gpiod_chip_get_line(gpiod_ctx, LOCK_BUTTON_PIN);
    struct gpiod_line *unlock_button_line = gpiod_chip_get_line(gpiod_ctx, UNLOCK_BUTTON_PIN);

    if (gpiod_line_request_input(lock_button_line, "lock_button") != 0 ||
        gpiod_line_request_input(unlock_button_line, "unlock_button") != 0) {
        perror("Failed to request lines");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

