    if (gpiod_line_set_value(lock_button_line, 1) != 0 ||
        gpiod_line_set_value(unlock_button_line, 1) != 0) {
        perror("Failed to set pull-up resistors");
        gpiod_line_release(lock_button_line);
        gpiod_line_release(unlock_button_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

