#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL 100
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S"

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

static void sig_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, POLL_INTERVAL * 1000000};
    struct timespec start_time, end_time;
    struct tm *timeinfo;
    char timestamp[20];
    int result;

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize gpiod library
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    int pir_line = gpiod_line_request_input(gpiod_ctx, "PIR", PIR_PIN);
    if (pir_line < 0) {
        perror("Failed to request PIR line");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int relay_line = gpiod_line_request_output(gpiod_ctx, "RELAY", RELAY_PIN, 0);
    if (relay_line < 0) {
        perror("Failed to request RELAY line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Wait for rising edge on PIR line
        result = gpiod_line_event_wait(pir_line, &sleep_time);
        if (result < 0) {
            perror("Failed to wait for PIR event");
            break;
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &start_time);
        timeinfo = localtime(&start_time.tv_sec);
        strftime(timestamp, sizeof(timestamp), LOG_FORMAT, timeinfo);

        // Activate floodlight
        result = gpiod_line_set_value(relay_line, 1);
        if (result < 0) {
            perror("Failed to activate floodlight");
            break;
        }

        // Wait for 60 seconds
        sleep(60);

        // Get current time
        clock_gettime(CLOCK_REALTIME, &end_time);
        timeinfo = localtime(&end_time.tv_sec);
        strftime(timestamp, sizeof(timestamp), LOG_FORMAT, timeinfo);

        // Deactivate floodlight
        result = gpiod_line_set_value(relay_line, 0);
        if (result < 0) {
            perror("Failed to deactivate floodlight");
            break;
        }

        // Append log entry
        fprintf(log_file, "%s, %d\n", timestamp, (int)(end_time.tv_sec - start_time.tv_sec));
        if (ferror(log_file)) {
            perror("Failed to write to log file");
            break;
        }
    }

    // Clean up
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return 0;
}

