#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <gpiod.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define LOG_USER 1

static int gpiod_ctx = -1;
static int socket_fd = -1;
static FILE *log_file = NULL;

static void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_USER, format, args);
    va_end(args);
    if (log_file) {
        fprintf(log_file, "%s", asctime(localtime(&time(NULL))));
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
}

static void handle_signal(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (socket_fd != -1) {
        close(socket_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    syslog(LOG_USER, "Received signal %d, exiting gracefully", signum);
    exit(0);
}

static void setup_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        log_message("Failed to open GPIO chip: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
    struct gpiod_line *servo_line = gpiod_chip_get_line(gpiod_ctx, SERVO_PIN);
    if (servo_line == NULL) {
        log_message("Failed to get GPIO line %d: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
    int flags = GPIOD_LINE_REQUEST_OUTPUT;
    int ret = gpiod_line_request_output(servo_line, "servo", flags);
    if (ret != 0) {
        log_message("Failed to request GPIO line %d as output: %s", SERVO_PIN, strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
    struct gpiod_line *pir_line = gpiod_chip_get_line(gpiod_ctx, PIR_PIN);
    if (pir_line == NULL) {
        log_message("Failed to get GPIO line %d: %s", PIR_PIN, strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
    flags = GPIOD_LINE_REQUEST_INPUT;
    ret = gpiod_line_request_input(pir_line, "pir");
    if (ret != 0) {
        log_message("Failed to request GPIO line %d as input: %s", PIR_PIN, strerror(errno));
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

