        return;
    }
    usleep(120000); // Wait for conversion to complete
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        log_error("Failed to read lux data from BH1750");
        return;
    }
    int lux = (data[0] << 8) | data[1];
    log_lux_reading(lux);
}

static void control_relay(int lux) {
    if (lux < 150) {
        gpiod_line_set_value(relay_line, 1);
    } else {
        gpiod_line_set_value(relay_line, 0);
    }
}

