#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <mosquitto.h>

#define GPIO_PIN 17
#define MQTT_TOPIC "home/lights/control"
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define LOG_TAG "mqtt_relay"

static struct mosquitto *mosq;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int gpio_fd;
static int mqtt_connected = 0;

static void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (mosq) {
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        closelog();
        exit(EXIT_SUCCESS);
    }
}

static void log_event(int level, const char *tag, const char *message) {
    syslog(level, "%s: %s", tag, message);
}

static void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        mqtt_connected = 1;
        log_event(LOG_INFO, LOG_TAG, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_event(LOG_ERR, LOG_TAG, "Failed to connect to MQTT broker");
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->payloadlen == 0) {
        log_event(LOG_ERR, LOG_TAG, "Received empty payload");
        return;
    }

    const char *payload = (const char *)msg->payload;
    if (strcmp(payload, "ON") == 0) {
        log_event(LOG_INFO, LOG_TAG, "Received ON command");
        gpiod_line_set_value(line, 1);
    } else if (strcmp(payload, "OFF") == 0) {
        log_event(LOG_INFO, LOG_TAG, "Received OFF command");
        gpiod_line_set_value(line, 0);
    } else {
        log_event(LOG_ERR, LOG_TAG, "Received invalid payload");
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    mqtt_connected = 0;
    log_event(LOG_INFO, LOG_TAG, "Disconnected from MQTT broker");
}

static void on_subscribe(struct mosquitto *mosq, void *userdata, int mid, int qos_count, const int *granted_qos) {
    log_event(LOG_INFO, LOG_TAG, "Subscribed to MQTT topic");
}

static void on_unsubscribe(struct mosquitto *mosq, void *userdata, int mid) {
    log_event(LOG_INFO, LOG_TAG, "Unsubscribed from MQTT topic");
}

static void on_publish(struct mosquitto *mosq, void *userdata, int mid) {
    log_event(LOG_INFO, LOG_TAG, "Published message");
}

static void on_error(struct mosquitto *mosq, void *userdata, int error) {
    log_event(LOG_ERR, LOG_TAG, "MQTT error: %d", error);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    openlog(LOG_TAG, LOG_PID, LOG_USER);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_event(LOG_ERR, LOG_TAG, "Failed to open GPIO chip");
        closelog();
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        log_event(LOG_ERR, LOG_TAG, "Failed to get GPIO line");
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_request_output(line, "relay_controller", 0);
    if (gpio_fd < 0) {
        log_event(LOG_ERR, LOG_TAG, "Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0); // Relay OFF

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_event(LOG_ERR, LOG_TAG, "Failed to create MQTT client");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        mosquitto_lib_cleanup();
        closelog();
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_subscribe_callback_set(mosq, on_subscribe);
    mosquitto_unsubscribe_callback_set(mosq, on_unsubscribe);
    mosquitto_publish_callback_set(mosq, on_publish);
    mosquitto_error_callback_set(mosq, on_error);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE) != MOSQ_ERR_SUCCESS) {
        log_event(LOG_ERR, LOG_TAG, "Failed to connect to MQTT broker");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        closelog();
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (mosquitto_loop(mosq, -1, 1) != MOSQ_ERR_SUCCESS) {
            log_event(LOG_ERR, LOG_TAG, "MQTT loop error");
            sleep(5);
        }
    }

    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    mosquitto_lib_cleanup();
    closelog();

    return EXIT_SUCCESS;
}

