#define SERVO_1_TARGET 1000  // 1000 µs
#define SERVO_2_TARGET 1500  // 1500 µs
#define SERVO_3_TARGET 2000  // 2000 µs
#define SERVO_4_TARGET 500  // 500 µs
#define SERVO_5_TARGET 2500  // 2500 µs

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line[5];
    int ret;

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for PWM
    for (int i = 0; i < 5; i++) {
        line[i] = gpiod_chip_get_line(chip, i);
        if (!line[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Request PWM functionality
    for (int i = 0; i < 5; i++) {
        ret = gpiod_line_request_output(line[i], "servo_pwm", 0);
        if (ret) {
            perror("Failed to request PWM output");
            gpiod_line_release(line[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set PWM period
    for (int i = 0; i < 5; i++) {
        ret = gpiod_line_set_value(line[i], 1);  // Set high to start PWM
        if (ret) {
            perror("Failed to set PWM high");
            gpiod_line_release(line[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        usleep(PWM_PERIOD / 2);  // Wait for half period
        ret = gpiod_line_set_value(line[i], 0);  // Set low to end PWM
        if (ret) {
            perror("Failed to set PWM low");
            gpiod_line_release(line[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set PWM frequency
    for (int i = 0; i < 5; i++) {
        ret = gpiod_line_set_value(line[i], 1);  // Set high to start PWM
        if (ret) {
            perror("Failed to set PWM high");
            gpiod_line_release(line[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        usleep(PWM_PERIOD / 2);  // Wait for half period
        ret = gpiod_line_set_value(line[i], 0);  // Set low to end PWM
        if (ret) {
            perror("Failed to set PWM low");
            gpiod_line_release(line[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set PWM duty cycle for each servo
    for (int i = 0; i < 5; i++) {
        int duty_cycle = (SERVO_1_TARGET - SERVO_MIN) * (PWM_PERIOD / 2) / (SERVO_MAX - SERVO_MIN);
        for (int j = 0; j < duty_cycle; j++) {
            ret = gpiod_line_set_value(line[i], 1);  // Set high to start PWM
            if (ret) {
                perror("Failed to set PWM high");
                gpiod_line_release(line[i]);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
            usleep(PWM_PERIOD / 2);  // Wait for half period
            ret = gpiod_line_set_value(line[i], 0);  // Set low to end PWM
            if (ret) {
                perror("Failed to set PWM low");
                gpiod_line_release(line[i]);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
        }
        usleep(3000000);  // Hold for 3 seconds
    }

    // Clean up
    for (int i = 0; i < 5; i++) {
        gpiod_line_release(line[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}
