        motor_a_output = kp * motor_a_error + ki * motor_a_integral + kd * motor_a_derivative;
        motor_b_output = kp * motor_b_error + ki * motor_b_integral + kd * motor_b_derivative;

        if (motor_a_output < 0) {
            motor_a_output = 0;
        } else if (motor_a_output > 255) {
            motor_a_output = 255;
        }

        if (motor_b_output < 0) {
            motor_b_output = 0;
        } else if (motor_b_output > 255) {
            motor_b_output = 255;
        }

        set_motor_pwm(motor_a_output, motor_a_dir);
        set_motor_pwm(motor_b_output, motor_b_dir);

        if (motor_a_stalled) {
            motor_a_stall_time = time(NULL);
        }

        if (motor_b_stalled) {
            motor_b_stall_time = time(NULL);
        }

        if (motor_a_stall_time > last_time + STALL_TIMEOUT) {
            printf("Motor A stalled\n");
            set_motor_stall(1, 1);
        } else {
            set_motor_stall(1, 0);
        }

        if (motor_b_stall_time > last_time + STALL_TIMEOUT) {
            printf("Motor B stalled\n");
            set_motor_stall(2, 1);
        } else {
            set_motor_stall(2, 0);
        }

        last_time = time(NULL);

        nanosleep(&ts, NULL);
    }

    return NULL;
}

