#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_TTP223 4
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "relay_toggle.log"

static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
    gpio_set_value(GPIO_RELAY, 0);
    gpio_close(gpiochip);
    fclose(logfile);
    fprintf(stderr, "Program terminated by user.\n");
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec sleep_time = {0, 10000000}; // 10ms
    struct timespec debounce_time = {0, DEBOUNCE_DELAY_MS * 1000000}; // 50ms
    struct timespec start_time, end_time;
    time_t now;
    char timestamp[20];
    int gpiochip, line, value, prev_value = -1;
    FILE *logfile;

    // Initialize GPIO
    gpiochip = gpiochip_open_by_name("gpiochip0");
    if (gpiochip < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiochip_get_line(gpiochip, GPIO_TTP223);
    if (line < 0) {
        perror("Failed to get GPIO line");
        gpiochip_close(gpiochip);
        exit(EXIT_FAILURE);
    }

    if (gpio_claim_line(line, GPIO_LINE_REQUEST_FLAG_INPUT) < 0) {
        perror("Failed to claim GPIO line");
        gpiochip_close(gpiochip);
        gpio_line_release(line);
        exit(EXIT_FAILURE);
    }

    if (gpio_export_line(line, 1) < 0) {
        perror("Failed to export GPIO line");
        gpiochip_close(gpiochip);
        gpio_line_release(line);
        exit(EXIT_FAILURE);
    }

    if (gpio_set_value(GPIO_RELAY, 0) < 0) {
        perror("Failed to set initial relay state");
        gpiochip_close(gpiochip);
        gpio_line_release(line);
        gpio_unexport_line(line);
        exit(EXIT_FAILURE);
    }

    logfile = fopen(LOG_FILE, "a");
    if (logfile == NULL) {
        perror("Failed to open log file");
        gpiochip_close(gpiochip);
        gpio_line_release(line);
        gpio_unexport_line(line);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);

    while (!should_exit) {
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
            perror("Failed to get start time");
            continue;
        }

        // Read TTP223 sensor
        value = gpio_get_value(line);
        if (value < 0) {
            perror("Failed to read GPIO line");
            continue;
        }

        // Debounce
        if (value == prev_value) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) < 0) {
                perror("Failed to get end time");
                continue;
            }
            if (end_time.tv_sec - start_time.tv_sec > 0 || (end_time.tv_sec == start_time.tv_sec && end_time.tv_nsec - start_time.tv_nsec >= debounce_time.tv_nsec)) {
                if (value == 1) {
                    if (gpio_set_value(GPIO_RELAY, !gpio_get_value(GPIO_RELAY)) < 0) {
                        perror("Failed to toggle relay");
                        continue;
                    }
                    now = time(NULL);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
                    fprintf(logfile, "%s %s\n", timestamp, gpio_get_value(GPIO_RELAY) ? "ON" : "OFF");
                }
            }
        }

        prev_value = value;

        // Sleep for 10ms
        nanosleep(&sleep_time, NULL);
    }

    fclose(logfile);
    gpio_unexport_line(line);
    gpio_line_release(line);
    gpiochip_close(gpiochip);

    return EXIT_SUCCESS;
}

