#define LOG_FILE "water_flow.log"
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define DEBOUNCE_TIMEOUT 1000000 // 1 second in microseconds
#define LPM_THRESHOLD 5.0
#define HYS_THRESHOLD 4.5

static pthread_mutex_t pulse_mutex;
static int pulse_count = 0;
static int solenoid_state = 1; // Open by default
static FILE *log_file;

static void log_event(const char *event, const char *state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s - %s\n", timestamp, event, state);
}

static void *flow_sensor_thread(void *arg) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line, "flow_sensor");
    if (ret) {
        perror("Failed to request GPIO line input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    struct timespec timeout = {0, DEBOUNCE_TIMEOUT};
    int last_state = 0;
    int pulse_start = 0;

    while (1) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("Failed to read GPIO line value");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (ret != last_state) {
            last_state = ret;
            pulse_start = gpiod_line_get_value(line) ? 1 : 0;
        }

        if (pulse_start && gpiod_line_get_value(line) == 0) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }

        nanosleep(&timeout, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return NULL;
}

static void handle_signal(int sig) {
    log_event("Signal received", sig == SIGINT ? "INT" : "TERM");
    solenoid_state = 1; // Open solenoid
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpiod_chip_close(gpiod_chip_open_by_name("gpiochip0"));
    exit(EXIT_SUCCESS);
}

int main() {
    pthread_t flow_thread;
    struct sigaction sa;

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        pthread_mutex_destroy(&pulse_mutex);
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (pthread_create(&flow_thread, NULL, flow_sensor_thread, NULL) != 0) {
        perror("Failed to create flow sensor thread");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        exit(EXIT_FAILURE);
    }

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        double liters_per_minute = (pulse_count * 60.0) / 1000.0; // 1000 pulses per liter
        pthread_mutex_unlock(&pulse_mutex);

        log_event("LPM", liters_per_minute > LPM_THRESHOLD ? "HIGH" : "LOW");

        if (liters_per_minute > LPM_THRESHOLD && solenoid_state == 1) {
            solenoid_state = 0; // Close solenoid
            log_event("Solenoid", "CLOSED");
        } else if (liters_per_minute < HYS_THRESHOLD && solenoid_state == 0) {
            solenoid_state = 1; // Open solenoid
            log_event("Solenoid", "OPEN");
        }

        sleep(1);
    }

    pthread_join(flow_thread, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpiod_chip_close(gpiod_chip_open_by_name("gpiochip0"));
    return 0;
}

