    int data = 0;
    int attempts = 0;
    int ret;

    while (attempts < timeout) {
        ret = ioctl(gpiod_handle, GPIO_GET_LINEVALUE, data_line);
        if (ret < 0) {
            perror("Failed to read GPIO line value");
            return;
        }

        if (data == 0) {
            break;
        }

        attempts++;
        usleep(1000);
    }

    if (attempts == timeout) {
        fprintf(stderr, "Timeout waiting for HX711 to be ready\n");
        return;
    }

    ret = ioctl(gpiod_handle, GPIO_GET_LINEVALUE, sck_line);
    if (ret < 0) {
        perror("Failed to read GPIO line value");
        return;
    }

    for (int i = 0; i < 24; i++) {
        ret = ioctl(gpiod_handle, GPIO_GET_LINEVALUE, data_line);
        if (ret < 0) {
            perror("Failed to read GPIO line value");
            return;
        }

        data <<= 1;
        if (data_line->value) {
            data |= 1;
        }

        ret = ioctl(gpiod_handle, GPIO_SET_LINEVALUE, sck_line, 1);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
            return;
        }

        ret = ioctl(gpiod_handle, GPIO_SET_LINEVALUE, sck_line, 0);
        if (ret < 0) {
            perror("Failed to set GPIO line value");
            return;
        }
    }

    actual_weight = data;
}

static void load_cell_calibrate() {
    FILE *config_file;
    char line[BUFFER_SIZE];
    char *key, *value;

    config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        fprintf(stderr, "Failed to open config file %s\n", CONFIG_FILE);
        return;
    }

    while (fgets(line, BUFFER_SIZE, config_file)) {
        key = strtok(line, "=");
        value = strtok(NULL, "\n");

        if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atoi(value);
        }
    }

    fclose(config_file);
}

static void servo_init() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode for SERVO");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

static void servo_set_pulse_width(int pulse_width) {
    if (gpioPWM(SERVO_PIN, pulse_width) < 0) {
        perror("Failed to set PWM pulse width for SERVO");
    }
}

static void send_response(int client_fd, const char *response) {
    if (send(client_fd, response, strlen(response), 0) < 0) {
        perror("Failed to send response");
    }
}

static void log_event(const char *event) {
    FILE *log_file;
    json_object *root, *event_obj, *date_obj, *time_obj, *target_weight_obj, *actual_weight_obj, *error_obj;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return;
    }

    root = json_object_new_object();
    event_obj = json_object_new_string(event);
    json_object_object_add(root, "event", event_obj);

    date_obj = json_object_new_string(inet_ntoa(inet_addr("127.0.0.1")));
    json_object_object_add(root, "date", date_obj);

    time_obj = json_object_new_string(ctime(&time(NULL)));
    json_object_object_add(root, "time", time_obj);

    target_weight_obj = json_object_new_int(target_weight);
    json_object_object_add(root, "target_weight", target_weight_obj);

    actual_weight_obj = json_object_new_int(actual_weight);
    json_object_object_add(root, "actual_weight", actual_weight_obj);

    error_obj = json_object_new_string("");
    json_object_object_add(root, "error", error_obj);

    json_object_to_file(log_file, root);
    fclose(log_file);

    json_object_put(root);
}

int main() {
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len;
    char buffer[BUFFER_SIZE];
    int client_fd;
    int ret;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    load_cell_init();
    load_cell_calibrate();
    servo_init();

    sock_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (sock_fd < 0) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(12345);

    ret = bind(sock_fd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (ret < 0) {
        perror("Failed to bind socket");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    ret = listen(sock_fd, 5);
    if (ret < 0) {
        perror("Failed to listen on socket");
        close(sock_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        client_len = sizeof(client_addr);
        client_fd = accept(sock_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Failed to accept connection");
            continue;
        }

        ret = recv(client_fd, buffer, BUFFER_SIZE, 0);
        if (ret < 0) {
            perror("Failed to receive data");
            close(client_fd);
            continue;
        }

        buffer[ret] = '\0';
        target_weight = atoi(buffer);

        servo_set_pulse_width(pulse_width);

        ret = gpioWrite(SERVO_PIN, 1);
        if (ret < 0) {
            perror("Failed to set SERVO pin high");
            close(client_fd);
            continue;
        }

        usleep(1000000);

        ret = gpioWrite(SERVO_PIN, 0);
        if (ret < 0) {
            perror("Failed to set SERVO pin low");
            close(client_fd);
            continue;
        }

        load_cell_read();

        actual_weight = actual_weight * calibration_factor;

        char response[BUFFER_SIZE];
        snprintf(response, BUFFER_SIZE, "{\"actual_weight\": %d}", actual_weight);
        send_response(client_fd, response);

        log_event(response);

        close(client_fd);
    }

    gpioTerminate();
    close(sock_fd);

    return 0;
}
```

### Explanation:

1. **GPIO Initialization**: The program initializes the GPIO pins for the HX711 load cell and the SG90 servo motor using `libgpiod`.

2. **Load Cell Communication**: The `load_cell_read` function reads the load cell data by bit-banging the HX711. It waits for the data line to go low, then reads 24 bits.

3. **Calibration**: The `load_cell_calibrate` function reads the calibration factor from `config.ini`. If the file is missing or malformed, it uses default values.

4. **Servo Initialization**: The `servo_init` function initializes the GPIO pin for the servo motor using `pigpio`.

5. **TCP Server**: The program listens on `127.0.0.1:12345` for incoming connections. It reads the target weight from the client, sets the servo pulse width, dispenses the ingredient, waits for stabilization, reads the actual weight, and sends the response back to the client.

6. **Logging**: Each dispensing event is logged to `dispensing_log.json` in JSON format.

7. **Error Handling**: The program includes error handling for initialization, communication timeouts, API call failures, file I/O problems, and network errors. It also uses signal handlers to ensure a clean shutdown on `SIGINT` and `SIGTERM`.

8. **Resource Management**: The program ensures that all resources are released on exit paths, including closing sockets and terminating GPIO and `pigpio` libraries.

