#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_RELAY 17
#define GPIO_TOUCH 4
#define DEBOUNCE_TIME_DEFAULT 50
#define DEBOUNCE_TIME_MAX 1000

static int gpiod_chip = -1;
static int gpiod_line_touch = -1;
static int gpiod_line_relay = -1;
static int debounce_time = DEBOUNCE_TIME_DEFAULT;
static int relay_state = 0;

static void sigint_handler(int signum) {
    if (gpiod_chip != -1) {
        gpiod_line_touch = gpiod_line_release(gpiod_line_touch);
        gpiod_line_relay = gpiod_line_release(gpiod_line_relay);
        gpiod_chip = gpiod_chip_release(gpiod_chip);
    }
    exit(EXIT_SUCCESS);
}

static void sigterm_handler(int signum) {
    if (gpiod_chip != -1) {
        gpiod_line_touch = gpiod_line_release(gpiod_line_touch);
        gpiod_line_relay = gpiod_line_release(gpiod_line_relay);
        gpiod_chip = gpiod_chip_release(gpiod_chip);
    }
    exit(EXIT_SUCCESS);
}

static void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

static void set_relay_state(int state) {
    if (state) {
        gpiod_line_set_value(gpiod_line_relay, 1);
    } else {
        gpiod_line_set_value(gpiod_line_relay, 0);
    }
    relay_state = state;
    log_relay_state(relay_state);
}

static void debounce_and_toggle_relay(int gpio_value) {
    static int last_gpio_value = -1;
    static struct timespec last_change_time;
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (last_gpio_value == -1) {
        last_gpio_value = gpio_value;
        last_change_time = current_time;
        return;
    }

    if (gpio_value != last_gpio_value) {
        last_gpio_value = gpio_value;
        clock_gettime(CLOCK_MONOTONIC, &last_change_time);
    }

    if (current_time.tv_sec - last_change_time.tv_sec > 0) {
        return;
    }

    if (current_time.tv_sec - last_change_time.tv_sec == 0 &&
        current_time.tv_nsec - last_change_time.tv_nsec >= debounce_time * 1000000) {
        set_relay_state(!relay_state);
    }
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    if (argc > 1 && strcmp(argv[1], "-d") == 0 && argc > 2) {
        debounce_time = atoi(argv[2]);
        if (debounce_time < 0 || debounce_time > DEBOUNCE_TIME_MAX) {
            fprintf(stderr, "Invalid debounce time. Must be between 0 and %d milliseconds.\n", DEBOUNCE_TIME_MAX);
            return EXIT_FAILURE;
        }
    }

    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line_touch = gpiod_chip_get_line(gpiod_chip, GPIO_TOUCH);
    if (gpiod_line_touch == -1) {
        perror("Failed to get GPIO line for touch sensor");
        gpiod_chip_release(gpiod_chip);
        return EXIT_FAILURE;
    }

    gpiod_line_relay = gpiod_chip_get_line(gpiod_chip, GPIO_RELAY);
    if (gpiod_line_relay == -1) {
        perror("Failed to get GPIO line for relay");
        gpiod_line_release(gpiod_line_touch);
        gpiod_chip_release(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(gpiod_line_touch, "touch_sensor") != 0) {
        perror("Failed to request input for touch sensor");
        gpiod_line_release(gpiod_line_relay);
        gpiod_line_release(gpiod_line_touch);
        gpiod_chip_release(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpiod_line_relay, "relay", 0) != 0) {
        perror("Failed to request output for relay");
        gpiod_line_release(gpiod_line_relay);
        gpiod_line_release(gpiod_line_touch);
        gpiod_chip_release(gpiod_chip);
        return EXIT_FAILURE;
    }

    set_relay_state(0);

    while (1) {
        int gpio_value = gpiod_line_get_value(gpiod_line_touch);
        debounce_and_toggle_relay(gpio_value);
        usleep(100000); // Sleep for 100ms
    }

    gpiod_line_release(gpiod_line_relay);
    gpiod_line_release(gpiod_line_touch);
    gpiod_chip_release(gpiod_chip);

    return EXIT_SUCCESS;
}

