#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_PERIOD 20000
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define KEY_INCREMENT 10

static struct termios original_termios;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int pwm_fd;

void restore_termios() {
    tcsetattr(STDIN_FILENO, TCSANOW, &original_termios);
}

void handle_sigint(int signum) {
    if (pwm_fd >= 0) {
        gpiod_line_set_value(line, 0);
        close(pwm_fd);
    }
    restore_termios();
    exit(1);
}

void setup_pwm() {
    pwm_fd = open("/sys/class/pwm/pwmchip0/pwm1", O_WRONLY);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        exit(1);
    }

    struct pwm_config config = {
        .period_ns = PWM_PERIOD,
        .duty_ns = MIN_PULSE_WIDTH,
        .polarity = PWM_POLARITY_NORMAL
    };

    if (ioctl(pwm_fd, PWM_CONFIG, &config) < 0) {
        perror("Failed to configure PWM");
        close(pwm_fd);
        exit(1);
    }
}

void set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Angle out of range: %d\n", angle);
        return;
    }

    int pulse_width = (angle / (float)MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH;
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Pulse width out of range: %d\n", pulse_width);
        return;
    }

    if (ioctl(pwm_fd, PWM_SET_DUTY, pulse_width) < 0) {
        perror("Failed to set PWM duty cycle");
        exit(1);
    }
}

int main() {
    if (gpiod_chip_open_by_name("gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if (gpiod_chip_get_line(chip, SERVO_PIN, &line) < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(line, "servo", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    tcgetattr(STDIN_FILENO, &original_termios);
    struct termios new_termios = original_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VMIN] = 1;
    new_termios.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) < 0) {
        perror("Failed to set terminal attributes");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    signal(SIGINT, handle_sigint);

    setup_pwm();
    set_servo_angle(90);

    while (1) {
        char key;
        if (read(STDIN_FILENO, &key, 1) == 1) {
            if (key == '+') {
                set_servo_angle(MIN_ANGLE + KEY_INCREMENT);
            } else if (key == '-') {
                set_servo_angle(MAX_ANGLE - KEY_INCREMENT);
            } else if (key == 'q') {
                break;
            }
        }
    }

    restore_termios();
    gpiod_line_close(line);
    gpiod_chip_close(chip);
    close(pwm_fd);

    return 0;
}

