    }
}

int main() {
    if (gpiod_chip_open_by_name("gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if (gpiod_chip_get_line(chip, SERVO_PIN, &line) < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(1);
    }

    if (gpiod_line_request_output(line, "servo", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    tcgetattr(STDIN_FILENO, &original_termios);
    struct termios new_termios = original_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VMIN] = 1;
    new_termios.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) < 0) {
        perror("Failed to set terminal attributes");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        exit(1);
    }

    signal(SIGINT, handle_sigint);

    setup_pwm();
    set_servo_angle(90);

    while (1) {
        char key;
        if (read(STDIN_FILENO, &key, 1) == 1) {
            if (key == '+') {
                set_servo_angle(MIN_ANGLE + KEY_INCREMENT);
            } else if (key == '-') {
                set_servo_angle(MAX_ANGLE - KEY_INCREMENT);
            } else if (key == 'q') {
                break;
            }
        }
    }

    restore_termios();
    gpiod_line_close(line);
    gpiod_chip_close(chip);
    close(pwm_fd);

    return 0;
}
