#define RPM_INTERVAL 5000000000  // 5 seconds in nanoseconds
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t should_exit = 0;
static struct timespec last_pulse_time;
static struct timespec current_time;
static struct timespec interval_start;
static struct timespec interval_end;
static struct timespec interval_duration;
static int gpio_fd;
static FILE *log_file;

static void handle_signal(int signum) {
    should_exit = 1;
}

static void init_gpio() {
    const char *chip_name = "gpiochip0";
    const char *line_name = "17";
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line, "motor_rpm");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_set_config(line, GPIO_LINE_CONFIG_INPUT_PULL_UP, 0);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO line pull-up\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_event_open(line, GPIOD_LINE_REQUEST_EVENT_RISING_EDGE);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO line event\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void close_gpio() {
    gpiod_line_event_close(gpio_fd);
    gpiod_line_release(gpio_fd);
    gpiod_chip_close(gpio_fd);
}

static void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
}

static void close_log_file() {
    fclose(log_file);
}

static void calculate_rpm() {
    struct timespec delta;
    double delta_seconds;
    double rpm;

    clock_gettime(CLOCK_MONOTONIC, &current_time);
    delta.tv_sec = current_time.tv_sec - last_pulse_time.tv_sec;
    delta.tv_nsec = current_time.tv_nsec - last_pulse_time.tv_nsec;
    if (delta.tv_nsec < 0) {
        delta.tv_sec--;
        delta.tv_nsec += 1000000000;
    }
    delta_seconds = delta.tv_sec + delta.tv_nsec / 1000000000.0;
    rpm = 60.0 / delta_seconds;
    printf("RPM: %.2f\n", rpm);
    fprintf(log_file, "%s,%.2f\n", ctime(&current_time.tv_sec), rpm);
    fflush(log_file);
}

static void main_loop() {
    struct timespec timeout;
    int ret;

    clock_gettime(CLOCK_MONOTONIC, &interval_start);
    while (!should_exit) {
        timeout.tv_sec = 0;
        timeout.tv_nsec = RPM_INTERVAL;
        ret = gpiod_line_event_wait(gpio_fd, &timeout);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for GPIO line event\n");
            should_exit = 1;
        } else if (ret == 0) {
            // Timeout occurred, calculate RPM
            calculate_rpm();
            clock_gettime(CLOCK_MONOTONIC, &interval_end);
            interval_duration.tv_sec = interval_end.tv_sec - interval_start.tv_sec;
            interval_duration.tv_nsec = interval_end.tv_nsec - interval_start.tv_nsec;
            if (interval_duration.tv_nsec < 0) {
                interval_duration.tv_sec--;
                interval_duration.tv_nsec += 1000000000;
            }
            if (interval_duration.tv_sec >= 5) {
                interval_start = interval_end;
            }
        } else {
            // Rising edge detected, update last pulse time
            clock_gettime(CLOCK_MONOTONIC, &last_pulse_time);
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_log_file();

    main_loop();

    close_gpio();
    close_log_file();

    return 0;
}

