#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_TTP223 4
#define GPIO_RELAY 17
#define POLL_INTERVAL_MS 50
#define TIMEOUT_MS 10000

volatile sig_atomic_t exit_flag = 0;

static void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line_ttp223, *line_relay;
    struct gpiod_line_request request;
    struct timespec timeout;
    int state = 0;
    int relay_state = 0;
    int count = 0;

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line_ttp223 = gpiod_chip_get_line(chip, GPIO_TTP223);
    if (!line_ttp223) {
        perror("Failed to get GPIO line for TTP223");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line_relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line_relay) {
        perror("Failed to get GPIO line for relay");
        gpiod_line_release(line_ttp223);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request lines
    request.flags = GPIOD_LINE_REQUEST_FLAG_INPUT;
    ret = gpiod_line_request_input(line_ttp223, "TTP223", &request);
    if (ret) {
        perror("Failed to request GPIO line for TTP223");
        gpiod_line_release(line_ttp223);
        gpiod_line_release(line_relay);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    request.flags = GPIOD_LINE_REQUEST_FLAG_OUTPUT;
    ret = gpiod_line_request_output(line_relay, "Relay", &request);
    if (ret) {
        perror("Failed to request GPIO line for relay");
        gpiod_line_release(line_ttp223);
        gpiod_line_release(line_relay);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set initial state of relay
    relay_state = 0;
    ret = gpiod_line_set_value(line_relay, relay_state);
    if (ret) {
        perror("Failed to set initial relay state");
        gpiod_line_release(line_ttp223);
        gpiod_line_release(line_relay);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!exit_flag) {
        // Read TTP223 state
        ret = gpiod_line_get_value(line_ttp223);
        if (ret == -1) {
            perror("Failed to read TTP223 state");
            gpiod_line_release(line_ttp223);
            gpiod_line_release(line_relay);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Check if TTP223 is pressed
        if (ret == 1) {
            count++;
            if (count >= TIMEOUT_MS / POLL_INTERVAL_MS) {
                // Force relay OFF if sensor remains HIGH for more than 10 seconds
                relay_state = 0;
                ret = gpiod_line_set_value(line_relay, relay_state);
                if (ret) {
                    perror("Failed to set relay state");
                    gpiod_line_release(line_ttp223);
                    gpiod_line_release(line_relay);
                    gpiod_chip_close(chip);
                    exit(EXIT_FAILURE);
                }
            }
        } else {
            count = 0;
        }

        // Toggle relay state on rising edge of TTP223
        if (state != ret) {
            relay_state = !relay_state;
            ret = gpiod_line_set_value(line_relay, relay_state);
            if (ret) {
                perror("Failed to set relay state");
                gpiod_line_release(line_ttp223);
                gpiod_line_release(line_relay);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
            state = ret;
        }

        // Sleep for POLL_INTERVAL_MS
        timeout.tv_sec = POLL_INTERVAL_MS / 1000;
        timeout.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000;
        ret = nanosleep(&timeout, NULL);
        if (ret) {
            perror("Failed to sleep");
            gpiod_line_release(line_ttp223);
            gpiod_line_release(line_relay);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Release resources
    gpiod_line_release(line_ttp223);
    gpiod_line_release(line_relay);
    gpiod_chip_close(chip);

    return 0;
}

