    static uint32_t last_tick = 0;
    uint32_t delta_ticks = tick - last_tick;
    last_tick = tick;
    flow_rate = (1000000 / delta_ticks) * 60; // Convert to L/min
    fprintf(flow_fd, "%lu,%d,%d\n", time(NULL) * 1000, flow_rate, valve_position);
}

