#define IN1 24
#define IN2 25
#define ENB 12
#define IN3 16
#define IN4 20
#define A1 5
#define B1 6
#define A2 26
#define B2 19
#define SAMPLE_TIME 100000
#define PWM_FREQ 100
#define RPM_TARGET 60
#define LOG_FILE "motor_log.csv"

static int chip_fd;
static pthread_t encoder_thread1, encoder_thread2;
static pthread_mutex_t encoder_mutex1, encoder_mutex2;
static int encoder_count1 = 0, encoder_count2 = 0;
static int encoder_direction1 = 0, encoder_direction2 = 0;
static int pid_output = 0;
static FILE *log_file;

static void *encoder_thread1_func(void *arg) {
    struct gpiod_line *line_a1, *line_b1;
    int value_a1, value_b1;
    int last_value_a1 = 0, last_value_b1 = 0;
    struct timespec sleep_time;

    line_a1 = gpiod_chip_get_line(chip_fd, A1);
    line_b1 = gpiod_chip_get_line(chip_fd, B1);
    gpiod_line_request_edge_event(line_a1, "encoder1_a", GPIOD_EDGE_BOTH);
    gpiod_line_request_edge_event(line_b1, "encoder1_b", GPIOD_EDGE_BOTH);

    while (1) {
        gpiod_line_event_wait(line_a1, &sleep_time);
        gpiod_line_event_wait(line_b1, &sleep_time);

        value_a1 = gpiod_line_get_value(line_a1);
        value_b1 = gpiod_line_get_value(line_b1);

        if (value_a1 != last_value_a1) {
            if (value_b1 != last_value_b1) {
                encoder_direction1 = (value_a1 == value_b1) ? 1 : -1;
            }
            last_value_a1 = value_a1;
        }

        if (value_b1 != last_value_b1) {
            last_value_b1 = value_b1;
        }

        pthread_mutex_lock(&encoder_mutex1);
        encoder_count1 += encoder_direction1;
        pthread_mutex_unlock(&encoder_mutex1);
    }

    gpiod_line_release(line_a1);
    gpiod_line_release(line_b1);
    return NULL;
}

static void *encoder_thread2_func(void *arg) {
    struct gpiod_line *line_a2, *line_b2;
    int value_a2, value_b2;
    int last_value_a2 = 0, last_value_b2 = 0;
    struct timespec sleep_time;

    line_a2 = gpiod_chip_get_line(chip_fd, A2);
    line_b2 = gpiod_chip_get_line(chip_fd, B2);
    gpiod_line_request_edge_event(line_a2, "encoder2_a", GPIOD_EDGE_BOTH);
    gpiod_line_request_edge_event(line_b2, "encoder2_b", GPIOD_EDGE_BOTH);

    while (1) {
        gpiod_line_event_wait(line_a2, &sleep_time);
        gpiod_line_event_wait(line_b2, &sleep_time);

        value_a2 = gpiod_line_get_value(line_a2);
        value_b2 = gpiod_line_get_value(line_b2);

        if (value_a2 != last_value_a2) {
            if (value_b2 != last_value_b2) {
                encoder_direction2 = (value_a2 == value_b2) ? 1 : -1;
            }
            last_value_a2 = value_a2;
        }

        if (value_b2 != last_value_b2) {
            last_value_b2 = value_b2;
        }

        pthread_mutex_lock(&encoder_mutex2);
        encoder_count2 += encoder_direction2;
        pthread_mutex_unlock(&encoder_mutex2);
    }

    gpiod_line_release(line_a2);
    gpiod_line_release(line_b2);
    return NULL;
}

static void pid_control() {
    static int last_error = 0;
    static int integral = 0;
    static int previous_output = 0;
    int error, derivative;

    error = RPM_TARGET - (encoder_count1 + encoder_count2) / 2;
    integral += error;
    derivative = error - last_error;

    pid_output = (int)(0.1 * error + 0.01 * integral + 0.001 * derivative);

    last_error = error;
}

static void set_motor_speed(int speed) {
    int duty_cycle = (speed * PWM_FREQ) / RPM_TARGET;
    gpio_export(ENA1, GPIOF_OUT_INIT_LOW);
    gpio_export(ENA2, GPIOF_OUT_INIT_LOW);
    gpio_set_value(ENA1, duty_cycle > 0);
