        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip_fd, IN4);
    if (!line) {
        perror("Failed to get GPIO line IN4");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip_fd, A1);
    if (!line) {
        perror("Failed to get GPIO line A1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip_fd, B1);
    if (!line) {
        perror("Failed to get GPIO line B1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip_fd, A2);
    if (!line) {
        perror("Failed to get GPIO line A2");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip_fd, B2);
    if (!line) {
        perror("Failed to get GPIO line B2");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&encoder_mutex1, NULL);
    pthread_mutex_init(&encoder_mutex2, NULL);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Time,RPM1,RPM2,P,I,D,Output\n");
    fflush(log_file);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pthread_create(&encoder_thread1, NULL, encoder_thread1_func, NULL);
    pthread_create(&encoder_thread2, NULL, encoder_thread2_func, NULL);

    while (1) {
        pid_control();
        set_motor_speed(pid_output);

        pthread_mutex_lock(&encoder_mutex1);
        int rpm1 = (encoder_count1 + encoder_count2) / 2;
        pthread_mutex_unlock(&encoder_mutex1);

        pthread_mutex_lock(&encoder_mutex2);
        int rpm2 = (encoder_count1 + encoder_count2) / 2;
        pthread_mutex_unlock(&encoder_mutex2);

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double time = now.tv_sec + now.tv_nsec / 1e9;

        fprintf(log_file, "%.6f,%d,%d,%d,%d,%d\n", time, rpm1, rpm2, pid_output, pid_output, pid_output);
        fflush(log_file);

        usleep(SAMPLE_TIME);
    }

    pthread_join(encoder_thread1, NULL);
    pthread_join(encoder_thread2, NULL);

    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
