#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define RELAY_PIN 17
#define LOG_FILE "relay_log.txt"
#define MAX_ELECTRODES 12
#define POLL_INTERVAL 50

static int i2c_fd;
static int relay_fd;
static struct gpiod_chip *relay_chip;
static struct gpiod_line *relay_line;
static struct gpiod_line_request request;
static struct timespec last_change;
static FILE *log_file;

static void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (relay_fd >= 0) {
        gpiochip_close(relay_chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

static void log_relay_state(int state) {
    time_t now;
    struct tm *tm_info;
    char timestamp[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: Relay state: %d\n", timestamp, state);
    fflush(log_file);
}

static void mpr121_init() {
    uint8_t data[12];
    int ret;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Soft reset
    data[0] = 0x80;
    ret = write(i2c_fd, data, 1);
    if (ret < 0) {
        perror("Failed to write soft reset");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    usleep(100000); // Wait for reset to complete

    // Configuration
    data[0] = 0x2B; // Set threshold for all electrodes
    data[1] = 0x01; // Touch threshold
    data[2] = 0x01; // Release threshold
    for (int i = 0; i < MAX_ELECTRODES; i++) {
        ret = write(i2c_fd, data, 3);
        if (ret < 0) {
            perror("Failed to write configuration");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }
        data[0] += 3;
    }

    // Enable run mode
    data[0] = 0x2F;
    data[1] = 0x01;
    ret = write(i2c_fd, data, 2);
    if (ret < 0) {
        perror("Failed to enable run mode");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void relay_init() {
    // Open GPIO chip
    relay_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!relay_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request line
    relay_line = gpiod_chip_get_line(relay_chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(relay_chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(relay_line, "relay", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(relay_chip);
        gpiod_line_release(relay_line);
        exit(EXIT_FAILURE);
    }

    // Initialize relay state
    relay_fd = open("/sys/class/gpio/gpio" RELAY_PIN "/value", O_WRONLY);
    if (relay_fd < 0) {
        perror("Failed to open relay value file");
        gpiod_chip_close(relay_chip);
        gpiod_line_release(relay_line);
        exit(EXIT_FAILURE);
    }
    log_relay_state(0);
}

static void read_mpr121() {
    uint8_t data[12];
    int ret;
    int touched = 0;

    ret = read(i2c_fd, data, 12);
    if (ret < 0) {
        perror("Failed to read MPR121 data");
        return;
    }

    for (int i = 0; i < MAX_ELECTRODES; i++) {
        if (data[i] > 0) {
            touched = 1;
            break;
        }
    }

    if (touched != (relay_line->value == 1)) {
        relay_line->value = touched;
        log_relay_state(relay_line->value);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    mpr121_init();
    relay_init();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_close(relay_chip);
        gpiod_line_release(relay_line);
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_mpr121();
        usleep(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(relay_chip);
    gpiod_line_release(relay_line);
    return 0;
}

