#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_VALVE1 17
#define GPIO_VALVE2 18
#define LOG_FILE "valve_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S\n"

static gpiod_chip *chip = NULL;
static gpiod_line *line1 = NULL;
static gpiod_line *line2 = NULL;
static FILE *log_file = NULL;

static void signal_handler(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    line1 = gpiod_chip_get_line(chip, GPIO_VALVE1);
    if (!line1) {
        perror("Failed to request GPIO line 17");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    line2 = gpiod_chip_get_line(chip, GPIO_VALVE2);
    if (!line2) {
        perror("Failed to request GPIO line 18");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set line direction
    if (gpiod_line_request_output(line1, "Valve 1", 0) < 0) {
        perror("Failed to set GPIO line 17 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line2, "Valve 2", 0) < 0) {
        perror("Failed to set GPIO line 18 as output");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Activate Valve 1 for 500 ms
        gpiod_line_set_value(line1, 1);
        sleep(0.5);
        gpiod_line_set_value(line1, 0);

        // Log activation event
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), LOG_FORMAT, tm);
        fprintf(log_file, "%sValve 1 activated\n", timestamp);

        // Pause for 5 seconds
        sleep(5);

        // Activate Valve 2 for 1000 ms
        gpiod_line_set_value(line2, 1);
        sleep(1);
        gpiod_line_set_value(line2, 0);

        // Log activation event
        time_t now2 = time(NULL);
        struct tm *tm2 = localtime(&now2);
        char timestamp2[20];
        strftime(timestamp2, sizeof(timestamp2), LOG_FORMAT, tm2);
        fprintf(log_file, "%sValve 2 activated\n", timestamp2);

        // Pause for 10 seconds
        sleep(10);
    }

    // Close log file
    fclose(log_file);

    return 0;
}

