#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define GPIO_RELAY 17
#define STABILIZATION_DELAY 100
#define MAX_ELECTRODES 12

static int i2c_fd;
static int relay_fd;
static struct gpiod_chip *relay_chip;
static struct gpiod_line *relay_line;
static struct gpiod_line_request relay_request;
static struct gpiod_chip *i2c_chip;
static struct gpiod_line *i2c_sda;
static struct gpiod_line *i2c_scl;
static struct gpiod_line_request i2c_sda_request;
static struct gpiod_line_request i2c_scl_request;

static void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (relay_fd >= 0) {
        close(relay_fd);
    }
    if (relay_chip) {
        gpiod_chip_close(relay_chip);
    }
    if (i2c_chip) {
        gpiod_chip_close(i2c_chip);
    }
    exit(EXIT_SUCCESS);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_relay() {
    relay_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!relay_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    relay_line = gpiod_chip_get_line(relay_chip, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(relay_chip);
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_output(relay_line, "relay", 0, &relay_request);
    if (relay_request.flags & GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) {
        gpiod_line_set_value(relay_line, 1);
    } else {
        gpiod_line_set_value(relay_line, 0);
    }
}

static void init_i2c_lines() {
    i2c_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!i2c_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    i2c_sda = gpiod_chip_get_line(i2c_chip, 2);
    if (!i2c_sda) {
        perror("Failed to get I2C SDA line");
        gpiod_chip_close(i2c_chip);
        exit(EXIT_FAILURE);
    }
    i2c_scl = gpiod_chip_get_line(i2c_chip, 3);
    if (!i2c_scl) {
        perror("Failed to get I2C SCL line");
        gpiod_line_close(i2c_sda);
        gpiod_chip_close(i2c_chip);
        exit(EXIT_FAILURE);
    }
    gpiod_line_request_output(i2c_sda, "i2c_sda", 0, &i2c_sda_request);
