#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_LOAD_CELL_DOUT 4
#define GPIO_LOAD_CELL_CLK 17
#define GPIO_LOCK 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define THRESHOLD 10.0
#define CALIBRATION_READS 100
#define TIMEOUT 500
#define TIMEOUT_MS 500

static int gpiod_ctx = -1;
static FILE *calibration_file = NULL;
static FILE *log_file = NULL;
static double scale_factor = 1.0;
static double offset = 0.0;

static void sigint_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (calibration_file != NULL) {
        fclose(calibration_file);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void load_calibration() {
    if ((calibration_file = fopen(CALIBRATION_FILE, "r")) == NULL) {
        fprintf(stderr, "Failed to open calibration file: %s\n", CALIBRATION_FILE);
        scale_factor = 1.0;
        offset = 0.0;
        return;
    }

    if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Failed to read calibration data from file: %s\n", CALIBRATION_FILE);
        scale_factor = 1.0;
        offset = 0.0;
    }

    fclose(calibration_file);
}

static void save_calibration() {
    if ((calibration_file = fopen(CALIBRATION_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open calibration file for writing: %s\n", CALIBRATION_FILE);
        return;
    }

    fprintf(calibration_file, "%.10f %.10f\n", scale_factor, offset);

    fclose(calibration_file);
}

static void perform_startup_calibration() {
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_READS; i++) {
        sum += read_load_cell();
        usleep(100000); // 100ms delay between readings
    }
    offset = sum / CALIBRATION_READS;
}

static double read_load_cell() {
    int data = 0;
    int clock = 0;
    int bit = 0;
    int timeout = 0;

    // Start the conversion
    gpiod_line_set_value(gpiod_ctx, GPIO_LOAD_CELL_CLK, 0);
    usleep(10000); // 10ms delay
    gpiod_line_set_value(gpiod_ctx, GPIO_LOAD_CELL_CLK, 1);
    usleep(10000); // 10ms delay

    // Read the data
    for (bit = 0; bit < 24; bit++) {
        gpiod_line_set_value(gpiod_ctx, GPIO_LOAD_CELL_CLK, 0);
        usleep(10000); // 10ms delay
        data <<= 1;
        clock = gpiod_line_get_value(gpiod_ctx, GPIO_LOAD_CELL_DOUT);
        if (clock == 1) {
            data |= 1;
        }
        gpiod_line_set_value(gpiod_ctx, GPIO_LOAD_CELL_CLK, 1);
        usleep(10000); // 10ms delay
    }

    // End the conversion
    gpiod_line_set_value(gpiod_ctx, GPIO_LOAD_CELL_CLK, 0);
    usleep(10000); // 10ms delay
    gpiod_line_set_value(gpiod_ctx, GPIO_LOAD_CELL_CLK, 1);
    usleep(10000); // 10ms delay

    return (double)data / 8.0 - 32768.0;
}

static void log_weight(double weight) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, weight);

    fclose(log_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if ((gpiod_ctx = gpiod_chip_open_by_name("gpiochip0")) == -1) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(gpiod_ctx));
        return 1;
    }

    if ((gpiod_line_request_input(gpiod_ctx, GPIO_LOAD_CELL_DOUT, "load_cell_dout")) == -1) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LOAD_CELL_DOUT, gpiod_strerror(gpiod_ctx));
        gpiod_chip_close(gpiod_ctx);
        return 1;
    }

    if ((gpiod_line_request_output(gpiod_ctx, GPIO_LOCK, "lock")) == -1) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_LOCK, gpiod_strerror(gpiod_ctx));
        gpiod_line_release(gpiod_ctx, GPIO_LOAD_CELL_DOUT);
        gpiod_chip_close(gpiod_ctx);
        return 1;
    }

    load_calibration();

    perform_startup_calibration();

    while (1) {
        double weight = read_load_cell();
        log_weight(weight);

        if (weight > THRESHOLD) {
            gpiod_line_set_value(gpiod_ctx, GPIO_LOCK, 1);
        } else {
            gpiod_line_set_value(gpiod_ctx, GPIO_LOCK, 0);
        }

        usleep(TIMEOUT_MS * 1000); // 500ms delay
    }

    gpiod_line_release(gpiod_ctx, GPIO_LOAD_CELL_DOUT);
    gpiod_line_release(gpiod_ctx, GPIO_LOCK);
    gpiod_chip_close(gpiod_ctx);

    return 0;
}

