#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID 17
#define LOG_FILE "stock_events.txt"
#define TIMEOUT 1000000 // 1 second in microseconds

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

void log_event(const char *format, ...) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    va_list args;
    va_start(args, format);
    fprintf(log_file, "%s: ", buffer);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    va_end(args);
}

void handle_signal(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    int hx711_dout = HX711_DOUT;
    int hx711_sck = HX711_SCK;
    int solenoid = SOLENOID;
    int weight = 0;
    int read_timeout = TIMEOUT;
    int read_attempts = 0;
    int read_success = 0;
    int read_error = 0;
    int lock_active = 0;

    // Initialize GPIO
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        log_event("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    int dout_line = gpiod_chip_get_line(gpiod_ctx, hx711_dout);
    if (dout_line == -1) {
        log_event("Failed to get GPIO line for DOUT");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int sck_line = gpiod_chip_get_line(gpiod_ctx, hx711_sck);
    if (sck_line == -1) {
        log_event("Failed to get GPIO line for SCK");
        gpiod_line_release(dout_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int dout_flags = GPIOD_LINE_REQUEST_INPUT;
    int sck_flags = GPIOD_LINE_REQUEST_OUTPUT;
    int dout_config = gpiod_line_request(dout_line, "hx711_dout", dout_flags);
    if (dout_config != 0) {
        log_event("Failed to request GPIO line for DOUT");
        gpiod_line_release(dout_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int sck_config = gpiod_line_request(sck_line, "hx711_sck", sck_flags);
    if (sck_config != 0) {
        log_event("Failed to request GPIO line for SCK");
        gpiod_line_release(dout_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_event("Failed to open log file");
        gpiod_line_release(dout_line);
        gpiod_line_release(sck_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Wait for the HX711 to be ready
        while (!gpiod_line_get_value(dout_line)) {
            usleep(1000);
        }

        // Read the weight
        read_success = 0;
        read_error = 0;
        read_attempts = 0;
        while (!read_success && read_attempts < 3) {
            read_attempts++;
            if (read_attempts == 3) {
                log_event("Failed to read weight after 3 attempts");
                read_error = 1;
                break;
            }
            usleep(1000);
            if (gpiod_line_get_value(dout_line)) {
                log_event("Data line stuck high");
                read_error = 1;
                break;
            }
            gpiod_line_set_value(sck_line, 1);
            usleep(1000);
            gpiod_line_set_value(sck_line, 0);
            usleep(1000);
            weight = 0;
            for (int i = 0; i < 24; i++) {
                weight <<= 1;
                if (gpiod_line_get_value(dout_line)) {
                    weight |= 1;
                }
                usleep(1000);
            }
            if (weight < 0) {
                weight = -weight;
            }
            read_success = 1;
        }

        if (read_error) {
            continue;
        }

        // Check if the weight is below 100g
        if (weight < 100) {
            // Activate the solenoid lock
            if (gpiod_line_set_value(solenoid, 1) != 0) {
                log_event("Failed to activate solenoid lock");
            } else {
                lock_active = 1;
                usleep(5000000); // 5 seconds
                if (gpiod_line_set_value(solenoid, 0) != 0) {
                    log_event("Failed to deactivate solenoid lock");
                }
            }
        }

        // Log the event
        log_event("Weight: %d g", weight);

        // Wait for 1 second
        usleep(1000000);
    }

    // Clean up
    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return 0;
}

