        log_event("Weight: %d g", weight);

        // Wait for 1 second
        usleep(1000000);
    }

    // Clean up
    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return 0;
}
