static int gpiod_ctx = -1;
static FILE *calibration_file = NULL;
static FILE *security_log = NULL;
static int solenoid_state = 0;

static void sigint_handler(int signum) {
    if (solenoid_state) {
        gpio_set_value(gpiod_ctx, SOLENOID, 0);
    }
    if (calibration_file) {
        fclose(calibration_file);
    }
    if (security_log) {
        fclose(security_log);
    }
    if (gpiod_ctx != -1) {
        gpiod_close(gpiod_ctx);
    }
    exit(0);
}

static void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *dout_line, *clk_line;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    dout_line = gpiod_chip_get_line(chip, HX711_DOUT);
    if (!dout_line) {
        perror("Failed to get GPIO line for HX711 DOUT");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    clk_line = gpiod_chip_get_line(chip, HX711_CLK);
    if (!clk_line) {
        perror("Failed to get GPIO line for HX711 CLK");
        gpiod_line_release(dout_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(dout_line, "HX711 DOUT");
    if (ret) {
