        gpiod_line_release(dout_line);
        gpiod_line_release(clk_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(clk_line, "HX711 CLK", 0);
    if (ret) {
        perror("Failed to request GPIO line for HX711 CLK");
        gpiod_line_release(dout_line);
        gpiod_line_release(clk_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_ctx = gpiod_chip_fd(chip);
    if (gpiod_ctx < 0) {
        perror("Failed to get GPIO context");
        gpiod_line_release(dout_line);
        gpiod_line_release(clk_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void init_files() {
    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (!calibration_file) {
        calibration_file = fopen(CALIBRATION_FILE, "w");
        if (!calibration_file) {
            perror("Failed to open calibration file");
            exit(EXIT_FAILURE);
        }
    }

    security_log = fopen(SECURITY_LOG, "a");
    if (!security_log) {
        perror("Failed to open security log file");
        fclose(calibration_file);
        exit(EXIT_FAILURE);
    }
}

static void save_calibration(float calibration_factor) {
    fprintf(calibration_file, "%.10f\n", calibration_factor);
    fclose(calibration_file);
}

static float read_calibration() {
    float calibration_factor;
    if (fscanf(calibration_file, "%f", &calibration_factor) != 1) {
        perror("Failed to read calibration factor");
        return 0.0;
    }
    return calibration_factor;
}

static void write_security_log(float weight, time_t timestamp) {
    fprintf(security_log, "%ld,%.10f\n", timestamp, weight);
    fclose(security_log);
}

static void unlock_solenoid() {
    gpio_set_value(gpiod_ctx, SOLENOID, 0);
    solenoid_state = 0;
}

static void lock_solenoid() {
    gpio_set_value(gpiod_ctx, SOLENOID, 1);
    solenoid_state = 1;
}

static int read_data() {
    int data = 0;
    int i;
    int timeout_count = 0;

    for (i = 0; i < 24; i++) {
        gpio_set_value(gpiod_ctx, HX711_CLK, 1);
        usleep(1000);
        gpio_set_value(gpiod_ctx, HX711_CLK, 0);
        usleep(1000);

        if (gpio_get_value(gpiod_ctx, HX711_DOUT)) {
            data |= (1 << (23 - i));
        }
    }

    if (timeout_count > 100) {
        return -1; // Timeout
    }

    return data;
}

static void main() {
    float calibration_factor = read_calibration();
    if (calibration_factor == 0.0) {
        printf("No calibration found. Please place a known weight and press Enter.\n");
        getchar();

        int weight = 0;
        printf("Enter the known weight in kg: ");
        scanf("%d", &weight);

        calibration_factor = (float)weight * 1000000; // Convert to 24-bit signed format
        save_calibration(calibration_factor);
    }

    init_gpio();
    init_files();

    signal(SIGINT, sigint_handler);

    while (1) {
        int data = read_data();
        if (data == -1) {
            printf("Timeout reading data from HX711.\n");
            continue;
        }

        float weight = (float)data / calibration_factor;
        time_t timestamp = time(NULL);

        if (weight > THRESHOLD) {
            lock_solenoid();
            write_security_log(weight, timestamp);
            sleep(5);
            unlock_solenoid();
        }
    }

    fclose(security_log);
    fclose(calibration_file);
    gpiod_close(gpiod_ctx);
}

