#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

void log_event(int relay_state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log, "%s, %s\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(log);
}

void setup_gpio() {
    const char *chip_name = "gpiochip0";
    const char *sensor_label = "sensor";
    const char *relay_label = "relay";

    struct gpiod_chip *chip = gpiod_chip_open_by_name(chip_name);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor_line == NULL) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        perror("Failed to get relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int sensor_flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int relay_flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH;

    int sensor_request = gpiod_line_request(sensor_line, sensor_label, sensor_flags);
    if (sensor_request < 0) {
        perror("Failed to request sensor line");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int relay_request = gpiod_line_request(relay_line, relay_label, relay_flags);
    if (relay_request < 0) {
        perror("Failed to request relay line");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
}

int main() {
    setup_gpio();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int relay_state = 0; // Initial state: OFF

    while (!should_exit) {
        int sensor_value = gpiod_line_get_value(SENSOR_PIN);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            continue;
        }

        if (sensor_value == 0) { // Obstacle detected
            relay_state = !relay_state;
            log_event(relay_state);
            gpiod_line_set_value(RELAY_PIN, relay_state);
