#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"

static int gpiod_ctx = -1;
static FILE *log_file = NULL;

static void log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file);
}

static void handle_signal(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
        gpiod_ctx = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    printf("Exiting on signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec sleep_time = {0, 1000000}; // 1ms
    struct timespec start_time;
    struct tm *tm_info;
    char timestamp[20];

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO context
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Request lines
    int pwr_line = gpiod_line_request_output(gpiod_ctx, "PIR", PIR_PIN, 0);
    if (pwr_line == -1) {
        fprintf(stderr, "Error: Failed to request PIR line\n");
        gpiod_chip_close(gpiod_ctx);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    int buzzer_line = gpiod_line_request_output(gpiod_ctx, "BUZZER", BUZZER_PIN, 0);
    if (buzzer_line == -1) {
        fprintf(stderr, "Error: Failed to request BUZZER line\n");
        gpiod_line_release(pwr_line);
        gpiod_chip_close(gpiod_ctx);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read PIR line
        int pwr_state = gpiod_line_get_value(pwr_line);
        if (pwr_state == -1) {
            fprintf(stderr, "Error: Failed to read PIR line\n");
            gpiod_line_release(pwr_line);
            gpiod_line_release(buzzer_line);
            gpiod_chip_close(gpiod_ctx);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Check for motion
        if (pwr_state == 1) {
            // Log motion
            clock_gettime(CLOCK_REALTIME, &start_time);
            tm_info = localtime(&start_time.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
            log_motion(timestamp);

            // Activate buzzer
            gpiod_line_set_value(buzzer_line, 1);
            if (gpiod_line_get_value(buzzer_line) == -1) {
                fprintf(stderr, "Error: Failed to set BUZZER line high\n");
                gpiod_line_release(pwr_line);
                gpiod_line_release(buzzer_line);
                gpiod_chip_close(gpiod_ctx);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }

            // Wait for 2 seconds
            nanosleep(&sleep_time, NULL);

            // Deactivate buzzer
            gpiod_line_set_value(buzzer_line, 0);
            if (gpiod_line_get_value(buzzer_line) == -1) {
                fprintf(stderr, "Error: Failed to set BUZZER line low\n");
                gpiod_line_release(pwr_line);
                gpiod_line_release(buzzer_line);
                gpiod_chip_close(gpiod_ctx);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
        }

        // Sleep for 1ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(pwr_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(gpiod_ctx);
    fclose(log_file);

    return 0;
}
