#define MAX_DURATION 3600
#define MIN_DURATION 1

volatile sig_atomic_t exit_flag = 0;

static void sig_handler(int signum) {
    exit_flag = 1;
}

static int read_config_file(const char *filename, int *duration) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), file) == NULL) {
        perror("Failed to read configuration file");
        fclose(file);
        return -1;
    }

    char *token;
    token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Invalid configuration file format\n");
        fclose(file);
        return -1;
    }

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Invalid configuration file format\n");
        fclose(file);
        return -1;
    }

    *duration = atoi(token);
    if (*duration < MIN_DURATION || *duration > MAX_DURATION) {
        fprintf(stderr, "Duration out of range (1-3600 seconds)\n");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

static int setup_gpio() {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "watering", 0);
    if (ret) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

static int activate_valve(int duration) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1);
    if (ret) {
        perror("Failed to set GPIO line high");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    struct timespec sleep_time = {0, duration * 1000000};
    nanosleep(&sleep_time, NULL);

    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret) {
        perror("Failed to set GPIO line low");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

int main() {
    int duration;

    if (read_config_file(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!exit_flag) {
        activate_valve(duration);
        printf("Valve activated for %d seconds\n", duration);
    }

    printf("Valve turned off\n");

    return EXIT_SUCCESS;
}

