#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LOG_FILE "trace_log.txt"
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_LEFT_PWM_PIN 22
#define MOTOR_RIGHT_PWM_PIN 23
#define MOTOR_LEFT_DIR_PIN 24
#define MOTOR_RIGHT_DIR_PIN 25
#define PWM_FREQUENCY 1000
#define SAMPLE_PERIOD 10000000 // 10 ms

static int gpiod_ctx = -1;
static FILE *log_file = NULL;
static int left_motor_speed = 150;
static int right_motor_speed = 150;

static void sigint_handler(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void setup_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    int left_sensor_line = gpiod_chip_get_line(gpiod_ctx, LEFT_SENSOR_PIN);
    int middle_sensor_line = gpiod_chip_get_line(gpiod_ctx, MIDDLE_SENSOR_PIN);
    int right_sensor_line = gpiod_chip_get_line(gpiod_ctx, RIGHT_SENSOR_PIN);
    int motor_left_pwm_line = gpiod_chip_get_line(gpiod_ctx, MOTOR_LEFT_PWM_PIN);
    int motor_right_pwm_line = gpiod_chip_get_line(gpiod_ctx, MOTOR_RIGHT_PWM_PIN);
    int motor_left_dir_line = gpiod_chip_get_line(gpiod_ctx, MOTOR_LEFT_DIR_PIN);
    int motor_right_dir_line = gpiod_chip_get_line(gpiod_ctx, MOTOR_RIGHT_DIR_PIN);

    if (left_sensor_line == -1 || middle_sensor_line == -1 || right_sensor_line == -1 ||
        motor_left_pwm_line == -1 || motor_right_pwm_line == -1 ||
        motor_left_dir_line == -1 || motor_right_dir_line == -1) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_input(left_sensor_line, "left_sensor");
    gpiod_line_request_input(middle_sensor_line, "middle_sensor");
    gpiod_line_request_input(right_sensor_line, "right_sensor");
    gpiod_line_request_output(motor_left_pwm_line, "motor_left_pwm", 0);
    gpiod_line_request_output(motor_right_pwm_line, "motor_right_pwm", 0);
    gpiod_line_request_output(motor_left_dir_line, "motor_left_dir", 0);
    gpiod_line_request_output(motor_right_dir_line, "motor_right_dir", 0);

    if (gpiod_line_request_edge_detect(left_sensor_line, GPIOD_EDGE_BOTH, 0) == -1 ||
        gpiod_line_request_edge_detect(middle_sensor_line, GPIOD_EDGE_BOTH, 0) == -1 ||
        gpiod_line_request_edge_detect(right_sensor_line, GPIOD_EDGE_BOTH, 0) == -1) {
        perror("Failed to request edge detection");
        gpiod_line_release(left_sensor_line);
        gpiod_line_release(middle_sensor_line);
        gpiod_line_release(right_sensor_line);
        gpiod_line_release(motor_left_pwm_line);
        gpiod_line_release(motor_right_pwm_line);
        gpiod_line_release(motor_left_dir_line);
        gpiod_line_release(motor_right_dir_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

static void setup_pwm() {
    struct gpiod_line_bulk lines;
    lines.lines[0] = gpiod_line_get(motor_left_pwm_line);
    lines.lines[1] = gpiod_line_get(motor_right_pwm_line);
    lines.count = 2;

    if (gpiod_line_request_bulk(gpiod_ctx, "motor_pwm", &lines, 0) == -1) {
        perror("Failed to request PWM lines");
        gpiod_line_release_bulk(&lines);
        gpiod_line_release(motor_left_pwm_line);
        gpiod_line_release(motor_right_pwm_line);
        gpiod_line_release(motor_left_dir_line);
        gpiod_line_release(motor_right_dir_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    struct gpiod_pulse_request pulse_request;
    pulse_request.line_offset = 0;
    pulse_request.duty_cycle = 0;
    pulse_request.period_ns = 1000000 / PWM_FREQUENCY;
    pulse_request.enable = 1;

    if (gpiod_line_request_pulse(gpiod_ctx, "motor_pwm", &pulse_request) == -1) {
        perror("Failed to request PWM pulse");
        gpiod_line_release_bulk(&lines);
        gpiod_line_release(motor_left_pwm_line);
        gpiod_line_release(motor_right_pwm_line);
        gpiod_line_release(motor_left_dir_line);
        gpiod_line_release(motor_right_dir_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

static void log_data(int left, int middle, int right, int left_speed, int right_speed) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, left, middle, right, left_speed, right_speed);
}

static void control_robot(int left, int middle, int right) {
    if (middle == 0) {
        left_motor_speed = 150;
        right_motor_speed = 150;
    } else if (left == 0) {
        left_motor_speed = 150 / 2;
        right_motor_speed = 150;
    } else if (right == 0) {
        left_motor_speed = 150;
        right_motor_speed = 150 / 2;
    } else {
        left_motor_speed = 0;
        right_motor_speed = 0;
    }

    gpiod_line_set_value(motor_left_dir_line, left == 0);
    gpiod_line_set_value(motor_right_dir_line, right == 0);
    gpiod_line_set_value(motor_left_pwm_line, left_motor_speed);
    gpiod_line_set_value(motor_right_pwm_line, right_motor_speed);
}

int main() {
    signal(SIGINT, sigint_handler);

    setup_gpio();
    setup_pwm();

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release_bulk(&lines);
        gpiod_line_release(motor_left_pwm_line);
        gpiod_line_release(motor_right_pwm_line);
        gpiod_line_release(motor_left_dir_line);
        gpiod_line_release(motor_right_dir_line);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    int left_state = 1;
    int middle_state = 1;
    int right_state = 1;

    while (1) {
        usleep(SAMPLE_PERIOD);

        left_state = gpiod_line_get_value(left_sensor_line);
        middle_state = gpiod_line_get_value(middle_sensor_line);
        right_state = gpiod_line_get_value(right_sensor_line);

        control_robot(left_state, middle_state, right_state);

        log_data(left_state, middle_state, right_state, left_motor_speed, right_motor_speed);
    }

    fclose(log_file);
    gpiod_line_release_bulk(&lines);
    gpiod_line_release(motor_left_pwm_line);
    gpiod_line_release(motor_right_pwm_line);
    gpiod_line_release(motor_left_dir_line);
    gpiod_line_release(motor_right_dir_line);
    gpiod_chip_close(gpiod_ctx);

    return 0;
}

