static void log_event(const char *event, int lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file, "%ld.%09ld %s %d %d\n", ts.tv_sec, ts.tv_nsec, event, lux, relay_state);
}

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (relay_fd >= 0) {
        close(relay_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (line) {
        gpiod_line_release(line);
    }
    exit(0);
}

static void setup_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line, "grow_lamp", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void setup_logging() {
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    log_event("Start", 0, 0);
}

static void read_lux() {
    uint8_t command = 0x10; // Start measurement at 1lx resolution
    if (write(i2c_fd, &command, 1) != 1) {
        perror("Failed to write command to sensor");
        return;
    }
    usleep(MEASUREMENT_DELAY * 1000); // Wait for measurement delay

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read lux data from sensor");
        return;
    }

    uint16_t lux = (data[0] << 8) | data[1];
    log_event("Lux", lux, 0);
}

static void turn_on_relay() {
    gpiod_line_set_value(line, 1);
    log_event("Relay On", 0, 1);
}

static void turn_off_relay() {
    gpiod_line_set_value(line, 0);
    log_event("Relay Off", 0, 0);
}

int main() {
    signal(SIGINT, handle_signal);

    setup_i2c();
    setup_gpio();
    setup_logging();

    while (1) {
        read_lux();
        if (lux < 150) {
            turn_on_relay();
        } else {
            turn_off_relay();
        }
        usleep(1000000); // Sleep for 1 second
    }

    return 0;
}

