#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_LOCK 21
#define GPIO_UNLOCK 22
#define GPIO_SERVO 18
#define PWM_FREQUENCY 50
#define PWM_RANGE 2500
#define DEBOUNCE_DELAY 100

static gpiod_chip *chip;
static gpiod_line *lock_line, *unlock_line, *servo_line;
static gpiod_line_request lock_request, unlock_request, servo_request;
static gpiod_line_event lock_event, unlock_event;
static int lock_state = 0, unlock_state = 0;
static int servo_pulse_width = 1000;

static void sigint_handler(int signum) {
    gpiod_line_release(lock_line);
    gpiod_line_release(unlock_line);
    gpiod_line_release(servo_line);
    gpiod_chip_close(chip);
    printf("Exiting...\n");
    exit(0);
}

static void debounce(gpiod_line *line, int *state) {
    struct timespec ts = {0, DEBOUNCE_DELAY * 1000000};
    while (gpiod_line_event_wait(line, &ts) == 0) {
        gpiod_line_event_read(line, &lock_event);
        if (lock_event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            *state = 1;
        } else if (lock_event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            *state = 0;
        }
    }
}

static void set_servo_pulse_width(int width) {
    if (width < 500 || width > 2500) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500 µs)\n");
        return;
    }
    gpiod_line_set_value(servo_line, 1);
    usleep(width);
    gpiod_line_set_value(servo_line, 0);
}

int main() {
    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    lock_line = gpiod_chip_get_line(chip, GPIO_LOCK);
    unlock_line = gpiod_chip_get_line(chip, GPIO_UNLOCK);
    servo_line = gpiod_chip_get_line(chip, GPIO_SERVO);

    if (!lock_line || !unlock_line || !servo_line) {
        fprintf(stderr, "Error: Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_input(lock_line, "lock", &lock_request);
    gpiod_line_request_input(unlock_line, "unlock", &unlock_request);
    gpiod_line_request_output(servo_line, "servo", &servo_request);

    if (!lock_request || !unlock_request || !servo_request) {
        fprintf(stderr, "Error: Failed to request GPIO lines\n");
        gpiod_line_release(lock_line);
        gpiod_line_release(unlock_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        debounce(lock_line, &lock_state);
        debounce(unlock_line, &unlock_state);

        if (lock_state) {
            printf("Lock button pressed\n");
            set_servo_pulse_width(1000);
        } else if (unlock_state) {
            printf("Unlock button pressed\n");
            set_servo_pulse_width(2000);
