#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define VOLTAGE 3.3
#define CURRENT 0.060
#define MOTOR_DELAY_1 200
#define MOTOR_DELAY_2 300

static int gpiod_chip = -1;
static int gpiod_line1 = -1;
static int gpiod_line2 = -1;

static void signal_handler(int signum) {
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    if (gpiod_line1 != -1) {
        gpiod_line_release(gpiod_line1);
    }
    if (gpiod_line2 != -1) {
        gpiod_line_release(gpiod_line2);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    gpiod_chip = chip->fd;

    // Request lines
    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (line1 == NULL) {
        perror("Failed to request GPIO line 17");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    gpiod_line1 = line1->fd;

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (line2 == NULL) {
        perror("Failed to request GPIO line 27");
        gpiod_line_release(gpiod_line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    gpiod_line2 = line2->fd;

    // Set line direction to output
    ret = gpiod_line_request_output(line1, "motor1", 0);
    if (ret < 0) {
        perror("Failed to set GPIO line 17 to output");
        gpiod_line_release(gpiod_line1);
        gpiod_line_release(gpiod_line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line2, "motor2", 0);
    if (ret < 0) {
        perror("Failed to set GPIO line 27 to output");
        gpiod_line_release(gpiod_line1);
        gpiod_line_release(gpiod_line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set line value to high
    ret = gpiod_line_set_value(line1, 1);
    if (ret < 0) {
        perror("Failed to set GPIO line 17 to high");
