#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_SOUND_SENSOR_PIN 17
#define GPIO_ALARM_LED_PIN 27
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_MS 10

static gpiod_chip *chip = NULL;
static gpiod_line *sound_sensor_line = NULL;
static gpiod_line *alarm_led_line = NULL;
static zmq_ctx_t *context = NULL;
static zmq_socket *socket = NULL;

static void handle_signal(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
    if (socket) {
        zmq_close(socket);
    }
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "Modes: sound_sensor, alarm_node\n");
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, GPIO_SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Failed to get sound sensor line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    alarm_led_line = gpiod_chip_get_line(chip, GPIO_ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Failed to get alarm LED line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_line_request_input(sound_sensor_line, "sound_sensor", flags);
    if (ret) {
        perror("Failed to request sound sensor line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(alarm_led_line, "alarm_led", 0);
    if (ret) {
        perror("Failed to request alarm LED line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize ZeroMQ
    context = zmq_ctx_new();
    if (!context) {
        perror("Failed to create ZeroMQ context");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    socket = zmq_socket(context, ZMQ_SUB);
    if (!socket) {
        perror("Failed to create ZeroMQ socket");
        zmq_ctx_destroy(context);
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = zmq_connect(socket, "tcp://localhost:5555");
    if (ret) {
        perror("Failed to connect to ZeroMQ socket");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (ret) {
        perror("Failed to subscribe to ZeroMQ topic");
        zmq_close(socket);
        zmq_ctx_destroy(context);
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (strcmp(mode, "sound_sensor") == 0) {
        while (1) {
            int value = gpiod_line_get_value(sound_sensor_line);
            if (value == 0) {
                zmq_msg_t msg;
                zmq_msg_init(&msg);
                zmq_msg_send(&msg, socket, 0);
                zmq_msg_close(&msg);
            }
            usleep(POLL_INTERVAL_MS * 1000);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        while (1) {
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            zmq_msg_recv(&msg, socket, 0);
            zmq_msg_close(&msg);

            ret = gpiod_line_set_value(alarm_led_line, 1);
            if (ret) {
                perror("Failed to set alarm LED line");
                zmq_msg_close(&msg);
                continue;
            }

            usleep(1000000);

            ret = gpiod_line_set_value(alarm_led_line, 0);
            if (ret) {
                perror("Failed to clear alarm LED line");
                zmq_msg_close(&msg);
                continue;
            }
        }
    }

    // This line should never be reached
    return EXIT_FAILURE;
}

