#include <syslog.h>
#include <mosquitto.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define MARK 9000
#define SPACE 4500
#define MARK_560 560
#define SPACE_1690 1690
#define SPACE_560 560
#define NEC_HEADER 9000
#define NEC_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_BIT_SPACE_1 1690
#define NEC_BIT_SPACE_0 560
#define NEC_CHECKSUM 0x69

#define MAX_PULSES 1000
#define MAX_COMMAND_LENGTH 33

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct mosquitto *mosq;
static int pulse_count = 0;
static int pulse_buffer[MAX_PULSES];
static int pulse_index = 0;
static int command_length = 0;
static char command[MAX_COMMAND_LENGTH];

static void alert_callback(struct gpiod_line *line, unsigned int offset, unsigned int flags, void *data) {
    int value = gpiod_line_get_value(line);
    if (value == 0) {
        pulse_buffer[pulse_index++] = gpiod_line_get_value(line);
        if (pulse_index >= MAX_PULSES) {
            syslog(LOG_ERR, "Pulse buffer overflow");
            exit(EXIT_FAILURE);
        }
    }
}

static void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc == 0) {
        syslog(LOG_INFO, "Connected to MQTT broker");
    } else {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %d", rc);
        exit(EXIT_FAILURE);
    }
}

static void mqtt_publish_callback(struct mosquitto *mosq, void *userdata, int mid) {
    syslog(LOG_INFO, "Message published with mid %d", mid);
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker: %d", rc);
}

static void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, message->payload);
}

static void handle_signal(int sig) {
    syslog(LOG_INFO, "Received signal %d, cleaning up", sig);
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int rc;
    struct sigaction sa;

    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
