#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_CONTINUOUS_HIGH_RES_MODE_2 0x11
#define BH1750_CONTINUOUS_LOW_RES_MODE 0x13
#define BH1750_ONE_TIME_HIGH_RES_MODE 0x20
#define BH1750_ONE_TIME_HIGH_RES_MODE_2 0x21
#define BH1750_ONE_TIME_LOW_RES_MODE 0x23
#define UDP_PORT 5005
#define UDP_MULTICAST_GROUP "239.255.255.250"

static int i2c_fd;
static int udp_fd;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open UDP socket
    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("Failed to open UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct sockaddr_in multicast_addr;
    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_addr.s_addr = inet_addr(UDP_MULTICAST_GROUP);
    multicast_addr.sin_port = htons(UDP_PORT);

    // Join multicast group
    if (setsockopt(udp_fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, (void*)&multicast_addr, sizeof(multicast_addr)) < 0) {
        perror("Failed to join multicast group");
        close(udp_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Start conversion
        if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Failed to start conversion");
            continue;
        }

        // Wait for conversion to complete
        usleep(180000);

        // Read lux value
        uint16_t lux;
        if (read(i2c_fd, &lux, 2) != 2) {
            perror("Failed to read lux value");
            lux = 0; // Set to NaN
        }

        // Broadcast UDP packet
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "%d,%f", BH1750_ADDR, lux / 1.2);
        if (sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr*)&multicast_addr, sizeof(multicast_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close UDP socket
    close(udp_fd);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

