#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define ENABLE_REGISTER 0x00
#define CFG6_REGISTER 0x06
#define SP_EN_BIT 0x01
#define PON_BIT 0x02
#define ID_REGISTER 0x01
#define ID_VALUE 0x5441534341444141
#define LOG_FILE "spectral_log.csv"
#define SAMPLE_INTERVAL 5

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {SAMPLE_INTERVAL, 0};
    uint8_t id_data[2];
    uint8_t enable_data[1];
    uint8_t cfg6_data[1];
    uint8_t spectral_data[10];
    char timestamp[20];

    // Initialize GPIO
    ret = gpiochip_open(0);
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiochip_close(0);
        exit(EXIT_FAILURE);
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2c_close(i2c_fd);
        gpiochip_close(0);
        exit(EXIT_FAILURE);
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Read sensor ID
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, ID_REGISTER, 2, id_data);
    if (ret < 0) {
        perror("Failed to read sensor ID");
        goto cleanup;
    }
    if (id_data[0] != ID_VALUE || id_data[1] != ID_VALUE) {
        fprintf(stderr, "Invalid sensor ID\n");
        goto cleanup;
    }

    // Power on the sensor
    enable_data[0] = PON_BIT;
    ret = i2c_smbus_write_byte_data(i2c_fd, ENABLE_REGISTER, enable_data[0]);
    if (ret < 0) {
        perror("Failed to power on sensor");
        goto cleanup;
    }

    // Configure SMUX
    cfg6_data[0] = 0x00; // Example configuration, adjust as needed
    ret = i2c_smbus_write_byte_data(i2c_fd, CFG6_REGISTER, cfg6_data[0]);
    if (ret < 0) {
        perror("Failed to configure SMUX");
        goto cleanup;
    }

    // Enable spectral measurement
    enable_data[0] |= SP_EN_BIT;
    ret = i2c_smbus_write_byte_data(i2c_fd, ENABLE_REGISTER, enable_data[0]);
    if (ret < 0) {
        perror("Failed to enable spectral measurement");
        goto cleanup;
    }

    while (!should_exit) {
        // Read spectral data
        ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x02, 10, spectral_data);
        if (ret < 0) {
            perror("Failed to read spectral data");
            goto cleanup;
        }

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write data to log file
        fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                timestamp,
                spectral_data[0], spectral_data[1], spectral_data[2],
                spectral_data[3], spectral_data[4], spectral_data[5],
                spectral_data[6], spectral_data[7], spectral_data[8]);

        // Sleep for the specified interval
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
    }
    if (gpiochip_open(0) >= 0) {
        gpiochip_close(0);
    }

    return should_exit ? EXIT_SUCCESS : EXIT_FAILURE;
}

