#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"
#define DEFAULT_ERROR_FILENAME "seismic_error.log"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

#define D7S_REG_STATUS 0x00
#define D7S_REG_X 0x01
#define D7S_REG_Y 0x02
#define D7S_REG_Z 0x03
#define D7S_REG_STATUS_MASK 0x0F
#define D7S_STATUS_SENSOR_ABSENT 0x01
#define D7S_STATUS_BUS_ERROR 0x02

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static FILE *error_file = NULL;
static int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
static char *output_filename = DEFAULT_OUTPUT_FILENAME;
static char *error_filename = DEFAULT_ERROR_FILENAME;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int running = 1;

static void handle_signal(int signum) {
    running = 0;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    exit(0);
}

static void log_error(const char *message) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
}

static int read_i2c_register(int reg) {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = i2c_smbus_read_byte_data(i2c_fd, reg);
        if (ret >= 0) {
            return ret;
        }
        usleep(BACKOFF_MS * 1000);
        retries++;
    }

    log_error("I2C read failed");
    return -1;
}

static int write_i2c_register(int reg, int value) {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = i2c_smbus_write_byte_data(i2c_fd, reg, value);
        if (ret >= 0) {
            return ret;
        }
        usleep(BACKOFF_MS * 1000);
        retries++;
    }

    log_error("I2C write failed");
    return -1;
}

static void read_seismic_data() {
    int status;
    int x, y, z;
    char timestamp[20];

    time_t now;
    struct tm *tm_info;

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    status = read_i2c_register(D7S_REG_STATUS);
    if (status < 0) {
        return;
    }

    if (status & D7S_STATUS_SENSOR_ABSENT) {
        log_error("Sensor absent");
        return;
    }

    if (status & D7S_STATUS_BUS_ERROR) {
        log_error("Bus error");
        return;
    }

    x = read_i2c_register(D7S_REG_X);
    y = read_i2c_register(D7S_REG_Y);
    z = read_i2c_register(D7S_REG_Z);

    if (x < 0 || y < 0 || z < 0) {
        log_error("I2C read failed");
        return;
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file);
}

int main(int argc, char *argv[]) {
    int opt;
    struct sigaction sa;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = atoi(optarg);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                break;
            case 'f':
                output_filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_address>] [-i <sampling_interval>] [-f <output_filename>]\n", argv[0]);
                exit(1);
        }
    }

    csv_file = fopen(output_filename, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        exit(1);
    }

    error_file = fopen(error_filename, "w");
    if (error_file == NULL) {
        perror("Failed to open error file");
        fclose(csv_file);
        exit(1);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        fclose(csv_file);
        fclose(error_file);
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        fclose(csv_file);
        fclose(error_file);
        exit(1);
    }

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        read_seismic_data();
        sleep(sampling_interval);
    }

    close(i2c_fd);
    fclose(csv_file);
    fclose(error_file);

    return 0;
}

