#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define UART_DEVICE "/dev/serial0"
#define UART_BAUDRATE 115200
#define UART_TIMEOUT 0.5
#define SELECT_TIMEOUT 2
#define MAX_LINE_LENGTH 256

static int uart_fd = -1;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_tx, *gpio_rx;
static struct timespec select_timeout_ts;
static struct timespec uart_timeout_ts;
static char line_buffer[MAX_LINE_LENGTH];
static size_t line_buffer_length = 0;
static int running = 1;

static void handle_sigint(int signum) {
    running = 0;
}

static void handle_sigterm(int signum) {
    running = 0;
}

static void setup_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to open UART: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    struct termios uart_attr;
    if (tcgetattr(uart_fd, &uart_attr) == -1) {
        fprintf(stderr, "Failed to get UART attributes: %s\n", strerror(errno));
        close(uart_fd);
        exit(EXIT_FAILURE);
    }

    cfsetispeed(&uart_attr, UART_BAUDRATE);
    cfsetospeed(&uart_attr, UART_BAUDRATE);
    uart_attr.c_cflag &= ~PARENB;
    uart_attr.c_cflag &= ~CSTOPB;
    uart_attr.c_cflag &= ~CSIZE;
    uart_attr.c_cflag |= CS8;
    uart_attr.c_cflag &= ~CRTSCTS;
    uart_attr.c_cflag |= CREAD | CLOCAL;
    uart_attr.c_lflag &= ~ICANON;
    uart_attr.c_lflag &= ~ECHO;
    uart_attr.c_lflag &= ~ECHOE;
    uart_attr.c_lflag &= ~ECHONL;
    uart_attr.c_lflag &= ~ISIG;
    uart_attr.c_iflag &= ~(IXON | IXOFF | IXANY);
    uart_attr.c_oflag &= ~OPOST;
    uart_attr.c_cc[VTIME] = (int)(UART_TIMEOUT * 10);
    uart_attr.c_cc[VMIN] = 0;

    if (tcsetattr(uart_fd, TCSANOW, &uart_attr) == -1) {
        fprintf(stderr, "Failed to set UART attributes: %s\n", strerror(errno));
        close(uart_fd);
        exit(EXIT_FAILURE);
    }

    select_timeout_ts.tv_sec = SELECT_TIMEOUT;
    select_timeout_ts.tv_nsec = 0;
    uart_timeout_ts.tv_sec = (int)(UART_TIMEOUT * 1000000000);
    uart_timeout_ts.tv_nsec = 0;
}

static void setup_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpio_tx = gpiod_chip_get_line(gpio_chip, 14);
    if (!gpio_tx) {
        fprintf(stderr, "Failed to get GPIO line 14: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    gpio_rx = gpiod_chip_get_line(gpio_chip, 15);
    if (!gpio_rx) {
        fprintf(stderr, "Failed to get GPIO line 15: %s\n", strerror(errno));
        gpiod_line_release(gpio_tx);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_tx, "TXD", 0) == -1) {
        fprintf(stderr, "Failed to request GPIO line 14 as output: %s\n", strerror(errno));
        gpiod_line_release(gpio_rx);
        gpiod_line_release(gpio_tx);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(gpio_rx, "RXD") == -1) {
        fprintf(stderr, "Failed to request GPIO line 15 as input: %s\n", strerror(errno));
        gpiod_line_release(gpio_tx);
        gpiod_line_release(gpio_rx);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (gpio_tx) {
        gpiod_line_release(gpio_tx);
    }
    if (gpio_rx) {
        gpiod_line_release(gpio_rx);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

static void parse_line(const char *line) {
    char *timestamp_str, *range_str;
    char *endptr;
    double range_meters;

    timestamp_str = strtok(line, ",");
    if (!timestamp_str) {
        fprintf(stderr, "Invalid line format: %s\n", line);
        return;
    }

    range_str = strtok(NULL, ",");
    if (!range_str) {
        fprintf(stderr, "Invalid line format: %s\n", line);
        return;
    }

    range_meters = strtod(range_str, &endptr);
    if (endptr == range_str || *endptr != '\n') {
        fprintf(stderr, "Invalid range format: %s\n", range_str);
        return;
    }

    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range_meters);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    setup_gpio();
    setup_uart();

    while (running) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        int select_result = select(uart_fd + 1, &read_fds, NULL, NULL, &select_timeout_ts);
        if (select_result == -1) {
            if (errno != EINTR) {
                fprintf(stderr, "Select failed: %s\n", strerror(errno));
            }
            continue;
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            char buffer[1];
            ssize_t bytes_read = read(uart_fd, buffer, 1);
            if (bytes_read == -1) {
                if (errno != EINTR) {
                    fprintf(stderr, "Read failed: %s\n", strerror(errno));
                }
                continue;
            }

            if (bytes_read == 0) {
                fprintf(stderr, "Sensor absent or bus error\n");
                break;
            }

            line_buffer[line_buffer_length++] = buffer[0];
            if (line_buffer[line_buffer_length - 1] == '\n') {
                line_buffer[line_buffer_length] = '\0';
                parse_line(line_buffer);
                line_buffer_length = 0;
            }
        }
    }

    cleanup();
    return 0;
}

