    if (!range_str) {
        fprintf(stderr, "Invalid line format: %s\n", line);
        return;
    }

    range_meters = strtod(range_str, &endptr);
    if (endptr == range_str || *endptr != '\n') {
        fprintf(stderr, "Invalid range format: %s\n", range_str);
        return;
    }

    struct tm tm;
    time_t now = time(NULL);
    localtime_r(&now, &tm);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range_meters);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    setup_gpio();
    setup_uart();

    while (running) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        int select_result = select(uart_fd + 1, &read_fds, NULL, NULL, &select_timeout_ts);
        if (select_result == -1) {
            if (errno != EINTR) {
                fprintf(stderr, "Select failed: %s\n", strerror(errno));
            }
            continue;
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            char buffer[1];
            ssize_t bytes_read = read(uart_fd, buffer, 1);
            if (bytes_read == -1) {
                if (errno != EINTR) {
                    fprintf(stderr, "Read failed: %s\n", strerror(errno));
                }
                continue;
            }

            if (bytes_read == 0) {
                fprintf(stderr, "Sensor absent or bus error\n");
                break;
            }

            line_buffer[line_buffer_length++] = buffer[0];
            if (line_buffer[line_buffer_length - 1] == '\n') {
                line_buffer[line_buffer_length] = '\0';
                parse_line(line_buffer);
                line_buffer_length = 0;
            }
        }
    }

    cleanup();
    return 0;
}
