#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define UART_DEVICE "/dev/ttyAMA0"
#define UART_BAUDRATE 115200
#define UART_FLAGS 0
#define UART_TIMEOUT 1000

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define EMERGENCY_STOP_MESSAGE "EMERGENCY STOP!\n"

static int gpiod_ctx = -1;
static int uart_fd = -1;

static void handle_signal(int signum) {
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    if (gpiod_ctx >= 0) {
        gpiod_chip_close(gpiod_ctx);
    }
    exit(1);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize libgpiod
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    // Configure GPIO pins as inputs with pull-up resistors
    struct gpiod_line *left_sensor_line = gpiod_chip_get_line(gpiod_ctx, LEFT_SENSOR_PIN);
    struct gpiod_line *middle_sensor_line = gpiod_chip_get_line(gpiod_ctx, MIDDLE_SENSOR_PIN);
    struct gpiod_line *right_sensor_line = gpiod_chip_get_line(gpiod_ctx, RIGHT_SENSOR_PIN);

    if (gpiod_line_request_input(left_sensor_line, "left_sensor") < 0 ||
        gpiod_line_request_input(middle_sensor_line, "middle_sensor") < 0 ||
        gpiod_line_request_input(right_sensor_line, "right_sensor") < 0) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(gpiod_ctx);
        exit(1);
    }

    // Initialize UART
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("Failed to open UART device");
        gpiod_chip_close(gpiod_ctx);
        exit(1);
    }

    struct termios uart_config;
    tcgetattr(uart_fd, &uart_config);
    cfsetispeed(&uart_config, UART_BAUDRATE);
    cfsetospeed(&uart_config, UART_BAUDRATE);
    uart_config.c_cflag &= ~PARENB;
    uart_config.c_cflag &= ~CSTOPB;
    uart_config.c_cflag &= ~CSIZE;
    uart_config.c_cflag |= CS8;
    uart_config.c_cflag &= ~CRTSCTS;
    uart_config.c_cflag |= CREAD | CLOCAL;
    uart_config.c_lflag &= ~ICANON;
    uart_config.c_lflag &= ~ECHO;
    uart_config.c_lflag &= ~ECHOE;
    uart_config.c_lflag &= ~ECHONL;
    uart_config.c_lflag &= ~ISIG;
    uart_config.c_iflag &= ~(IXON | IXOFF | IXANY);
    uart_config.c_oflag &= ~OPOST;
    uart_config.c_cc[VMIN] = 0;
    uart_config.c_cc[VTIME] = UART_TIMEOUT;
    tcsetattr(uart_fd, TCSANOW, &uart_config);

    while (1) {
        struct timespec sleep_time = {0, 10000000}; // 10 ms
        nanosleep(&sleep_time, NULL);

        int left_sensor_state = gpiod_line_get_value(left_sensor_line);
        int middle_sensor_state = gpiod_line_get_value(middle_sensor_line);
        int right_sensor_state = gpiod_line_get_value(right_sensor_line);

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        printf("%s: Left: %d, Middle: %d, Right: %d\n", timestamp, left_sensor_state, middle_sensor_state, right_sensor_state);

        if (left_sensor_state == 0 && middle_sensor_state == 0 && right_sensor_state == 0) {
            char emergency_stop_message[20];
            snprintf(emergency_stop_message, sizeof(emergency_stop_message), EMERGENCY_STOP_MESSAGE);
            if (write(uart_fd, emergency_stop_message, strlen(emergency_stop_message)) < 0) {
                perror("Failed to write to UART");
            }
        }
    }

    close(uart_fd);
    gpiod_chip_close(gpiod_ctx);
    return 0;
}

